window.STEPS=Object.assign(window.STEPS||{},{"고2-202009-05":{"길":"그래프에서 좌극한과 우극한을 따로 읽어 더한다","단계":[{"제목":"$x=-1$에서의 좌극한","힌트":"$x$가 $-1$보다 작은 쪽에서 $-1$에 가까워질 때 그래프는 어느 높이에 가까워지는가?","식":["$\\lim_{x\\to-1-}f(x)=1$"],"설명":"$x<-1$인 부분은 오른쪽 위로 뻗는 직선이고 $x=-1$에서 속이 빈 점 $(-1,1)$에 가까워진다. $f(-1)=-1$은 그 점에서의 함숫값일 뿐 좌극한과 관계없다.","확인":"1","스킬":"D12","고비":true},{"제목":"$x=1$에서의 우극한","힌트":"$x$가 $1$보다 큰 쪽에서 $1$에 가까워질 때 그래프는 어느 높이에 가까워지는가?","식":["$\\lim_{x\\to1+}f(x)=2$"],"설명":"$x>1$인 부분은 속이 빈 점 $(1,2)$에서 시작하는 곡선이므로 $2$에 가까워진다. $f(1)=1$은 우극한과 관계없다.","확인":"2","스킬":"D12"},{"제목":"두 극한값의 합","힌트":"읽은 두 값을 더하면?","식":["$\\lim_{x\\to-1-}f(x)+\\lim_{x\\to1+}f(x)=1+2=3$"],"설명":"좌극한과 우극한은 각각 따로 읽은 값이므로 그대로 더한다.","확인":"3","스킬":"D12"}]},"고2-202009-30":{"길":"$x<0$ 부분과 $x\\ge0$ 부분의 교점 개수를 구간별로 더해 $h(t)$를 만든다","단계":[{"제목":"$x<0$ 부분과 직선의 교점 개수","힌트":"$x<0$에서 $f(x)=(x+1)^2+1$의 최솟값과 $x\\to0-$일 때의 값은? 직선 $y=\\frac{t}{3}$는 몇 번 만나는가?","식":["$t<3$이면 $r(t)=0$","$3<t<6$이면 $r(t)=2$","$t=3$ 또는 $t\\ge6$이면 $r(t)=1$"],"설명":"$x<0$에서 $f(x)$는 $x=-1$에서 최솟값 $1$을 갖고, $x\\to0-$이면 $2$에 가까워지지만 $x<0$이므로 $2$에 닿지 않는다. 직선의 높이 $\\frac{t}{3}$가 $1$이면 접하는 한 점, $1$과 $2$ 사이이면 두 점, $2$ 이상이면 $x\\le-1$ 쪽의 한 점에서 만난다. 이 개수를 $r(t)$라 한다.","확인":null,"스킬":"G1"},{"제목":"$x\\ge0$ 부분의 식 정리","힌트":"$x\\ge0$에서 $f(-x)-t$를 완전제곱으로 쓰면 꼭짓점과 $y$절편은?","식":["$f(-x)-t=(x-1)^2+1-t$","꼭짓점 $(1,\\,1-t)$, $y$절편 $2-t$"],"설명":"$f(-x)=x^2-2x+2$이다. 이 이차함수는 $x=1$에서 최솟값 $1-t$를 갖고 $x=0$에서 $2-t$이다. 여기에 절댓값을 씌우면 $x$축 아래 부분이 위로 접힌다.","확인":null,"스킬":"G5"},{"제목":"$t<\\frac{3}{2}$일 때 $x\\ge0$ 부분의 교점 개수","힌트":"직선 높이 $\\frac{t}{3}$를 꼭짓점 높이 $1-t$와 비교하면 처음 만나는 때는 언제인가?","식":["$t<\\frac{3}{4}$이면 $s(t)=0$","$t=\\frac{3}{4}$이면 $s(t)=1$","$\\frac{3}{4}<t<\\frac{3}{2}$이면 $s(t)=2$"],"설명":"$\\frac{t}{3}=1-t$에서 $t=\\frac{3}{4}$이면 직선이 꼭짓점에 접하여 한 점이고, 그보다 작으면 직선이 그래프 아래에 있어 만나지 않는다. $\\frac{3}{4}<t<\\frac{3}{2}$이면 $|1-t|<\\frac{t}{3}<2-t$이므로 $t$가 $1$보다 작든 크든 직선이 $x=1$ 양쪽에서 한 점씩 만난다. 이 개수를 $s(t)$라 한다.","확인":null,"스킬":"G5"},{"제목":"$t\\ge\\frac{3}{2}$일 때 $x\\ge0$ 부분의 교점 개수","힌트":"접힌 봉우리의 높이 $t-1$, $x=0$에서의 높이 $|2-t|$를 직선 높이 $\\frac{t}{3}$와 비교하면?","식":["$\\frac{3}{2}\\le t\\le3$이면 $s(t)=3$","$t>3$이면 $s(t)=2$"],"설명":"$\\frac{3}{2}\\le t\\le3$이면 $|2-t|\\le\\frac{t}{3}\\le t-1$이어서 직선이 접힌 봉우리와 두 점, 오른쪽에서 올라가는 부분과 한 점에서 만나 3개이다. $t=\\frac{3}{2}$, $t=3$에서는 $x=0$의 점이 그 중 하나로 들어가 3개로 같다. $t>3$이면 $\\frac{t}{3}<t-2$로 직선이 $x=0$에서의 높이보다 낮아져 봉우리와 한 점만 만나므로 2개이다.","확인":null,"스킬":"C2","고비":true},{"제목":"$h(t)=r(t)+s(t)$ 구간별 정리","힌트":"같은 $t$의 범위에서 $r(t)$와 $s(t)$를 더하면?","식":["$t<\\frac{3}{4}$이면 $h(t)=0$, $t=\\frac{3}{4}$이면 $h(t)=1$","$\\frac{3}{4}<t<\\frac{3}{2}$이면 $h(t)=2$, $\\frac{3}{2}\\le t<3$이면 $h(t)=3$","$3\\le t<6$이면 $h(t)=4$, $t\\ge6$이면 $h(t)=3$"],"설명":"$x<0$과 $x\\ge0$의 교점은 $x$좌표가 다르므로 개수를 더한다. $t=3$에서는 $r(3)=1$, $s(3)=3$이고 $3<t<6$에서는 $r(t)=2$, $s(t)=2$여서 모두 $4$이다. $t\\ge6$에서는 $r(t)=1$, $s(t)=2$이다.","확인":null,"스킬":"G1"},{"제목":"$\\alpha_k$와 $h(\\alpha_k)$ 구하기","힌트":"$h(t)$의 값이 바뀌는 경계에서 좌극한과 우극한이 다른가? 경계의 함숫값은 어느 구간에 속하는가?","식":["$\\alpha_1=\\frac{3}{4}$, $\\alpha_2=\\frac{3}{2}$, $\\alpha_3=3$, $\\alpha_4=6$","$h(\\alpha_1)=1$, $h(\\alpha_2)=3$, $h(\\alpha_3)=4$, $h(\\alpha_4)=3$"],"설명":"$t=\\frac{3}{4}, \\frac{3}{2}, 3, 6$에서 $h(t)$의 값이 바뀌어 좌극한과 우극한이 다르다. $s(t)$를 구할 때 그래프 모양이 바뀌던 $t=1$, $t=2$에서는 $h(t)$가 같은 값이므로 $\\alpha$가 아니다. 함숫값은 경계가 포함된 구간의 값으로 읽는다.","확인":null,"스킬":"D12"},{"제목":"합의 값 구하기","힌트":"$4\\alpha_k\\times h(\\alpha_k)$를 네 개 더하면?","식":["$4\\left(\\frac{3}{4}\\times1+\\frac{3}{2}\\times3+3\\times4+6\\times3\\right)=141$"],"설명":"괄호 안은 $\\frac{3}{4}+\\frac{9}{2}+12+18=\\frac{141}{4}$이므로 $4$를 곱하면 정수가 된다.","확인":"141","스킬":"D12"}]},"고2-202011-04":{"길":"함숫값은 속이 찬 점에서, 극한값은 속이 빈 점의 높이에서 읽는다","단계":[{"제목":"$f(3)$의 값","힌트":"$x=3$에서 속이 찬 점의 높이는?","식":["$f(3)=1$"],"설명":"$x=3$에서 속이 찬 점은 $(3,1)$뿐이다. 속이 빈 점 $(3,3)$, $(3,2)$는 극한이 향하는 값일 뿐 함숫값이 아니다.","확인":"1","스킬":"D12"},{"제목":"$x=1$에서의 좌극한","힌트":"$x$가 $1$보다 작은 쪽에서 $1$에 가까워질 때 그래프는 어느 높이에 가까워지는가?","식":["$\\lim_{x\\to1-}f(x)=1$"],"설명":"$x<1$인 부분은 $(0,2)$에서 내려와 속이 빈 점 $(1,1)$에 가까워진다. $f(1)=0$은 좌극한과 관계없다.","확인":"1","스킬":"D12","고비":true},{"제목":"두 값의 합","힌트":"읽은 두 값을 더하면?","식":["$f(3)+\\lim_{x\\to1-}f(x)=1+1=2$"],"설명":"함숫값과 좌극한을 각각 따로 읽은 뒤 더한다.","확인":"2","스킬":"D12"}]},"고2-202011-07":{"길":"부등식에 $x$를 곱해 양 끝의 극한을 같게 만들어 끼운다","단계":[{"제목":"부등식을 $xf(x)$ 꼴로 바꾸기","힌트":"각 변을 $x^2+1$로 나눈 뒤 $x>0$을 곱하면 가운데 식은?","식":["$\\frac{x(5x-1)}{x^2+1}<xf(x)<\\frac{x(5x+2)}{x^2+1}\\ (x>0)$"],"설명":"$x^2+1>0$이므로 각 변을 나누어도 부등호 방향이 같다. $x\\to\\infty$를 다루므로 $x>0$으로 보고 각 변에 $x$를 곱해도 부등호 방향이 바뀌지 않는다.","확인":null,"스킬":"C9","고비":true},{"제목":"양 끝 식의 극한으로 가운데 극한 정하기","힌트":"왼쪽 식과 오른쪽 식에서 $x\\to\\infty$일 때의 극한은 각각 얼마인가?","식":["$\\lim_{x\\to\\infty}\\frac{x(5x-1)}{x^2+1}=5$","$\\lim_{x\\to\\infty}\\frac{x(5x+2)}{x^2+1}=5$","$\\lim_{x\\to\\infty}xf(x)=5$"],"설명":"분자 $5x^2-x$, $5x^2+2x$와 분모 $x^2+1$의 최고차항 계수의 비가 모두 $5$이다. 양 끝의 극한이 같으므로 그 사이에 낀 $xf(x)$의 극한도 같은 값이다.","확인":"5","스킬":"C9"}]},"고2-202011-09":{"길":"다항함수의 연속성으로 $f(2)$를 먼저 구한 뒤 둘째 극한에서 $a$를 구한다","단계":[{"제목":"$f(2)$의 값","힌트":"$\\lim_{x\\to2}(x+1)f(x)=6$에서 $x+1$에 $2$를 대입하면 $f(2)$는?","식":["$\\lim_{x\\to2}(x+1)f(x)=3f(2)=6$","$f(2)=2$"],"설명":"다항함수는 모든 실수에서 연속이므로 $\\lim_{x\\to2}f(x)=f(2)$이다. 곱의 극한은 극한의 곱이므로 $3\\times f(2)=6$이다.","확인":"2","스킬":"D12"},{"제목":"$a$의 값","힌트":"$\\lim_{x\\to2}(x^2+ax-1)f(x)$에서 $x^2+ax-1$에 $x=2$를 대입하면?","식":["$\\lim_{x\\to2}(x^2+ax-1)f(x)=(2a+3)f(2)$","$(2a+3)\\times2=26$","$a=5$"],"설명":"$x=2$를 대입한 $x^2+ax-1$은 $4+2a-1=2a+3$이다. 앞에서 구한 $f(2)=2$를 곱한 값이 $26$이다.","확인":"5","스킬":"C7","고비":true},{"제목":"$a+f(2)$의 값","힌트":"구한 두 값을 더하면?","식":["$a+f(2)=5+2=7$"],"설명":"$a=5$, $f(2)=2$를 더한다.","확인":"7","스킬":"C7"}]},"고2-202011-20":{"길":"$f$의 그래프로 $g(t)$를 구간별로 정한 뒤 극한 조건에서 $k$를 구한다","단계":[{"제목":"$y=f(x)$의 그래프 모양","힌트":"$\\frac{kx}{x-1}$의 점근선과 $0<x<1$에서의 부호는? 절댓값을 씌우면 그 부분은?","식":["$f(x)=\\left|\\frac{k}{x-1}+k\\right|$","점근선 $x=1$, $y=k$"],"설명":"$y=\\frac{kx}{x-1}$은 원점을 지나고 $0<x<1$에서 값이 음수이므로 절댓값으로 그 부분이 위로 접힌다. 그 결과 $x<0$에서는 $0<f(x)<k$이고, $0<x<1$에서는 $0$에서 한없이 커지며, $x>1$에서는 $k$보다 큰 값에서 $k$에 가까워진다.","확인":null,"스킬":"G5"},{"제목":"$g(t)$의 구간별 값","힌트":"직선 $y=t$를 아래에서 위로 올리며 $t=0$, $t=k$ 근처에서 교점이 몇 개인지 센다. $t=k$에서 $x<0$ 부분은 닿는가?","식":["$t<0$이면 $g(t)=0$","$t=0$ 또는 $t=k$이면 $g(t)=1$","$0<t<k$ 또는 $t>k$이면 $g(t)=2$"],"설명":"$f(x)\\ge0$이므로 $t<0$이면 만나지 않고 $t=0$이면 원점 한 점이다. $t=k$이면 $x<0$ 부분은 $y=k$에 한없이 가까워질 뿐 닿지 않고 $x>1$ 부분은 $k$보다 큰 값이어서 $0<x<1$ 부분의 한 점만 만난다. $0<t<k$이면 $x<0$ 부분과 $0<x<1$ 부분에서, $t>k$이면 $0<x<1$ 부분과 $x>1$ 부분에서 한 점씩 만나 2개이다.","확인":null,"스킬":"G5","고비":true},{"제목":"두 극한값의 합","힌트":"$t\\to0+$일 때와 $t\\to2-$일 때 $t$는 어느 구간에 있는가?","식":["$\\lim_{t\\to0+}g(t)+\\lim_{t\\to2-}g(t)=2+2=4$"],"설명":"$t\\to0+$이면 $0<t<k$이므로 $g(t)=2$이다. $t\\to2-$이면 $t$가 $2$ 바로 왼쪽에 있어 $k$가 $2$보다 크든 작든 같든 $0<t<k$ 또는 $t>k$에 들어가므로 $g(t)=2$이다.","확인":"4","스킬":"D12"},{"제목":"$k$의 값","힌트":"$g(4)$는 얼마이어야 하고, $g(t)$가 그 값이 되는 $t$는 어디인가?","식":["$4+g(4)=5$에서 $g(4)=1$","$g(t)=1$인 $t$는 $0$ 또는 $k$","$k=4$"],"설명":"$g(4)=1$이면 $t=4$가 $0$ 또는 $k$여야 한다. $4\\ne0$이므로 $k=4$이다.","확인":"4","스킬":"G5"},{"제목":"$f(3)$의 값","힌트":"$f(x)=\\left|\\frac{kx}{x-1}\\right|$에 $k$와 $x=3$을 대입하면?","식":["$f(3)=\\left|\\frac{4\\times3}{3-1}\\right|=6$"],"설명":"$k=4$를 대입한 $f(x)=\\left|\\frac{4x}{x-1}\\right|$에 $x=3$을 넣는다.","확인":"6","스킬":"T4"}]},"고2-202011-22":{"길":"분자를 인수분해해 $x-1$을 약분한 뒤 대입한다","단계":[{"제목":"분자의 인수분해","힌트":"$x^2+6x-7$은 $x-1$을 인수로 갖는다. 나머지 인수는?","식":["$x^2+6x-7=(x-1)(x+7)$"],"설명":"$x\\to1$이면 분모가 $0$에 가까워지므로 분자도 $x=1$에서 $0$이 되어야 하고, 곱 꼴로 고쳐 $x-1$을 약분한다.","확인":null,"스킬":"D11","고비":true},{"제목":"약분 후 극한값","힌트":"$x-1$을 약분한 식에 $x=1$을 대입하면?","식":["$\\lim_{x\\to1}\\frac{(x-1)(x+7)}{x-1}=\\lim_{x\\to1}(x+7)=8$"],"설명":"$x\\ne1$인 동안 $\\frac{x-1}{x-1}=1$이므로 약분해도 극한값은 같다.","확인":"8","스킬":"D11"}]},"고2-202011-28":{"길":"세 점 A, P, Q의 좌표로 $S(t)$를 $t$의 식으로 쓴 뒤 분자를 유리화한다","단계":[{"제목":"점 A의 좌표","힌트":"$y=x^2$을 원의 방정식에 대입하면 $y$에 대한 이차방정식은?","식":["$y+y^2=2$","$(y+2)(y-1)=0$","$\\mathrm{A}(1,\\,1)$"],"설명":"$x^2=y$를 $x^2+y^2=2$에 대입하면 $y^2+y-2=0$이다. $y=x^2\\ge0$이므로 $y=-2$는 버리고 $y=1$이며, 제1사분면이므로 $x=1$이다.","확인":null,"스킬":"G1"},{"제목":"점 Q의 좌표와 $\\overline{\\mathrm{OQ}}$","힌트":"$y=tx$와 $y=x^2$을 연립했을 때 제1사분면의 해는?","식":["$x(x-t)=0$","$\\mathrm{Q}(t,\\,t^2)$","$\\overline{\\mathrm{OQ}}=t\\sqrt{1+t^2}$"],"설명":"$tx=x^2$에서 $x=0$ 또는 $x=t$이다. $x=0$은 원점이어서 제1사분면의 점이 아니므로 버리고 $x=t$이다. $\\overline{\\mathrm{OQ}}=\\sqrt{t^2+t^4}=t\\sqrt{1+t^2}$이다.","확인":null,"스킬":"G1"},{"제목":"선분 PQ의 길이","힌트":"원점은 원의 중심이다. 직선 위에서 O, Q, P의 순서는?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{2}$","$\\overline{\\mathrm{PQ}}=\\sqrt{2}-t\\sqrt{1+t^2}$"],"설명":"P는 원 위의 점이므로 $\\overline{\\mathrm{OP}}$는 반지름 $\\sqrt{2}$이다. $0<t<1$에서 $t\\sqrt{1+t^2}<\\sqrt{2}$이므로 O, Q, P 순서이고 $\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{OP}}-\\overline{\\mathrm{OQ}}$이다.","확인":null,"스킬":"G10"},{"제목":"높이 $\\overline{\\mathrm{AH}}$와 넓이 $S(t)$","힌트":"점 $\\mathrm{A}(1,1)$에서 직선 $tx-y=0$까지의 거리는?","식":["$\\overline{\\mathrm{AH}}=\\frac{|t-1|}{\\sqrt{t^2+1}}=\\frac{1-t}{\\sqrt{1+t^2}}$","$S(t)=\\frac{1}{2}\\left(\\sqrt{2}-t\\sqrt{1+t^2}\\right)\\times\\frac{1-t}{\\sqrt{1+t^2}}$"],"설명":"PQ를 밑변으로 보면 A에서 직선 $y=tx$에 내린 수선의 길이가 높이이다. $0<t<1$이므로 $|t-1|=1-t$이다.","확인":null,"스킬":"G10"},{"제목":"$\\frac{S(t)}{(1-t)^2}$ 정리","힌트":"$t\\to1-$일 때 분자와 분모가 모두 $0$이 된다. 무엇을 유리화하는가?","식":["$\\frac{S(t)}{(1-t)^2}=\\frac{\\sqrt{2}-t\\sqrt{1+t^2}}{2(1-t)\\sqrt{1+t^2}}$","$=\\frac{(t^2+2)(1+t)}{2\\sqrt{1+t^2}\\left(\\sqrt{2}+t\\sqrt{1+t^2}\\right)}$"],"설명":"분자에 $\\sqrt{2}+t\\sqrt{1+t^2}$을 곱하고 나누면 분자가 $2-t^2(1+t^2)=(t^2+2)(1-t^2)$이 된다. $1-t^2=(1-t)(1+t)$이므로 분모의 $1-t$와 약분된다.","확인":null,"스킬":"D11","고비":true},{"제목":"$k$의 값과 $20k$의 값","힌트":"약분한 식에 $t=1$을 대입하면?","식":["$k=\\frac{3\\times2}{2\\sqrt{2}\\left(\\sqrt{2}+\\sqrt{2}\\right)}=\\frac{3}{4}$","$20k=15$"],"설명":"분자는 $(1+2)(1+1)=6$, 분모는 $2\\sqrt{2}\\times2\\sqrt{2}=8$이다.","확인":"15","스킬":"D11"}]},"고2-202011-29":{"길":"$g$가 끊길 수 있는 $x=1$, $x=3$에서 연속 조건을 세워 경우를 나눈다","단계":[{"제목":"연속을 확인할 점","힌트":"$f(x)$는 다항함수이다. $f(x)g(x)$가 끊길 수 있는 점은 어디인가?","식":["$f(1)g(1)=\\lim_{x\\to1-}f(x)g(x)=\\lim_{x\\to1+}f(x)g(x)$","$f(3)g(3)=\\lim_{x\\to3-}f(x)g(x)=\\lim_{x\\to3+}f(x)g(x)$"],"설명":"$f(x)$는 모든 실수에서 연속이므로 $g(x)$가 식이 바뀌는 $x=1$, $x=3$에서만 확인하면 된다. 이 두 점에서 함숫값, 좌극한, 우극한이 모두 같아야 한다.","확인":null,"스킬":"D12"},{"제목":"$x=1$에서의 조건","힌트":"$g(1)$, 좌극한, 우극한은 각각 얼마이고, 두 값이 다르면 $f(1)$은 어때야 하는가?","식":["$f(1)=(a-1)(a-2)$","$(a-1)(a-2)(7-b)=(a-1)(a-2)(1+b)$","$a=1$ 또는 $a=2$ 또는 $b=3$"],"설명":"$x=1$에서 $g$의 함숫값과 좌극한은 $7-b$, 우극한은 $1+b$이다. 정리하면 $(a-1)(a-2)(6-2b)=0$이므로 세 인수 중 하나가 $0$이어야 한다.","확인":null,"스킬":"D12"},{"제목":"$x=3$에서의 조건","힌트":"$x=3$에서 $g$의 함숫값, 좌극한, 우극한은 각각 얼마인가?","식":["$f(3)=(a-2)(a-5)$","$(a-2)(a-5)(7-b)=(a-2)(a-5)(3+b)$","$a=2$ 또는 $a=5$ 또는 $b=2$"],"설명":"$x=3$에서 $g$의 함숫값과 우극한은 $7-b$, 좌극한은 $3+b$이다. 정리하면 $(a-2)(a-5)(4-2b)=0$이다.","확인":null,"스킬":"D12"},{"제목":"$a$의 값에 따라 경우 나누기","힌트":"$a$를 $1$부터 $5$까지 바꾸어 두 조건을 모두 만족하는 $b$를 찾으면?","식":["$a=1$이면 $b=2$, $a=5$이면 $b=3$","$a=2$이면 $b$는 $1,2,3,4,5$","$a=3$, $a=4$이면 만족하는 $b$가 없다"],"설명":"$a=1$은 $x=1$ 조건이 성립해 $x=3$ 조건에서 $b=2$가 필요하고, $a=5$는 $x=3$ 조건이 성립해 $x=1$ 조건에서 $b=3$이 필요하다. $a=2$는 두 조건이 모두 성립하여 $b$가 자유롭다. $a=3$, $a=4$는 두 조건에서 각각 $b=3$, $b=2$가 필요해 동시에 만족하는 $b$가 없으므로 버린다.","확인":null,"스킬":"C2","고비":true},{"제목":"순서쌍의 개수","힌트":"경우별 개수를 모두 더하면?","식":["$(1,2)$, $(2,1)$, $(2,2)$, $(2,3)$, $(2,4)$, $(2,5)$, $(5,3)$","$1+5+1=7$"],"설명":"$a=1$에서 1개, $a=2$에서 5개, $a=5$에서 1개이다.","확인":"7","스킬":"C2"}]},"고2-202109-05":{"길":"좌극한과 우극한을 속이 빈 점과 속이 찬 점의 높이로 따로 읽는다","단계":[{"제목":"$x=-1$에서의 우극한","힌트":"$x$가 $-1$보다 큰 쪽에서 $-1$에 가까워질 때 그래프는 어느 높이에 가까워지는가?","식":["$\\lim_{x\\to-1+}f(x)=2$"],"설명":"$-1<x<0$인 부분은 속이 빈 점 $(-1,2)$에서 원점으로 내려가는 직선이므로 $2$에 가까워진다. $f(-1)=-1$은 $x\\le-1$ 쪽의 값이어서 우극한과 관계없다.","확인":"2","스킬":"D12","고비":true},{"제목":"$x=1$에서의 좌극한","힌트":"$x$가 $1$보다 작은 쪽에서 $1$에 가까워질 때 그래프는 어느 높이에 가까워지는가?","식":["$\\lim_{x\\to1-}f(x)=1$"],"설명":"$0\\le x\\le1$인 부분은 원점에서 속이 찬 점 $(1,1)$까지의 선분이므로 $x\\to1-$이면 $1$에 가까워진다. $x>1$ 쪽의 속이 빈 점 $(1,2)$는 좌극한과 관계없다.","확인":"1","스킬":"D12"},{"제목":"두 극한값의 합","힌트":"읽은 두 값을 더하면?","식":["$\\lim_{x\\to-1+}f(x)+\\lim_{x\\to1-}f(x)=2+1=3$"],"설명":"두 극한을 각각 따로 읽은 뒤 더한다.","확인":"3","스킬":"D12"}]},"고2-202109-26":{"길":"차수를 정하고 분모가 $0$이 되는 점에서 분자도 $0$이 되는 조건을 쓴다","단계":[{"제목":"$f(x)$의 꼴","힌트":"$\\frac{f(x)}{2x^2}$의 극한이 $0$이 아닌 값이면 $f(x)$의 차수와 최고차항 계수는?","식":["$f(x)=2x^2+ax+b$"],"설명":"$x\\to\\infty$에서 $\\frac{f(x)}{2x^2}$의 극한이 $1$이면 $f(x)$는 이차식이고 최고차항의 계수가 $2$이다.","확인":null,"스킬":"A11"},{"제목":"분자가 $0$이 되는 조건","힌트":"$x\\to1$일 때 분모 $(x-1)(x-2)$는 어떤 값에 가까워지는가? 극한이 존재하려면 분자는?","식":["$\\lim_{x\\to1}\\{f(x)-3\\}=0$","$f(1)=2+a+b=3$","$b=1-a$"],"설명":"분모가 $0$에 가까워지는데 극한이 $4$로 존재하므로 분자 $f(x)-3$도 $0$에 가까워져야 한다. $f(x)$가 다항함수이므로 $f(1)=3$이다.","확인":null,"스킬":"D11","고비":true},{"제목":"분자의 인수분해","힌트":"$f(1)-3=0$이므로 $f(x)-3$은 어떤 인수를 가지는가?","식":["$f(x)-3=2x^2+ax-a-2=(x-1)(2x+a+2)$"],"설명":"$b=1-a$를 대입하면 $f(x)-3=2x^2+ax-a-2$이고, $x=1$에서 $0$이므로 $x-1$을 인수로 갖는다.","확인":null,"스킬":"D11"},{"제목":"$a$의 값","힌트":"$x-1$을 약분한 뒤 $x=1$을 대입한 값이 $4$이려면?","식":["$\\lim_{x\\to1}\\frac{(x-1)(2x+a+2)}{(x-1)(x-2)}=\\frac{a+4}{-1}$","$-(a+4)=4$","$a=-8$"],"설명":"약분하면 $\\frac{2x+a+2}{x-2}$이고 $x=1$을 대입하면 분자는 $a+4$, 분모는 $-1$이다.","확인":"-8","스킬":"D11"},{"제목":"$f(4)$의 값","힌트":"$b=1-a$로 $b$를 구해 $f(x)$를 완성하고 $x=4$를 대입하면?","식":["$b=1-(-8)=9$","$f(x)=2x^2-8x+9$","$f(4)=32-32+9=9$"],"설명":"$a=-8$을 $b=1-a$에 대입해 $b$를 구한 뒤 $f(x)$에 $x=4$를 넣는다.","확인":"9","스킬":"A11"}]},"고2-202109-30":{"길":"$g$의 값이 $-2$, $0$, $2$뿐임을 써서 교점 5개를 $f$의 영점으로 바꾼다","단계":[{"제목":"$g(x)$가 가질 수 있는 값","힌트":"$f(t)>0$일 때와 $f(t)<0$일 때 $\\frac{|f(t)|}{f(t)}$는 각각 얼마인가?","식":["$g(\\alpha)=2$: $f$가 $0$을 지나며 음에서 양으로 바뀜","$g(\\alpha)=-2$: $f$가 $0$을 지나며 양에서 음으로 바뀜","그 밖의 점에서는 $g(\\alpha)=0$"],"설명":"$f(t)>0$이면 $\\frac{|f(t)|}{f(t)}=1$, $f(t)<0$이면 $-1$이다. 부호가 바뀌지 않으면 좌극한과 우극한이 같아 $g=0$이고, $f$가 $0$이 되면서 부호가 바뀔 때만 $g=\\pm2$이다. 따라서 $g$의 값은 $-2$, $0$, $2$뿐이다.","확인":null,"스킬":"C6"},{"제목":"교점 5개를 $f$의 영점으로 바꾸기","힌트":"$y=-4\\left|\\log_2\\frac{x}{2}\\right|+2$가 높이 $-2$, $0$, $2$를 지나는 점은 모두 몇 개이고, 교점이 5개이면 어떤 점들이 교점인가?","식":["$y=-2$: $x=1,\\,4$","$y=0$: $x=\\sqrt{2},\\,2\\sqrt{2}$, $y=2$: $x=2$","$f(1)=f(2)=f(4)=0$"],"설명":"곡선은 $x=2$에서 최댓값 $2$를 갖고 좌우로 감소한다. $g$의 값이 $-2$, $0$, $2$뿐이므로 교점은 이 세 높이에서만 생기고 그 후보가 정확히 5개이므로 전부 교점이다. 그러면 $g(1)=g(4)=-2$, $g(2)=2$이므로 $x=1$, $2$, $4$에서 $f$가 $0$이다(1과 4에서 양에서 음으로, 2에서 음에서 양으로).","확인":null,"스킬":"G1","고비":true},{"제목":"$k$의 범위","힌트":"$x=1$, $2$, $4$에서 모두 같은 이차식으로 $0$이 될 수 있는가?","식":["$1<k\\le4$","$f(1)=f_1(1)=0$, $f(4)=f_2(4)=0$"],"설명":"$f_1(x)=ax^2+(2b-3)x+a^2-3$, $f_2(x)=-\\frac{1}{3}ax^2+(b+5)x+a^2-1$이라 한다. $k\\le1$이면 $x=1,2,4$에서 모두 $f=f_2$이고 $k>4$이면 모두 $f=f_1$이어서 이차식이 세 곳에서 $0$일 수 없으므로 버린다. 따라서 $1<k\\le4$이고 $x=1$에서는 $f_1$, $x=4$에서는 $f_2$를 쓴다.","확인":null,"스킬":"C2"},{"제목":"$a$의 부호 정하기","힌트":"$a<0$이면 $f_1$과 $f_2$의 볼록 방향과, $x=1$, $x=4$에서 부호가 바뀌는 방향으로 $x=2$의 값을 따져 보면?","식":["$a<0$이면 $f_1(2)\\ne0$, $f_2(2)\\ne0$","$a>0$"],"설명":"$a<0$이면 $f_1$은 위로 볼록해 양에서 음으로 바뀌는 $x=1$이 큰 근이므로 $f_1(2)\\ne0$이다. $f_2$는 아래로 볼록해 양에서 음으로 바뀌는 $x=4$가 작은 근이므로 $f_2(2)\\ne0$이다. 어느 식을 쓰든 $f(2)=0$이 성립하지 않으므로 $a<0$은 버린다.","확인":null,"스킬":"C2"},{"제목":"$a$의 값 구하기","힌트":"$f_1(1)=0$, $f_2(4)=0$에서 $b$를 없애면 $a$에 대한 이차방정식은?","식":["$a^2+a+2b-6=0$, $a^2-\\frac{16}{3}a+4b+19=0$","$3a^2+22a-93=0$에서 $a=3$","$b=-3$"],"설명":"둘째 식에서 첫째 식의 $2$배를 빼면 $3a^2+22a-93=0$, 즉 $(3a+31)(a-3)=0$이다. $a>0$이므로 $a=-\\frac{31}{3}$은 버리고 $a=3$이며, 첫째 식에서 $b=-3$이다.","확인":"3","스킬":"A10"},{"제목":"$k$의 값 구하기","힌트":"$a=3$, $b=-3$일 때 $f_1$, $f_2$를 쓰고 $x=k$에서 이어지는 조건은?","식":["$f_1(x)=3x^2-9x+6$, $f_2(x)=-x^2+2x+8$","$3k^2-9k+6=-k^2+2k+8$, $4k^2-11k-2=0$","$k=\\frac{11+3\\sqrt{17}}{8}$"],"설명":"$f_2(2)=8\\ne0$이므로 $x=2$에서 $f=f_1$이어야 하고 $2<k\\le4$이다. 조건 (가)에서 $x=k$의 좌극한과 우극한이 같으므로 $f_1(k)=f_2(k)$이다. $k=\\frac{11-3\\sqrt{17}}{8}$은 음수여서 $k>2$에 맞지 않아 버린다.","확인":null,"스킬":"D12"},{"제목":"$16(p+q)$의 값","힌트":"$k=p+q\\sqrt{17}$로 놓으면 $p$, $q$는?","식":["$p=\\frac{11}{8}$, $q=\\frac{3}{8}$","$16(p+q)=16\\times\\frac{14}{8}=28$"],"설명":"$k=\\frac{11}{8}+\\frac{3}{8}\\sqrt{17}$이고 $p$, $q$가 유리수이므로 계수를 그대로 읽는다.","확인":"28","스킬":"D12"}]},"고2-202111-04":{"길":"좌극한과 우극한을 속이 찬 점과 속이 빈 점의 높이로 따로 읽어 곱한다","단계":[{"제목":"$x=0$에서의 좌극한","힌트":"$x$가 $0$보다 작은 쪽에서 $0$에 가까워질 때 그래프는 어느 높이에 가까워지는가?","식":["$\\lim_{x\\to0-}f(x)=2$"],"설명":"$x<0$인 곡선은 $x=0$에서 속이 찬 점 $(0,2)$로 이어지므로 $2$에 가까워진다. $x>0$ 쪽에서 시작하는 속이 빈 점 $(0,0)$은 우극한과 관계된 점이다.","확인":"2","스킬":"D12","고비":true},{"제목":"$x=1$에서의 우극한","힌트":"$x$가 $1$보다 큰 쪽에서 $1$에 가까워질 때 그래프는 어느 높이에 가까워지는가?","식":["$\\lim_{x\\to1+}f(x)=1$"],"설명":"$x>1$인 곡선은 속이 빈 점 $(1,1)$에서 시작하므로 $1$에 가까워진다. $f(1)=0$과 좌극한은 우극한과 관계없다.","확인":"1","스킬":"D12"},{"제목":"두 극한값의 곱","힌트":"읽은 두 값을 곱하면?","식":["$\\lim_{x\\to0-}f(x)\\times\\lim_{x\\to1+}f(x)=2\\times1=2$"],"설명":"두 극한을 각각 따로 읽은 뒤 곱한다.","확인":"2","스킬":"D12"}]},"고2-202111-07":{"길":"평균변화율을 $k$의 식으로 쓴 뒤 양수 조건으로 $k$를 고른다","단계":[{"제목":"평균변화율을 $k$로 나타내기","힌트":"$f(0)$의 값과 $\\frac{f(k)-f(0)}{k-0}$을 약분한 식은?","식":["$f(0)=0$","$\\frac{f(k)-f(0)}{k-0}=\\frac{k^3+k^2-2k}{k}=k^2+k-2$"],"설명":"$x$의 값이 $0$에서 $k$까지 변할 때의 평균변화율은 $\\frac{f(k)-f(0)}{k-0}$이다. $k>0$이므로 분자와 분모를 $k$로 약분할 수 있다.","확인":null,"스킬":"D2","고비":true},{"제목":"$k$의 값 구하기","힌트":"평균변화율이 $10$이라고 놓고 이차방정식을 풀면?","식":["$k^2+k-2=10$","$(k+4)(k-3)=0$","$k=3$"],"설명":"$k=-4$ 또는 $k=3$인데 $k$가 양수이므로 $k=-4$는 버리고 $k=3$이다.","확인":"3","스킬":"D2"}]},"고2-202111-12":{"길":"미분가능이면 연속이므로 연속 조건과 좌우 미분계수 조건을 함께 쓴다","단계":[{"제목":"$x=1$에서의 연속 조건","힌트":"미분가능하면 $x=1$에서 연속이다. 좌극한과 $f(1)$이 같다는 식은?","식":["$\\lim_{x\\to1-}f(x)=f(1)$에서 $1-a+2b=-3+b$","$b=a-4$"],"설명":"$f(x)$가 실수 전체에서 미분가능하므로 $x=1$에서 연속이다. $x<1$의 식에 $x=1$을 넣은 값과 $f(1)=-3+b$가 같아야 한다.","확인":null,"스킬":"D12"},{"제목":"$x=1$에서의 미분계수 조건","힌트":"$x<1$과 $x>1$에서 각각 도함수를 구하고 $x=1$의 값을 비교하면?","식":["$x<1$이면 $f'(x)=3x^2-a$, $x>1$이면 $f'(x)=-3$","$3-a=-3$","$a=6$"],"설명":"$x=1$에서 연속이므로 좌미분계수는 왼쪽 식 $x^3-ax+2b$를 미분해 $x=1$을 넣은 값 $3-a$이고, 우미분계수는 오른쪽 식의 기울기 $-3$이다. 미분가능하려면 두 값이 같아야 한다.","확인":"6","스킬":"D12","고비":true},{"제목":"$a\\times b$의 값","힌트":"$b=a-4$에 구한 $a$를 넣어 $b$를 구한 뒤 곱하면?","식":["$b=6-4=2$","$a\\times b=6\\times2=12$"],"설명":"연속 조건에서 얻은 $b=a-4$에 $a=6$을 대입한다.","확인":"12","스킬":"D12"}]},"고2-202111-13":{"길":"$\\lim f(x)=0$과 $\\lim\\frac{f(x)}{x}$를 조임 정리로 구해 분자 분모를 $x$로 나눈다","단계":[{"제목":"$x\\to0$일 때 $f(x)$의 극한","힌트":"부등식의 양 끝 식의 극한은 각각 얼마인가?","식":["$\\lim_{x\\to0}\\left(\\frac{1}{2}x^2+2x\\right)=\\lim_{x\\to0}(x^2+2x)=0$","$\\lim_{x\\to0}f(x)=0$"],"설명":"양 끝 식의 극한이 모두 $0$으로 같으므로 그 사이에 낀 $f(x)$의 극한도 $0$이다.","확인":"0","스킬":"C9"},{"제목":"부등식을 $\\frac{f(x)}{x}$ 꼴로 바꾸기","힌트":"각 변을 $x$로 나눌 때 $x>0$과 $x<0$에서 부등호의 방향은 각각 어떻게 되는가?","식":["$x>0$이면 $\\frac{1}{2}x+2<\\frac{f(x)}{x}<x+2$","$x<0$이면 $x+2<\\frac{f(x)}{x}<\\frac{1}{2}x+2$"],"설명":"$x>0$이면 부등호 방향이 그대로이고, $x<0$이면 음수로 나누므로 부등호 방향이 바뀐다. 그래서 $x<0$에서는 큰 쪽과 작은 쪽의 식이 서로 바뀐다.","확인":null,"스킬":"C9","고비":true},{"제목":"$\\lim_{x\\to0}\\frac{f(x)}{x}$의 값","힌트":"$x\\to0+$와 $x\\to0-$에서 양 끝 식의 극한은 각각 얼마인가?","식":["$x\\to0+$이면 양 끝이 모두 $2$에 가까워짐","$x\\to0-$이면 양 끝이 모두 $2$에 가까워짐","$\\lim_{x\\to0}\\frac{f(x)}{x}=2$"],"설명":"우극한과 좌극한이 모두 $2$이므로 극한값이 존재하고 $2$이다.","확인":"2","스킬":"C9"},{"제목":"구하는 극한값","힌트":"분자와 분모를 $x$로 나누어 $f(x)$, $\\frac{f(x)}{x}$ 꼴로 바꾸면?","식":["$\\lim_{x\\to0}\\frac{xf(x)+5x}{2f(x)-x}=\\lim_{x\\to0}\\frac{f(x)+5}{2\\times\\frac{f(x)}{x}-1}$","$=\\frac{0+5}{2\\times2-1}=\\frac{5}{3}$"],"설명":"$x\\ne0$이므로 분자와 분모를 $x$로 나눌 수 있다. 앞에서 구한 $\\lim f(x)=0$, $\\lim\\frac{f(x)}{x}=2$를 대입한다.","확인":"5/3","스킬":"C9"}]},"고2-202111-15":{"길":"분모가 $0$이 되는 점에서 분자의 값을 정해 $f(1)$, $g(1)$, 미분계수를 구한다","단계":[{"제목":"$f(1)$과 $f'(1)$","힌트":"$x\\to1$일 때 분모 $x-1\\to0$이므로 극한이 존재하려면 분자는? 그 값으로 분자를 고쳐 쓰면?","식":["$f(1)=a-2$","$\\frac{f(x)-a+2}{x-1}=\\frac{f(x)-f(1)}{x-1}$이므로 $f'(1)=4$"],"설명":"분자 $f(x)-a+2$가 $0$에 가까워져야 하고 $f$는 다항함수이므로 $f(1)=a-2$이다. 그러면 분자는 $f(x)-f(1)$이어서 극한이 미분계수 $f'(1)$이다.","확인":null,"스킬":"D3","고비":true},{"제목":"$g(1)$과 $g'(1)$","힌트":"$g(x)+a-2$가 $g(x)-g(1)$이 되려면 $g(1)$은?","식":["$g(1)=2-a$","$\\frac{g(x)+a-2}{x-1}=\\frac{g(x)-g(1)}{x-1}$이므로 $g'(1)=a$"],"설명":"같은 방법으로 분자 $g(x)+a-2$가 $0$에 가까워져야 하므로 $g(1)=2-a$이다. 그러면 주어진 극한이 $g'(1)$이다.","확인":null,"스킬":"D3"},{"제목":"$f(x)g(x)$의 $x=1$에서의 미분계수","힌트":"곱의 미분법으로 $(fg)'(1)$을 $f(1)$, $f'(1)$, $g(1)$, $g'(1)$로 쓰면?","식":["$(fg)'(1)=f'(1)g(1)+f(1)g'(1)$","$=4(2-a)+(a-2)\\times a=a^2-6a+8$"],"설명":"곱의 미분법 $(fg)'=f'g+fg'$에 $x=1$을 대입하고 앞에서 구한 네 값을 넣는다.","확인":null,"스킬":"D1"},{"제목":"$a$의 값 구하기","힌트":"$(fg)'(1)=-1$로 놓고 이차방정식을 풀면?","식":["$a^2-6a+8=-1$","$(a-3)^2=0$","$a=3$"],"설명":"$a^2-6a+9=0$은 완전제곱식이므로 중근 $a=3$ 하나뿐이다.","확인":"3","스킬":"D1"}]},"고2-202111-18":{"길":"네 점의 좌표로 사다리꼴의 밑변과 높이를 세우고 유리화로 약분한다","단계":[{"제목":"네 점의 좌표 구하기","힌트":"직선 $y=2t$, $y=t+1$이 각 곡선과 만나는 점의 $x$좌표는 얼마인가?","식":["$\\mathrm{A}\\left(\\sqrt{2t},\\,2t\\right),\\ \\mathrm{B}\\left(\\sqrt{2},\\,2t\\right)$","$\\mathrm{C}\\left(\\sqrt{t+1},\\,t+1\\right),\\ \\mathrm{D}\\left(\\sqrt{\\frac{t+1}{t}},\\,t+1\\right)$"],"설명":"제1사분면이므로 $x>0$이다. $y=x^2$에서는 $x=\\sqrt{y}$, $y=tx^2$에서는 $x=\\sqrt{\\frac{y}{t}}$이다.","확인":null,"스킬":"G10"},{"제목":"사다리꼴의 밑변과 높이","힌트":"$\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{CD}}$의 길이와 두 변 사이의 거리는 얼마인가?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{2}\\left(1-\\sqrt{t}\\right),\\ \\overline{\\mathrm{CD}}=\\sqrt{\\frac{t+1}{t}}\\left(1-\\sqrt{t}\\right)$","높이 $=(t+1)-2t=1-t$"],"설명":"두 변이 모두 $x$축과 평행하므로 사각형 $\\mathrm{ABDC}$는 사다리꼴이다. 높이는 두 직선 $y=2t$, $y=t+1$ 사이의 거리이다.","확인":null,"스킬":"G10"},{"제목":"S(t)를 쓰고 약분하기","힌트":"$\\frac{S(t)}{(1-t)^2}$에서 $1-t$를 어떻게 약분하는가?","식":["$S(t)=\\frac{1}{2}\\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)\\left(1-\\sqrt{t}\\right)(1-t)$","$\\frac{S(t)}{(1-t)^2}=\\frac{1}{2}\\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)\\times\\frac{1-\\sqrt{t}}{1-t}=\\frac{1}{2}\\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)\\times\\frac{1}{1+\\sqrt{t}}$"],"설명":"$1-t=\\left(1-\\sqrt{t}\\right)\\left(1+\\sqrt{t}\\right)$이므로 $1-\\sqrt{t}$가 약분된다. 0이 되는 인수가 사라져야 극한을 계산할 수 있다.","확인":null,"스킬":"D11","고비":true},{"제목":"극한값 계산","힌트":"$t\\to1-$일 때 $\\sqrt{\\frac{t+1}{t}}$와 $1+\\sqrt{t}$는 각각 어떤 값에 가까워지는가?","식":["$\\sqrt{\\frac{t+1}{t}}\\to\\sqrt{2},\\ 1+\\sqrt{t}\\to2$","$\\frac{1}{2}\\times\\left(\\sqrt{2}+\\sqrt{2}\\right)\\times\\frac{1}{2}=\\frac{\\sqrt{2}}{2}$"],"설명":"약분한 뒤에는 분모가 $0$으로 가지 않으므로 각 항에 $t=1$을 대입하는 것과 같다.","확인":null,"스킬":"D11"}]},"고2-202111-22":{"길":"분자·분모를 최고차항 $x^2$으로 나누어 $0$으로 가는 항을 지운다","단계":[{"제목":"분자·분모를 최고차항으로 나누기","힌트":"분자와 분모를 각각 $x^2$으로 나누면 어떤 식이 되는가?","식":["$\\frac{9+\\frac{1}{x^2}}{3+\\frac{5}{x}}$"],"설명":"$x\\to\\infty$일 때 분자·분모가 모두 한없이 커지므로, 분모의 최고차항 $x^2$으로 나눈다.","확인":null,"스킬":"A11","고비":true},{"제목":"0으로 가는 항 정리","힌트":"$x\\to\\infty$일 때 $\\frac{1}{x^2}$, $\\frac{5}{x}$는 어떤 값에 가까워지는가?","식":["$\\frac{1}{x^2}\\to0,\\ \\frac{5}{x}\\to0$","$\\lim_{x\\to\\infty}\\frac{9+\\frac{1}{x^2}}{3+\\frac{5}{x}}=\\frac{9+0}{3+0}=3$"],"설명":"분모가 $x$의 거듭제곱인 항은 $x$가 커질수록 $0$에 가까워진다.","확인":"3","스킬":"A11"}]},"고2-202111-28":{"길":"(나)의 $\\alpha\\ne1$ 조건으로 $f$의 인수 꼴을 정하고 계수를 맞춘다","단계":[{"제목":"두 조건이 주는 값","힌트":"(가), (나)에서 분모가 $0$으로 가는데 극한이 존재하려면 분자의 값은 어떠해야 하는가?","식":["$f(1)=0,\\ f'(1)=\\lim_{x\\to1}\\frac{f(x)}{x-1}=3$","$f(2)=0$"],"설명":"분모가 $0$으로 가면 분자도 $0$으로 가야 극한이 존재한다. (가)는 $f(1)=0$이므로 $\\frac{f(x)-f(1)}{x-1}$의 극한, 곧 미분계수 $f'(1)$이다. (나)는 분모 $(x-2)f'(x)\\to0$이므로 $f(2)=0$이다.","확인":null,"스킬":"D11"},{"제목":"f(x)의 꼴 세우기","힌트":"$f(1)=f(2)=0$인 삼차함수는 어떤 꼴로 놓는가?","식":["$f(x)=k(x-1)(x-2)(x-c)\\ (k\\ne0)$"],"설명":"삼차함수이고 $x=1$, $x=2$가 근이므로 나머지 한 근을 $c$로 둔다.","확인":null,"스킬":"A4"},{"제목":"c가 2가 아닐 때의 극한값","힌트":"$c\\ne2$이면 $\\lim_{x\\to2}\\frac{f(x)}{(x-2)f'(x)}$는 얼마인가?","식":["$\\frac{f(x)}{(x-2)f'(x)}=\\frac{k(x-1)(x-c)}{f'(x)}$","$f'(2)=k(2-1)(2-c)=k(2-c)\\ne0$이므로 극한은 $\\frac{k(2-c)}{k(2-c)}=1$"],"설명":"$f'(2)\\ne0$이므로 분모에도 $x-2$가 남지 않아 극한값은 $1$이다. 그러나 (나)에서 $\\alpha\\ne1$이므로 $c\\ne2$인 경우는 버리고, $c=2$이다.","확인":"1","스킬":"C2","고비":true},{"제목":"c=2일 때 α의 값","힌트":"$f(x)=k(x-1)(x-2)^2$일 때 $\\frac{f(x)}{(x-2)f'(x)}$를 약분하면 어떻게 되는가?","식":["$f'(x)=k\\{(x-2)^2+2(x-1)(x-2)\\}=k(x-2)(3x-4)$","$\\frac{f(x)}{(x-2)f'(x)}=\\frac{x-1}{3x-4}\\to\\frac{2-1}{6-4}=\\frac{1}{2}$"],"설명":"분자 $k(x-1)(x-2)^2$과 분모 $k(x-2)^2(3x-4)$에서 $(x-2)^2$을 약분한 뒤 $x=2$를 대입한다.","확인":"1/2","스킬":"D11"},{"제목":"k와 f(4)의 값","힌트":"$f'(1)=3$으로 $k$를 구하면 $f(4)$는 얼마인가?","식":["$f'(1)=k(1-2)(3-4)=k$이므로 $k=3$","$f(4)=3\\times(4-1)\\times(4-2)^2=36$"],"설명":"$f'(x)=k(x-2)(3x-4)$에 $x=1$을 넣어 $k$를 정하고, $f(x)=k(x-1)(x-2)^2$에 $x=4$를 넣는다.","확인":"36","스킬":"A3"},{"제목":"α와 f(4)의 곱","힌트":"$\\alpha\\times f(4)$의 값은 얼마인가?","식":["$\\alpha\\times f(4)=\\frac{1}{2}\\times36=18$"],"설명":"앞에서 구한 $\\alpha=\\frac{1}{2}$와 $f(4)=36$을 곱한다.","확인":"18","스킬":"D11"}]},"고2-202111-30":{"길":"경우별 $h(t)$를 구해 연속인 $k$의 집합이 $k\\ge24$ 꼴이 되는 경우를 찾는다","단계":[{"제목":"g(x)의 식 정리","힌트":"$f(x+a)$와 $|f(x)|$를 완전제곱 꼴로 쓰면 각 구간의 식은 어떻게 되는가?","식":["$f(x)=(x-a)^2-a^2+b$","$x\\le a$: $g(x)=x^2-a^2+b$,  $x>a$: $g(x)=\\left|(x-a)^2-a^2+b\\right|$"],"설명":"$x\\le a$에서는 꼭짓점이 $\\left(0,\\,-a^2+b\\right)$인 포물선이고 $g(a)=f(2a)=b$이다. $x>a$에서는 꼭짓점이 $\\left(a,\\,-a^2+b\\right)$인 포물선에 절댓값이 씌워진다.","확인":null,"스킬":"A6"},{"제목":"그래프의 경우 나누기","힌트":"$x>a$ 쪽이 출발하는 높이 $\\left|b-a^2\\right|$는 $x\\le a$ 쪽의 끝 높이 $b$와 비교해 어떤 경우로 나뉘는가?","식":["(i) $a^2-b\\le0$","(ii) $0<a^2-b<b$","(iii) $a^2-b=b$","(iv) $a^2-b>b$"],"설명":"오른쪽 가지의 출발 높이가 $0$, $b$와 어떤 순서인지에 따라 직선 $y=t$와 만나는 점의 수가 바뀌는 $t$의 값이 달라진다.","확인":null,"스킬":"G5"},{"제목":"h(t)=2가 되는 구간","힌트":"$t$가 충분히 클 때 $y=t$는 그래프와 몇 점에서 만나고, 그 구간은 경우마다 어디부터인가?","식":["(i), (ii), (iii): $t>b$에서 $h(t)=2$, 경계 $T=b$이고 $h(b)=3$","(iv): $t\\ge a^2-b$에서 $h(t)=2$, 경계 $T=a^2-b$이고 $h(T)=2$","$T$ 바로 왼쪽에서는 모든 경우에 $h(t)=3$ 또는 $4$"],"설명":"왼쪽 포물선과 오른쪽 가지에서 한 점씩 만나면 $h(t)=2$이다. 또 $t<-a^2+b$이면 만나지 않으므로 $h(t)=0$이다. (i)~(iii)은 $h(T)-2\\ne0$이고 (iv)는 $h(T)-2=0$이라는 차이가 생긴다.","확인":null,"스킬":"G1"},{"제목":"연속이 되는 조건 세우기","힌트":"$h(t)-2$가 $0$이 되는 구간과 $h(t-k)$가 $0$인 구간으로 곱이 연속이 될 조건을 어떻게 표현하는가?","식":["$t>T$에서 $h(t)-2=0$이므로 곱은 $0$","$T$ 왼쪽에서 $h(t)-2\\ne0$이므로 $h(t-k)=0$이어야 하고, 곧 $T-k\\le-a^2+b$"],"설명":"$t>T$에서 곱이 $0$이므로 $t=T$ 왼쪽에서도 곱이 $0$이어야 연속이다. $h(t-k)$는 $t-k<-a^2+b$일 때만 $0$이다. $h(T)-2\\ne0$인 경우는 $t=T$에서도 $h(T-k)=0$이어야 하므로 등호가 빠진다.","확인":null,"스킬":"D12","고비":true},{"제목":"경우별로 연속인 k의 범위","힌트":"(i)~(iv)에서 곱이 연속인 $k$의 범위는 각각 어떻게 되는가?","식":["(i), (ii): $k>a^2$,  (iii): $k>2b$","(iv): $k\\ge2\\left(a^2-b\\right)$"],"설명":"(i)~(iii)은 $h(T)-2\\ne0$이라 등호가 빠진 열린 범위가 되어, 연속인 $k$의 집합이 $k\\ge24$인 모든 실수가 될 수 없으므로 버린다. (iv)는 $h(T)-2=0$이라 등호가 들어가므로 $k\\ge2\\left(a^2-b\\right)$가 $k\\ge24$와 같아야 한다.","확인":null,"스킬":"C2"},{"제목":"a²−b의 값 구하기","힌트":"$2\\left(a^2-b\\right)=24$에서 $a^2-b$는 얼마인가?","식":["$2\\left(a^2-b\\right)=24$","$a^2-b=12$,  $b=a^2-12$"],"설명":"연속인 $k$의 범위가 $k\\ge24$이므로 경계값이 서로 같아야 한다.","확인":"12","스킬":"C5"},{"제목":"a와 b의 값 정하기","힌트":"$b>0$과 (iv)의 조건 $a^2-b>b$로 $a^2$의 범위를 구하면 $a$는 얼마인가?","식":["$b=a^2-12>0$에서 $a^2>12$","$a^2-b>b$에서 $12>a^2-12$이므로 $a^2<24$","$12<a^2<24$인 자연수 $a$는 $4$, $b=16-12=4$"],"설명":"$a$가 자연수이므로 $a^2=16$인 경우만 범위 안에 들어온다.","확인":"4","스킬":"C7"},{"제목":"10a+b의 값","힌트":"$10a+b$의 값은 얼마인가?","식":["$10a+b=10\\times4+4=44$"],"설명":"$a=4$, $b=4$를 대입한다.","확인":"44","스킬":"C7"}]},"고2-202209-05":{"길":"각 극한을 가까이 가는 쪽 그래프의 높이로 읽어 더한다","단계":[{"제목":"x→−1+ 극한 읽기","힌트":"$x$가 $-1$의 오른쪽에서 다가갈 때 곡선은 어느 높이로 다가가는가?","식":["$\\lim_{x\\to-1+}f(x)=2$"],"설명":"$-1$의 오른쪽 곡선은 속이 빈 점 $(-1,\\,2)$로 다가간다. 속이 찬 점 $(-1,\\,3)$은 $f(-1)$의 값일 뿐 극한과 상관없다.","확인":"2","스킬":"D12","고비":true},{"제목":"x→1− 극한 읽기","힌트":"$x$가 $1$의 왼쪽에서 다가갈 때 곡선은 어느 높이로 다가가는가?","식":["$\\lim_{x\\to1-}f(x)=1$"],"설명":"$1$의 왼쪽 곡선은 속이 빈 점 $(1,\\,1)$로 다가간다. 속이 찬 점 $(1,\\,2)$는 $f(1)$의 값일 뿐이다.","확인":"1","스킬":"D12"},{"제목":"두 극한의 합","힌트":"두 극한값의 합은 얼마인가?","식":["$2+1=3$"],"설명":"읽은 두 극한값을 더한다.","확인":"3","스킬":"D12"}]},"고2-202209-26":{"길":"구하는 식을 주어진 두 극한이 보이는 꼴의 곱으로 바꾼다","단계":[{"제목":"구하는 식을 곱으로 나누기","힌트":"$\\frac{(x+1)f(x)}{g(x)}$를 $\\frac{f(x)}{x-1}$과 $\\frac{x^2-1}{g(x)}$의 곱으로 어떻게 쓰는가?","식":["$\\frac{(x+1)f(x)}{g(x)}=\\frac{f(x)}{x-1}\\times\\frac{x^2-1}{g(x)}$"],"설명":"$x^2-1=(x-1)(x+1)$이므로 $x\\ne1$에서 $\\frac{x^2-1}{x-1}=x+1$이다. 곱해서 약분하면 원래 식과 같다.","확인":null,"스킬":"D3","고비":true},{"제목":"뒤 인수의 극한","힌트":"$\\lim_{x\\to1}\\frac{g(x)}{x^2-1}=\\frac{1}{2}$에서 $\\lim_{x\\to1}\\frac{x^2-1}{g(x)}$는 얼마인가?","식":["$\\lim_{x\\to1}\\frac{x^2-1}{g(x)}=\\frac{1}{\\frac{1}{2}}=2$"],"설명":"극한값이 $0$이 아니므로 역수의 극한은 극한값의 역수이다.","확인":"2","스킬":"D3"},{"제목":"곱의 극한","힌트":"앞 인수의 극한 $8$과 뒤 인수의 극한을 곱하면 얼마인가?","식":["$\\lim_{x\\to1}\\frac{(x+1)f(x)}{g(x)}=8\\times2=16$"],"설명":"두 극한이 모두 존재하므로 곱의 극한은 극한값의 곱이다.","확인":"16","스킬":"D3"}]},"고2-202209-29":{"길":"끊어지는 점이 겹침과 분모가 $0$인 점의 분자가 $0$임을 이용해 $m$, $a$를 정한다","단계":[{"제목":"f와 g가 끊어지는 점","힌트":"(가)에서 좌우극한이 다른 점은 $f$와 $g$에서 각각 어디인가?","식":["$f$: $\\alpha=2m$","$g$: $\\beta=m+1$"],"설명":"각 함수는 이차식·일차식의 경계에서만 끊어질 수 있다. $f$의 경계는 $x=2m$, $g$의 경계는 $x=m+1$이다.","확인":null,"스킬":"D12"},{"제목":"m의 값 정하기","힌트":"$x=2m$에서 $g$의 극한이 존재한다면 (가)의 $f$는 어떻게 되는가?","식":["$f(x)=\\frac{f(x)}{g(x)}\\times g(x)$","$2m=m+1$,  $m=1$"],"설명":"$x=2m$에서 $g$의 극한이 존재하면 (나)에 의해 $f$의 극한도 존재해 $f$가 끊어진다는 (가)와 어긋난다. 그래서 $g$도 $x=2m$에서 끊어져야 하고, $f$와 $g$가 끊어지는 점이 같다.","확인":"1","스킬":"C5","고비":true},{"제목":"a의 후보 구하기","힌트":"$m=1$일 때 $\\lim_{x\\to1}g(x)=0$이면 $f(1)$은 얼마여야 하는가?","식":["$\\lim_{x\\to1}g(x)=a-a=0$","$f(1)=-a^2+a+2=-(a+1)(a-2)=0$","$a=-1$ 또는 $a=2$"],"설명":"$m=1$이면 두 경계가 모두 $x=2$이므로 $x=1$에서는 두 함수 모두 첫째 식이다. 분모가 $0$으로 가는데 극한이 존재하므로 분자 $f(1)$도 $0$이다.","확인":null,"스킬":"D11"},{"제목":"a=−1인 경우 버리기","힌트":"$a=-1$일 때 $x=2$ 좌우에서 $\\frac{f(x)}{g(x)}$의 극한은 같은가?","식":["$\\lim_{x\\to2-}\\frac{x^2-2x+1}{-x+1}=-1$","$\\lim_{x\\to2+}\\frac{-3x-4}{x+2}=-\\frac{5}{2}$"],"설명":"좌우극한이 달라 (나)를 만족시키지 않으므로 $a=-1$은 버린다.","확인":null,"스킬":"C2"},{"제목":"a=2인 경우 확인","힌트":"$a=2$일 때 $x=2$ 좌우에서 $\\frac{f(x)}{g(x)}$의 극한은 얼마인가?","식":["$\\lim_{x\\to2-}\\frac{x^2+x-2}{2x-2}=2$","$\\lim_{x\\to2+}\\frac{-3x+8}{x-1}=2$"],"설명":"좌우극한이 같으므로 (나)를 만족시킨다. 따라서 $a=2$, $m=1$이다.","확인":"2","스킬":"C2"},{"제목":"g(a²)의 값","힌트":"$a^2=4$이므로 $g(4)$는 어느 식으로 계산하고 얼마인가?","식":["$4>m+1=2$이므로 $g(4)=4-a+1=3$"],"설명":"$x>m+1$ 구간의 식 $g(x)=x-a+1$에 $x=4$, $a=2$를 넣는다.","확인":"3","스킬":"A3"},{"제목":"m+g(a²)의 값","힌트":"$m+g\\left(a^2\\right)$은 얼마인가?","식":["$m+g\\left(a^2\\right)=1+3=4$"],"설명":"$m=1$과 $g(4)=3$을 더한다.","확인":"4","스킬":"A3"}]},"고2-202211-04":{"길":"$f(x)$를 위아래로 끼운 두 식의 극한이 같음을 이용한다","단계":[{"제목":"f(x)의 극한 정하기","힌트":"$x\\to0$일 때 $2x+1$과 $(x+1)^2$은 각각 어떤 값에 가까워지는가?","식":["$\\lim_{x\\to0}(2x+1)=\\lim_{x\\to0}(x+1)^2=1$","$\\lim_{x\\to0}f(x)=1$"],"설명":"$f(x)$가 두 식 사이에 끼어 있고 두 식의 극한이 같으므로 $f(x)$의 극한도 그 값이다.","확인":"1","스킬":"C9","고비":true},{"제목":"곱의 극한","힌트":"$\\lim_{x\\to0}(x+5)f(x)$는 얼마인가?","식":["$\\lim_{x\\to0}(x+5)f(x)=5\\times1=5$"],"설명":"두 인수의 극한이 각각 존재하므로 곱의 극한은 극한값의 곱이다.","확인":"5","스킬":"C9"}]},"고2-202211-06":{"길":"분자·분모를 $x^2$으로 나누어 $\\frac{f(x)}{x}$의 극한이 보이게 한다","단계":[{"제목":"x²으로 나누기","힌트":"분자·분모를 $x^2$으로 나누면 $\\{f(x)\\}^2$은 어떤 꼴이 되는가?","식":["$\\frac{2-\\frac{1}{x^2}}{\\left\\{\\frac{f(x)}{x}\\right\\}^2+3}$"],"설명":"$\\frac{\\{f(x)\\}^2}{x^2}=\\left\\{\\frac{f(x)}{x}\\right\\}^2$이므로 주어진 극한 $\\lim_{x\\to\\infty}\\frac{f(x)}{x}$를 쓸 수 있는 꼴이 된다.","확인":null,"스킬":"A11","고비":true},{"제목":"분모의 극한","힌트":"$\\frac{f(x)}{x}\\to3$일 때 분모는 어떤 값에 가까워지는가?","식":["$\\left\\{\\frac{f(x)}{x}\\right\\}^2+3\\to3^2+3=12$"],"설명":"분자의 $\\frac{1}{x^2}$은 $0$으로 가서 분자는 $2$에 가까워진다.","확인":"12","스킬":"A11"},{"제목":"극한값 구하기","힌트":"분자 $2$와 분모 $12$로 극한값은 얼마인가?","식":["$\\frac{2}{12}=\\frac{1}{6}$"],"설명":"분자와 분모의 극한이 모두 존재하고 분모의 극한이 $0$이 아니므로 비의 극한은 극한값의 비이다.","확인":"1/6","스킬":"A11"}]},"고2-202211-07":{"길":"$x\\to0-$와 $x\\to0+$의 극한을 그래프에서 따로 읽어 같다고 놓는다","단계":[{"제목":"x→0−에서의 극한","힌트":"$x$가 $0$의 왼쪽에서 다가갈 때 $f$와 $g$는 각각 어느 높이로 다가가는가?","식":["$\\lim_{x\\to0-}f(x)=2,\\ \\lim_{x\\to0-}g(x)=1$","$\\lim_{x\\to0-}\\{f(x)+kg(x)\\}=2+k$"],"설명":"$x<0$ 쪽에서 $f$는 속이 찬 점 $(0,\\,2)$에, $g$는 속이 찬 점 $(0,\\,1)$에 닿는다.","확인":null,"스킬":"D12"},{"제목":"x→0+에서의 극한","힌트":"$x$가 $0$의 오른쪽에서 다가갈 때 $f$와 $g$는 각각 어느 높이로 다가가는가?","식":["$\\lim_{x\\to0+}f(x)=-1,\\ \\lim_{x\\to0+}g(x)=3$","$\\lim_{x\\to0+}\\{f(x)+kg(x)\\}=-1+3k$"],"설명":"$x>0$ 쪽에서 $f$는 속이 빈 점 $(0,\\,-1)$로, $g$는 속이 빈 점 $(0,\\,3)$으로 다가간다.","확인":null,"스킬":"D12"},{"제목":"극한이 존재할 조건","힌트":"좌극한과 우극한이 같다고 놓으면 $k$는 얼마인가?","식":["$2+k=-1+3k$","$k=\\frac{3}{2}$"],"설명":"$x=0$에서 극한이 존재하려면 좌극한과 우극한이 같아야 한다.","확인":"3/2","스킬":"D12","고비":true}]},"고2-202211-09":{"길":"$x=1$을 대입해 $a$를 구한 뒤 $f(1)$을 극한으로 구한다","단계":[{"제목":"a의 값 구하기","힌트":"$(x-1)f(x)=\\sqrt{x^2+3}+a$에 $x=1$을 넣으면 어떻게 되는가?","식":["$0=\\sqrt{1+3}+a$","$a=-2$"],"설명":"$f(1)$이 존재하므로 $x=1$에서 좌변은 $0\\times f(1)=0$이다.","확인":"-2","스킬":"D12"},{"제목":"f(x)를 유리화로 정리","힌트":"$x\\ne1$에서 $f(x)$의 분자 $\\sqrt{x^2+3}-2$를 어떻게 정리하는가?","식":["$f(x)=\\frac{\\sqrt{x^2+3}-2}{x-1}=\\frac{x^2-1}{(x-1)\\left(\\sqrt{x^2+3}+2\\right)}=\\frac{x+1}{\\sqrt{x^2+3}+2}$"],"설명":"분자에 $\\sqrt{x^2+3}+2$를 곱하면 $x^2+3-4=x^2-1=(x-1)(x+1)$이 되어 $x-1$이 약분된다.","확인":null,"스킬":"D11","고비":true},{"제목":"f(1)의 값","힌트":"$f$가 $x=1$에서 연속이므로 $f(1)=\\lim_{x\\to1}f(x)$는 얼마인가?","식":["$f(1)=\\lim_{x\\to1}\\frac{x+1}{\\sqrt{x^2+3}+2}=\\frac{2}{4}=\\frac{1}{2}$"],"설명":"약분한 식에 $x=1$을 대입한다.","확인":"1/2","스킬":"D12"}]},"고2-202211-10":{"길":"평균변화율 조건으로 일차항의 계수를 구한 뒤 미분한다","단계":[{"제목":"평균변화율로 일차항 계수 구하기","힌트":"$f(x)=x^2+ax+b$에서 $\\frac{f(6)-f(0)}{6-0}=0$을 식으로 쓰면 $a$는 얼마인가?","식":["$f(x)=x^2+ax+b$","$\\frac{f(6)-f(0)}{6-0}=\\frac{36+6a}{6}=0$","$a=-6$"],"설명":"최고차항의 계수가 $1$이므로 $x^2+ax+b$로 놓는다. $f(6)-f(0)$에서 상수항 $b$가 사라진다.","확인":"-6","스킬":"D2","고비":true},{"제목":"f'(4)의 값","힌트":"$f'(x)$를 구하고 $x=4$를 넣으면 얼마인가?","식":["$f'(x)=2x-6$","$f'(4)=2\\times4-6=2$"],"설명":"$f(x)=x^2-6x+b$를 미분한다.","확인":"2","스킬":"D1"}]},"고2-202211-11":{"길":"두 극한식을 모두 $f'(1)$ 꼴로 바꾼다","단계":[{"제목":"첫째 극한으로 f'(1) 구하기","힌트":"$f(1+h)-f(1-h)$에 $f(1)$을 끼워 두 몫으로 나누면 $f'(1)$은 얼마인가?","식":["$\\frac{f(1+h)-f(1)}{h}+\\frac{f(1-h)-f(1)}{-h}\\to f'(1)+f'(1)$","$2f'(1)=6$,  $f'(1)=3$"],"설명":"$-h\\to0$이므로 둘째 몫도 $f'(1)$로 간다.","확인":"3","스킬":"D3","고비":true},{"제목":"둘째 극한을 미분계수 꼴로","힌트":"$x-1$을 $x^3-1$로 바꾸기 위해 어떤 인수를 곱하고 나누는가?","식":["$\\frac{f(x^3)-f(1)}{x-1}=\\frac{f(x^3)-f(1)}{x^3-1}\\times(x^2+x+1)$"],"설명":"$x^3-1=(x-1)\\left(x^2+x+1\\right)$이다. $x\\to1$일 때 $x^3\\to1$이므로 앞의 몫은 $f'(1)$로 간다.","확인":null,"스킬":"D1"},{"제목":"극한값 구하기","힌트":"$f'(1)$과 $x^2+x+1$의 극한을 곱하면 얼마인가?","식":["$f'(1)\\times(1+1+1)=3\\times3=9$"],"설명":"$x\\to1$일 때 $x^2+x+1\\to3$이다.","확인":"9","스킬":"D3"}]},"고2-202211-17":{"길":"분모가 $0$이어야 극한이 $-2$가 됨을 써서 $f(2)$를 정하고 미분계수 꼴로 바꾼다","단계":[{"제목":"g(2)와 g'(2) 식 세우기","힌트":"곱의 미분법으로 $g'(x)$를 구하고 $x=2$를 넣으면 어떻게 되는가?","식":["$g(2)=(4-4+2)f(2)=2f(2)$","$g'(x)=(2x-2)f(x)+\\left(x^2-2x+2\\right)f'(x)$","$g'(2)=2f(2)+2f'(2)$"],"설명":"$x=2$에서 $2x-2=2$, $x^2-2x+2=2$이다.","확인":null,"스킬":"D13"},{"제목":"f(2)의 값 정하기","힌트":"$2f(2)-1\\ne0$이면 $x\\to2$에서 $\\frac{g(x)-1}{2f(x)-1}$은 어떤 값에 가까워지는가?","식":["$2f(2)-1\\ne0$이면 $\\lim_{x\\to2}\\frac{g(x)-1}{2f(x)-1}=\\frac{2f(2)-1}{2f(2)-1}=1$","$1\\ne-2$이므로 $2f(2)-1=0$,  $f(2)=\\frac{1}{2}$"],"설명":"다항함수는 연속이므로 분모가 $0$이 아니면 $x=2$를 대입한 값이 극한이다. 극한이 $-2$이므로 그 경우는 버리고, 분모가 $0$이어야 한다. 이때 $g(2)=2f(2)=1$이다.","확인":"1/2","스킬":"C2","고비":true},{"제목":"극한을 미분계수 꼴로 바꾸기","힌트":"$g(2)=1$, $2f(2)=1$을 써서 극한을 $\\frac{g(x)-g(2)}{x-2}$ 꼴로 바꾸면 어떻게 되는가?","식":["$\\frac{g(x)-1}{2f(x)-1}=\\frac{g(x)-g(2)}{2\\{f(x)-f(2)\\}}=\\frac{\\frac{g(x)-g(2)}{x-2}}{2\\times\\frac{f(x)-f(2)}{x-2}}$","$\\frac{g'(2)}{2f'(2)}=-2$,  $g'(2)=-4f'(2)$"],"설명":"$f'(2)=0$이면 $g'(2)=2f(2)=1$이라 분자는 $1$, 분모는 $0$으로 가서 극한이 존재하지 않는다. 그러므로 $f'(2)\\ne0$이다.","확인":null,"스킬":"D3"},{"제목":"f'(2)의 값","힌트":"$g'(2)=1+2f'(2)$와 $g'(2)=-4f'(2)$를 연립하면 $f'(2)$는 얼마인가?","식":["$-4f'(2)=1+2f'(2)$","$f'(2)=-\\frac{1}{6}$"],"설명":"$g'(2)=2f(2)+2f'(2)$에서 $f(2)=\\frac{1}{2}$를 넣은 것이 $1+2f'(2)$이다.","확인":"-1/6","스킬":"D3"},{"제목":"g'(2)의 값","힌트":"$g'(2)=-4f'(2)$에 $f'(2)$를 넣으면 얼마인가?","식":["$g'(2)=-4\\times\\left(-\\frac{1}{6}\\right)=\\frac{2}{3}$"],"설명":"앞에서 구한 $f'(2)$를 대입한다.","확인":"2/3","스킬":"D3"}]},"고2-202211-19":{"길":"기울기 $m$이 커질 때 교점 수가 바뀌는 순간을 경우로 나누어 센다","단계":[{"제목":"교점과 고정점 찾기","힌트":"원과 $y=2|x|$가 만나는 점, 그리고 직선이 항상 지나는 점은 어디인가?","식":["$x^2+(2x)^2=5$에서 $x=\\pm1$이므로 $(-1,\\,2),\\ (1,\\,2)$","직선 $y=m(x+5)$는 $m$에 관계없이 $(-5,\\,0)$을 지난다"],"설명":"$y=2|x|$를 $x^2+y^2=5$에 대입하면 $5x^2=5$이다. 직선은 $x=-5$일 때 $y=0$이다.","확인":null,"스킬":"G3"},{"제목":"점 (1, 2)를 지나는 기울기","힌트":"점 $(-5,\\,0)$에서 점 $(1,\\,2)$를 지나는 직선의 기울기는 얼마인가?","식":["$m=\\frac{2-0}{1-(-5)}=\\frac{1}{3}$"],"설명":"이때 직선이 원과 $y=2|x|$의 교점을 지나므로 두 도형과의 교점 중 하나가 겹친다.","확인":"1/3","스킬":"G3"},{"제목":"원에 접하는 기울기","힌트":"원 위의 점 $(-1,\\,2)$에서의 접선은 점 $(-5,\\,0)$을 지나는가?","식":["접선: $-x+2y=5$, 곧 $y=\\frac{1}{2}(x+5)$","점 $(-5,\\,0)$을 지나므로 $m=\\frac{1}{2}$에서 접한다"],"설명":"원 $x^2+y^2=5$ 위의 점 $(x_1,\\,y_1)$에서의 접선은 $x_1x+y_1y=5$이다. 접점 $(-1,\\,2)$는 $y=2|x|$ 위의 점이기도 하다.","확인":"1/2","스킬":"G2"},{"제목":"겹침까지 생각해 교점 수 세기","힌트":"$0<m<\\frac{1}{3}$에서는 몇 개이고, $m=\\frac{1}{3}$에서는 겹치는 점을 한 번만 세면 몇 개인가?","식":["$0<m<\\frac{1}{3}$: 원과 $2$개, $y=2|x|$와 $2$개이므로 $4$","$m=\\frac{1}{3}$: $2+2-1=3$","$\\frac{1}{3}<m<\\frac{1}{2}$: $4$,  $m=\\frac{1}{2}$: $1+2-1=2$"],"설명":"$m<\\frac{1}{2}$에서 직선은 원과 두 점에서 만나고, $x>-5$에서 $y>0$이므로 모두 반원 위의 점이다. $y=2|x|$와는 두 가지에서 한 점씩 만난다. $m=\\frac{1}{2}$에서는 접점 $(-1,\\,2)$가 $y=2|x|$와의 교점과 겹친다.","확인":"3","스킬":"C2","고비":true},{"제목":"기울기가 큰 구간의 교점 수","힌트":"$m>\\frac{1}{2}$이면 원과 만나지 않는데, $m=2$일 때 $y=2|x|$와는 몇 점에서 만나는가?","식":["$\\frac{1}{2}<m<2$: $0+2=2$","$m=2$: $y=2x$와 평행해 $y=-2x$와만 만나므로 $1$","$m>2$: $1$"],"설명":"$m\\ge2$이면 직선이 오른쪽 가지 $y=2x\\ (x\\ge0)$와 만나지 못하고, 왼쪽 가지 $y=-2x$와는 항상 만난다.","확인":"1","스킬":"C2"},{"제목":"불연속인 m의 합","힌트":"$f(m)$의 값이 바뀌는 $m$을 모두 더하면 얼마인가?","식":["$f(m)=4,\\ 3,\\ 4,\\ 2,\\ 1$이 $m=\\frac{1}{3},\\ \\frac{1}{2},\\ 2$에서 바뀐다","$\\frac{1}{3}+\\frac{1}{2}+2=\\frac{17}{6}$"],"설명":"$m=\\frac{1}{3}$에서 $4\\to3\\to4$, $m=\\frac{1}{2}$에서 $4\\to2$, $m=2$에서 $2\\to1$로 바뀌어 이 세 점에서만 불연속이다.","확인":"17/6","스킬":"C2"}]},"고2-202211-22":{"길":"$f'(x)$를 구하고 $x=2$를 대입한다","단계":[{"제목":"도함수 구하기","힌트":"$x^3-5x+8$의 각 항을 미분하면 어떻게 되는가?","식":["$f'(x)=3x^2-5$"],"설명":"$x^n$의 도함수는 $nx^{n-1}$이고 상수항의 도함수는 $0$이다.","확인":null,"스킬":"D1","고비":true},{"제목":"f'(2)의 값","힌트":"$f'(x)$에 $x=2$를 넣으면 얼마인가?","식":["$f'(2)=3\\times2^2-5=7$"],"설명":"도함수에 $x=2$를 대입한다.","확인":"7","스킬":"D1"}]},"고2-202211-27":{"길":"분모가 $0$으로 가는 극한에서 두 함수가 $x+3$을 인수로 가짐을 찾고 계수를 맞춘다","단계":[{"제목":"x=−3에서의 두 함수 값","힌트":"두 극한에서 분모가 $0$으로 가므로 $f(-3)g(-3)$과 $f(-3)+g(-3)$은 얼마인가?","식":["$f(-3)g(-3)=0$","$f(-3)+g(-3)=0$","$f(-3)=g(-3)=0$"],"설명":"분모가 $0$으로 가는데 극한이 존재하므로 분자도 $0$으로 간다. 곱과 합이 모두 $0$인 두 수는 모두 $0$이다.","확인":null,"스킬":"D11"},{"제목":"f와 g의 꼴 세우기","힌트":"$f$는 일차함수, $g$는 최고차항의 계수가 $1$인 이차함수이고 모두 $x=-3$을 근으로 가질 때 어떤 꼴인가?","식":["$f(x)=a(x+3)$","$g(x)=(x+3)(x+c)$"],"설명":"$f(-3)=g(-3)=0$이므로 두 함수 모두 $x+3$을 인수로 가진다.","확인":null,"스킬":"A4"},{"제목":"두 극한을 a와 c의 식으로","힌트":"$x+3$을 약분하면 두 극한은 각각 $a$, $c$의 어떤 식이 되는가?","식":["$\\lim_{x\\to-3}\\frac{f(x)g(x)}{(x+3)^2}=\\lim_{x\\to-3}a(x+c)=a(c-3)=4$","$\\lim_{x\\to-3}\\frac{f(x)+g(x)}{x+3}=\\lim_{x\\to-3}(a+x+c)=a+c-3=-4$"],"설명":"첫째는 분자 $a(x+3)^2(x+c)$를 $(x+3)^2$으로, 둘째는 분자 $a(x+3)+(x+3)(x+c)$를 $x+3$으로 약분한다.","확인":null,"스킬":"D11"},{"제목":"a와 c 구하기","힌트":"둘째 식으로 $c$를 $a$로 나타내 첫째 식에 넣으면 $a$는 얼마인가?","식":["$c=-1-a$","$a(-4-a)=4$,  $(a+2)^2=0$","$a=-2,\\ c=1$"],"설명":"완전제곱식이 $0$이 되므로 $a$가 하나로 정해진다.","확인":"-2","스킬":"A6","고비":true},{"제목":"g(2)−f(2)의 값","힌트":"$f(2)$와 $g(2)$를 구해 빼면 얼마인가?","식":["$f(2)=-2\\times5=-10,\\ g(2)=5\\times3=15$","$g(2)-f(2)=15-(-10)=25$"],"설명":"$f(x)=-2(x+3)$, $g(x)=(x+3)(x+1)$에 $x=2$를 넣는다.","확인":"25","스킬":"A3"}]},"고2-202211-29":{"길":"꺾이는 점의 위치로 경우를 나누고 각 점에서 미분가능 조건을 세운다","단계":[{"제목":"a의 크기로 경우 나누기","힌트":"$|2x-a|$는 어느 점에서 꺾이고, 그 점이 $x=5$의 오른쪽에 있는지에 따라 어떻게 나뉘는가?","식":["$|2x-a|$는 $x=\\frac{a}{2}$에서 꺾인다","(i) $\\frac{a}{2}\\le5$, 곧 $a\\le10$","(ii) $\\frac{a}{2}>5$, 곧 $a\\ge11$"],"설명":"$a\\le10$이면 $x\\ge5$에서 $2x-a\\ge0$이라 절댓값이 그대로 풀린다. $a\\ge11$이면 $x\\ge5$ 안의 $x=\\frac{a}{2}$에서 꺾인다. $g(x)=(x-5)(x-b)$는 다항함수라 어디서나 미분가능하다.","확인":null,"스킬":"C2"},{"제목":"(i) x=5에서 좌우 미분계수","힌트":"$f(5)g(5)=0$이므로 $x=5$에서 왼쪽·오른쪽 미분계수는 각각 어떻게 되는가?","식":["$x\\to5-$: $\\lim\\frac{(x+5)(x-5)(x-b)}{x-5}=10(5-b)$","$x\\to5+$: $\\lim\\frac{(2x-a)(x-5)(x-b)}{x-5}=(10-a)(5-b)$","$10(5-b)=(10-a)(5-b)$이므로 $a(5-b)=0$"],"설명":"$a$는 자연수이므로 $a\\ne0$이고 $b=5$이다.","확인":null,"스킬":"D12"},{"제목":"(i)의 순서쌍 개수","힌트":"$b=5$이고 $a=1,\\ 2,\\ \\dots,\\ 10$일 때 순서쌍 $(a,\\,b)$는 몇 개인가?","식":["$(a,\\,b)=(1,\\,5),\\ (2,\\,5),\\ \\dots,\\ (10,\\,5)$"],"설명":"$a=10$도 $a\\le10$에 들어가고, $x=5$ 말고는 꺾이는 점이 없어 조건이 더 없다.","확인":"10","스킬":"C2"},{"제목":"(ii) x=5에서의 조건","힌트":"$a\\ge11$이면 $5\\le x<\\frac{a}{2}$에서 $f(x)=-2x+a$이다. 오른쪽 미분계수와 조건은 어떻게 되는가?","식":["$x\\to5+$: $\\lim(-2x+a)(x-b)=(a-10)(5-b)$","$10(5-b)=(a-10)(5-b)$이므로 $(a-20)(5-b)=0$","$a=20$ 또는 $b=5$"],"설명":"왼쪽 미분계수는 (i)과 같이 $10(5-b)$이다.","확인":null,"스킬":"D12"},{"제목":"(ii) x=a/2에서의 조건","힌트":"$x=\\frac{a}{2}$에서 $f$가 꺾이므로 $f\\cdot g$가 미분가능하려면 두 미분계수는 어떻게 되는가?","식":["$x\\to\\frac{a}{2}-$: $\\lim\\{-2(x-5)(x-b)\\}=(10-a)\\left(\\frac{a}{2}-b\\right)$","$x\\to\\frac{a}{2}+$: $\\lim\\{2(x-5)(x-b)\\}=(a-10)\\left(\\frac{a}{2}-b\\right)$","$(a-10)(a-2b)=0$이므로 $a=2b$"],"설명":"$f\\left(\\frac{a}{2}\\right)=0$이므로 곱의 미분계수는 $\\frac{f(x)g(x)}{x-\\frac{a}{2}}$의 극한이다. $a\\ge11$이라 $a\\ne10$이고, 따라서 $a=2b$이다.","확인":null,"스킬":"D12","고비":true},{"제목":"(ii)의 순서쌍 개수","힌트":"$a=20$ 또는 $b=5$와 $a=2b$를 모두 만족하는 $(a,\\,b)$는 몇 개인가?","식":["$b=5$이면 $a=10$이라 $a\\ge11$에 어긋나 버린다","$a=20$이면 $b=10$이므로 $(a,\\,b)=(20,\\,10)$"],"설명":"두 조건을 함께 풀면 하나만 남는다.","확인":"1","스킬":"C2"},{"제목":"전체 순서쌍의 개수","힌트":"(i)과 (ii)의 개수를 더하면 얼마인가?","식":["$10+1=11$"],"설명":"$a\\le10$과 $a\\ge11$은 겹치지 않으므로 더한다.","확인":"11","스킬":"C2"}]},"고2-202309-05":{"길":"각 극한을 가까이 가는 쪽 그래프의 높이로 읽어 더한다","단계":[{"제목":"x→1− 극한 읽기","힌트":"$x$가 $1$의 왼쪽에서 다가갈 때 곡선은 어느 높이로 다가가는가?","식":["$\\lim_{x\\to1-}f(x)=2$"],"설명":"$1$의 왼쪽 곡선은 속이 찬 점 $(1,\\,2)$에 닿는다. 속이 빈 점 $(1,\\,1)$은 오른쪽 선분의 끝이다.","확인":"2","스킬":"D12","고비":true},{"제목":"x→3+ 극한 읽기","힌트":"$x$가 $3$의 오른쪽에서 다가갈 때 그래프는 어느 높이로 다가가는가?","식":["$\\lim_{x\\to3+}f(x)=3$"],"설명":"$3$의 오른쪽 직선은 속이 빈 점 $(3,\\,3)$으로 다가간다. 속이 찬 점 $(3,\\,1)$은 $f(3)$의 값일 뿐 극한과 상관없다.","확인":"3","스킬":"D12"},{"제목":"두 극한의 합","힌트":"두 극한값의 합은 얼마인가?","식":["$2+3=5$"],"설명":"읽은 두 극한값을 더한다.","확인":"5","스킬":"D12"}]},"고2-202309-20":{"길":"$x=3$에서의 극한과 $x$축과 한 점에서 만나는 조건으로 $k$의 범위를 정한 뒤 보기를 판정한다","단계":[{"제목":"ㄱ 판정: k의 값","힌트":"$f(1)=1$에서 $k$는 얼마이고, 그때 $g(2)$는 어느 식으로 계산하는가?","식":["$f(1)=(1-k)^2=1$, $k>0$이므로 $k=2$","$2\\le3$이므로 $g(2)=f(2)=(2-2)^2=0$"],"설명":"$x\\le3$에서 $g(x)=f(x)$이다. $g(2)=0$이므로 ㄱ은 참이다.","확인":"2","스킬":"C3"},{"제목":"(가), (나)를 식으로 쓰기","힌트":"(가) $x=3$의 좌우극한과 (나) $x$축과의 교점은 각각 어떻게 식이 되는가?","식":["(가) $\\lim_{x\\to3-}g(x)=(3-k)^2,\\ \\lim_{x\\to3+}g(x)=k(3-a-k)^2$이므로 $(3-k)^2=k(3-a-k)^2$","(나) $f$는 $x=k$에서, $kf(x-a)$는 $x=k+a$에서 $x$축에 닿는다"],"설명":"$g$는 $x\\le3$에서 $f(x)$, $x>3$에서 $kf(x-a)$이다. 두 포물선의 꼭짓점은 각각 $(k,\\,0)$, $(k+a,\\,0)$이다.","확인":null,"스킬":"G1"},{"제목":"k가 3 이상인 경우 버리기","힌트":"$k=3$과 $k>3$일 때 (가)의 등식이 성립하는가?","식":["$k=3$: 좌극한 $0$, 우극한 $3a^2>0$","$k>3$: $k(k+a-3)^2>k(k-3)^2>(3-k)^2$"],"설명":"$k=3$이면 좌우극한이 달라 (가)에 어긋난다. $k>3$이면 $k+a-3>k-3>0$이고 $k>1$이라 (가)의 양변이 같을 수 없다. 따라서 $k<3$이다.","확인":null,"스킬":"C2"},{"제목":"k<3에서 k+a의 위치로 나누기","힌트":"$k<3$일 때 $k+a$가 $3$보다 큰 경우, 같은 경우, 작은 경우를 각각 (가), (나)로 따지면 어떻게 되는가?","식":["$k+a>3$: $x=k$, $x=k+a$ 두 점에서 $x$축과 만나 (나)에 어긋남","$k+a=3$: 좌극한 $(3-k)^2>0$, 우극한 $0$이라 (가)에 어긋남","$k+a<3$: $x>3$에서 $g>0$이라 $x=k$에서만 $x$축과 만나 가능"],"설명":"$k+a>3$이면 $x\\le3$ 쪽의 $x=k$와 $x>3$ 쪽의 $x=k+a$가 모두 $x$축 위의 점이다. $k+a<3$이면 $x>3$ 쪽의 $kf(x-a)$는 $x=3$ 이후 양수이다. 그러므로 $k<k+a<3$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"k의 범위 정하기","힌트":"$k<k+a<3$일 때 (가)의 등식에서 $k$와 $1$의 크기는 어떠한가?","식":["$k=\\frac{(3-k)^2}{(3-k-a)^2}$","$0<3-k-a<3-k$이므로 분수는 $1$보다 크다","$1<k<3$"],"설명":"분모의 밑이 분자의 밑보다 작은 양수이므로 비가 $1$보다 크고, 이것이 $k$이다.","확인":null,"스킬":"C2"},{"제목":"ㄴ 판정","힌트":"$k<k+a<3$이면 $g(k+a)$와 $g(3)$ 중 어느 쪽이 큰가?","식":["$g(k+a)=f(k+a),\\ g(3)=f(3)$","$x>k$에서 $f$는 증가하므로 $f(k+a)<f(3)$"],"설명":"$k+a\\le3$이므로 두 값 모두 $f$의 값이다. $k<k+a<3$에서 $f$는 $x=k$ 오른쪽에서 증가한다. 따라서 ㄴ은 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판정: 반례 찾기","힌트":"$k=\\frac{3}{2}$일 때 조건을 만족하는 $a$가 있고, 그때 $(k-1)(k-2)$는 얼마인가?","식":["$\\frac{9}{4}=\\frac{3}{2}\\left(\\frac{3}{2}-a\\right)^2$,  $a=\\frac{3-\\sqrt{6}}{2}$","$0<a<\\frac{3}{2}$이므로 $k<k+a<3$을 만족한다","$(k-1)(k-2)=\\frac{1}{2}\\times\\left(-\\frac{1}{2}\\right)=-\\frac{1}{4}<0$"],"설명":"$1<k<3$ 안의 $k=\\frac{3}{2}$에 맞는 $a$가 존재하므로 조건을 모두 만족하는 경우이다. 이때 $(k-1)(k-2)<0$이므로 ㄷ은 거짓이다.","확인":"-1/4","스킬":"C3"},{"제목":"옳은 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 무엇인가?","식":["ㄱ 참, ㄴ 참, ㄷ 거짓"],"설명":"옳은 것은 ㄱ, ㄴ이다.","확인":null,"스킬":"C3"}]},"고2-202309-26":{"길":"첫째 극한으로 $g-f$의 최고차항을, 둘째 극한으로 인수 $x-3$을 정한다","단계":[{"제목":"g−f의 최고차항 계수","힌트":"$\\lim_{x\\to\\infty}\\frac{f(x)}{g(x)-x^2}=1$이면 $f$와 $g(x)-x^2$의 최고차항 계수는 어떤 관계인가?","식":["$f$, $g$의 $x^2$의 계수를 $a$, $b$라 하면 $\\frac{a}{b-1}=1$","$b-a=1$"],"설명":"극한이 $0$이 아닌 값이므로 분자 $f$와 분모 $g(x)-x^2$은 모두 이차식이다. 두 최고차항 계수가 같으므로 $g-f$의 $x^2$ 계수 $b-a$가 $1$이다.","확인":null,"스킬":"A11","고비":true},{"제목":"g−f의 인수 정하기","힌트":"$x\\to3$에서 분모가 $0$으로 가는데 극한이 존재하면 $g(3)-f(3)$은 얼마인가?","식":["$g(3)-f(3)=0$","$g(x)-f(x)=(x-3)(x+k)$"],"설명":"$g-f$는 최고차항의 계수가 $1$인 이차식이고 $x=3$에서 $0$이므로 $x-3$을 인수로 가진다.","확인":null,"스킬":"D11"},{"제목":"k의 값","힌트":"$\\lim_{x\\to3}\\frac{(x-3)(x+k)}{x-3}=8$에서 $k$는 얼마인가?","식":["$\\lim_{x\\to3}(x+k)=3+k=8$","$k=5$"],"설명":"$x-3$을 약분한 뒤 $x=3$을 대입한다.","확인":"5","스킬":"D11"},{"제목":"g(5)−f(5)의 값","힌트":"$g(x)-f(x)=(x-3)(x+5)$에 $x=5$를 넣으면 얼마인가?","식":["$g(5)-f(5)=(5-3)(5+5)=20$"],"설명":"구한 식에 $x=5$를 대입한다.","확인":"20","스킬":"A11"}]},"고2-202309-30":{"길":"$g(t)$가 바뀌는 $t$를 $b$, $b^2$, $b^2-a^2$로 놓고 세 조건에 맞는 경우를 찾는다","단계":[{"제목":"그래프 모양과 만나는 점의 수","힌트":"$x\\le0$ 부분과 $x>0$ 부분은 직선 $y=t$와 각각 몇 점에서 만나는가?","식":["$x\\to0-$: $\\lim f=b$,  $x\\to0+$: $\\lim f=b^2$,  $x>0$: $f(x)=(x-a)^2+b^2-a^2$","$x\\le0$ 부분: $0<t\\le b$이면 $2$개, $t>b$이면 $1$개","$x>0$ 부분: $t<b^2-a^2$이면 $0$개, $t=b^2-a^2$이면 $1$개, $b^2-a^2<t<b^2$이면 $2$개, $t\\ge b^2$이면 $1$개"],"설명":"$x\\le0$ 부분은 $x=0$에서 높이 $b$이고 $x$축에서 꺾이는 곡선이다. $x>0$ 부분은 꼭짓점 $\\left(a,\\,b^2-a^2\\right)$인 포물선이며, $0<a<b$이므로 $0<b^2-a^2<b^2$이다. $t=b^2$일 때 왼쪽 끝 $x=0$은 $x>0$이 아니라 빠진다.","확인":null,"스킬":"G1"},{"제목":"세 값의 순서로 경우 나누기","힌트":"$g(t)$가 바뀌는 $t=b^2-a^2,\\ b,\\ b^2$에서 $b$의 위치에 따라 어떤 경우로 나뉘는가?","식":["(i) $b<b^2-a^2$","(ii) $b=b^2-a^2$","(iii) $b^2-a^2<b<b^2$","(iv) $b=b^2$, 곧 $b=1$","(v) $b^2<b$, 곧 $0<b<1$"],"설명":"$b^2-a^2<b^2$은 늘 성립하므로 $b$가 이 두 값 사이·바깥·같은 자리인지로 나눈다.","확인":null,"스킬":"C2"},{"제목":"(i), (ii) 버리기","힌트":"(i)에서 $g$의 최솟값, (ii)에서 $g$가 바뀌는 폭은 어떠한가?","식":["(i): $b<t<b^2-a^2$에서 $g(t)=1$","(ii): $g$는 $2\\to3\\to2$로 $t=b$, $t=b^2$에서 각각 $1$씩만 바뀐다"],"설명":"(i)은 최솟값이 $2$라는 조건에 어긋난다. (ii)는 $\\left|\\lim_{t\\to\\alpha-}g(t)-\\lim_{t\\to\\alpha+}g(t)\\right|=2$인 $\\alpha$가 없어 (가)에 어긋난다.","확인":null,"스킬":"C2"},{"제목":"(iv), (v) 버리기","힌트":"(iv)에서는 (다), (v)에서는 (나)를 만족하는가?","식":["(iv) $b=1$: $\\beta=1$이고 $g(1)=3$, $\\alpha=1$ 또는 $1-a^2$에서도 $g(\\alpha)=3$이므로 (다)에 어긋남","(v) $0<b<1$: $\\lim_{t\\to\\beta-}g-\\lim_{t\\to\\beta+}g+1=g(\\beta)$인 $\\beta$가 없어 (나)에 어긋남"],"설명":"(iv)는 $g$가 $2,\\,3,\\,4,\\,3,\\,2$ 순으로 바뀌고, (v)는 $g$가 바뀌는 세 곳 $b^2-a^2$, $b^2$, $b$ 어디에서도 $\\lim_{t\\to\\beta-}g-\\lim_{t\\to\\beta+}g+1=g(\\beta)$가 되지 않는다. 남는 경우는 (iii)이다.","확인":null,"스킬":"C2"},{"제목":"(iii)에서 α와 β 읽기","힌트":"(iii)에서 $g(t)$가 바뀌는 곳과 조건 (가), (나)를 만족하는 $\\alpha$, $\\beta$는 각각 무엇인가?","식":["$g(t)=2\\ (t<b^2-a^2),\\ 4\\ (b^2-a^2<t\\le b),\\ 3\\ (b<t<b^2),\\ 2\\ (t\\ge b^2)$","(가): $|2-4|=2$이므로 $\\alpha=b^2-a^2$","(나): $\\beta=b^2$에서 $3-2+1=2=g\\left(b^2\\right)$"],"설명":"$g(\\alpha)=3$, $g(\\beta)=2$이므로 (다)도 만족한다. $t=b$에서는 $4-3+1=2$이지만 $g(b)=4$라 (나)를 만족하지 않는다.","확인":null,"스킬":"D12","고비":true},{"제목":"a의 값","힌트":"$f\\left(\\frac{1}{2}\\right)=\\alpha=f(a)$에서 $a$는 얼마인가?","식":["$f(a)=b^2-a^2=\\alpha$이고 $f\\left(\\frac{1}{2}\\right)=\\frac{1}{4}-a+b^2=\\alpha$","$\\frac{1}{4}-a=-a^2$,  $\\left(a-\\frac{1}{2}\\right)^2=0$,  $a=\\frac{1}{2}$"],"설명":"$x>0$에서 $f(x)=x^2-2ax+b^2$이므로 $f\\left(\\frac{1}{2}\\right)=\\frac{1}{4}-a+b^2$이다.","확인":"1/2","스킬":"A6"},{"제목":"b의 값","힌트":"$\\alpha=b^2-\\frac{1}{4}$, $\\beta=b^2$을 $\\alpha+24\\beta=30$에 넣으면 $b$는 얼마인가?","식":["$25b^2-\\frac{1}{4}=30$,  $b^2=\\frac{121}{100}$","$b>1$이므로 $b=\\frac{11}{10}$"],"설명":"(iii)은 $b<b^2$, 곧 $b>1$인 경우이므로 $b$는 양수 $\\frac{11}{10}$이다.","확인":"11/10","스킬":"A3"},{"제목":"p+q의 값","힌트":"$f(-2)+f(1)$을 기약분수로 쓰면 $p+q$는 얼마인가?","식":["$f(-2)=\\left|-\\frac{1}{2}\\times4+\\frac{11}{10}\\right|=\\frac{9}{10}$,  $f(1)=1-1+\\frac{121}{100}=\\frac{121}{100}$","$f(-2)+f(1)=\\frac{211}{100}$,  $p+q=100+211=311$"],"설명":"$x\\le0$에서 $f(x)=\\left|-\\frac{1}{2}x^2+\\frac{11}{10}\\right|$, $x>0$에서 $f(x)=x^2-x+\\frac{121}{100}$이다. $211$과 $100$은 서로소이다.","확인":"311","스킬":"A3"}]},"고2-202311-04":{"길":"각 극한을 가까이 가는 쪽 그래프의 높이로 읽어 더한다","단계":[{"제목":"x→0− 극한 읽기","힌트":"$x$가 $0$의 왼쪽에서 다가갈 때 곡선은 어느 높이로 다가가는가?","식":["$\\lim_{x\\to0-}f(x)=4$"],"설명":"$0$의 왼쪽 선분은 속이 빈 점 $(0,\\,4)$로 다가간다. 속이 찬 점 $(0,\\,2)$는 $f(0)$의 값일 뿐이다.","확인":"4","스킬":"D12","고비":true},{"제목":"x→2+ 극한 읽기","힌트":"$x$가 $2$의 오른쪽에서 다가갈 때 그래프는 어느 높이로 다가가는가?","식":["$\\lim_{x\\to2+}f(x)=2$"],"설명":"$2$의 오른쪽에는 높이 $2$인 수평선이 있다. 속이 찬 점 $(2,\\,0)$은 $f(2)$의 값일 뿐 극한과 상관없다.","확인":"2","스킬":"D12"},{"제목":"두 극한의 합","힌트":"두 극한값의 합은 얼마인가?","식":["$4+2=6$"],"설명":"읽은 두 극한값을 더한다.","확인":"6","스킬":"D12"}]},"고2-202311-06":{"길":"$x=1$에서 연속인 조건과 좌우 미분계수가 같은 조건으로 $a$, $b$를 구한다","단계":[{"제목":"연속 조건","힌트":"$x=1$에서 연속이려면 두 식의 $x=1$에서의 값은 어떻게 되는가?","식":["$\\lim_{x\\to1-}f(x)=a+b+1,\\ f(1)=-3b-1$","$a+b+1=-3b-1$,  곧 $a+4b=-2$"],"설명":"미분가능하면 연속이므로 두 식이 $x=1$에서 같은 값을 가져야 한다.","확인":null,"스킬":"D12"},{"제목":"미분계수 조건","힌트":"두 식의 $x=1$에서의 미분계수를 각각 구해 같다고 놓으면 어떻게 되는가?","식":["$x<1$: $f'(x)=2ax+b$이므로 $f'(1)=2a+b$","$x\\ge1$: $f'(x)=-3b$","$2a+b=-3b$,  곧 $a=-2b$"],"설명":"$x=1$에서 연속이므로 각 식의 도함수에 $x=1$을 넣은 값이 좌우 미분계수이다. 미분가능하면 둘이 같다.","확인":null,"스킬":"D12","고비":true},{"제목":"a, b 구하기","힌트":"$a+4b=-2$에 $a=-2b$를 넣으면 $b$는 얼마인가?","식":["$-2b+4b=-2$,  $b=-1$","$a=-2b=2$"],"설명":"연립방정식을 대입으로 푼다.","확인":"-1","스킬":"A10"},{"제목":"a+b의 값","힌트":"$a+b$는 얼마인가?","식":["$a+b=2+(-1)=1$"],"설명":"구한 $a$, $b$를 더한다.","확인":"1","스킬":"A10"}]},"고2-202311-07":{"길":"적분으로 $f(x)$를 구하고 도함수의 부호가 바뀌는 점에서 극솟값을 읽는다","단계":[{"제목":"f(x) 구하기","힌트":"$f'(x)=3x^2-6x$를 적분하고 $f(1)=1$로 적분상수를 구하면 어떻게 되는가?","식":["$f(x)=x^3-3x^2+C$","$f(1)=1-3+C=1$,  $C=3$"],"설명":"$f'(x)$의 부정적분에 적분상수 $C$가 붙는다.","확인":"3","스킬":"D4"},{"제목":"극소가 되는 x","힌트":"$f'(x)=3x(x-2)$의 부호는 $x=0$, $x=2$의 앞뒤에서 어떻게 바뀌는가?","식":["$x<0$: $+$,  $0<x<2$: $-$,  $x>2$: $+$"],"설명":"$x=0$에서는 $+$에서 $-$로 바뀌어 극대이고, $x=2$에서는 $-$에서 $+$로 바뀌어 극소이다.","확인":"2","스킬":"D4","고비":true},{"제목":"극솟값 구하기","힌트":"$f(x)=x^3-3x^2+3$에 극소가 되는 $x$를 넣으면 얼마인가?","식":["$f(2)=8-12+3=-1$"],"설명":"극솟값은 극소가 되는 점에서의 함숫값이다.","확인":"-1","스킬":"D4"}]},"고2-202311-10":{"길":"정적분이 상수임을 이용해 $c$로 놓고 식을 세운다","단계":[{"제목":"정적분을 상수로 놓기","힌트":"$\\int_0^2f(t)\\,dt$는 $x$에 따라 변하는가?","식":["$\\int_0^2f(t)\\,dt=c$ (상수)","$f(x)=x+c$"],"설명":"적분 구간의 끝이 모두 상수이므로 정적분은 $x$와 상관없는 수이다.","확인":null,"스킬":"D9","고비":true},{"제목":"c의 값 구하기","힌트":"$f(t)=t+c$를 $0$에서 $2$까지 적분한 값이 $c$와 같다고 놓으면 $c$는 얼마인가?","식":["$c=\\int_0^2(t+c)\\,dt=\\left[\\frac{1}{2}t^2+ct\\right]_0^2=2+2c$","$c=-2$"],"설명":"정적분의 정의에서 $c$가 나오므로 $c=\\int_0^2f(t)\\,dt$를 $c$에 대한 방정식으로 푼다.","확인":"-2","스킬":"D9"},{"제목":"f(3)의 값","힌트":"$f(x)=x-2$에 $x=3$을 넣으면 얼마인가?","식":["$f(3)=3-2=1$"],"설명":"$c=-2$를 $f(x)=x+c$에 넣는다.","확인":"1","스킬":"D9"}]},"고2-202311-12":{"길":"곱의 미분법에서 $x^2-2x$가 $0$이 되는 점을 이용한다","단계":[{"제목":"g'(x) 구하기","힌트":"$g(x)=\\left(x^2-2x\\right)f(x)$를 곱의 미분법으로 미분하면 어떻게 되는가?","식":["$g'(x)=(2x-2)f(x)+\\left(x^2-2x\\right)f'(x)$"],"설명":"다항함수 $f$는 미분가능하므로 $f'(x)$를 그대로 쓴다.","확인":null,"스킬":"D13"},{"제목":"g'(0)과 g'(2)","힌트":"$x=0$, $x=2$에서 $x^2-2x$의 값은 얼마이고 그때 $g'$은 어떻게 되는가?","식":["$g'(0)=-2f(0)$","$g'(2)=2f(2)$"],"설명":"$x^2-2x=x(x-2)$는 $x=0$, $x=2$에서 $0$이라 $f'$가 들어간 항이 사라진다.","확인":null,"스킬":"D13","고비":true},{"제목":"f(2)−f(0)의 값","힌트":"$g'(0)+g'(2)=16$을 식으로 쓰면 $f(2)-f(0)$은 얼마인가?","식":["$g'(0)+g'(2)=2\\{f(2)-f(0)\\}=16$","$f(2)-f(0)=8$"],"설명":"$-2f(0)+2f(2)$를 $2$로 묶는다.","확인":"8","스킬":"D13"}]},"고2-202311-16":{"길":"두 교점의 $x$좌표를 $t$로 나타내 거리 $f(t)$를 식으로 쓴다","단계":[{"제목":"두 교점의 x좌표","힌트":"$\\left|\\frac{2}{x}-3\\right|=t$에서 $x$좌표는 어떻게 나타나는가?","식":["$x<0$이면 $\\left|\\frac{2}{x}-3\\right|=-\\frac{2}{x}+3>3>t$이므로 만나지 않는다","$\\frac{2}{x}-3=t$에서 $x=\\frac{2}{3+t}$","$\\frac{2}{x}-3=-t$에서 $x=\\frac{2}{3-t}$"],"설명":"$0<t<3$이므로 두 해 모두 양수이다. 그래프는 $x=\\frac{2}{3}$에서 $x$축에 닿고, 그 양쪽에서 직선과 한 점씩 만난다.","확인":null,"스킬":"G1","고비":true},{"제목":"f(t)를 식으로 정리","힌트":"두 교점 사이의 거리 $f(t)$를 통분해 정리하면 어떻게 되는가?","식":["$f(t)=\\frac{2}{3-t}-\\frac{2}{3+t}=\\frac{4t}{(3-t)(3+t)}$"],"설명":"$3-t<3+t$이므로 $\\frac{2}{3-t}$가 큰 쪽이다. 큰 $x$좌표에서 작은 $x$좌표를 뺀다.","확인":null,"스킬":"A11"},{"제목":"극한값 구하기","힌트":"$\\frac{f(t)}{t}$를 약분한 뒤 $t\\to0+$로 보내면 얼마인가?","식":["$\\frac{f(t)}{t}=\\frac{4}{(3-t)(3+t)}\\to\\frac{4}{3\\times3}=\\frac{4}{9}$"],"설명":"분자의 $t$를 약분하면 분모가 $0$으로 가지 않으므로 $t=0$을 대입한다.","확인":"4/9","스킬":"A11"}]},"고2-202311-19":{"길":"극댓값과 극솟값 사이에 $3n$이 드는지로 $a_n$을 정하고 합이 $7$인 경우를 찾는다","단계":[{"제목":"극값 구하기","힌트":"$f'(x)=0$인 $x$에서 극댓값과 극솟값은 각각 얼마인가?","식":["$f'(x)=3(x-1)(x-3)$","극댓값 $f(1)=k+4$,  극솟값 $f(3)=k$"],"설명":"$x=1$에서 $f'$이 $+$에서 $-$로, $x=3$에서 $-$에서 $+$로 바뀐다.","확인":null,"스킬":"D6"},{"제목":"a_n의 값 정하기","힌트":"직선 $y=3n$이 극솟값 $k$, 극댓값 $k+4$와 어떤 위치일 때 교점이 $1$, $2$, $3$개인가?","식":["$k<3n<k+4$: $a_n=3$","$3n=k$ 또는 $3n=k+4$: $a_n=2$","그 밖: $a_n=1$"],"설명":"직선이 극값 사이에 있으면 세 점에서, 극값의 높이에 있으면 접하는 곳을 포함해 두 점에서 만난다.","확인":null,"스킬":"D6"},{"제목":"합이 7이 되는 구성","힌트":"$a_n$이 $1,\\ 2,\\ 3$ 중 하나일 때 네 수의 합이 $7$이 되려면 $a_n=2$인 $n$은 몇 개인가?","식":["$3+2+1+1=7$","$a_n=3$이 $1$개, $a_n=2$가 $1$개, $a_n=1$이 $2$개"],"설명":"$k=3m$과 $k+4=3l$을 동시에 만족하는 정수 $m$, $l$은 없으므로 $a_n=2$인 $n$은 많아야 $1$개이다. $a_n\\ge1$이라 $3+3+1+0$은 안 되고, $a_n=2$가 없으면 합이 $6$이나 $8$이 되어 $7$이 안 된다.","확인":"1","스킬":"C2","고비":true},{"제목":"k가 3의 배수인 경우","힌트":"$k=3,\\ 6,\\ 9,\\ 12$일 때 $a_1,\\ a_2,\\ a_3,\\ a_4$와 합은 각각 어떻게 되는가?","식":["$k=3$: $(2,3,1,1)$,  $k=6$: $(1,2,3,1)$,  $k=9$: $(1,1,2,3)$  합 $7$","$k=12$: $(1,1,1,2)$  합 $5$"],"설명":"$k=12$이면 $12<3n<16$인 $n\\le4$가 없어 $3$이 나오지 않으므로 버린다. 따라서 $k=3,\\ 6,\\ 9$이고 합은 $18$이다.","확인":"18","스킬":"C2"},{"제목":"k+4가 3의 배수인 경우","힌트":"$k+4=3,\\ 6,\\ 9,\\ 12$일 때 $a_1,\\ a_2,\\ a_3,\\ a_4$와 합은 각각 어떻게 되는가?","식":["$k=2$: $(3,2,1,1)$,  $k=5$: $(1,3,2,1)$,  $k=8$: $(1,1,3,2)$  합 $7$","$k=-1$: $(2,1,1,1)$  합 $5$"],"설명":"$k+4=3$이면 $-1<3n<3$인 자연수 $n$이 없어 $3$이 나오지 않으므로 버린다. 따라서 $k=2,\\ 5,\\ 8$이고 합은 $15$이다.","확인":"15","스킬":"C2"},{"제목":"모든 k의 합","힌트":"두 경우의 $k$를 모두 더하면 얼마인가?","식":["$(3+6+9)+(2+5+8)=18+15=33$"],"설명":"두 경우의 $k$는 겹치지 않으므로 합을 더한다.","확인":"33","스킬":"C2"}]},"고2-202311-20":{"길":"접선 기울기와 원점을 지나는 직선 기울기가 같을 조건을 $k$의 이차방정식으로 보고 보기를 따진다","단계":[{"제목":"ㄱ 판정","힌트":"$f(x)$를 전개해 미분하면 $f'(0)$은 얼마인가?","식":["$f(x)=x^3-11x^2+24x+36$","$f'(x)=3x^2-22x+24$,  $f'(0)=24$"],"설명":"$(x+1)(x-6)^2=(x+1)\\left(x^2-12x+36\\right)$를 전개한다. ㄱ은 참이다.","확인":null,"스킬":"D1"},{"제목":"ㄴ 판정: t=6일 때","힌트":"$t=6$일 때 직선의 기울기는 얼마이고, $f'(k)$가 그 값이 되는 양의 $k$는 무엇인가?","식":["$\\frac{f(6)}{6}=0$","$f'(k)=(3k-4)(k-6)=0$,  $k=\\frac{4}{3}$ 또는 $6$","작은 값이 $\\frac{4}{3}$이므로 $g(6)=\\frac{4}{3}$"],"설명":"$f(6)=7\\times0=0$이다. 양의 실수 $k$가 $2$개이므로 작은 값이 $g(6)$이고 ㄴ은 참이다.","확인":"0","스킬":"D1"},{"제목":"기울기 s(t)의 범위","힌트":"$s(t)=\\frac{f(t)}{t}$의 최솟값과, $s(t)=24$가 되는 $t$는 무엇인가?","식":["$s(t)=\\frac{(t+1)(t-6)^2}{t}\\ge0$이고 $t=6$에서 최솟값 $0$","$s(t)=24$: $t^3-11t^2+36=0$,  $(t-2)(t^2-9t-18)=0$","$t=2$ 또는 $t=\\alpha=\\frac{9+3\\sqrt{17}}{2}$"],"설명":"$t\\to0+$, $t\\to\\infty$에서 $s(t)\\to\\infty$이므로 $0<t\\le2$ 또는 $t\\ge\\alpha$에서 $s(t)\\ge24$이고, $2<t<\\alpha$에서 $0\\le s(t)<24$이다.","확인":null,"스킬":"D1"},{"제목":"s=24일 때의 k와 근의 개수","힌트":"$f'(k)=s$의 양의 근은 $s$의 크기에 따라 몇 개인가?","식":["$f'(k)=24$: $3k\\left(k-\\frac{22}{3}\\right)=0$, 양의 근 $k=\\frac{22}{3}$","$s\\ge24$: 두 근의 곱 $\\frac{24-s}{3}\\le0$이라 양의 근 $1$개, 값은 $\\frac{22}{3}$ 이상","$0\\le s<24$: 곱과 합이 모두 양수라 양의 근 $2$개"],"설명":"$3k^2-22k+24-s=0$의 두 근의 합은 $\\frac{22}{3}$이다. $s=0$이면 두 근은 $\\frac{4}{3}$, $6$이고, $s$가 $24$까지 커지면 작은 근은 $0$으로, 큰 근은 $\\frac{22}{3}$로 간다.","확인":"22/3","스킬":"D1","고비":true},{"제목":"치역과 자연수의 합","힌트":"$g(t)$의 치역에 들어가지 않는 자연수는 어떤 수들인가?","식":["$s\\ge24$인 $t$에서 $g(t)$는 $\\frac{22}{3}$ 이상의 모든 값","$0\\le s<24$인 $t$에서 작은 근 $g(t)$는 $0<g(t)\\le\\frac{4}{3}$의 모든 값","치역은 $\\left(0,\\,\\frac{4}{3}\\right]\\cup\\left[\\frac{22}{3},\\,\\infty\\right)$이므로 빠진 자연수는 $2,\\ 3,\\ 4,\\ 5,\\ 6,\\ 7$"],"설명":"$s(t)$가 연속이라 구간마다 $s$가 구간 전체를 지나므로 근도 구간 전체를 지난다. $1\\le\\frac{4}{3}$이라 $1$은 치역에 있고, $7<\\frac{22}{3}<8$이다. 합은 $2+3+4+5+6+7=27$이므로 ㄷ은 참이다.","확인":"27","스킬":"C3"},{"제목":"옳은 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 무엇인가?","식":["ㄱ 참, ㄴ 참, ㄷ 참"],"설명":"옳은 것은 ㄱ, ㄴ, ㄷ이다.","확인":null,"스킬":"C3"}]},"고2-202311-22":{"길":"분모를 유리화해 $x-3$을 약분한다","단계":[{"제목":"분모의 유리화","힌트":"분자와 분모에 $\\sqrt{x+1}+2$를 곱하면 분모는 어떻게 되는가?","식":["$\\frac{(x-3)\\left(\\sqrt{x+1}+2\\right)}{\\left(\\sqrt{x+1}-2\\right)\\left(\\sqrt{x+1}+2\\right)}=\\frac{(x-3)\\left(\\sqrt{x+1}+2\\right)}{x-3}$"],"설명":"$\\left(\\sqrt{x+1}\\right)^2-2^2=x+1-4=x-3$이므로 분모에 분자와 같은 $x-3$이 생긴다.","확인":null,"스킬":"D11","고비":true},{"제목":"극한값 구하기","힌트":"$x-3$을 약분한 뒤 $x\\to3$으로 보내면 얼마인가?","식":["$\\lim_{x\\to3}\\left(\\sqrt{x+1}+2\\right)=2+2=4$"],"설명":"약분하면 분모가 $0$으로 가지 않으므로 $x=3$을 대입한다.","확인":"4","스킬":"D11"}]},"고2-202311-24":{"길":"$\\int_1^xf'(t)\\,dt=f(x)-f(1)$로 보아 미분계수의 정의 꼴로 만든다","단계":[{"제목":"정적분 계산","힌트":"$f'$의 한 부정적분이 $f$일 때 $\\int_1^xf'(t)\\,dt$는 어떻게 쓰는가?","식":["$\\int_1^xf'(t)\\,dt=f(x)-f(1)$"],"설명":"정적분은 부정적분의 위끝 값에서 아래끝 값을 뺀 것이다.","확인":null,"스킬":"D9","고비":true},{"제목":"미분계수 구하기","힌트":"$\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}$은 무엇의 정의이고 값은 얼마인가?","식":["$\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}=f'(1)$","$f'(x)=3x^2+4x$,  $f'(1)=7$"],"설명":"$x=1$에서의 미분계수 정의 꼴이다. $f(x)=x^3+2x^2+2$를 미분해 $x=1$을 넣는다.","확인":"7","스킬":"D3"}]},"고2-202311-26":{"길":"속도가 $0$이 되며 부호가 바뀌는 시각으로 방향이 바뀌는 때를 찾는다","단계":[{"제목":"두 점의 속도","힌트":"위치를 미분해 두 점의 속도 $v_1$, $v_2$를 구하면 어떻게 되는가?","식":["$v_1(t)=3t^2-6t-24$","$v_2(t)=2t-a$"],"설명":"속도는 위치를 시각 $t$로 미분한 것이다.","확인":null,"스킬":"D10"},{"제목":"점 P의 방향이 바뀌는 시각","힌트":"$t>0$에서 $v_1(t)=0$이 되고 그 앞뒤에서 부호가 바뀌는 $t$는 언제인가?","식":["$v_1(t)=3(t+2)(t-4)$","$0<t<4$: $v_1<0$,  $t>4$: $v_1>0$"],"설명":"$t>0$에서 $v_1=0$인 때는 $t=4$뿐이고, 그 앞뒤에서 부호가 바뀌므로 $k=4$이다.","확인":"4","스킬":"D10","고비":true},{"제목":"a의 값","힌트":"점 Q도 $t=4$에서 방향이 바뀌려면 $v_2(4)$는 얼마여야 하는가?","식":["$v_2(4)=8-a=0$","$a=8$"],"설명":"$v_2(t)=2t-a$는 일차식이라 $0$이 되는 시각의 앞뒤에서 부호가 바뀐다.","확인":"8","스킬":"D10"},{"제목":"a+k의 값","힌트":"$a+k$는 얼마인가?","식":["$a+k=8+4=12$"],"설명":"구한 $a$와 $k$를 더한다.","확인":"12","스킬":"D10"}]},"고2-202311-28":{"길":"(가)로 차수 후보를, (나)로 $x$의 최저 차수를 정해 $f$, $g$의 꼴을 세운다","단계":[{"제목":"(가)에서 차수 후보","힌트":"$\\lim_{x\\to\\infty}\\frac{\\{f(x)\\}^2g(x)}{x^5}$이 $0$이 아닌 값이려면 분자의 차수는 얼마인가?","식":["$f$, $g$의 차수를 $p$, $q$라 하면 $2p+q=5$","$(p,\\,q)=(0,\\,5),\\ (1,\\,3),\\ (2,\\,1)$"],"설명":"분자와 분모의 차수가 같아야 극한이 $0$이 아닌 값이다. $p$, $q$는 $0$ 이상의 정수이다.","확인":null,"스킬":"A11"},{"제목":"(나)에서 x의 최저 차수","힌트":"$x\\to0$에서 $\\frac{f(x)\\{g(x)\\}^2}{x^5}$이 $0$이 아닌 값이면 $f\\{g\\}^2$에서 $x$의 최저 차수는 얼마인가?","식":["$f(x)\\{g(x)\\}^2=x^5h(x)\\ (h(0)\\ne0)$"],"설명":"최저 차수가 $5$보다 작으면 극한이 존재하지 않고, $5$보다 크면 극한이 $0$이다. 극한이 $0$이 아니므로 최저 차수는 정확히 $5$이다.","확인":null,"스킬":"A11"},{"제목":"차수 후보 거르기","힌트":"$f$의 최저 차수를 $r$, $g$의 최저 차수를 $s$라 하면 $r+2s=5$를 만족하는 후보는 무엇인가?","식":["$(0,\\,5)$: $f$는 $x$를 인수로 갖지 않아 $r=0$, $2s=5$가 안 된다","$(2,\\,1)$: $f\\{g\\}^2$의 차수가 $4<5$라 안 된다","$(1,\\,3)$: $f(x)=ax$, $g(x)=x^2(bx+c)$"],"설명":"$g$는 제곱되어 $x$의 짝수 거듭제곱이 되므로 $r$이 홀수여야 한다. $(1,\\,3)$에서는 $r=1$, $s=2$이다. $a$, $b$, $c$는 음이 아닌 정수이고 $a\\ne0$, $b\\ne0$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"두 조건을 a, b, c의 식으로","힌트":"$f(x)=ax$, $g(x)=x^2(bx+c)$를 (가), (나)에 넣어 극한을 구하면 어떻게 되는가?","식":["(가): $\\lim_{x\\to\\infty}\\frac{a^2x^4(bx+c)}{x^5}=a^2b=4$","(나): $\\lim_{x\\to0}\\frac{ax\\cdot x^4(bx+c)^2}{x^5}=ac^2=2$"],"설명":"(가)는 최고차항의 계수끼리, (나)는 $x^5$을 약분한 뒤 $x=0$을 대입한 값이다.","확인":null,"스킬":"D11"},{"제목":"a, b, c 구하기","힌트":"$ac^2=2$를 만족하는 음이 아닌 정수 $a$, $c$와 $a^2b=4$의 $b$는 무엇인가?","식":["$ac^2=2$에서 $c=1,\\ a=2$","$a^2b=4$에서 $b=1$"],"설명":"$c=0$이면 $ac^2=0\\ne2$이고, $c\\ge2$이면 $c^2\\ge4>2$라 $a$가 정수가 될 수 없다. 따라서 $c=1$이다.","확인":null,"스킬":"A3"},{"제목":"g(2)의 값","힌트":"$f(x)=2x$, $g(x)=x^2(x+1)$에서 $g(2)$는 얼마인가?","식":["$g(2)=2^2\\times(2+1)=12$"],"설명":"$x=2$를 $g(x)=x^2(x+1)$에 넣는다.","확인":"12","스킬":"A3"},{"제목":"f(2)+g(2)의 값","힌트":"$f(2)+g(2)$는 얼마인가?","식":["$f(2)+g(2)=4+12=16$"],"설명":"$f(2)=2\\times2=4$이다.","확인":"16","스킬":"A3"}]},"고2-202311-30":{"길":"(가)로 $F(2)$와 $f$의 두 근을 정하고 (나)를 $F$의 극솟값이 $0$인 조건으로 바꾼다","단계":[{"제목":"F(2)의 값","힌트":"$F(x)=\\int_0^xf(t)\\,dt$라 할 때 $\\lim_{x\\to2-}\\frac{g(x)-4}{x-2}$가 존재하려면 $F(2)$는 얼마인가?","식":["$x<2$에서 $g(x)=F(x)-4$","$\\lim_{x\\to2-}\\{g(x)-4\\}=F(2)-8=0$","$F(2)=8$"],"설명":"분모가 $0$으로 가는데 극한이 존재하므로 분자도 $0$으로 간다.","확인":"8","스킬":"D9"},{"제목":"f(0)과 f(2)의 값","힌트":"(가)의 세 값을 $f$로 쓰면 어떤 관계가 되는가?","식":["$\\lim_{x\\to2-}\\frac{g(x)-4}{x-2}=F'(2)=f(2)$","$\\lim_{x\\to2+}\\frac{g(x)+4}{x-2}=\\lim_{x\\to2+}\\frac{-\\{F(x)-8\\}}{x-2}=-f(2)$","$g'(0)=F'(0)=f(0)$","$f(2)=-f(2)=f(0)$이므로 $f(0)=f(2)=0$"],"설명":"$F(2)=8$이므로 $x\\ge2$에서 $g(x)+4=-F(x)+8=-\\{F(x)-8\\}$이다. $x<2$에서 $g$는 $F-4$이므로 $g'(0)=f(0)$이다.","확인":null,"스킬":"D12"},{"제목":"f(x)의 꼴 세우기","힌트":"$f(0)=f(2)=0$인 삼차함수를 어떻게 놓고, $f'(2)<0$에서 $b$의 범위는 어떻게 되는가?","식":["$f(x)=ax(x-2)(x-b)\\ (a>0)$","$f'(2)=2a(2-b)<0$이므로 $b>2$"],"설명":"최고차항의 계수가 양수이므로 $a>0$이다.","확인":null,"스킬":"A4"},{"제목":"(나)를 F의 조건으로 바꾸기","힌트":"$g(x)=4$를 $x<2$와 $x\\ge2$로 나누어 $F$로 쓰면 $x<2$에서 근은 몇 개인가?","식":["$x<2$: $F(x)=8$,  $x\\ge2$: $-F(x)+4=4$, 곧 $F(x)=0$","$F'(x)=f(x)$이므로 $F$는 $x<0$에서 감소, $0<x<2$에서 증가, $2<x<b$에서 감소, $x>b$에서 증가","$F(0)=0,\\ F(2)=8$"],"설명":"$x<2$에서 $F(x)=8$의 근은 $x<0$에서만 $1$개이다. 서로 다른 두 실근이어야 하므로 $x\\ge2$에서 $F(x)=0$의 근이 $1$개여야 한다. $F$는 $x=b$에서 극솟값을 가지므로 $F(b)=0$이다.","확인":"1","스킬":"D6","고비":true},{"제목":"b의 값","힌트":"$F(b)=0$을 적분으로 계산하면 $b$는 얼마인가?","식":["$F(b)=a\\left[\\frac{t^4}{4}-\\frac{(b+2)t^3}{3}+bt^2\\right]_0^b=\\frac{ab^3(4-b)}{12}=0$","$b=4$"],"설명":"$a>0$, $b>2$이므로 $4-b=0$이다.","확인":"4","스킬":"D9"},{"제목":"a의 값","힌트":"$F(2)=8$에서 $a$는 얼마인가?","식":["$F(2)=a\\int_0^2t(t-2)(t-4)\\,dt=a\\left[\\frac{t^4}{4}-2t^3+4t^2\\right]_0^2=4a$","$4a=8$,  $a=2$"],"설명":"$b=4$를 넣은 $f(t)=at(t-2)(t-4)$를 $0$에서 $2$까지 적분한다.","확인":"2","스킬":"D9"},{"제목":"f(5)의 값","힌트":"$f(x)=2x(x-2)(x-4)$에 $x=5$를 넣으면 얼마인가?","식":["$f(5)=2\\times5\\times3\\times1=30$"],"설명":"구한 $a$, $b$를 넣은 식에 $x=5$를 대입한다.","확인":"30","스킬":"D9"}]},"고2-202409-05":{"길":"각 극한을 가까이 가는 쪽 그래프의 높이로 읽어 더한다","단계":[{"제목":"x→−1 극한 읽기","힌트":"$x$가 $-1$의 왼쪽과 오른쪽에서 다가갈 때 곡선은 각각 어느 높이로 다가가는가?","식":["$\\lim_{x\\to-1-}f(x)=-1,\\ \\lim_{x\\to-1+}f(x)=-1$","$\\lim_{x\\to-1}f(x)=-1$"],"설명":"양쪽 곡선이 모두 속이 빈 점 $(-1,\\,-1)$로 다가가므로 극한이 있다. 속이 찬 점 $(-1,\\,0)$은 $f(-1)$의 값일 뿐이다.","확인":"-1","스킬":"D12","고비":true},{"제목":"x→1− 극한 읽기","힌트":"$x$가 $1$의 왼쪽에서 다가갈 때 선분은 어느 높이로 다가가는가?","식":["$\\lim_{x\\to1-}f(x)=2$"],"설명":"$1$의 왼쪽 선분은 속이 빈 점 $(1,\\,2)$로 다가간다. 속이 찬 점 $(1,\\,-1)$은 $f(1)$의 값일 뿐이다.","확인":"2","스킬":"D12"},{"제목":"두 극한의 합","힌트":"두 극한값의 합은 얼마인가?","식":["$-1+2=1$"],"설명":"읽은 두 극한값을 더한다.","확인":"1","스킬":"D12"}]},"고2-202409-21":{"길":"$g(t)$ 가 바뀌는 두 점을 $k,\\ 2k,\\ 16$ 에 맞춰 가능한 $(a,\\ b)$ 를 모두 찾는다","단계":[{"제목":"$g(t)$ 의 값이 바뀌는 점","힌트":"$t>0$ 일 때 $x\\le0$ 쪽과 $x>0$ 쪽의 근의 개수는 각각 $t$ 가 어디를 지날 때 바뀌는가?","식":["$x\\le0$: $0<2^{x+a}\\le2^a$ 이므로 $t\\le2^a$ 일 때만 근 1개","$x>0$: $b>0$ 이면 $t>b^2$ 일 때 근 1개, $b<0$ 이면 $t<b^2$ 일 때 근 2개이고 $t\\ge b^2$ 일 때 근 1개","$g(t)$ 가 바뀌는 점은 $t=2^a$ 와 $t=b^2$"],"설명":"$x\\le0$ 쪽은 $t=2^a$ 에서 근이 1개에서 0개로 줄고, $x>0$ 쪽은 $b>0$ 이면 $t=b^2$ 에서 0개에서 1개로, $b<0$ 이면 2개에서 1개로 바뀐다. $b=0$ 이면 $x>0$ 쪽 근은 늘 1개라 바뀌는 점이 없다.","확인":null,"스킬":"G1"},{"제목":"$2^a,\\ b^2$ 의 조건과 $(a,\\ b)$ 후보","힌트":"바뀌는 점 두 곳이 $k,\\ 2k$ 이고 $t=16$ 도 바뀌는 점이어야 한다면 $2^a$ 와 $b^2$ 이 될 수 있는 값은?","식":["$\\{2^a,\\ b^2\\}=\\{k,\\ 2k\\}$, 그리고 $2^a=16$ 또는 $b^2=16$","$2^a=16$ 이면 $b^2=8$ 또는 $32$, $b^2=16$ 이면 $2^a=8$ 또는 $32$","$(a,\\ b)$ 후보: $(4,\\ \\pm2\\sqrt2),\\ (4,\\ \\pm4\\sqrt2),\\ (3,\\ \\pm4),\\ (5,\\ \\pm4)$"],"설명":"바뀌는 점이 $k$, $2k$ 두 곳이므로 $2^a\\ne b^2$ 이고 한 쪽이 다른 쪽의 2배이다. $t=16$ 에서 좌우 극한이 같으면 곱이 제곱수라 $2$ 가 될 수 없으므로 $16$ 도 바뀌는 점이다. $2^a=b^2=16$ 은 바뀌는 점이 한 곳뿐이라 조건을 만족시키지 못하므로 버린다.","확인":"8","스킬":"C2"},{"제목":"후보별 $t=16$ 의 좌·우극한 곱","힌트":"$t=16$ 의 바로 왼쪽과 오른쪽에서 근의 개수를 더해 곱을 구하면 곱이 $2$ 인 후보는 몇 쌍인가?","식":["$a=4$ ($t=16$ 에서 $x\\le0$ 쪽 근이 사라짐): $b=\\pm2\\sqrt2$ 이면 $2\\times1=2$, $b=-4\\sqrt2$ 이면 $3\\times2=6$, $b=4\\sqrt2$ 이면 $1\\times0=0$","$a=3$ ($t>8$ 에서 $x\\le0$ 쪽 근이 이미 없음): $b=-4$ 이면 $2\\times1=2$, $b=4$ 이면 $0\\times1=0$","$a=5$ ($t<32$ 라 $x\\le0$ 쪽 근 1개 유지): $b=-4$ 이면 $3\\times2=6$, $b=4$ 이면 $1\\times2=2$"],"설명":"곱이 $6$ 또는 $0$ 인 후보는 $2$ 가 되지 않으므로 버린다. 곱이 $2$ 인 $(a,\\ b)$ 는 $(4,\\ -2\\sqrt2),\\ (4,\\ 2\\sqrt2),\\ (3,\\ -4),\\ (5,\\ 4)$ 의 4쌍이다.","확인":"4","스킬":"C2","고비":true},{"제목":"$a+b$ 의 최댓값과 최솟값의 곱","힌트":"4쌍의 $a+b$ 중 가장 큰 값과 가장 작은 값을 곱하면?","식":["$a+b=4-2\\sqrt2,\\ 4+2\\sqrt2,\\ -1,\\ 9$","$9\\times(-1)=-9$"],"설명":"$4\\pm2\\sqrt2$ 는 약 $1.2$ 와 $6.8$ 이라 $-1$ 보다 크고 $9$ 보다 작다. 최댓값은 $9$, 최솟값은 $-1$ 이다.","확인":"-9","스킬":"C2"}]},"고2-202409-28":{"길":"(가)로 $f(x)=px^2+qx$ 꼴을 얻고 (나)에서 극한이 존재해야 하는 점으로 $p$ 를 정한다","단계":[{"제목":"$x\\to0$ 의 좌·우극한 정리","힌트":"$x<0$ 일 때 $\\sqrt{x^2}$ 를 풀어 왼쪽 극한을 구하면 오른쪽 극한은?","식":["$x<0$ 이면 $\\sqrt{x^2}=-x$ 이므로 $\\dfrac{-x-f(x)}{x+f(x)}=-1$, 왼쪽 극한은 $-1$","$-1\\times(\\text{오른쪽 극한})=-2$ 에서 $\\displaystyle\\lim_{x\\to0+}\\frac{x-f(x)}{x+f(x)}=2$"],"설명":"$x<0$ 에서는 분자가 분모의 $-1$ 배이므로 $f$ 의 모양과 관계없이 왼쪽 극한은 $-1$ 이다. $x>0$ 에서는 $\\sqrt{x^2}=x$ 이다.","확인":"2","스킬":"D11"},{"제목":"$f(0)$ 의 값","힌트":"$f(x)=px^2+qx+r$ 로 두고 오른쪽 극한을 구할 때 $r\\ne0$ 이면 극한은 얼마가 되는가?","식":["$f(x)=px^2+qx+r\\ (p>0)$ 이라 하면 $r\\ne0$ 일 때 $\\displaystyle\\lim_{x\\to0+}\\frac{x-f(x)}{x+f(x)}=\\frac{0-r}{0+r}=-1$","극한이 $2$ 여야 하므로 $r=0$"],"설명":"$r\\ne0$ 이면 $x=0$ 을 그대로 넣을 수 있고 극한이 $-1$ 이 되어 $2$ 와 다르다. 따라서 $r=0$ 이고 $f(x)=px^2+qx$ 이다.","확인":"0","스킬":"A11"},{"제목":"$q$ 의 값","힌트":"$r=0$ 으로 두고 분모·분자를 $x$ 로 약분한 뒤 $x\\to0+$ 로 보내면 $q$ 는?","식":["$\\dfrac{x-px^2-qx}{x+px^2+qx}=\\dfrac{(1-q)-px}{(1+q)+px}$","$x\\to0+$ 이면 $\\dfrac{1-q}{1+q}=2$, $1-q=2+2q$","$q=-\\dfrac13$"],"설명":"$q=-1$ 이면 분모가 $px^2$ 이 되어 극한이 발산하므로 $q\\ne-1$ 이어야 하고, 구한 값은 이를 만족시킨다.","확인":"-1/3","스킬":"D11"},{"제목":"분모가 $0$ 이 되는 점에서 (나) 따지기","힌트":"$\\sqrt{x^2}-3=0$ 이 되는 $a$ 는 몇 개이며, 그중 극한이 반드시 존재하지 않는 곳은?","식":["$\\sqrt{x^2}-3=|x|-3=0$ 에서 $x=\\pm3$, 다른 $a$ 에서는 분모가 $0$ 이 아니므로 극한이 존재","$f(x)=px^2-\\dfrac13x$ 에서 $f(-7)=49p+\\dfrac73>0,\\ f(-2)=4p+\\dfrac23>0$","$a=-3$ 에서는 분자 $f(-7)f(-2)\\ne0$ 이므로 극한이 존재하지 않는다"],"설명":"극한이 존재하지 않는 $a$ 는 $3$ 과 $-3$ 중 정확히 하나여야 한다. $a=-3$ 에서 극한이 존재하려면 $f(-7)f(-2)=0$ 이어야 하는데 $p>0$ 이면 두 값이 모두 양수라 불가능하므로 이 경우는 버린다. 따라서 존재하지 않는 쪽이 $a=-3$ 이고 $a=3$ 에서는 극한이 존재해야 한다.","확인":null,"스킬":"D11","고비":true},{"제목":"$a=3$ 에서 극한이 존재할 조건","힌트":"$x\\to3$ 에서 분모가 $0$ 으로 가는데 극한이 존재하려면 분자 $f(-1)f(4)$ 는 어떠해야 하는가?","식":["$x\\to3$ 이면 분모 $\\to0$ 이므로 $f(-1)f(4)=0$","$f(-1)=p+\\dfrac13>0$ 이므로 $f(4)=16p-\\dfrac43=0$","$p=\\dfrac1{12}$"],"설명":"분모가 $0$ 으로 가는데 극한이 존재하려면 분자도 $0$ 으로 가야 한다. $f(-1)>0$ 이므로 $f(4)=0$ 이어야 한다.","확인":"1/12","스킬":"D11"},{"제목":"$f(24)$ 의 값","힌트":"$p$ 와 $q$ 를 $f(x)$ 에 넣고 $x=24$ 를 대입하면?","식":["$f(x)=\\dfrac1{12}x^2-\\dfrac13x=\\dfrac1{12}x(x-4)$","$f(24)=\\dfrac1{12}\\times24\\times20=40$"],"설명":"$f(4)=0$ 이므로 인수분해한 꼴로 계산하면 편하다.","확인":"40","스킬":"A11"}]},"고2-202410-04":{"길":"극한은 함숫값이 아니라 가까이 가는 쪽 그래프의 높이로 읽는다","단계":[{"제목":"$x\\to-1-$ 일 때의 값","힌트":"$x$ 가 $-1$ 의 왼쪽에서 가까이 갈 때 그래프의 높이는?","식":["$x<-1$ 에서 그래프는 수평선 $y=3$","$\\displaystyle\\lim_{x\\to-1-}f(x)=3$"],"설명":"$x=-1$ 의 왼쪽에 있는 그래프가 향하는 높이를 읽는다. $x=-1$ 의 오른쪽 곡선 끝의 열린 점은 왼쪽 극한과 관계없다.","확인":"3","스킬":"D12"},{"제목":"$x\\to0+$ 일 때의 값","힌트":"$x$ 가 $0$ 의 오른쪽에서 가까이 갈 때 선분이 향하는 높이는?","식":["$x>0$ 에서 선분은 열린 점 $(0,\\ 1)$ 로 향한다","$\\displaystyle\\lim_{x\\to0+}f(x)=1$"],"설명":"$x=0$ 에 찍힌 점 $(0,\\ 2)$ 는 함숫값일 뿐 극한과 관계없어 버린다. 왼쪽 곡선이 향하는 $0$ 도 $x\\to0+$ 와 관계없다.","확인":"1","스킬":"D12","고비":true},{"제목":"두 극한의 합","힌트":"두 극한값을 더하면?","식":["$3+1=4$"],"설명":"왼쪽 극한 $3$ 과 오른쪽 극한 $1$ 을 더한다.","확인":"4","스킬":"D12"}]},"고2-202410-05":{"길":"각 변에 $x$ 를 곱해 $xf(x)$ 를 두 식 사이에 끼우고 양 끝의 극한이 같음을 쓴다","단계":[{"제목":"부등식의 각 변에 $x$ 곱하기","힌트":"$x>\\frac12$ 이면 $x$ 의 부호는 어떻고 부등호 방향은 어떻게 되는가?","식":["$\\dfrac{3x}{2x+1}<xf(x)<\\dfrac{3x}{2x-1}$"],"설명":"$x>\\frac12$ 이므로 $x>0$ 이고, 각 변에 양수 $x$ 를 곱해도 부등호 방향은 그대로이다.","확인":null,"스킬":"C9","고비":true},{"제목":"양 끝 식의 극한","힌트":"분모·분자를 $x$ 로 나누고 $x\\to\\infty$ 로 보내면?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{3x}{2x+1}=\\lim_{x\\to\\infty}\\frac{3}{2+\\frac1x}=\\frac32$","$\\displaystyle\\lim_{x\\to\\infty}\\frac{3x}{2x-1}=\\lim_{x\\to\\infty}\\frac{3}{2-\\frac1x}=\\frac32$"],"설명":"$x\\to\\infty$ 이면 $\\frac1x\\to0$ 이므로 두 극한이 같은 값이다.","확인":null,"스킬":"C9"},{"제목":"끼움 정리로 $xf(x)$ 의 극한","힌트":"$xf(x)$ 가 극한이 같은 두 식 사이에 있을 때 $\\displaystyle\\lim_{x\\to\\infty}xf(x)$ 는?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{3x}{2x+1}=\\lim_{x\\to\\infty}\\frac{3x}{2x-1}$ 이므로 $\\displaystyle\\lim_{x\\to\\infty}xf(x)=\\frac32$"],"설명":"양 끝 식의 극한이 같으므로 그 사이에 낀 $xf(x)$ 의 극한도 같은 값이다.","확인":"3/2","스킬":"C9"}]},"고2-202410-07":{"길":"$x=2$ 에서 연속이고 좌·우미분계수가 같다는 두 식으로 $a$, $b$ 를 정한다","단계":[{"제목":"$x=2$ 에서의 연속 조건","힌트":"미분가능하면 연속이므로 $x\\to2-$, $x\\to2+$ 의 극한이 $f(2)$ 와 같다고 놓으면?","식":["$\\displaystyle\\lim_{x\\to2-}f(x)=2-a,\\ \\lim_{x\\to2+}f(x)=4+2b+a$","$2-a=4+2b+a$ 에서 $b=-a-1$"],"설명":"미분가능한 점에서는 반드시 연속이다. 연속 조건만으로는 $a$, $b$ 가 하나로 정해지지 않는다.","확인":null,"스킬":"D12"},{"제목":"좌·우미분계수가 같을 조건","힌트":"$x\\le2$ 쪽 기울기와 $x>2$ 쪽 식의 $x=2$ 에서의 미분계수를 구해 같다고 놓으면 $b$ 는?","식":["$x\\le2$ 쪽은 기울기가 $1$ 인 직선이라 좌미분계수는 $1$","$x>2$ 쪽은 $2x+b$ 이므로 우미분계수는 $4+b$","$4+b=1$ 에서 $b=-3$"],"설명":"좌미분계수와 우미분계수가 같아야 $x=2$ 에서 미분가능하다. $x>2$ 쪽 식의 도함수는 $2x+b$ 이다.","확인":"-3","스킬":"D12","고비":true},{"제목":"$a$ 의 값과 $f(2)$","힌트":"$b=-3$ 을 연속 조건에 넣어 $a$ 를 구하고 $f(2)$ 를 계산하면?","식":["$-3=-a-1$ 에서 $a=2$","$f(2)=2-a=0$"],"설명":"$f(2)$ 는 $x\\le2$ 쪽 식 $x-a$ 로 계산한다.","확인":"0","스킬":"D12"}]},"고2-202410-14":{"길":"$x=0$, $x=4$ 대입으로 $b$, $a$ 를 정하고 유리화해 $x\\to0$ 의 극한으로 $f(0)$ 을 구한다","단계":[{"제목":"$x=0$ 대입으로 $b$ 정하기","힌트":"(가)의 양변에 $x=0$ 을 넣으면 $b$ 는?","식":["$\\left(\\sqrt{1}-1\\right)f(0)=0+0+b$","$b=0$"],"설명":"$x=0$ 은 $x\\ge-\\frac12$ 범위에 들어간다. $\\sqrt{2\\times0+1}-1=0$ 이므로 $f(0)$ 의 값과 관계없이 좌변이 $0$ 이다.","확인":"0","스킬":"D12"},{"제목":"$x=4$ 대입으로 $a$ 정하기","힌트":"$x=4$ 와 $f(4)=2$ 를 (가)에 넣으면 $a$ 는?","식":["$\\left(\\sqrt{9}-1\\right)f(4)=16+4a$","$2\\times2=16+4a$ 에서 $a=-3$"],"설명":"$\\sqrt{2\\times4+1}=3$ 이다.","확인":null,"스킬":"D12"},{"제목":"$x\\ne0$ 에서 $f(x)$ 의 약분","힌트":"$a,\\ b$ 를 넣고 분모를 유리화하면 $x$ 가 약분되는 꼴은?","식":["$x\\ne0$ 에서 $f(x)=\\dfrac{x^2-3x}{\\sqrt{2x+1}-1}=\\dfrac{x(x-3)\\left(\\sqrt{2x+1}+1\\right)}{\\left(\\sqrt{2x+1}-1\\right)\\left(\\sqrt{2x+1}+1\\right)}$","$=\\dfrac{x(x-3)\\left(\\sqrt{2x+1}+1\\right)}{2x}=\\dfrac{(x-3)\\left(\\sqrt{2x+1}+1\\right)}{2}$"],"설명":"$\\left(\\sqrt{2x+1}-1\\right)\\left(\\sqrt{2x+1}+1\\right)=2x$ 이고, $x\\ne0$ 이므로 분모·분자의 $x$ 를 약분할 수 있다.","확인":null,"스킬":"D11","고비":true},{"제목":"연속 조건으로 $f(0)$ 구하기","힌트":"$f$ 가 $x=0$ 에서 연속이므로 $f(0)=\\displaystyle\\lim_{x\\to0}f(x)$ 를 계산하면?","식":["$f(0)=\\displaystyle\\lim_{x\\to0}\\frac{(x-3)\\left(\\sqrt{2x+1}+1\\right)}{2}=\\frac{(-3)\\times2}{2}$","$=-3$"],"설명":"$f$ 는 실수 전체에서 연속이므로 $f(0)$ 은 $x\\ne0$ 에서의 식의 극한과 같다.","확인":"-3","스킬":"D12"}]},"고2-202410-20":{"길":"$g(t)$ 를 점 $(0,\\ a)$ 에서 그은 기울기로 보고 보기마다 $a$ 와 $k$ 를 구해 따진다","단계":[{"제목":"$g(t)$ 의 뜻과 ㄱ","힌트":"$f(0)$ 을 구해 $g(t)$ 를 $t$ 로 나타내고 $a=1$ 일 때 $g(1)$ 을 따지면?","식":["$f(0)=(0-1)(0-a)=a$","$g(t)=\\dfrac{f(t)-f(0)}{t-0}=\\dfrac{f(t)-a}{t}$","$a=1$ 이면 $g(1)=\\dfrac{f(1)-1}{1}=\\dfrac{0-1}{1}=-1$"],"설명":"$g(t)$ 는 두 점 $(0,\\ a),\\ (t,\\ f(t))$ 를 잇는 직선의 기울기이다. $f(1)=0$ 이므로 ㄱ 은 참이다.","확인":null,"스킬":"G9"},{"제목":"ㄴ: 최댓값이 $1$ 이 되는 $a$","힌트":"구간별로 $g(t)$ 를 쓰고 최댓값이 $1$ 이 되는 $a$ 를 찾으면?","식":["$g(t)=t-a-1\\ (0<t<1),\\ \\ -\\dfrac{a}{t}\\ (1\\le t<2),\\ \\ \\dfrac{1-a}{t}\\ (t\\ge2)$","최댓값 후보는 $g(1)=-a$ 와 $g(2)=\\dfrac{1-a}{2}$","$-a=1$ 이든 $\\dfrac{1-a}{2}=1$ 이든 $a=-1$, 이때 $g(2)=\\dfrac{1-(-1)}{2}=1$"],"설명":"$a>-1$ 이면 모든 구간에서 $g(t)<1$ 이라 최댓값이 $1$ 이 될 수 없고, $a<-1$ 이면 $g(1)=-a>1$ 이다. 따라서 $a=-1$ 이고 $g(2)=1\\ne\\frac12$ 이므로 ㄴ 은 거짓이다.","확인":"-1","스킬":"G9"},{"제목":"ㄷ: $g(k)=g(k+1)=g(k+2)$ 의 조건","힌트":"세 값이 같으면 네 점이 한 직선 위에 있으므로 $k$ 의 범위를 나눠 $f(k+1),\\ f(k+2)$ 를 정하면?","식":["$1\\le k<2$ 이면 $f(k+1)=f(k+2)=1$ 이므로 $a=1$ 이어야 하고 $g(k)=-\\dfrac1k\\ne0=g(k+1)$ 이라 불가능","$0<k<1$ 이면 $f(k+1)=0,\\ f(k+2)=1$ 이므로 직선의 기울기는 $1$, $f(k)=-1$, $a=-k-1$","$(k-1)(k-a)=-1$ 에 $a=-k-1$ 을 넣으면 $2k^2-k=0$, $k=\\dfrac12,\\ a=-\\dfrac32$"],"설명":"$g$ 의 값이 같다는 것은 점 $(0,\\ a)$ 에서 세 점으로 그은 직선의 기울기가 같다는 뜻이다. $1\\le k<2$ 인 경우는 $g(k)\\ne g(k+1)$ 이라 버린다. $0<k<1$ 에서는 $(k+1,\\ 0),\\ (k+2,\\ 1)$ 을 지나는 기울기 $1$ 직선이 $(0,\\ a)$ 와 $(k,\\ f(k))$ 를 지난다.","확인":"1/2","스킬":"G9","고비":true},{"제목":"ㄷ: 직선 $y=-\\frac32$ 와의 교점","힌트":"$x<1$ 에서 $f(x)=(x-1)\\left(x+\\frac32\\right)$ 의 최솟값과 $-\\frac32$ 를 비교하면?","식":["$x<1$ 에서 $f(x)=x^2+\\dfrac12x-\\dfrac32=\\left(x+\\dfrac14\\right)^2-\\dfrac{25}{16}$","$x=-\\dfrac14<1$ 에서 최솟값 $-\\dfrac{25}{16}<-\\dfrac32$","$x\\ge1$ 에서는 $f(x)=0$ 또는 $1$ 이라 직선 $y=-\\dfrac32$ 와 만나지 않는다"],"설명":"아래로 볼록한 포물선의 최솟값이 $-\\frac32$ 보다 작으므로 꼭짓점 양쪽에서 직선 $y=-\\frac32$ 와 한 번씩 만난다. $f(1)=0>-\\frac32$ 이라 오른쪽 교점도 $x<1$ 안에 있으므로 서로 다른 두 점에서 만나 ㄷ 은 참이다.","확인":"-25/16","스킬":"G1"},{"제목":"보기 종합","힌트":"세 보기의 참·거짓을 모으면?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참"],"설명":"옳은 것은 ㄱ, ㄷ 이다.","확인":null,"스킬":"C3"}]},"고2-202410-24":{"길":"첫 극한으로 $f$ 의 꼴을 정하고 둘째 극한으로 상수항과 $x$ 의 계수를 정한다","단계":[{"제목":"$f(x)$ 의 꼴 정하기","힌트":"$\\dfrac{f(x)-2x^3}{x^2}$ 이 수렴하려면 $f(x)-2x^3$ 은 몇 차 이하이고 $x^2$ 의 계수는?","식":["$\\dfrac{f(x)-2x^3}{x^2}$ 이 수렴하므로 $f(x)-2x^3$ 은 이차 이하이고 $x^2$ 의 계수는 $3$","$f(x)=2x^3+3x^2+ax+b$"],"설명":"다항식을 $x^2$ 으로 나눈 식이 $x\\to\\infty$ 에서 수렴하면 분자의 차수는 2 이하이고 극한값은 $x^2$ 의 계수이다.","확인":null,"스킬":"A11"},{"제목":"$b$ 의 값","힌트":"$\\displaystyle\\lim_{x\\to0}\\frac{f(x)}{x}=3$ 이 존재하려면 $f(0)$ 은?","식":["$x\\to0$ 에서 분모 $\\to0$ 이므로 분자 $f(x)\\to0$","$f(0)=b=0$"],"설명":"분모가 $0$ 으로 가는데 극한이 존재하므로 분자도 $0$ 으로 가야 한다.","확인":"0","스킬":"D11","고비":true},{"제목":"$a$ 의 값","힌트":"$b=0$ 을 넣고 $x$ 로 약분한 뒤 $x\\to0$ 으로 보내면?","식":["$\\displaystyle\\lim_{x\\to0}\\frac{2x^3+3x^2+ax}{x}=\\lim_{x\\to0}\\left(2x^2+3x+a\\right)=a$","$a=3$"],"설명":"약분한 식은 다항식이므로 $x=0$ 을 그대로 넣으면 극한값이 된다.","확인":null,"스킬":"D11"},{"제목":"$f(2)$ 의 값","힌트":"$f(x)=2x^3+3x^2+3x$ 에 $x=2$ 를 넣으면?","식":["$f(2)=2\\times8+3\\times4+3\\times2=16+12+6=34$"],"설명":"각 항을 따로 계산해 더한다.","확인":"34","스킬":"A11"}]},"고2-202410-27":{"길":"두 점의 좌표를 $t$ 로 구하고 $\\overline{\\mathrm{OB}}-\\overline{\\mathrm{OA}}$ 를 유리화해 $t-1$ 을 약분한다","단계":[{"제목":"두 점 A, B 의 좌표","힌트":"$\\dfrac{2t}{x}=-\\dfrac1tx+3$ 에서 $x$ 에 대한 이차식을 인수분해하면?","식":["$\\dfrac{2t}{x}=-\\dfrac{x}{t}+3$ 의 양변에 $tx$ 를 곱하면 $2t^2=-x^2+3tx$","$x^2-3tx+2t^2=(x-t)(x-2t)=0$","$\\mathrm{A}(t,\\ 2),\\ \\mathrm{B}(2t,\\ 1)$"],"설명":"$\\mathrm{B}$ 의 $x$좌표가 더 크므로 $x=t$ 가 A, $x=2t$ 가 B 이다. $y$좌표는 $y=\\frac{2t}{x}$ 에서 구한다.","확인":null,"스킬":"G1"},{"제목":"분자의 유리화와 약분","힌트":"$\\overline{\\mathrm{OA}},\\ \\overline{\\mathrm{OB}}$ 를 구하고 분자를 유리화하면 $t-1$ 이 약분되는 꼴은?","식":["$\\overline{\\mathrm{OA}}=\\sqrt{t^2+4},\\ \\overline{\\mathrm{OB}}=\\sqrt{4t^2+1}$","$\\dfrac{\\overline{\\mathrm{OB}}-\\overline{\\mathrm{OA}}}{t-1}=\\dfrac{(4t^2+1)-(t^2+4)}{(t-1)\\left(\\overline{\\mathrm{OB}}+\\overline{\\mathrm{OA}}\\right)}=\\dfrac{3(t+1)}{\\overline{\\mathrm{OB}}+\\overline{\\mathrm{OA}}}$"],"설명":"$(4t^2+1)-(t^2+4)=3t^2-3=3(t-1)(t+1)$ 이므로 분모의 $t-1$ 이 약분된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$k$ 와 $k^2$ 의 값","힌트":"$t\\to1+$ 로 보내 $k$ 를 구하고 제곱하면?","식":["$k=\\dfrac{3\\times2}{\\sqrt5+\\sqrt5}=\\dfrac3{\\sqrt5}$","$k^2=\\dfrac95$"],"설명":"$t=1$ 이면 $\\overline{\\mathrm{OA}}=\\sqrt5,\\ \\overline{\\mathrm{OB}}=\\sqrt5$ 이다.","확인":"9/5","스킬":"D3"},{"제목":"$30k^2$ 의 값","힌트":"$30\\times k^2$ 을 계산하면?","식":["$30\\times\\dfrac95=54$"],"설명":"$k^2=\\frac95$ 이므로 $30$ 을 곱하면 정수가 된다.","확인":"54","스킬":"D3"}]},"고2-202410-30":{"길":"$|g|$ 의 개형과 (가)로 $f$ 의 꼭짓점을 정하고 (나)로 $a,\\ b$ 와 $f(x)$ 를 구한다","단계":[{"제목":"$x<1$ 에서 $|g|$ 의 개형","힌트":"$g(x)=b-\\dfrac{ab}{x+a}$ 의 점근선을 이용해 $x<1$ 의 세 구간에서 $|g|$ 가 어떻게 변하는가?","식":["$g(x)=b-\\dfrac{ab}{x+a}$ 이므로 점근선은 $x=-a,\\ y=b$","$x<-a$ 에서 $|g|$ 는 $b$ 보다 큰 값을 한 번씩, $-a<x<0$ 에서는 $\\infty$ 에서 $0$ 까지 줄고, $0\\le x<1$ 에서는 $0$ 에서 $c$ 미만까지 는다 ($c=\\dfrac{b}{1+a}$)","$x=1$ 에서 연속이므로 $f(1)=c$ 이고 $0<c<b$"],"설명":"$y=t$ 와 만나는 점은 $x<-a$ 쪽에서 $t>b$ 일 때 1개, $-a<x<0$ 쪽에서 모든 $t>0$ 에서 1개, $0\\le x<1$ 쪽에서 $0<t<c$ 일 때 1개이다.","확인":null,"스킬":"G5"},{"제목":"꼭짓점의 $x$좌표가 $1$ 보다 커야 하는 까닭","힌트":"꼭짓점의 $x$좌표 $k$ 가 $1$ 이하이면 $h(t)$ 는 $t=b$ 에서 어떻게 변하는가?","식":["$k\\le1$ 이면 $x\\ge1$ 에서 $|f|$ 는 $c$ 에서 시작해 늘기만 한다","$0<t\\le b$ 에서 $h(t)=2,\\ t>b$ 에서 $h(t)=3$","$t=b$ 에서 $h$ 가 늘어 (가)에 어긋나므로 $k>1$"],"설명":"$t=b$ 를 지나면 $x<-a$ 쪽에서 교점이 하나 생기는데 $|f|$ 쪽 교점은 줄지 않아 $h$ 가 늘어난다. 따라서 $k\\le1$ 인 경우는 버린다.","확인":null,"스킬":"G5"},{"제목":"(가)를 만족시키는 꼭짓점의 높이","힌트":"$f(x)=(x-k)^2+m$ 에서 $m$ 이 $-b$ 보다 큰 경우, 작은 경우, 같은 경우에 $t=b$ 에서 $h$ 는 어떻게 변하는가?","식":["$t=b$ 를 지날 때 $x<-a$ 쪽 교점이 1개 늘어난다","$m>-b$ 또는 $m<-b$: $|f|$ 쪽 교점이 줄지 않아 $h$ 가 늘어난다","$m=-b$: $|f|$ 쪽 교점이 3개에서 1개로 줄어 $h$ 는 4에서 3으로 줄어든다"],"설명":"$m>-b$ 이면 $|f|$ 의 극댓값이 없거나 $b$ 보다 작고, $m<-b$ 이면 극댓값 $-m$ 이 $b$ 보다 크다. 두 경우 모두 $t=b$ 에서 $|f|$ 쪽 교점은 그대로이고 $h$ 가 늘어 (가)에 어긋나므로 버린다. $|f|$ 의 극댓값이 $b$ 인 $m=-b$ 일 때만 (가)를 만족시킨다.","확인":null,"스킬":"C2","고비":true},{"제목":"$h(t)$ 의 구간별 값","힌트":"$f(k)=-b$ 일 때 $t=c$ 에서 $y=t$ 와 $|g(x)|$ 의 교점은 몇 개인가?","식":["$t<0$: $0$, $t=0$: $3$, $0<t<c$: $6$, $t=c$: $5$, $c<t<b$: $4$, $t\\ge b$: $3$","$h$ 가 불연속인 곳은 $t=0,\\ c,\\ b$"],"설명":"$0<t<c$ 에서는 $x<1$ 쪽 2개와 $x\\ge1$ 쪽 4개가 만난다. $t=c$ 에서는 $0\\le x<1$ 쪽 교점이 사라져 5개이고, $c<t<b$ 에서는 $x\\ge1$ 쪽 교점이 3개라 4개이다.","확인":"5","스킬":"G1"},{"제목":"(나)로 $b$ 와 $a$ 구하기","힌트":"불연속인 점 $0,\\ \\alpha,\\ \\beta$ 와 $h(0)=\\alpha,\\ h(\\alpha)=\\beta-1$ 로 $b$ 를 구하면?","식":["불연속인 점이 $0,\\ c,\\ b$ 이므로 $\\alpha=c,\\ \\beta=b$","$h(0)=\\alpha$ 에서 $c=3$, $h(\\alpha)=h(c)=5=\\beta-1$ 에서 $b=6$","$c=\\dfrac{b}{1+a}=\\dfrac{6}{1+a}=3$ 에서 $a=1$"],"설명":"$h(0)=3$ 이므로 $\\alpha=3$ 이고 $h(c)=5$ 이므로 $\\beta=6$ 이다.","확인":"6","스킬":"G1"},{"제목":"$f(x)$ 의 식","힌트":"$f(x)=(x-k)^2-6$ 에 $f(1)=c=3$ 을 넣어 $k$ 를 구하면?","식":["$(1-k)^2-6=3$ 에서 $(1-k)^2=9$","$k=4$ 또는 $k=-2$ 이고 $k>1$ 이므로 $k=4$"],"설명":"$k>1$ 이어야 하므로 $k=-2$ 는 버린다. $f(x)=(x-4)^2-6$ 이다.","확인":"4","스킬":"G7"},{"제목":"$f(a-b)$ 의 값","힌트":"$a-b$ 를 구해 $f(x)=(x-4)^2-6$ 에 넣으면?","식":["$a-b=1-6=-5$","$f(-5)=(-5-4)^2-6=81-6=75$"],"설명":"$f(x)=(x-4)^2-6$ 에 $x=-5$ 를 대입한다.","확인":"75","스킬":"G1"}]},"고2-202509-05":{"길":"좌·우극한은 함숫값이 아니라 가까이 가는 쪽 그래프의 높이로 읽는다","단계":[{"제목":"$x\\to1-$ 일 때의 값","힌트":"$x$ 가 $1$ 의 왼쪽에서 가까이 갈 때 곡선이 향하는 높이는?","식":["$x<1$ 의 곡선은 점 $(1,\\ 1)$ 로 향한다","$\\displaystyle\\lim_{x\\to1-}f(x)=1$"],"설명":"$x>1$ 의 선분이 향하는 열린 점 $(1,\\ -1)$ 의 높이는 오른쪽 극한이므로 이 극한과 관계없다.","확인":"1","스킬":"D12"},{"제목":"$x\\to3+$ 일 때의 값","힌트":"$x$ 가 $3$ 의 오른쪽에서 가까이 갈 때 곡선이 향하는 높이는?","식":["$x>3$ 의 곡선은 열린 점 $(3,\\ -2)$ 로 향한다","$\\displaystyle\\lim_{x\\to3+}f(x)=-2$"],"설명":"$x=3$ 에 찍힌 점 $(3,\\ 3)$ 은 함숫값일 뿐 극한과 관계없어 버린다.","확인":"-2","스킬":"D12","고비":true},{"제목":"두 극한의 합","힌트":"두 극한값을 더하면?","식":["$1+(-2)=-1$"],"설명":"왼쪽 극한 $1$ 과 오른쪽 극한 $-2$ 를 더한다.","확인":"-1","스킬":"D12"}]},"고2-202509-17":{"길":"밑변 $\\overline{\\mathrm{PQ}}$ 와 높이로 $S(t)$ 를 쓰고 유리화·인수분해로 $t-1$ 을 약분한다","단계":[{"제목":"$S(t)$ 의 식","힌트":"점 $\\mathrm{P},\\ \\mathrm{Q}$ 의 좌표를 구하고 $\\overline{\\mathrm{PQ}}$ 를 밑변으로 보면 높이는 얼마인가?","식":["$\\mathrm{P}(t,\\ t^2),\\ \\mathrm{Q}(t,\\ \\sqrt t)$ 이고 $\\overline{\\mathrm{PQ}}=t^2-\\sqrt t$","$\\mathrm{A}$ 에서 직선 $x=t$ 까지의 거리는 $t-1$","$S(t)=\\dfrac12\\left(t^2-\\sqrt t\\right)(t-1)$"],"설명":"$t>1$ 이므로 $t^2>\\sqrt t$ 이다. 직선 $x=t$ 가 밑변을 포함하므로 높이는 $\\mathrm{A}$ 의 $x$좌표 $1$ 과 $t$ 의 차이다.","확인":null,"스킬":"G10"},{"제목":"$t-1$ 이 약분되는 꼴","힌트":"$\\dfrac{S(t)}{(t-1)^2}$ 에서 $\\dfrac{t^2-\\sqrt t}{t-1}$ 의 분자에 $t^2+\\sqrt t$ 를 곱하면 약분되는 꼴은?","식":["$\\dfrac{S(t)}{(t-1)^2}=\\dfrac12\\times\\dfrac{t^2-\\sqrt t}{t-1}$","$\\dfrac{t^2-\\sqrt t}{t-1}=\\dfrac{t^4-t}{(t-1)\\left(t^2+\\sqrt t\\right)}=\\dfrac{t(t-1)\\left(t^2+t+1\\right)}{(t-1)\\left(t^2+\\sqrt t\\right)}=\\dfrac{t\\left(t^2+t+1\\right)}{t^2+\\sqrt t}$"],"설명":"$\\left(t^2-\\sqrt t\\right)\\left(t^2+\\sqrt t\\right)=t^4-t$ 이고 $t^4-t=t(t-1)\\left(t^2+t+1\\right)$ 이므로 $t-1$ 이 약분된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$\\dfrac{t^2-\\sqrt t}{t-1}$ 의 극한","힌트":"$t\\to1+$ 로 보내면 $\\dfrac{t\\left(t^2+t+1\\right)}{t^2+\\sqrt t}$ 의 값은?","식":["$\\displaystyle\\lim_{t\\to1+}\\frac{t\\left(t^2+t+1\\right)}{t^2+\\sqrt t}=\\frac{1\\times3}{1+1}=\\frac32$"],"설명":"약분한 식은 $t=1$ 에서 분모가 $0$ 이 아니므로 그대로 대입한다.","확인":"3/2","스킬":"D3"},{"제목":"구하는 극한값","힌트":"앞의 극한에 $\\dfrac12$ 을 곱하면?","식":["$\\displaystyle\\lim_{t\\to1+}\\frac{S(t)}{(t-1)^2}=\\dfrac12\\times\\dfrac32=\\dfrac34$"],"설명":"$\\frac12$ 은 극한 밖에 둔 상수이므로 마지막에 곱한다.","확인":"3/4","스킬":"D3"}]},"고2-202509-30":{"길":"$f=g$ 의 두 근에서 좌·우극한을 따져 불연속점 $2$ 와 (나)로 $a$ 와 $f$ 를 정한다","단계":[{"제목":"$h$ 의 식이 바뀌는 점","힌트":"$f\\ge g$ 가 항상 성립하면 $h$ 는 어떤 함수가 되고, 그러면 (가)를 만족시키는가?","식":["$f\\ge g$ 가 항상 성립하면 $h=g+f$ 가 다항함수라 연속이므로 (가)에 어긋난다","따라서 $f(x)=g(x)$ 는 서로 다른 두 실근 $x_1<x_2$ 를 가진다","$x\\le x_1$ 또는 $x\\ge x_2$ 에서 $h=g+f$, $x_1<x<x_2$ 에서 $h=g-f$"],"설명":"$f-g$ 는 최고차항의 계수가 양수인 이차함수이므로 두 근 사이에서만 $f<g$ 이다.","확인":null,"스킬":"G6"},{"제목":"두 근에서의 좌·우극한","힌트":"$x=x_1,\\ x_2$ 에서 $f=g$ 임을 쓰면 좌극한과 우극한은 각각 얼마인가?","식":["$x=x_1$: $\\displaystyle\\lim_{x\\to x_1-}h=2g(x_1),\\ \\lim_{x\\to x_1+}h=0$","$x=x_2$: $\\displaystyle\\lim_{x\\to x_2-}h=0,\\ \\lim_{x\\to x_2+}h=2g(x_2)$","불연속인 점이 $2$ 뿐이므로 $x_1=2,\\ g(x_2)=0$ 또는 $x_2=2,\\ g(x_1)=0$"],"설명":"$f=g$ 인 점에서 $g+f$ 와 $g-f$ 의 값은 $2g$ 와 $0$ 이다. 두 값이 같으려면 그 점에서 $g=0$ 이어야 하므로 두 근 중 하나는 $g=0$ 이라 연속이고 나머지 하나가 $x=2$ 이다.","확인":null,"스킬":"D12"},{"제목":"(나)로 $x=2$ 의 위치 정하기","힌트":"$g$ 가 증가함수임을 쓰고 두 경우에서 $x=2$ 의 $|h-1|$ 의 좌·우극한이 같은지 따지면?","식":["$x_1=2$ 이면 $g(x_2)=0$ 이고 $g$ 가 증가하므로 $g(2)<0$, $|h-1|$ 의 좌극한 $|2g(2)-1|>1$, 우극한 $|0-1|=1$ 이라 극한이 존재하지 않는다","$x_2=2$ 이면 $g(x_1)=0$ 이고 $g(2)>0$, 좌극한 $|0-1|=1$ 이므로 $|2g(2)-1|=1$","$g(2)=0$ 또는 $1$ 에서 $g(2)>0$ 이므로 $g(2)=1$"],"설명":"$x_1=2$ 인 경우는 $x=2$ 에서 $|h-1|$ 의 극한이 존재하지 않아 버린다. $x_2=2$ 인 경우 $|2g(2)-1|=1$ 에서 $g(2)=0$ 도 나오지만 $g(2)>0$ 이므로 버린다.","확인":null,"스킬":"C2","고비":true},{"제목":"$a$ 와 $x_1$ 의 값","힌트":"$g(2)=1$ 에서 $a$ 를 구하고 $g(x_1)=0$ 으로 $x_1$ 을 구하면?","식":["$g(2)=\\dfrac23+a=1$ 에서 $a=\\dfrac13$","$g(x)=\\dfrac13x+\\dfrac13$, $g(x_1)=0$ 에서 $x_1=-1$"],"설명":"$x_2=2$ 이고 $f(-1)=g(-1)=0,\\ f(2)=g(2)=1$ 이다.","확인":"1/3","스킬":"G1"},{"제목":"$p$ 의 값","힌트":"$f(x)-g(x)=p(x+1)(x-2)$ 로 놓고 $h(0)$ 을 $p$ 로 나타내면?","식":["$f(x)-g(x)=p(x+1)(x-2)\\ (p>0)$","$x_1<0<x_2$ 이므로 $h(0)=g(0)-f(0)=-p\\times1\\times(-2)=2p$","$2p=\\dfrac73$ 에서 $p=\\dfrac76$"],"설명":"$f-g$ 의 두 근이 $-1,\\ 2$ 이고 최고차항의 계수가 양수이므로 $p>0$ 이다.","확인":"7/6","스킬":"A3"},{"제목":"$h(5)$ 의 값","힌트":"$x=5$ 에서 $h$ 의 식을 정하고 $g(5)$ 와 $f(5)-g(5)$ 로 계산하면?","식":["$5>x_2$ 이므로 $h(5)=g(5)+f(5)=2g(5)+\\{f(5)-g(5)\\}$","$g(5)=\\dfrac53+\\dfrac13=2,\\ f(5)-g(5)=\\dfrac76\\times6\\times3=21$","$h(5)=4+21=25$"],"설명":"$x\\ge x_2$ 에서는 $f\\ge g$ 이므로 $h=g+f$ 이다.","확인":"25","스킬":"G6"}]},"고2-202510-04":{"길":"좌·우극한은 함숫값이 아니라 가까이 가는 쪽 그래프의 높이로 읽는다","단계":[{"제목":"$x\\to-1-$ 일 때의 값","힌트":"$x$ 가 $-1$ 의 왼쪽에서 가까이 갈 때 선분이 향하는 높이는?","식":["$x<-1$ 의 선분은 점 $(-1,\\ 2)$ 로 향한다","$\\displaystyle\\lim_{x\\to-1-}f(x)=2$"],"설명":"$x>-1$ 쪽에서 시작하는 열린 점 $(-1,\\ 1)$ 은 오른쪽 극한이므로 왼쪽 극한과 관계없다.","확인":"2","스킬":"D12"},{"제목":"$x\\to2+$ 일 때의 값","힌트":"$x$ 가 $2$ 의 오른쪽에서 가까이 갈 때 선분이 향하는 높이는?","식":["$x>2$ 의 선분은 열린 점 $(2,\\ 3)$ 에서 시작한다","$\\displaystyle\\lim_{x\\to2+}f(x)=3$"],"설명":"$x=2$ 에 찍힌 점 $(2,\\ 1)$ 은 함숫값이고 열린 점 $(2,\\ 2)$ 는 왼쪽 극한이므로 모두 관계없어 버린다.","확인":"3","스킬":"D12","고비":true},{"제목":"두 극한의 합","힌트":"두 극한값을 더하면?","식":["$2+3=5$"],"설명":"왼쪽 극한 $2$ 와 오른쪽 극한 $3$ 을 더한다.","확인":"5","스킬":"D12"}]},"고2-202510-06":{"길":"각 구간이 다항식이므로 경계 $x=a$ 에서 좌극한과 함숫값이 같다고 놓는다","단계":[{"제목":"연속이어야 하는 점","힌트":"각 구간의 식이 다항식이면 연속 여부를 따져야 하는 점은 어디인가?","식":["$x<a$ 와 $x\\ge a$ 에서 모두 다항식이므로 $x=a$ 에서만 연속이면 된다"],"설명":"경계 $x=a$ 에서 좌극한, 우극한, 함숫값이 모두 같아야 한다.","확인":null,"스킬":"D12"},{"제목":"$x=a$ 에서의 좌극한과 함숫값","힌트":"$x\\to a-$ 의 극한과 $f(a)$ 를 각각 구하면?","식":["$\\displaystyle\\lim_{x\\to a-}f(x)=(a-2a)^2=a^2$","$f(a)=a^2-3a+6$"],"설명":"$x\\ge a$ 쪽 식은 $x=a$ 에서 연속이므로 우극한도 $a^2-3a+6$ 이다.","확인":null,"스킬":"D12","고비":true},{"제목":"$a$ 의 값","힌트":"좌극한과 함숫값이 같다는 식을 풀면?","식":["$a^2=a^2-3a+6$ 에서 $3a=6$","$a=2$"],"설명":"$a^2$ 이 양변에서 소거되어 일차방정식이 된다.","확인":"2","스킬":"D12"}]},"고2-202510-10":{"길":"$x^2-1=(x-1)(x+1)$ 로 쪼개 주어진 극한 $(x-1)f(x)$ 를 그대로 쓴다","단계":[{"제목":"$(x-1)f(x)$ 꺼내기","힌트":"$x^2-1=(x-1)(x+1)$ 로 쪼개 $(x-1)f(x)$ 를 따로 두면?","식":["$\\dfrac{(x^2-1)f(x)}{3x+1}=\\dfrac{x+1}{3x+1}\\times(x-1)f(x)$"],"설명":"$f(x)$ 자체의 극한은 모르지만 $(x-1)f(x)$ 의 극한이 주어져 있으므로 이 꼴을 만든다.","확인":null,"스킬":"A11","고비":true},{"제목":"$\\dfrac{x+1}{3x+1}$ 의 극한","힌트":"분모·분자를 $x$ 로 나누고 $x\\to\\infty$ 로 보내면?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{x+1}{3x+1}=\\lim_{x\\to\\infty}\\frac{1+\\frac1x}{3+\\frac1x}=\\frac13$"],"설명":"$x\\to\\infty$ 이면 $\\frac1x\\to0$ 이다.","확인":"1/3","스킬":"A11"},{"제목":"두 극한의 곱","힌트":"두 극한이 모두 존재하므로 곱하면?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{(x^2-1)f(x)}{3x+1}=\\frac13\\times12=4$"],"설명":"극한이 각각 존재하면 곱의 극한은 극한의 곱과 같다.","확인":"4","스킬":"A11"}]},"고2-202510-12":{"길":"점 P 의 좌표를 $t$ 로 나타내고 $\\sqrt{t^2+1}-1$ 을 유리화해 $t^2$ 을 약분한다","단계":[{"제목":"점 P 의 좌표","힌트":"$x^2-3x=tx$ 에서 원점이 아닌 교점의 $x$좌표는?","식":["$x^2-3x=tx$ 에서 $x(x-t-3)=0$","$\\mathrm{P}$ 는 원점이 아니므로 $x=t+3$, $\\mathrm{P}(t+3,\\ t^2+3t)$"],"설명":"$y=tx$ 에 $x=t+3$ 을 넣으면 $y=t(t+3)=t^2+3t$ 이다.","확인":null,"스킬":"G1"},{"제목":"$\\overline{\\mathrm{OP}}$ 와 $\\overline{\\mathrm{OH}}$","힌트":"$\\mathrm{H}$ 의 좌표를 구하고 두 길이를 $t$ 로 나타내면?","식":["$\\mathrm{H}(t+3,\\ 0)$ 이므로 $\\overline{\\mathrm{OH}}=t+3$","$\\overline{\\mathrm{OP}}=\\sqrt{(t+3)^2+t^2(t+3)^2}=(t+3)\\sqrt{t^2+1}$"],"설명":"$t>0$ 이므로 $t+3>0$ 이고 $(t+3)^2$ 을 묶어 제곱근 밖으로 낼 수 있다.","확인":null,"스킬":"S3"},{"제목":"유리화로 $t^2$ 약분하기","힌트":"$\\dfrac{\\overline{\\mathrm{OP}}-\\overline{\\mathrm{OH}}}{t^2}$ 에서 $(t+3)$ 을 묶고 $\\sqrt{t^2+1}-1$ 을 유리화하면?","식":["$\\dfrac{\\overline{\\mathrm{OP}}-\\overline{\\mathrm{OH}}}{t^2}=\\dfrac{(t+3)\\left(\\sqrt{t^2+1}-1\\right)}{t^2}$","$=\\dfrac{(t+3)\\left\\{(t^2+1)-1\\right\\}}{t^2\\left(\\sqrt{t^2+1}+1\\right)}=\\dfrac{t+3}{\\sqrt{t^2+1}+1}$"],"설명":"$\\left(\\sqrt{t^2+1}-1\\right)\\left(\\sqrt{t^2+1}+1\\right)=t^2$ 이므로 분모의 $t^2$ 이 약분된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$t\\to0+$ 의 극한","힌트":"약분한 식에 $t\\to0+$ 를 대입하면?","식":["$\\displaystyle\\lim_{t\\to0+}\\frac{t+3}{\\sqrt{t^2+1}+1}=\\frac{3}{1+1}=\\frac32$"],"설명":"약분한 식은 $t=0$ 에서 분모가 $0$ 이 아니므로 그대로 대입한다.","확인":"3/2","스킬":"D3"}]},"고2-202510-16":{"길":"극한값이 $0$ 이려면 분자의 $(x-1)$ 인수가 분모보다 많아야 함을 쓴다","단계":[{"제목":"$f$ 의 꼴과 분자의 인수","힌트":"$f(1)=0$ 이면 $f(x)$ 와 $f(x+3)$ 은 어떻게 쓸 수 있는가?","식":["$f(x)=(x-1)(x-a)$","$f(x+3)=(x+2)(x+3-a)$","$\\dfrac{f(x+3)g(x)}{\\{f(x)\\}^2}=\\dfrac{(x+2)(x+3-a)g(x)}{(x-1)^2(x-a)^2}$"],"설명":"극한값이 $0$ 이려면 분자가 가진 $(x-1)$ 인수의 개수가 분모보다 많아야 한다.","확인":null,"스킬":"A11"},{"제목":"$a=1$ 인 경우 버리기","힌트":"$a=1$ 이면 분모의 $(x-1)$ 인수는 몇 개이고 분자는 몇 개까지 가질 수 있는가?","식":["$a=1$ 이면 분모는 $(x-1)^4$, 분자는 $(x+2)^2g(x)$","극한이 $0$ 이려면 분자가 $(x-1)^5$ 을 인수로 가져야 하는데 분자는 사차식이라 불가능"],"설명":"$g(x)$ 가 이차식이므로 분자 $(x+2)^2g(x)$ 는 사차식이고 $(x-1)^5$ 을 인수로 가질 수 없다. 따라서 $a\\ne1$ 이다.","확인":null,"스킬":"D11"},{"제목":"$a\\ne1$ 일 때 $a$ 와 $g(x)$","힌트":"분모의 $(x-1)$ 인수는 몇 개이며, 분자가 그 이상을 가지려면 $x+3-a$ 와 $g(x)$ 는 어떠해야 하는가?","식":["$a\\ne1$ 이면 분모는 $(x-1)^2(x-a)^2$ 이고 $(x-a)^2$ 은 $x=1$ 에서 $0$ 이 아니다","분자 $(x+2)(x+3-a)g(x)$ 가 $(x-1)^3$ 을 인수로 가져야 하고 $g$ 는 이차식이므로 $x+3-a=x-1$","$a=4,\\ g(x)=(x-1)^2$"],"설명":"$x+3-a$ 가 $x-1$ 이 아니면 분자의 $(x-1)$ 인수는 $g(x)$ 에서 나오는 2개가 최대라 부족하다. 따라서 $a=4$ 이고 $g(x)$ 가 $(x-1)^2$ 이어야 한다.","확인":"4","스킬":"D11","고비":true},{"제목":"$f(5)+g(5)$ 의 값","힌트":"$f(x)=(x-1)(x-4),\\ g(x)=(x-1)^2$ 에 $x=5$ 를 넣어 더하면?","식":["$f(5)=4\\times1=4,\\ g(5)=4^2=16$","$f(5)+g(5)=20$"],"설명":"$a=4$ 이므로 $f(x)=(x-1)(x-4)$ 이다.","확인":"20","스킬":"A11"}]},"고2-202510-26":{"길":"$k\\ne2$ 이면 두 극한의 차가 $0$ 임을 보여 $k$ 를 정하고 $k=2$ 에서 $a$ 를 구한다","단계":[{"제목":"$k$ 의 값 정하기","힌트":"$k$ 가 $2$ 보다 작을 때와 클 때 $x=k$ 근방에서 $f(x)$ 는 어떤 식이고 극한의 차는?","식":["$k<2$ 이면 $f(x)=-a(x-2)$ 이므로 두 극한이 모두 $-a$, 차는 $0$","$k>2$ 이면 $f(x)=a(x-2)$ 이므로 두 극한이 모두 $a$, 차는 $0$","차가 $6$ 이려면 $k=2$"],"설명":"$k\\ne2$ 이면 $x=k$ 근방에서 $f$ 가 일차식이라 좌·우 극한이 같다. 두 경우 모두 차가 $0$ 이라 $6$ 이 될 수 없으므로 버린다.","확인":null,"스킬":"D12","고비":true},{"제목":"$k=2$ 에서의 좌·우 극한","힌트":"$|x-2|$ 의 절댓값을 $x>2$ 와 $x<2$ 에서 각각 풀어 극한을 구하면?","식":["$\\displaystyle\\lim_{x\\to2+}\\frac{a|x-2|}{x-2}=\\lim_{x\\to2+}\\frac{a(x-2)}{x-2}=a$","$\\displaystyle\\lim_{x\\to2-}\\frac{a|x-2|}{x-2}=\\lim_{x\\to2-}\\frac{-a(x-2)}{x-2}=-a$"],"설명":"$f(2)=0$ 이므로 $f(x)-f(2)=a|x-2|$ 이다.","확인":null,"스킬":"D12"},{"제목":"$a$ 의 값","힌트":"두 극한의 차가 $6$ 이라는 식을 풀면?","식":["$a-(-a)=2a=6$","$a=3$"],"설명":"우극한에서 좌극한을 뺀다.","확인":"3","스킬":"D12"},{"제목":"$f(a+k)$ 의 값","힌트":"$a+k$ 를 구해 $f(x)=3|x-2|$ 에 넣으면?","식":["$a+k=3+2=5$","$f(5)=3|5-2|=9$"],"설명":"$a=3,\\ k=2$ 이다.","확인":"9","스킬":"D12"}]},"고2-202510-28":{"길":"$x=1$ 의 값을 극한으로 바꾼 연속함수에 사잇값 정리를 쓰고 $f(x)\\ne2$ 로 $c=1$ 을 정한다","단계":[{"제목":"연속함수 $g$ 만들기","힌트":"$x=1$ 에서의 값을 극한값으로 바꾼 함수를 만들면 $[0,\\ 2]$ 에서 연속인가?","식":["$g(x)=f(x)\\ (x\\ne1),\\ \\ g(1)=\\displaystyle\\lim_{x\\to1}f(x)=3f(2)$","$f$ 는 $x=1$ 에서만 불연속이므로 $g$ 는 $[0,\\ 2]$ 에서 연속"],"설명":"$f$ 의 불연속은 $x=1$ 의 함숫값이 극한값과 다르기 때문이므로, 그 값을 극한값으로 바꾼 $g$ 는 연속이다.","확인":null,"스킬":"D12"},{"제목":"$g(0)$ 과 $g(2)$ 의 위치","힌트":"$g(0)+g(2)=4$ 이고 두 값이 모두 $2$ 가 아니면 $2$ 와 어떤 관계인가?","식":["$g(0)=f(0)\\ne2,\\ g(2)=f(2)\\ne2,\\ g(0)+g(2)=4$","$g(0)<2<g(2)$ 또는 $g(2)<2<g(0)$"],"설명":"두 값이 모두 $2$ 보다 작거나 모두 $2$ 보다 크면 합이 $4$ 일 수 없으므로 버린다. 평균이 $2$ 이므로 한 쪽은 $2$ 보다 작고 다른 쪽은 크다.","확인":null,"스킬":"C8"},{"제목":"사잇값 정리로 $f(2)$ 구하기","힌트":"$g(c)=2$ 인 $c$ 가 $(0,\\ 2)$ 에 있다면 $f(x)\\ne2$ 라는 조건에서 $c$ 는 어디인가?","식":["사잇값 정리에 의해 $g(c)=2$ 인 $c$ 가 $0<c<2$ 에 존재","$x\\ne1$ 에서는 $g(x)=f(x)\\ne2$ 이므로 $c=1$","$g(1)=3f(2)=2$ 에서 $f(2)=\\dfrac23$"],"설명":"$g$ 가 연속이고 $g(0),\\ g(2)$ 가 $2$ 의 양쪽에 있으므로 $2$ 를 지나는 점이 있다. $x=1$ 이외의 점에서는 $f(x)\\ne2$ 라 그 점은 $x=1$ 뿐이다.","확인":"2/3","스킬":"C8","고비":true},{"제목":"$f(0)$ 과 구하는 비","힌트":"$f(0)+f(2)=4$ 로 $f(0)$ 을 구하고 비를 계산하면?","식":["$f(0)=4-\\dfrac23=\\dfrac{10}3$","$\\dfrac{f(0)}{f(2)}=\\dfrac{10}3\\div\\dfrac23=5$"],"설명":"$\\frac{10}{3}\\div\\frac23=\\frac{10}{3}\\times\\frac32$ 이다.","확인":"5","스킬":"C8"}]},"고2-202510-30":{"길":"$h$ 가 연속이 아닐 수 있는 $t$ 마다 좌·우극한과 함숫값을 맞춰 $a,\\ b,\\ c,\\ k$ 를 정한다","단계":[{"제목":"$h(t)$ 가 끊길 수 있는 점","힌트":"$f$ 가 불연속일 수 있는 $x$ 가 $t$ 또는 $t+k$ 자리에 오는 $t$ 는?","식":["$h(t)=f(t)\\times\\dfrac{f(t+k)-f(t)}{k}$","$f$ 는 $x=-4$ 에서 불연속 ($\\displaystyle\\lim_{x\\to-4}f(x)=0\\ne b$), $x=0$ 에서는 $\\displaystyle\\lim_{x\\to0-}f(x)=4a,\\ f(0)=c$ 이므로 $4a=c$ 일 때만 연속","$h$ 가 연속이 아닐 수 있는 $t$ 는 $-4-k,\\ -k,\\ -4,\\ 0$"],"설명":"$f$ 는 $x=-4,\\ x=0$ 을 제외하면 연속이므로 $t$ 와 $t+k$ 가 이 두 값 중 하나가 되는 $t$ 에서만 $h$ 를 따져 보면 된다.","확인":null,"스킬":"D12"},{"제목":"$t=-4-k$ 에서의 연속 조건","힌트":"$t\\to-4-k$ 일 때 $t+k\\to-4$ 이므로 $f(t+k)$ 의 극한과 $h(-4-k)$ 를 비교하면?","식":["$\\displaystyle\\lim_{t\\to-4-k}h(t)=f(-4-k)\\times\\dfrac{0-f(-4-k)}{k}$","$h(-4-k)=f(-4-k)\\times\\dfrac{b-f(-4-k)}{k}$ 와 같으려면 $b\\,f(-4-k)=0$","$b>0$ 이므로 $f(-4-k)=(-k)(a-4-k)=0$ 에서 $a=k+4$"],"설명":"$t+k\\to-4$ 일 때 $f(t+k)$ 의 극한은 $0$ 이지만 함숫값 $f(-4)$ 는 $b$ 이므로 두 식이 같으려면 $f(-4-k)=0$ 이어야 한다.","확인":null,"스킬":"D12","고비":true},{"제목":"$t=-k$ 에서의 연속 조건","힌트":"$t\\to-k\\pm$ 일 때 $t+k\\to0\\pm$ 이므로 좌·우극한이 같다고 놓으면?","식":["$\\displaystyle\\lim_{t\\to-k+}h(t)=f(-k)\\times\\dfrac{c-f(-k)}{k},\\ \\lim_{t\\to-k-}h(t)=f(-k)\\times\\dfrac{4a-f(-k)}{k}$","$f(-k)\\times(c-4a)=0$ 에서 $f(-k)=(4-k)\\times4\\ne0$ 이므로 $c=4a$"],"설명":"$k>4$ 이므로 $f(-k)=(4-k)\\times4\\ne0$ 이고, $c=4a$ 이면 $f$ 는 $x=0$ 에서도 연속이라 $t=0$ 은 따로 볼 필요가 없다.","확인":null,"스킬":"D12"},{"제목":"$t=-4$ 에서의 연속 조건","힌트":"$t\\to-4$ 일 때 $f(t)$ 의 극한과 $h(-4)$ 를 비교하면?","식":["$\\displaystyle\\lim_{t\\to-4}h(t)=0\\times\\dfrac{f(k-4)-0}{k}=0$","$h(-4)=b\\times\\dfrac{f(k-4)-b}{k}=0$ 에서 $b>0$ 이므로 $f(k-4)=b$"],"설명":"$t\\to-4$ 이면 $f(t)\\to0$ 이고 $f(t+k)\\to f(k-4)$ 이다.","확인":null,"스킬":"D12"},{"제목":"$k$ 의 값","힌트":"(나)의 $f(k)=b$ 와 $f(k-4)=b$ 가 모두 $x>0$ 에서 일어날 때 $k$ 는?","식":["$k>4$ 이므로 $k$ 와 $k-4$ 는 모두 양수이고 $f(x)=-x^2+6x+c$ 위의 점","$f(k)=f(k-4)$ 이므로 두 점은 축 $x=3$ 에 대칭","$\\dfrac{(k-4)+k}{2}=3$ 에서 $k=5$"],"설명":"$k\\ne k-4$ 이므로 같은 함숫값을 갖는 두 점은 축 $x=3$ 에 대해 대칭이다.","확인":"5","스킬":"G11"},{"제목":"$a,\\ b,\\ c$ 의 값","힌트":"$k=5$ 로 $a$ 와 $c$ 를 구하고 $b=f(5)$ 를 계산하면?","식":["$a=k+4=9,\\ c=4a=36$","$b=f(5)=-25+30+36=41$"],"설명":"$k=5$ 는 $k>4$ 를 만족시킨다.","확인":"41","스킬":"D12"},{"제목":"$f(c-a-b)$ 의 값","힌트":"$c-a-b$ 를 구해 $x<-4$ 쪽 식 $(x+4)(x+9)$ 에 넣으면?","식":["$c-a-b=36-9-41=-14$","$f(-14)=(-14+4)(-14+9)=(-10)\\times(-5)=50$"],"설명":"$-14<-4$ 이므로 $f(x)=(x+4)(x+a)$ 에 $a=9$ 를 넣어 계산한다.","확인":"50","스킬":"D12"}]},"고2-202609-05":{"길":"좌·우극한은 함숫값이 아니라 가까이 가는 쪽 그래프의 높이로 읽는다","단계":[{"제목":"$x\\to-1+$ 일 때의 값","힌트":"$x$ 가 $-1$ 의 오른쪽에서 가까이 갈 때 선분이 향하는 높이는?","식":["$-1<x<0$ 의 선분은 열린 점 $(-1,\\ 3)$ 에서 시작한다","$\\displaystyle\\lim_{x\\to-1+}f(x)=3$"],"설명":"$x=-1$ 에 찍힌 점 $(-1,\\ 1)$ 은 함숫값이자 왼쪽 극한의 높이이므로 오른쪽 극한과 관계없다.","확인":"3","스킬":"D12"},{"제목":"$x\\to2-$ 일 때의 값","힌트":"$x$ 가 $2$ 의 왼쪽에서 가까이 갈 때 곡선이 향하는 높이는?","식":["$0<x<2$ 의 곡선은 점 $(2,\\ -1)$ 로 향한다","$\\displaystyle\\lim_{x\\to2-}f(x)=-1$"],"설명":"$x>2$ 에서 시작하는 열린 점 $(2,\\ 0)$ 은 오른쪽 극한이므로 이 극한과 관계없다.","확인":"-1","스킬":"D12","고비":true},{"제목":"두 극한의 합","힌트":"두 극한값을 더하면?","식":["$3+(-1)=2$"],"설명":"오른쪽 극한 $3$ 과 왼쪽 극한 $-1$ 을 더한다.","확인":"2","스킬":"D12"}]},"고2-202609-17":{"길":"교점의 좌표를 $t$ 로 나타내 $(f+g)^2$ 을 만들고 $t-1$ 을 약분한다","단계":[{"제목":"교점의 $x$좌표 $f(t)$","힌트":"곡선과 직선의 식을 같다고 놓고 $x>0$ 을 쓰면 $x$ 는?","식":["$\\dfrac{t+2}{x}=\\dfrac{x}{t-1}$ 에서 $x^2=(t-1)(t+2)$","$x>0$ 이므로 $f(t)=\\sqrt{(t-1)(t+2)}$"],"설명":"$t>1$ 이므로 $(t-1)(t+2)>0$ 이고 $x>0$ 인 해만 취한다.","확인":null,"스킬":"G1"},{"제목":"$f(t)+g(t)$ 의 식","힌트":"$g(t)$ 를 직선 위의 점으로 구해 $f(t)+g(t)$ 를 하나로 묶으면?","식":["$g(t)=\\dfrac{f(t)}{t-1}=\\dfrac{\\sqrt{(t-1)(t+2)}}{t-1}$","$f(t)+g(t)=f(t)\\left(1+\\dfrac1{t-1}\\right)=\\dfrac{t\\sqrt{(t-1)(t+2)}}{t-1}$"],"설명":"$1+\\frac1{t-1}=\\frac{t}{t-1}$ 이다.","확인":null,"스킬":"A2"},{"제목":"$(t-1)(f+g)^2$ 의 약분","힌트":"$(f+g)^2$ 을 제곱해 $(t-1)$ 을 곱하면 약분되어 남는 식은?","식":["$(f+g)^2=\\dfrac{t^2(t-1)(t+2)}{(t-1)^2}=\\dfrac{t^2(t+2)}{t-1}$","$(t-1)(f+g)^2=t^2(t+2)$"],"설명":"제곱근이 제곱으로 없어지고 분모의 $(t-1)^2$ 과 분자의 $(t-1)$ 이 약분된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$t\\to1+$ 의 극한","힌트":"$t^2(t+2)$ 에 $t\\to1+$ 를 대입하면?","식":["$\\displaystyle\\lim_{t\\to1+}t^2(t+2)=1\\times3=3$"],"설명":"다항식이므로 $t=1$ 을 그대로 넣는다.","확인":"3","스킬":"D3"}]},"고2-202609-30":{"길":"(가)로 경우를 나누고 (나)를 두 꼭짓점 높이의 조건으로 바꿔 $a,\\ b$ 를 정한다","단계":[{"제목":"$b$ 의 범위와 (가)의 경우 나누기","힌트":"$f(1)>0$ 에서 $b$ 의 범위를 구하고 영점을 모아 집합의 원소가 4개인 경우를 나누면?","식":["$f(1)=-\\dfrac{49}{16}(1-b)>0$ 에서 $b>1$","영점은 $x\\ge0$ 에서 $0,\\ b$, $x<0$ 에서 $-2$ 와 $a$ ($a<0$ 일 때만 음수)","(가)를 만족시키는 경우는 음의 영점이 $-2$ 뿐 ($a=-2$ 또는 $0\\le a<2$) 이고 $b\\ne2$ 이거나, 음의 영점이 $-2,\\ a$ 이고 $b=2$ 또는 $b=-a$"],"설명":"집합의 원소는 $0$ 이 아닌 영점과 그 부호를 바꾼 수이다. 음의 영점이 $-2$ 하나뿐이면 원소는 $\\pm2,\\ \\pm b$ 라 $b=2$ 일 때는 2개로 줄어 버리고 $b\\ne2$ 일 때 4개이다. 음의 영점이 $-2,\\ a$ 두 개이면 $\\pm2,\\ \\pm a,\\ \\pm b$ 가 겹쳐 4개가 되어야 하므로 $b=2$ 또는 $b=-a$ 이다.","확인":null,"스킬":"C2"},{"제목":"(나)를 만족시키는 $\\alpha$ 의 조건","힌트":"$g(t)\\ge1$ 임을 쓰면 $\\alpha$ 와 $-\\alpha$ 가 각각 어떤 조건을 만족해야 하는가?","식":["$g(t)\\ge1$ 이므로 $g(\\alpha)\\ne\\displaystyle\\lim_{t\\to\\alpha+}g(t)$ 이고 곱이 같으면 $g(-\\alpha)\\ne\\displaystyle\\lim_{t\\to-\\alpha+}g(t)$ 도 성립해야 한다","$g(\\alpha)\\ne\\displaystyle\\lim_{t\\to\\alpha+}g(t)$ 인 $\\alpha\\ne0$ 은 꼭짓점의 높이 $\\dfrac{49}{64}b^2$ 와 $-\\dfrac{(a+2)^2}{4}$","$\\alpha$ 와 $-\\alpha$ 가 모두 그러려면 $\\dfrac{49}{64}b^2=\\dfrac{(a+2)^2}{4}$"],"설명":"$x<0$ 쪽과 $x\\ge0$ 쪽이 합쳐 모든 실수 값을 지나므로 $g(t)\\ge1$ 이다. 곱이 같은데 $-\\alpha$ 쪽에서 $g(-\\alpha)=\\lim_{t\\to-\\alpha+}g(t)$ 이면 양변을 나눠 $g(\\alpha)=\\lim_{t\\to\\alpha+}g(t)$ 가 되어 모순이다. 그래서 두 꼭짓점의 높이가 부호만 반대여야 한다.","확인":null,"스킬":"D12","고비":true},{"제목":"$b\\ne2$ 이고 음의 영점이 하나인 경우","힌트":"$a=-2$ 와 $0\\le a<2$ 에서 (나)의 두 조건을 따지면?","식":["$a=-2$: $-\\dfrac{(a+2)^2}{4}=0$ 이라 $\\alpha\\ne0$ 의 후보는 $\\dfrac{49}{64}b^2$ 하나뿐이어서 $-\\alpha$ 가 후보가 될 수 없다","$0\\le a<2$: $\\beta=\\dfrac{49}{64}b^2=\\dfrac{(a+2)^2}{4}$ 이면 $g(\\beta)=2,\\ \\displaystyle\\lim_{t\\to\\beta+}g(t)=1,\\ g(-\\beta)=2,\\ \\lim_{t\\to-\\beta+}g(t)=3$","$g(\\beta)g(-\\beta)=4\\ne3=1\\times3$"],"설명":"두 경우 모두 (나)를 만족시키지 못해 버린다. $0\\le a<2$ 에서 $t=\\beta$ 는 $x\\ge0$ 쪽 꼭짓점에서 1개, $x<0$ 쪽에서 1개 만나고, $t>\\beta$ 에서는 $x\\ge0$ 쪽 교점이 사라진다.","확인":null,"스킬":"C2"},{"제목":"$b\\ne2$ 이고 $b=-a$ 인 경우","힌트":"$b=-a$ 를 (나)의 조건식에 넣어 $a$ 를 구하고 $f(1)>0$ 과 비교하면?","식":["$\\dfrac{49}{64}a^2=\\dfrac{(a+2)^2}{4}$ 에서 $7|a|=4|a+2|$","$a<0$ 이면 $a=-\\dfrac8{11}$ 이고 $b=-a=\\dfrac8{11}<1$"],"설명":"$f(1)>0$ 이려면 $b>1$ 이어야 하므로 버린다. $a<-2$ 쪽에서는 $a=\\frac83$ 이 나오지만 $a<0$ 에 맞지 않는다.","확인":null,"스킬":"C2"},{"제목":"$b=2$ 인 경우의 $a$","힌트":"$b=2$ 이면 음의 영점이 둘이어야 하므로 $a$ 의 범위를 정하고 (나)의 조건식을 풀면?","식":["$a<0,\\ a\\ne-2$ 이고 $\\dfrac{49}{16}=\\dfrac{(a+2)^2}{4}$ 에서 $a+2=\\pm\\dfrac72$","$a=\\dfrac32$ 또는 $a=-\\dfrac{11}2$ 이고 $a<0$ 이므로 $a=-\\dfrac{11}2$"],"설명":"$a=\\frac32$ 는 음의 영점이 $-2$ 하나뿐이라 (가)를 만족시키지 못해 버린다. $a=-\\frac{11}2$ 에서 $\\beta=\\frac{49}{16}$ 이면 $g(\\beta)=3,\\ \\lim_{t\\to\\beta+}g(t)=2,\\ g(-\\beta)=2,\\ \\lim_{t\\to-\\beta+}g(t)=3$ 이고 $3\\times2=2\\times3$ 이라 (나)를 만족시킨다.","확인":"-11/2","스킬":"C2"},{"제목":"$f(-8)$ 의 값","힌트":"$x=-8$ 은 어느 쪽 식에 들어가며 값은?","식":["$f(-8)=(-8+2)\\left(-8+\\dfrac{11}2\\right)$","$=(-6)\\times\\left(-\\dfrac52\\right)=15$"],"설명":"$-8<0$ 이므로 $x<0$ 쪽 식 $(x+2)(x-a)$ 에 $a=-\\frac{11}2$ 를 넣는다.","확인":"15","스킬":"G1"}]},"ns-055aec0a17ff":{"길":"분자가 $0$ 이 되는 조건을 쓰고 분자를 유리화해 $x+1$ 을 약분한다","단계":[{"제목":"분자가 $0$ 이 되는 조건","힌트":"$x\\to-1$ 에서 분모가 $0$ 이 되는데 극한이 존재하려면 분자는?","식":["분모 $\\to0$ 이므로 분자 $\\sqrt{-1+a}-b\\to0$","$\\sqrt{a-1}=b$ 에서 $a=b^2+1\\ (b\\ge0)$"],"설명":"분모가 $0$ 으로 가는데 극한이 존재하므로 분자도 $0$ 으로 간다. 제곱근은 $0$ 이상이므로 $b\\ge0$ 이다.","확인":null,"스킬":"D11"},{"제목":"분자의 유리화","힌트":"$a=b^2+1$ 을 넣고 분자를 유리화하면 $x+1$ 이 약분되는 꼴은?","식":["$\\dfrac{\\sqrt{x+b^2+1}-b}{x+1}=\\dfrac{(x+b^2+1)-b^2}{(x+1)\\left(\\sqrt{x+b^2+1}+b\\right)}=\\dfrac{1}{\\sqrt{x+b^2+1}+b}$"],"설명":"$(x+b^2+1)-b^2=x+1$ 이므로 분모의 $x+1$ 이 약분된다.","확인":null,"스킬":"D11","고비":true},{"제목":"$b$ 의 값","힌트":"$x\\to-1$ 로 보낸 값이 $\\dfrac12$ 과 같다고 놓으면?","식":["$\\displaystyle\\lim_{x\\to-1}\\frac{1}{\\sqrt{x+b^2+1}+b}=\\frac{1}{b+b}=\\frac1{2b}$","$\\dfrac1{2b}=\\dfrac12$ 에서 $b=1$"],"설명":"$x=-1$ 이면 $\\sqrt{x+b^2+1}=\\sqrt{b^2}=b$ 이다.","확인":"1","스킬":"D11"},{"제목":"$a+b$ 의 값","힌트":"$a=b^2+1$ 에 $b$ 를 넣어 $a$ 를 구하고 더하면?","식":["$a=b^2+1=2$","$a+b=3$"],"설명":"구한 $b=1$ 을 $a=b^2+1$ 에 넣는다.","확인":"3","스킬":"D11"}]},"ns-0643f3046aca":{"길":"$\\overline{\\mathrm{PA}}$ 를 $a$ 로 나타내고 $a-\\sqrt{a^2-a}$ 를 유리화해 최고차항끼리 비교한다","단계":[{"제목":"$\\overline{\\mathrm{PQ}}$ 와 $\\overline{\\mathrm{PA}}$","힌트":"$\\mathrm{Q}$ 와 $\\mathrm{A}$ 의 좌표를 구해 두 길이를 $a$ 로 나타내면?","식":["$\\mathrm{Q}(0,\\ \\sqrt{a-1}),\\ \\mathrm{A}(1,\\ 0)$ 이므로 $\\overline{\\mathrm{PQ}}=a$","$\\overline{\\mathrm{PA}}=\\sqrt{(a-1)^2+(a-1)}=\\sqrt{a^2-a}$"],"설명":"$\\mathrm{A}$ 는 $y=\\sqrt{x-1}$ 이 $x$축과 만나는 점이다. $(a-1)^2+(a-1)=a^2-a$ 이다.","확인":null,"스킬":"A11"},{"제목":"$a-\\sqrt{a^2-a}$ 의 유리화","힌트":"분자와 분모에 $a+\\sqrt{a^2-a}$ 를 곱하면?","식":["$a-\\sqrt{a^2-a}=\\dfrac{a^2-(a^2-a)}{a+\\sqrt{a^2-a}}=\\dfrac{a}{a+\\sqrt{a^2-a}}$"],"설명":"$\\infty-\\infty$ 꼴이므로 합과 차의 곱을 이용해 분수로 바꾼다.","확인":null,"스킬":"A11","고비":true},{"제목":"$a\\to\\infty$ 의 극한","힌트":"분모·분자를 $a$ 로 나누고 $a\\to\\infty$ 로 보내면?","식":["$\\displaystyle\\lim_{a\\to\\infty}\\frac{a}{a+\\sqrt{a^2-a}}=\\lim_{a\\to\\infty}\\frac{1}{1+\\sqrt{1-\\frac1a}}=\\frac12$"],"설명":"$a>0$ 이므로 $\\sqrt{a^2-a}=a\\sqrt{1-\\frac1a}$ 이다.","확인":"1/2","스킬":"A11"}]},"ns-06a8cec67460":{"길":"(나)로 $f$ 의 꼴을 정하고 (가)에서 분자가 $x-2$ 를 인수로 가짐을 쓴다","단계":[{"제목":"$f(x)$ 의 꼴","힌트":"(나)의 극한이 $2$ 이려면 $f(x)$ 의 차수와 최고차항의 계수는?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{f(x)}{2x^2-3x-2}=2$ 이므로 $f(x)$ 는 이차식이고 최고차항의 계수는 $2\\times2=4$","$f(x)=4x^2+ax+b$"],"설명":"분모의 최고차항이 $2x^2$ 이므로 분자의 최고차항은 그 $2$ 배인 $4x^2$ 이다.","확인":"4","스킬":"A11"},{"제목":"$f(2)=0$ 조건","힌트":"$x\\to2$ 에서 분모가 $0$ 이 되는데 극한이 존재하려면 $f(2)$ 는?","식":["분모 $x^2-5x+6=(x-2)(x-3)\\to0$ 이므로 $f(2)=0$","$16+2a+b=0$ 에서 $b=-2a-16$"],"설명":"분모가 $0$ 으로 가는데 극한이 존재하므로 분자도 $0$ 으로 간다.","확인":null,"스킬":"D11","고비":true},{"제목":"$a$ 와 $b$ 의 값","힌트":"$f(x)$ 를 $(x-2)$ 로 묶어 약분하면?","식":["$f(x)=4x^2+ax-2a-16=(x-2)(4x+a+8)$","$\\displaystyle\\lim_{x\\to2}\\frac{(x-2)(4x+a+8)}{(x-2)(x-3)}=\\frac{16+a}{-1}=1$ 에서 $a=-17,\\ b=18$"],"설명":"$x\\to2$ 이면 $x-2\\ne0$ 이므로 약분할 수 있고 남은 식에 $x=2$ 를 넣는다.","확인":"-17","스킬":"D11"},{"제목":"$f(3)$ 의 값","힌트":"$f(x)=4x^2-17x+18$ 에 $x=3$ 을 넣으면?","식":["$f(3)=36-51+18=3$"],"설명":"각 항을 따로 계산해 더한다.","확인":"3","스킬":"A11"}]},"ns-0839b8362dc5":{"길":"좌극한·우극한·극한을 함숫값과 구별해 그래프의 높이로 읽는다","단계":[{"제목":"$x\\to-1+$ 일 때의 값","힌트":"$x$ 가 $-1$ 의 오른쪽에서 가까이 갈 때 곡선이 향하는 높이는?","식":["$x>-1$ 의 곡선은 열린 점 $(-1,\\ -1)$ 에서 시작한다","$\\displaystyle\\lim_{x\\to-1+}f(x)=-1$"],"설명":"$x=-1$ 에 찍힌 점 $(-1,\\ 1)$ 은 왼쪽 곡선의 끝이므로 오른쪽 극한과 관계없다.","확인":null,"스킬":"D12"},{"제목":"$x\\to1$ 일 때의 값","힌트":"$x=1$ 의 양쪽에서 그래프가 향하는 높이가 같은가?","식":["$x\\to1-$ 이면 곡선이 $(1,\\ 2)$ 로, $x\\to1+$ 이면 선분이 $(1,\\ 2)$ 에서 시작한다","$\\displaystyle\\lim_{x\\to1}f(x)=2$"],"설명":"좌극한과 우극한이 모두 $2$ 로 같으므로 극한값이 존재한다.","확인":"2","스킬":"D12"},{"제목":"$x\\to2+$ 일 때의 값","힌트":"$x$ 가 $2$ 의 오른쪽에서 가까이 갈 때 오른쪽 직선이 향하는 높이는?","식":["$x>2$ 의 직선은 점 $(2,\\ -1)$ 에서 시작한다","$\\displaystyle\\lim_{x\\to2+}f(x)=-1$"],"설명":"$x<2$ 쪽 선분 끝의 열린 점 $(2,\\ 1)$ 은 왼쪽 극한이므로 버린다.","확인":"-1","스킬":"D12","고비":true},{"제목":"세 값의 합","힌트":"세 극한값을 더하면?","식":["$-1+2+(-1)=0$"],"설명":"$x\\to1$ 은 양쪽 극한이 같아 하나의 값 $2$ 이다.","확인":"0","스킬":"D12"}]},"ns-091ebec2a3ff":{"길":"선지마다 해당 $x$ 근방의 그래프 높이를 읽고 함숫값과 구별한다","단계":[{"제목":"선지 ① 과 ④ 의 극한","힌트":"$x\\to0+$ 일 때 선분이 향하는 높이와 $x\\to3+$ 일 때 곡선이 향하는 높이는?","식":["$\\displaystyle\\lim_{x\\to0+}f(x)=0,\\ \\ \\lim_{x\\to3+}f(x)=0$"],"설명":"①은 $-1$ 이 아니라 $0$ 이고 ④는 $1$ 이 아니라 $0$ 이므로 버린다. $-1$ 은 $f(1)$ 의 값이다.","확인":"0","스킬":"D12"},{"제목":"선지 ③ 과 ⑤ 의 극한","힌트":"$x=2$ 의 양쪽에서 곡선이 향하는 높이와 $x\\to4-$ 일 때 곡선이 향하는 높이는?","식":["$\\displaystyle\\lim_{x\\to2}f(x)=2$ (양쪽 모두 열린 점 $(2,\\ 2)$ 로 향함)","$\\displaystyle\\lim_{x\\to4-}f(x)=3$"],"설명":"③은 $3$ 이 아니라 $2$ 이고 ⑤는 $0$ 이 아니라 $3$ 이므로 버린다. $x=2$ 에 찍힌 $f(2)=3$ 은 극한과 관계없다.","확인":"2","스킬":"D12","고비":true},{"제목":"선지 ② 의 극한","힌트":"$x\\to1+$ 일 때 곡선이 향하는 높이는?","식":["$x>1$ 의 곡선은 열린 점 $(1,\\ 1)$ 에서 시작한다","$\\displaystyle\\lim_{x\\to1+}f(x)=1$"],"설명":"②는 선지의 값과 같으므로 옳다.","확인":"1","스킬":"D12"}]},"ns-0dcdc182c9f1":{"길":"선지마다 극한을 직접 계산하고 $\\frac00$ 꼴은 인수분해로 약분한다","단계":[{"제목":"선지 ①~④ 의 극한","힌트":"①~④ 를 각각 대입, 분모·분자를 나누기, 발산 판단으로 계산하면?","식":["① $\\dfrac{2^2+1}{2\\times2-3}=5$, ② $\\displaystyle\\lim_{x\\to\\infty}\\frac{5+\\frac3x+\\frac2{x^2}}{1+\\frac1{x^2}}=5$","③ $x\\to0+$ 이면 $\\dfrac2x\\to\\infty$ 이므로 $\\infty$, ④ $x\\to-\\infty$ 이면 $\\dfrac2{x^2}\\to0$ 이므로 $3$"],"설명":"①~④ 는 모두 선지에 적힌 값과 같으므로 옳다.","확인":null,"스킬":"D11"},{"제목":"선지 ⑤ 의 극한","힌트":"분자를 인수분해해 $x-3$ 을 약분하면 극한값은?","식":["$\\dfrac{x^2-7x+12}{x-3}=\\dfrac{(x-3)(x-4)}{x-3}=x-4$","$\\displaystyle\\lim_{x\\to3}(x-4)=-1\\ne\\infty$"],"설명":"⑤ 는 극한이 $-1$ 이라 $\\infty$ 가 아니므로 옳지 않다. 따라서 옳지 않은 것은 ⑤ 이다.","확인":"-1","스킬":"D11","고비":true}]},"ns-0eda27f7b196":{"길":"선지 다섯 개의 극한을 각각 구해 크기를 비교하고 ④ 는 분자를 유리화한다","단계":[{"제목":"선지 ①, ②, ⑤ 의 극한","힌트":"① 은 최고차항의 비, ② 는 분모의 발산, ⑤ 는 대입으로 구하면?","식":["① $\\displaystyle\\lim_{x\\to\\infty}\\frac{10x}{2x+1}=\\frac{10}{2}=5$","② $x\\to-\\infty$ 이면 분모 $\\to\\infty$ 이므로 극한값은 $0$","⑤ $x\\to0$ 이면 $\\dfrac{6}{2}=3$"],"설명":"⑤ 는 분모가 $x=0$ 에서 $2$ 이므로 그대로 대입한다.","확인":null,"스킬":"D11"},{"제목":"선지 ③ 의 극한","힌트":"분자와 분모를 인수분해해 $x-2$ 를 약분하면?","식":["$\\dfrac{x^2-6x+8}{x^2-4}=\\dfrac{(x-2)(x-4)}{(x-2)(x+2)}=\\dfrac{x-4}{x+2}$","$x\\to2$ 이면 $\\dfrac{-2}{4}=-\\dfrac12$"],"설명":"$x\\to2$ 에서 $x-2\\ne0$ 이므로 약분할 수 있다.","확인":"-1/2","스킬":"D11"},{"제목":"선지 ④ 의 극한","힌트":"분모의 $\\sqrt{x+5}-2$ 를 유리화하면 $x+1$ 이 약분되는 꼴은?","식":["$\\dfrac{x+1}{\\sqrt{x+5}-2}=\\dfrac{(x+1)\\left(\\sqrt{x+5}+2\\right)}{(x+5)-4}=\\sqrt{x+5}+2$","$x\\to-1$ 이면 $2+2=4$"],"설명":"$(x+5)-4=x+1$ 이므로 분자의 $x+1$ 과 약분된다.","확인":"4","스킬":"D11","고비":true},{"제목":"극한값의 크기 비교","힌트":"①~⑤ 의 값 중 가장 큰 값은?","식":["$5,\\ 0,\\ -\\dfrac12,\\ 4,\\ 3$ 중 가장 큰 값은 $5$"],"설명":"가장 큰 값은 ① 의 $5$ 이다.","확인":"5","스킬":"D11"}]},"ns-0f264bdf1f7b":{"길":"발산과 좌·우극한의 불일치를 걸러 내고 $x\\to0$ 에서 수렴하는 선지를 찾는다","단계":[{"제목":"발산하는 선지 ①, ③","힌트":"①, ③ 의 식이 $x\\to\\infty$, $x\\to0$ 에서 어떤 값으로 가는가?","식":["① $x\\to\\infty$ 이면 $\\sqrt{x-3}\\to\\infty$","③ $x\\to0$ 이면 $\\dfrac1{x^2}\\to\\infty$ 이므로 $1-\\dfrac1{x^2}\\to-\\infty$"],"설명":"극한값이 존재하려면 유한한 값으로 수렴해야 하므로 $\\pm\\infty$ 로 가는 ①, ③ 은 버린다.","확인":null,"스킬":"D12"},{"제목":"좌·우극한이 다른 선지 ②, ④","힌트":"가우스 기호를 $x\\to0+$ 와 $x\\to0-$ 로 나눠 $\\left[x\\right]$ 의 값을 정하면 좌극한과 우극한은?","식":["② $x\\to0+$ 이면 $x-[x]\\to0-0=0$, $x\\to0-$ 이면 $[x]=-1$ 이므로 $x+1\\to1$","④ $x\\to0+$ 이면 $[x]=0$ 이므로 $0$, $x\\to0-$ 이면 $\\dfrac{[x]^2}{-x}=\\dfrac{1}{-x}\\to\\infty$"],"설명":"②, ④ 는 좌극한과 우극한이 달라 극한값이 존재하지 않으므로 버린다.","확인":"1","스킬":"N7","고비":true},{"제목":"선지 ⑤ 의 극한","힌트":"$\\dfrac{x^2}{|x|}$ 을 $|x|$ 로 간단히 하고 좌·우극한을 구하면?","식":["$\\dfrac{x^2}{|x|}=|x|$ 이므로 $x\\to0+$ 와 $x\\to0-$ 에서 모두 $0$","$\\displaystyle\\lim_{x\\to0}\\frac{x^2}{|x|}=0$"],"설명":"좌극한과 우극한이 같으므로 극한값이 존재한다. 따라서 극한값이 존재하는 것은 ⑤ 이다.","확인":"0","스킬":"D12"}]},"ns-1c3b0f701fdc":{"길":"그래프에서 함숫값·극한을 읽고, 합성함수는 안쪽 값이 다가오는 방향부터 정한다","단계":[{"제목":"①②③ 그래프에서 읽기","힌트":"$x=-1$ 에서 좌·우극한은 각각 얼마인가?","식":["$f(-1)=2,\\ \\lim_{x\\to1+}f(x)=-2$","$\\lim_{x\\to-1-}f(x)=0,\\ \\lim_{x\\to-1+}f(x)=0$ 이므로 $\\lim_{x\\to-1}f(x)=0$"],"설명":"$x=-1$ 에서 닫힌 점은 $(-1,2)$ 이고 좌·우 곡선은 모두 열린 점 $(-1,0)$ 으로 모인다. 극한값과 함숫값이 달라도 극한은 존재하므로 ①②③ 은 옳다.","확인":"0","스킬":"D12"},{"제목":"⑤ 불연속인 점 찾기","힌트":"극한값과 함숫값이 어긋나거나 좌·우극한이 다른 $x$ 는 어디인가?","식":["$x=-1$: 극한 $0\\ne f(-1)=2$","$x=1$: 좌극한 $0$, 우극한 $-2$ 로 서로 다름"],"설명":"그 밖의 점에서는 그래프가 끊기지 않는다. 불연속인 점은 $x=-1,\\ 1$ 의 $2$ 개이므로 ⑤ 는 옳다.","확인":null,"스킬":"D12"},{"제목":"안쪽 $f(x)$ 가 다가오는 방향","힌트":"$x\\to0+$ 일 때 $f(x)$ 는 $1$ 보다 작은 쪽에서 오는가, 큰 쪽에서 오는가?","식":["$x\\to0+$ 일 때 $f(x)<1$ 이고 $f(x)\\to1$ 이므로 $f(x)\\to1-$"],"설명":"$x=0$ 에서 그래프의 꼭대기 높이가 $1$ 이고, $x\\ne0$ 근처에서는 그보다 낮다. 안쪽 값은 $1$ 에 아래쪽에서 다가간다.","확인":null,"스킬":"T6","고비":true},{"제목":"④ 의 극한값","힌트":"$y\\to1-$ 일 때 $f(y)$ 의 극한은?","식":["$\\displaystyle\\lim_{x\\to0+}f(f(x))=\\lim_{y\\to1-}f(y)=0$"],"설명":"$y\\to1-$ 이면 곡선은 $(1,0)$ 으로 내려간다. 값은 $0$ 이어서 ④ 의 $1$ 과 다르므로 ④ 가 옳지 않다. $y\\to1+$ 의 값 $-2$ 는 방향이 달라 쓰지 않는다.","확인":"0","스킬":"T6"}]},"ns-1c6d26278362":{"길":"안쪽 식이 $1$, $4$ 에 어느 쪽에서 다가가는지 정한 뒤 그래프의 우극한·좌극한을 읽는다","단계":[{"제목":"첫째 극한의 값","힌트":"$\\dfrac{t+1}{t-1}$ 은 $t\\to\\infty$ 일 때 $1$ 의 어느 쪽에서 다가가는가?","식":["$\\dfrac{t+1}{t-1}=1+\\dfrac{2}{t-1}\\to1+$","$\\displaystyle\\lim_{t\\to\\infty}f\\!\\left(\\dfrac{t+1}{t-1}\\right)=\\lim_{x\\to1+}f(x)=1$"],"설명":"$t>1$ 이면 $\\dfrac{2}{t-1}>0$ 이어서 안쪽 값은 $1$ 보다 크다. $x=1$ 의 오른쪽 곡선은 닫힌 점 $(1,1)$ 에서 시작하므로 우극한은 $1$ 이다. 왼쪽의 열린 점 높이 $2$ 는 좌극한이어서 쓰지 않는다.","확인":"1","스킬":"T6"},{"제목":"둘째 극한의 값","힌트":"$\\dfrac{8t+1}{2t-1}$ 은 $t\\to-\\infty$ 일 때 $4$ 의 어느 쪽에서 다가가는가?","식":["$\\dfrac{8t+1}{2t-1}=4+\\dfrac{5}{2t-1}\\to4-$","$\\displaystyle\\lim_{t\\to-\\infty}f\\!\\left(\\dfrac{8t+1}{2t-1}\\right)=\\lim_{x\\to4-}f(x)=5$"],"설명":"$t<0$ 이면 $2t-1<0$ 이어서 $\\dfrac{5}{2t-1}<0$ 이고 안쪽 값은 $4$ 보다 작다. $x=4$ 의 왼쪽 곡선은 열린 점 $(4,5)$ 로 올라간다. 함숫값 $f(4)=3$ 은 극한과 무관하므로 쓰지 않는다.","확인":"5","스킬":"D12","고비":true},{"제목":"두 극한의 합","힌트":"앞의 두 극한값을 더하면?","식":["$1+5=6$"],"설명":"두 극한이 각각 존재하므로 합의 극한은 극한값의 합이다.","확인":"6","스킬":"T6"}]},"ns-22ce615f82cc":{"길":"직선과 포물선의 연립으로 $\\mathrm{Q}$ 를 구하고 수직이등분선의 $y$절편을 $a$ 로 나타낸 뒤 $a\\to0$ 을 취한다","단계":[{"제목":"점 $\\mathrm{Q}$ 의 좌표","힌트":"직선 $l$ 과 $y=x^2$ 을 연립했을 때 $x=1$ 이 아닌 근은?","식":["$l:\\ y=a(x-1)+1$","$x^2-ax+a-1=(x-1)(x-a+1)=0$","$\\mathrm{Q}\\left(a-1,\\ (a-1)^2\\right)$"],"설명":"$\\mathrm{P}$ 의 $x$ 좌표 $1$ 이 한 근이므로 다른 한 근은 $x=a-1$ 이다.","확인":null,"스킬":"S4"},{"제목":"선분 $\\mathrm{PQ}$ 의 중점","힌트":"두 점의 $x$ 좌표끼리, $y$ 좌표끼리 평균하면?","식":["$\\mathrm{M}\\left(\\dfrac{a}{2},\\ \\dfrac{a^2-2a+2}{2}\\right)$"],"설명":"$x$ 좌표는 $\\dfrac{1+(a-1)}{2}=\\dfrac a2$, $y$ 좌표는 $\\dfrac{1+(a-1)^2}{2}=\\dfrac{a^2-2a+2}{2}$ 이다.","확인":null,"스킬":"S4"},{"제목":"수직이등분선의 $y$절편","힌트":"기울기가 $-\\dfrac1a$ 이고 $\\mathrm{M}$ 을 지나는 직선이 $y$축과 만나는 높이는?","식":["$y=-\\dfrac1a\\left(x-\\dfrac a2\\right)+\\dfrac{a^2-2a+2}{2}$","$x=0$ 이면 $y=\\dfrac12+\\dfrac{a^2-2a+2}{2}=\\dfrac{a^2-2a+3}{2}$"],"설명":"직선 $l$ 의 기울기가 $a$ 이므로 수직인 직선의 기울기는 $-\\dfrac1a$ 이다. $a\\ne0$ 이어서 정의된다.","확인":null,"스킬":"A11","고비":true},{"제목":"$a\\to0$ 의 극한","힌트":"$\\mathrm{R}$ 의 $y$ 좌표에서 $a\\to0$ 으로 보내면?","식":["$\\displaystyle\\lim_{a\\to0}\\frac{a^2-2a+3}{2}=\\frac32$"],"설명":"다항식이므로 $a=0$ 을 그대로 넣는다.","확인":"3/2","스킬":"A11"}]},"ns-2c954d44d1e2":{"길":"부등식을 세제곱해 양변을 $2x^3+1$ 로 나눈 뒤 두 극한이 같음을 이용한다","단계":[{"제목":"부등식을 세제곱하고 나누기","힌트":"$x$ 가 충분히 클 때 $2x+3$ 의 부호는? 그때 세제곱하면 부등호는?","식":["$x>-\\dfrac32$ 이면 $0<2x+3<f(x)<2x+5$","$(2x+3)^3<\\{f(x)\\}^3<(2x+5)^3$","$\\dfrac{(2x+3)^3}{2x^3+1}<\\dfrac{\\{f(x)\\}^3}{2x^3+1}<\\dfrac{(2x+5)^3}{2x^3+1}$ ($x>0$)"],"설명":"양수끼리는 세제곱해도 부등호 방향이 그대로이다. $x\\to\\infty$ 이므로 $x>0$ 만 보면 되고 $2x^3+1>0$ 이어서 나눠도 방향이 같다. $2x+3\\le0$ 인 구간은 $x\\to\\infty$ 에서 쓰지 않는다.","확인":null,"스킬":"C9"},{"제목":"양쪽 극한과 끼움","힌트":"왼쪽 식과 오른쪽 식의 극한은 각각?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{(2x+3)^3}{2x^3+1}=\\frac82=4$","$\\displaystyle\\lim_{x\\to\\infty}\\frac{(2x+5)^3}{2x^3+1}=\\frac82=4$","$\\displaystyle\\lim_{x\\to\\infty}\\frac{\\{f(x)\\}^3}{2x^3+1}=4$"],"설명":"분모·분자의 최고차항 계수의 비는 $8:2$ 이다. 양쪽 극한이 같으므로 가운데 식의 극한도 같다.","확인":"4","스킬":"C9","고비":true}]},"ns-2d60a08ba0f6":{"길":"$\\overline{\\mathrm{AP}}^2$ 과 $\\mathrm{Q}$ 의 좌표를 $t$ 로 나타낸 뒤 $\\overline{\\mathrm{AQ}}^2$ 와의 비의 극한을 구한다","단계":[{"제목":"$\\overline{\\mathrm{AP}}^2$ 의 식","힌트":"$\\mathrm{A}(-1,0)$, $\\mathrm{P}(t,t+1)$ 의 좌표 차를 제곱해 더하면?","식":["$\\overline{\\mathrm{AP}}^2=(t+1)^2+(t+1)^2=2(t+1)^2$"],"설명":"$x$ 좌표의 차와 $y$ 좌표의 차가 모두 $t+1$ 이다.","확인":null,"스킬":"S4"},{"제목":"점 $\\mathrm{Q}$ 와 $\\overline{\\mathrm{AQ}}^2$","힌트":"$y=x+1$ 에 수직이고 $\\mathrm{P}$ 를 지나는 직선이 $y$축과 만나는 점은?","식":["$y=-(x-t)+t+1=-x+2t+1$","$\\mathrm{Q}(0,\\ 2t+1)$","$\\overline{\\mathrm{AQ}}^2=1^2+(2t+1)^2=4t^2+4t+2$"],"설명":"기울기가 $1$ 인 직선에 수직이면 기울기는 $-1$ 이다. $x=0$ 을 넣어 $y$절편을 구한다.","확인":null,"스킬":"S4","고비":true},{"제목":"비의 극한","힌트":"분모·분자를 최고차항 $t^2$ 으로 나누고 $t\\to\\infty$ 로 보내면?","식":["$\\displaystyle\\lim_{t\\to\\infty}\\frac{4t^2+4t+2}{2t^2+4t+2}=\\lim_{t\\to\\infty}\\frac{4+\\frac4t+\\frac2{t^2}}{2+\\frac4t+\\frac2{t^2}}=2$"],"설명":"$\\dfrac4t$, $\\dfrac2{t^2}$ 은 $0$ 으로 가므로 최고차항 계수의 비 $4:2$ 만 남는다.","확인":"2","스킬":"A11"}]},"ns-2ff6e8cbd28d":{"길":"$x-2=t$ 로 치환해 $\\lim\\dfrac{f(t)}{t}$ 의 값을 얻고 분모·분자를 $x$ 로 나눈다","단계":[{"제목":"치환과 인수분해","힌트":"$t=x-2$ 로 놓으면 $x^2-x-2$ 는 어떻게 쓰이는가?","식":["$x^2-x-2=(x-2)(x+1)=t(t+3)$","$\\displaystyle\\lim_{t\\to0}\\frac{f(t)}{t(t+3)}=1$"],"설명":"$x\\to2$ 는 $t\\to0$ 이고 $x+1=t+3$ 이다.","확인":null,"스킬":"A1"},{"제목":"$\\lim\\dfrac{f(t)}{t}$ 의 값","힌트":"$\\dfrac{f(t)}{t}$ 를 $\\dfrac{f(t)}{t(t+3)}$ 과 $t+3$ 의 곱으로 쓰면?","식":["$\\dfrac{f(t)}{t}=\\dfrac{f(t)}{t(t+3)}\\cdot(t+3)$","$\\displaystyle\\lim_{t\\to0}\\frac{f(t)}{t}=1\\cdot3=3$"],"설명":"곱의 극한은 각 극한의 곱이다. $t\\to0$ 일 때 $t+3\\to3$ 이다.","확인":"3","스킬":"D3","고비":true},{"제목":"분모·분자를 $x$ 로 나누기","힌트":"$\\dfrac{f(x)}{x}$ 가 나타나도록 $x$ 로 나누면?","식":["$\\dfrac{-6x^2+3x+5f(x)}{3x+2f(x)}=\\dfrac{-6x+3+5\\cdot\\frac{f(x)}{x}}{3+2\\cdot\\frac{f(x)}{x}}$"],"설명":"$x\\to0$ 이지만 $x\\ne0$ 이므로 $x$ 로 나눌 수 있다.","확인":null,"스킬":"A1"},{"제목":"극한값","힌트":"$x\\to0$ 일 때 $\\dfrac{f(x)}{x}\\to3$ 을 넣으면?","식":["$\\displaystyle\\lim_{x\\to0}\\frac{-6x+3+5\\cdot\\frac{f(x)}{x}}{3+2\\cdot\\frac{f(x)}{x}}=\\frac{3+5\\cdot3}{3+2\\cdot3}=\\frac{18}{9}=2$"],"설명":"$-6x\\to0$ 이므로 분자는 $3+15$, 분모는 $3+6$ 이다.","확인":"2","스킬":"D3"}]},"ns-393493e37be4":{"길":"합성함수는 안쪽 함수의 극한 방향부터 정하고 그 방향의 바깥 함수 극한을 그래프에서 읽는다","단계":[{"제목":"ㄱ. $x\\to1$ 에서 $f$ 의 극한","힌트":"$x=1$ 의 좌·우에서 $f$ 의 곡선이 향하는 높이는?","식":["$\\lim_{x\\to1-}f(x)=0,\\ \\lim_{x\\to1+}f(x)=0$","$\\lim_{x\\to1}f(x)=0$"],"설명":"좌극한과 우극한이 같으므로 극한이 존재한다. 닫힌 점 $f(1)=1$ 은 극한과 무관하다.","확인":"0","스킬":"D12"},{"제목":"ㄴ. 안쪽 $f(x)$ 의 방향","힌트":"$x\\to0+$ 와 $x\\to0-$ 에서 $f(x)$ 는 각각 $1$ 의 어느 쪽인가?","식":["$x\\to0+$: $f(x)<1$ 이고 $f(x)\\to1$ 이므로 $f(x)\\to1-$","$x\\to0-$: $f(x)=1$ 로 일정"],"설명":"$0<x<1$ 에서 그래프는 $(0,1)$ 에서 $(1,0)$ 쪽으로 내려가므로 $1$ 보다 작다. $x<0$ 에서는 수평선이어서 항상 $1$ 이다.","확인":null,"스킬":"T6","고비":true},{"제목":"ㄴ. 좌·우극한 비교","힌트":"$g$ 의 $y\\to1-$ 극한과 $g(1)$ 은 각각?","식":["$x\\to0+$: $\\lim_{y\\to1-}g(y)=1$","$x\\to0-$: $g(f(x))=g(1)=0$","$1\\ne0$ 이므로 극한이 존재하지 않는다"],"설명":"$g$ 는 $x=1$ 에서 열린 점 $(1,1)$ 과 닫힌 점 $(1,0)$ 을 가진다. 좌·우극한이 다르므로 ㄴ 은 극한값이 없다.","확인":null,"스킬":"T6"},{"제목":"ㄷ. $f(g(x))$ 의 극한","힌트":"$x\\to1$ 일 때 $g(x)$ 는 $1$ 의 어느 쪽에서 오는가?","식":["$x\\ne1$ 이므로 $g(x)=x$","$x\\to1\\pm$ 이면 $g(x)\\to1\\pm$ 이고 $f(g(x))\\to0$","$\\lim_{x\\to1}f(g(x))=0$"],"설명":"$g(1)=0$ 은 $x=1$ 일 때만의 값이어서 극한에서는 쓰지 않는다. 극한값이 존재하는 것은 ㄱ, ㄷ 이다.","확인":"0","스킬":"T6"}]},"ns-3aa4d89e0b73":{"길":"각 보기를 연속과 극한의 성질로 따지고 ㄴ 은 좌·우 값이 $\\pm1$ 인 반례를 만든다","단계":[{"제목":"ㄱ. 연속함수의 곱","힌트":"$f$ 가 연속이면 $\\{f(x)\\}^2=f(x)\\cdot f(x)$ 는?","식":["$\\displaystyle\\lim_{x\\to2}\\{f(x)\\}^2=\\{f(2)\\}^2$"],"설명":"연속인 두 함수의 곱은 연속이다. ㄱ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"ㄴ. 반례 만들기","힌트":"제곱하면 같아지는 $1$ 과 $-1$ 을 좌·우에 놓으면?","식":["$f(x)=1\\ (x\\ge2),\\ f(x)=-1\\ (x<2)$","$\\{f(x)\\}^2=1$ 은 연속이나 $f$ 는 좌극한 $-1$, 우극한 $1$ 로 불연속"],"설명":"제곱은 부호를 지우므로 $f$ 가 불연속이어도 $f^2$ 은 연속일 수 있다. ㄴ 은 옳지 않다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄷ. 극한이 존재하는 경우","힌트":"$\\lim f(x)=L$ 이면 $2f(x)+|f(x)|$ 는 어떤 값에 가까워지는가?","식":["$\\lim_{x\\to2}|f(x)|=|L|$","$\\lim_{x\\to2}\\{2f(x)+|f(x)|\\}=2L+|L|$"],"설명":"$|y|$ 는 연속이므로 극한이 존재하면 절댓값의 극한도 존재한다. $L\\ge0$ 이면 $3L$, $L<0$ 이면 $L$ 로 값이 정해지므로 ㄷ 은 옳다. 옳은 것은 ㄱ, ㄷ 이다.","확인":null,"스킬":"C3"}]},"ns-3d74fe52d734":{"길":"극한이 존재하려면 $x=3$ 에서 좌극한과 우극한이 같아야 하므로 둘을 식으로 쓰고 같게 놓는다","단계":[{"제목":"좌극한과 우극한의 식","힌트":"$x\\to3-$ 와 $x\\to3+$ 에서 $f(x)$ 는 각각 어느 식을 쓰는가?","식":["$\\displaystyle\\lim_{x\\to3-}f(x)=\\lim_{x\\to3-}(x^2+1)$","$\\displaystyle\\lim_{x\\to3+}f(x)=k$"],"설명":"$x<3$ 쪽은 $x^2+1$, $x>3$ 쪽은 $k$ 이다. 극한이 존재하려면 두 값이 같아야 한다.","확인":null,"스킬":"D12","고비":true},{"제목":"$k$ 의 값","힌트":"좌극한의 값을 구해 우극한과 같게 놓으면?","식":["$3^2+1=10$","$k=10$"],"설명":"$x^2+1$ 은 다항식이므로 $x=3$ 을 그대로 넣는다.","확인":"10","스킬":"D12"}]},"ns-43db3b663d76":{"길":"약분으로 $a$ 를, 분자 유리화로 $b$ 를 구한 뒤 $a-b$ 를 계산한다","단계":[{"제목":"첫째 극한으로 $a$ 구하기","힌트":"$x\\to-a$ 에서 분모·분자를 인수분해해 공통인수를 지우면?","식":["$\\dfrac{x^3+a^3}{x^2-a^2}=\\dfrac{(x+a)(x^2-ax+a^2)}{(x+a)(x-a)}=\\dfrac{x^2-ax+a^2}{x-a}$","$\\displaystyle\\lim_{x\\to-a}=\\frac{3a^2}{-2a}=-\\frac{3a}{2}=3$ 에서 $a=-2$"],"설명":"$x\\to-a$ 이지만 $x\\ne-a$ 이므로 $x+a$ 로 약분한다. $a\\ne0$ 이어야 극한이 $3$ 이 되므로 $a=0$ 은 쓰지 않는다.","확인":"-2","스킬":"D11"},{"제목":"분자의 유리화","힌트":"$a=-2$ 를 넣고 $\\infty-\\infty$ 꼴을 분수로 바꾸려면 무엇을 곱하는가?","식":["$\\sqrt{x^2+2x}-\\sqrt{x^2-bx}=\\dfrac{(x^2+2x)-(x^2-bx)}{\\sqrt{x^2+2x}+\\sqrt{x^2-bx}}$","$=\\dfrac{(2+b)x}{\\sqrt{x^2+2x}+\\sqrt{x^2-bx}}$"],"설명":"분자와 분모에 $\\sqrt{x^2+2x}+\\sqrt{x^2-bx}$ 를 곱한다. 두 제곱근의 차가 합과 차의 곱으로 정리된다.","확인":null,"스킬":"D11","고비":true},{"제목":"$b$ 의 값","힌트":"분모·분자를 $x$ 로 나누고 $x\\to\\infty$ 로 보내면?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{2+b}{\\sqrt{1+\\frac2x}+\\sqrt{1-\\frac bx}}=\\frac{2+b}{2}=3$","$b=4$"],"설명":"$x>0$ 이므로 $\\dfrac{x}{\\sqrt{x^2+2x}}=\\dfrac{1}{\\sqrt{1+\\frac2x}}$ 이다. 분모의 두 제곱근은 각각 $1$ 로 가까워진다.","확인":"4","스킬":"D11"},{"제목":"$a-b$ 의 값","힌트":"구한 $a$, $b$ 로 계산하면?","식":["$a-b=-2-4=-6$"],"설명":"앞에서 구한 두 값을 뺀다.","확인":"-6","스킬":"D11"}]},"ns-4902fb4a3d2f":{"길":"$x\\to n\\pm$ 에서 $[x]$ 의 값을 따로 넣어 두 극한이 같게 하는 $n$ 을 찾는다","단계":[{"제목":"좌극한과 우극한의 식","힌트":"$x\\to n+$ 일 때와 $x\\to n-$ 일 때 $[x]$ 는 각각 얼마인가?","식":["$x\\to n+$: $[x]=n$ 이므로 $\\dfrac{n^2+2n}{n}=n+2$","$x\\to n-$: $[x]=n-1$ 이므로 $\\dfrac{(n-1)^2+2n}{n-1}=\\dfrac{n^2+1}{n-1}$"],"설명":"$n$ 바로 오른쪽에서는 $[x]=n$, 바로 왼쪽에서는 $[x]=n-1$ 이다. $n=0$ 이면 오른쪽 분모가, $n=1$ 이면 왼쪽 분모가 $0$ 이어서 식이 정의되지 않으므로 $n\\ne0,\\ 1$ 이다.","확인":null,"스킬":"N7"},{"제목":"$n$ 의 값","힌트":"두 극한이 같다고 놓고 풀면?","식":["$n+2=\\dfrac{n^2+1}{n-1}$ 에서 $(n+2)(n-1)=n^2+1$","$n^2+n-2=n^2+1$ 이므로 $n=3$"],"설명":"극한이 존재하려면 좌극한과 우극한이 같아야 한다. 양변에 $n-1$ 을 곱하면 $n^2$ 항이 지워져 일차방정식이 된다.","확인":"3","스킬":"N7","고비":true},{"제목":"극한값 $\\beta$","힌트":"$n=3$ 일 때 좌극한과 우극한의 값은?","식":["우극한: $\\dfrac{9+6}{3}=5$","좌극한: $\\dfrac{4+6}{2}=5$"],"설명":"두 값이 같으므로 극한이 존재하고 $\\beta=5$ 이다.","확인":"5","스킬":"N7"},{"제목":"$\\alpha+\\beta$ 의 값","힌트":"$\\alpha=3$, $\\beta=5$ 이면?","식":["$\\alpha+\\beta=3+5=8$"],"설명":"$\\alpha$ 는 정수 $n$ 의 값이고 $\\beta$ 는 그 극한값이다.","확인":"8","스킬":"N7"}]},"ns-4ad671f630d8":{"길":"점이 찍힌 곳과 빈 곳을 구별해 극한 두 개와 함숫값을 읽어 더한다","단계":[{"제목":"$x\\to0+$ 의 극한","힌트":"$x=0$ 의 오른쪽 곡선은 어느 높이에서 시작하는가?","식":["$\\displaystyle\\lim_{x\\to0+}f(x)=1$"],"설명":"오른쪽 곡선은 닫힌 점 $(0,1)$ 에서 시작한다. 왼쪽 선이 향하는 열린 점 $(0,2)$ 는 좌극한이어서 쓰지 않는다.","확인":"1","스킬":"D12","고비":true},{"제목":"$x\\to1-$ 의 극한","힌트":"$x=1$ 의 왼쪽 곡선이 향하는 열린 점의 높이는?","식":["$\\displaystyle\\lim_{x\\to1-}f(x)=2$"],"설명":"곡선이 열린 점 $(1,2)$ 로 다가가므로 극한은 $2$ 이다. 닫힌 점의 높이 $3$ 은 함숫값이다.","확인":"2","스킬":"D12"},{"제목":"$f(1)$ 과 세 값의 합","힌트":"닫힌 점의 높이를 읽어 세 값을 더하면?","식":["$f(1)=3$","$1+2+3=6$"],"설명":"$f(1)$ 은 $x=1$ 에서 닫힌 점의 높이이다.","확인":"6","스킬":"D12"}]},"ns-4bd8d09c7403":{"길":"극한이 존재하므로 $f(1)=1$ 임을 읽고 미분계수 꼴로 바꿔 $f\\,'(1)$ 을 구한다","단계":[{"제목":"$f(1)$ 의 값 읽기","힌트":"$x\\to1$ 일 때 분모가 $0$ 으로 가는데 극한이 존재하면 분자는?","식":["분모 $x^2-1\\to0$ 이므로 분자 $f(x)-1\\to0$","$f$ 는 다항함수이므로 $f(1)-1=0$, 즉 $f(1)=1$"],"설명":"분모가 $0$ 으로 가면 분자도 $0$ 으로 가야 극한값이 존재한다. 다항함수는 연속이므로 $f(x)\\to f(1)$ 이다.","확인":null,"스킬":"D11"},{"제목":"미분계수 꼴로 변형","힌트":"$f(x)-1$ 을 $f(x)-f(1)$ 로 쓰고 $x^2-1=(x-1)(x+1)$ 로 인수분해하면?","식":["$\\dfrac{f(x)-1}{x^2-1}=\\dfrac{f(x)-f(1)}{x-1}\\times\\dfrac1{x+1}$"],"설명":"$x-1$ 이 분모에 나타나야 미분계수의 정의 $\\displaystyle\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}$ 를 쓸 수 있다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f\\,'(1)$ 의 값","힌트":"$f(x)=\\int(3x^2-4x+7)\\,dx$ 의 양변을 미분하면?","식":["$f\\,'(x)=3x^2-4x+7$","$f\\,'(1)=3-4+7=6$"],"설명":"부정적분을 미분하면 피적분함수가 된다.","확인":"6","스킬":"D3"},{"제목":"극한값","힌트":"$\\dfrac{f(x)-f(1)}{x-1}\\to f\\,'(1)$, $\\dfrac1{x+1}\\to\\dfrac12$ 을 곱하면?","식":["$\\displaystyle\\lim_{x\\to1}\\frac{f(x)-1}{x^2-1}=f\\,'(1)\\times\\frac12=3$"],"설명":"두 극한이 각각 존재하므로 곱의 극한은 극한의 곱이다.","확인":"3","스킬":"D3"}]},"ns-4ecd327c5b56":{"길":"각 선지를 좌·우극한과 함숫값으로 읽고 $x=2$ 에서 좌·우극한이 다른 것을 찾는다","단계":[{"제목":"①②④ 읽기","힌트":"$x=1$ 의 좌·우극한과 $f(-1)$, $f(2)$ 는 각각?","식":["$\\lim_{x\\to1-}f(x)=1,\\ \\lim_{x\\to1+}f(x)=1$ 이므로 $\\lim_{x\\to1}f(x)=1$","$f(-1)=0,\\ f(2)=2$"],"설명":"$x=1$ 은 속이 빈 점에서 좌·우가 모두 높이 $1$ 로 모이고, $f(-1)$, $f(2)$ 는 닫힌 점의 높이이다. ①②④ 는 옳다.","확인":null,"스킬":"D12"},{"제목":"$x=2$ 의 좌극한","힌트":"$x\\to2-$ 일 때 곡선이 향하는 열린 점의 높이는?","식":["$\\displaystyle\\lim_{x\\to2-}f(x)=0$"],"설명":"왼쪽에서 내려오는 선분은 열린 점 $(2,0)$ 으로 향한다. 닫힌 점의 높이 $f(2)=2$ 는 극한이 아니라 함숫값이다.","확인":"0","스킬":"D12","고비":true},{"제목":"$x=2$ 의 우극한과 ③","힌트":"$x\\to2+$ 일 때 곡선이 시작하는 열린 점의 높이는?","식":["$\\displaystyle\\lim_{x\\to2+}f(x)=-1$","$0\\ne-1$ 이므로 $\\lim_{x\\to2}f(x)$ 는 존재하지 않는다"],"설명":"⑤ 는 옳다. ③ 은 좌극한 $0$ 과 우극한 $-1$ 이 달라 극한값이 없으므로 옳지 않다.","확인":null,"스킬":"D12"}]},"ns-593b5dd203df":{"길":"극한의 모양으로 $f$ 의 차수와 최고차항을 정하고 $f(1)=0$, $f\\,'(1)=1$ 로 계수를 구한다","단계":[{"제목":"$f(x)$ 의 꼴","힌트":"분모가 $x^2+2x$ 이고 극한이 $3$ 이면 $f$ 의 차수와 최고차항 계수는?","식":["$f(x)=3x^2+ax+b$"],"설명":"분모와 분자의 차수가 같고 최고차항 계수의 비가 $3$ 이므로 $f$ 는 이차식이고 최고차항 계수는 $3$ 이다.","확인":null,"스킬":"A11"},{"제목":"$f(1)$ 과 $f\\,'(1)$ 의 조건","힌트":"$x\\to1$ 일 때 분모가 $0$ 으로 가는데 극한이 $1$ 이면 $f(1)$ 은?","식":["분모 $x-1\\to0$ 이므로 $f(1)=0$","$\\displaystyle\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}=f\\,'(1)=1$"],"설명":"분모가 $0$ 으로 가면 분자도 $0$ 이어야 하므로 $f(1)=0$ 이다. $f(1)=0$ 이면 주어진 극한은 미분계수의 정의 꼴이다.","확인":null,"스킬":"D11","고비":true},{"제목":"$a$ 의 값","힌트":"$f\\,'(x)=6x+a$ 에 $x=1$ 을 넣어 $1$ 과 같게 놓으면?","식":["$f\\,'(1)=6+a=1$","$a=-5$"],"설명":"$f(x)=3x^2+ax+b$ 를 미분하면 $f\\,'(x)=6x+a$ 이다.","확인":"-5","스킬":"A3"},{"제목":"$b$ 와 $f(2)$","힌트":"$f(1)=0$ 에 $a$ 를 넣어 $b$ 를 구한 뒤 $f(2)$ 를 계산하면?","식":["$f(1)=3+a+b=0$ 에서 $b=2$","$f(x)=3x^2-5x+2$ 이므로 $f(2)=12-10+2=4$"],"설명":"$3+(-5)+b=0$ 이므로 $b=2$ 이다.","확인":"4","스킬":"A3"}]},"ns-62e46d02db52":{"길":"보기마다 극한을 구하되 절댓값과 제곱근은 부호를 나눠 따져 옳은 것을 고른다","단계":[{"제목":"ㄱ, ㄷ: $x\\to\\infty$ 의 극한","힌트":"$-x^2+x$ 의 극한과 $\\dfrac5{x^2}$ 의 극한은 각각?","식":["ㄱ. $-x^2+x=x^2\\left(-1+\\dfrac1x\\right)\\to-\\infty$ 이므로 거짓","ㄷ. $\\dfrac{5}{x^2}\\to0$ 이므로 $4+\\dfrac5{x^2}\\to4$, 참"],"설명":"ㄱ 은 최고차항이 $-x^2$ 이어서 음의 무한대로 간다. ㄷ 은 분모가 커지는 항이 $0$ 으로 간다.","확인":null,"스킬":"C3"},{"제목":"ㄴ: 절댓값의 좌·우극한","힌트":"$x\\to-2-$ 에서 $|x+2|$ 는 어떤 식으로 바뀌는가?","식":["$x\\to-2-$: $|x+2|=-(x+2)$ 이므로 $\\dfrac{(x+2)(x-2)}{-(x+2)}=-(x-2)\\to4$","$x\\to-2+$: $\\dfrac{(x+2)(x-2)}{x+2}=x-2\\to-4$"],"설명":"$4\\ne-4$ 이므로 극한이 존재하지 않는다. ㄴ 은 거짓이다. 좌극한만 보고 $-4$ 로 단정하면 안 되고 우극한까지 비교한다.","확인":"4","스킬":"C2","고비":true},{"제목":"ㄹ, ㅁ: 부호를 따져 풀기","힌트":"$x\\to-\\infty$ 에서 $\\sqrt{x^2+3}$ 은 $x$ 로 어떻게 쓰이는가?","식":["ㄹ. $x\\to1$ 이면 $|x|=x$ 이므로 $\\dfrac{x+x}{x}=2$, 참","ㅁ. $x<0$ 이면 $\\sqrt{x^2+3}=-x\\sqrt{1+\\frac3{x^2}}$ 이므로 $\\displaystyle\\lim_{x\\to-\\infty}\\frac{\\sqrt{x^2+3}}{x}=-1$, 거짓"],"설명":"$x<0$ 일 때 $\\sqrt{x^2}=|x|=-x$ 이다. 따라서 ㅁ 의 값은 $1$ 이 아니라 $-1$ 이고, 옳은 것은 ㄷ, ㄹ 이다.","확인":"-1","스킬":"C2"}]},"ns-6387c2c1d287":{"길":"$\\frac1x=t$ 로 치환해 $f$ 의 꼴을 정하고, 분모가 $0$ 으로 가면 분자도 $0$ 임을 써서 $p$ 와 $a$ 를 구한다","단계":[{"제목":"치환으로 식 정리","힌트":"$\\dfrac1x=t$ 로 놓으면 $x\\to0+$ 는 어떤 극한이 되고 식은 어떻게 쓰이는가?","식":["$x\\to0+$ 이면 $t\\to\\infty$","$\\displaystyle\\lim_{t\\to\\infty}\\frac{\\frac1t f(t)-1}{2-\\frac1t}=\\lim_{t\\to\\infty}\\frac{f(t)-t}{2t-1}=1$"],"설명":"분모·분자에 $t$ 를 곱했다. $t\\to\\infty$ 의 극한이므로 분모·분자의 차수를 비교할 수 있다.","확인":null,"스킬":"A1"},{"제목":"$f(x)$ 의 꼴","힌트":"분모가 일차이고 극한이 $1$ 이면 분자 $f(t)-t$ 의 차수와 최고차항 계수는?","식":["$f(t)-t$ 는 일차식이고 최고차항 계수는 $2$","$f(x)-x=2x+p$ 이므로 $f(x)=3x+p$"],"설명":"분자의 차수가 분모보다 크면 발산하고 작으면 $0$ 으로 가므로 같아야 한다. 최고차항 계수의 비가 $1$ 이므로 분자의 계수는 분모와 같은 $2$ 이다.","확인":null,"스킬":"A11","고비":true},{"제목":"$p$ 의 값","힌트":"$x\\to2$ 에서 분모가 $0$ 으로 가는데 극한이 존재하면 $f(2)$ 는?","식":["분모 $x^2-3x+2=(x-1)(x-2)\\to0$ 이므로 $f(2)=0$","$6+p=0$ 에서 $p=-6$"],"설명":"분모가 $0$ 으로 가는데 극한이 수렴하려면 분자도 $0$ 으로 가야 한다. 따라서 $f(x)=3x-6$ 이다.","확인":"-6","스킬":"D11"},{"제목":"$a$ 와 $f(3)+a$","힌트":"$f(x)=3x-6$ 으로 약분해 $a$ 를 구하고 $f(3)$ 과 더하면?","식":["$\\displaystyle a=\\lim_{x\\to2}\\frac{3(x-2)}{(x-1)(x-2)}=\\lim_{x\\to2}\\frac{3}{x-1}=3$","$f(3)=3,\\ f(3)+a=6$"],"설명":"$x\\to2$ 이지만 $x\\ne2$ 이므로 $x-2$ 로 약분한다.","확인":"6","스킬":"D11"}]},"ns-6c1c4e8e4073":{"길":"절댓값 부등식을 풀어 $f(x)$ 를 위아래로 끼운 뒤 $x^4$ 으로 나눈 식의 극한을 비교한다","단계":[{"제목":"절댓값 부등식 풀기","힌트":"$|A|<1$ 은 $A$ 의 범위로 어떻게 쓰이는가?","식":["$-1<\\dfrac{f(x)}{x^2+1}-2x^2<1$","$2x^2-1<\\dfrac{f(x)}{x^2+1}<2x^2+1$"],"설명":"$|A|<1$ 은 $-1<A<1$ 이다. 각 변에 $2x^2$ 을 더한다.","확인":null,"스킬":"C9"},{"제목":"$f(x)$ 를 끼우고 $x^4$ 으로 나누기","힌트":"$x^2+1>0$ 이므로 각 변에 곱한 뒤 $x^4$ 으로 나누면?","식":["$(2x^2-1)(x^2+1)<f(x)<(2x^2+1)(x^2+1)$","$\\dfrac{(2x^2-1)(x^2+1)}{x^4}<\\dfrac{f(x)}{x^4}<\\dfrac{(2x^2+1)(x^2+1)}{x^4}$ ($x>0$)"],"설명":"양수를 곱하거나 나누면 부등호 방향이 그대로이다. $x\\to\\infty$ 이므로 $x>0$ 만 본다.","확인":null,"스킬":"C9","고비":true},{"제목":"양쪽 극한과 비교","힌트":"왼쪽 식과 오른쪽 식의 극한은 각각?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{(2x^2-1)(x^2+1)}{x^4}=2$","$\\displaystyle\\lim_{x\\to\\infty}\\frac{(2x^2+1)(x^2+1)}{x^4}=2$","$\\displaystyle\\lim_{x\\to\\infty}\\frac{f(x)}{x^4}=2$"],"설명":"분모·분자의 최고차항은 각각 $2x^4$, $x^4$ 이다. 양쪽 극한이 같으므로 가운데 식의 극한도 같다.","확인":"2","스킬":"C9"}]},"ns-6c25ac9775a8":{"길":"$g(x)$ 가 $2$ 에 어느 쪽에서 다가가는지 정하고 $f$ 의 극한을 읽은 뒤, 둘째 극한은 안쪽 $f(x)$ 의 값부터 본다","단계":[{"제목":"$x\\to-1+$ 일 때 $g(x)$ 의 방향","힌트":"$x=-1+h$ ($h>0$) 로 놓고 $g(x)$ 를 $h$ 로 나타내면?","식":["$g(-1)=1+1=2$","$g(-1+h)=(-1+h)^2-(-1+h)=2-3h+h^2$","$h\\to0+$ 이면 $g(x)\\to2-$"],"설명":"$h$ 가 작은 양수이면 $-3h+h^2<0$ 이어서 $g(x)<2$ 이다. 안쪽 값은 $2$ 에 아래쪽에서 다가간다.","확인":null,"스킬":"T6","고비":true},{"제목":"첫째 극한 $\\lim_{x\\to-1+}f(g(x))$","힌트":"$y\\to2-$ 일 때 $f(y)$ 의 극한은?","식":["$\\displaystyle\\lim_{x\\to-1+}f(g(x))=\\lim_{y\\to2-}f(y)=0$"],"설명":"$x=2$ 근처에서 그래프는 $(1,-1)$ 에서 $(3,1)$ 로 오르는 선분이고 $(2,0)$ 을 지난다. 정의역이 $-2\\le x\\le3$ 이므로 $y=2$ 의 왼쪽 값을 쓴다.","확인":"0","스킬":"T6"},{"제목":"둘째 극한과 합","힌트":"$x\\to1-$ 일 때 $f(x)$ 의 값은? 그 값에서 $g$ 의 값은?","식":["$-1\\le x<1$ 에서 $f(x)=1$ 이므로 $g(f(x))=g(1)=1-1=0$","$0+0=0$"],"설명":"$x\\to1-$ 에서 $f(x)$ 는 계속 $1$ 이다. $g$ 는 다항함수이므로 $g(1)$ 이 그대로 극한값이다.","확인":"0","스킬":"T6"}]},"ns-6c269d5c35b5":{"길":"분모가 $0$ 으로 가므로 분자도 $0$ 이라는 조건으로 $b$ 를 줄이고 인수분해로 $a$ 를 구한다","단계":[{"제목":"분자가 $0$ 이 되는 조건","힌트":"$x\\to2$ 에서 분모가 $0$ 으로 가는데 극한이 존재하면 분자는?","식":["$4+2a+b=0$","$b=-2a-4$"],"설명":"분모가 $0$ 으로 가는데 극한이 수렴하려면 분자도 $0$ 으로 가야 한다. $x=2$ 를 분자에 넣는다.","확인":null,"스킬":"D11"},{"제목":"인수분해로 $a$ 구하기","힌트":"$b$ 를 넣은 분자가 $x-2$ 를 인수로 가지므로 약분하면?","식":["$x^2+ax-2a-4=(x-2)(x+a+2)$","$\\displaystyle\\lim_{x\\to2}(x+a+2)=a+4=1$ 에서 $a=-3$"],"설명":"$x\\to2$ 이지만 $x\\ne2$ 이므로 $x-2$ 로 약분한다.","확인":"-3","스킬":"D11","고비":true},{"제목":"$b$ 와 $a+b$","힌트":"$a=-3$ 을 $b=-2a-4$ 에 넣고 $a+b$ 를 구하면?","식":["$b=6-4=2$","$a+b=-3+2=-1$"],"설명":"앞에서 구한 $b=-2a-4$ 에 $a$ 를 대입한다.","확인":"-1","스킬":"D11"}]},"ns-73780dce2c16":{"길":"$x=1,\\ 0,\\ -1,\\ -2$ 에서 좌극한·우극한·발산을 그래프로 읽어 보기마다 참거짓을 정한다","단계":[{"제목":"ㄱ. $x=1$ 의 극한","힌트":"$x=1$ 의 좌·우에서 곡선이 향하는 높이는?","식":["$\\lim_{x\\to1-}f(x)=1,\\ \\lim_{x\\to1+}f(x)=1$","$\\lim_{x\\to1}f(x)=1$"],"설명":"곡선은 열린 점 $(1,1)$ 로 양쪽에서 모인다. 닫힌 점 $f(1)=2$ 는 극한과 무관하다. ㄱ 은 참이다.","확인":null,"스킬":"D12"},{"제목":"ㄴ. $x=0$ 의 극한","힌트":"$x\\to0+$ 와 $x\\to0-$ 에서 $f(x)$ 는 각각 어느 쪽으로 가는가?","식":["$\\lim_{x\\to0+}f(x)=\\infty,\\ \\lim_{x\\to0-}f(x)=-\\infty$"],"설명":"$y$축이 점근선이고 좌·우의 방향이 반대이다. 극한이 존재하지 않으므로 ㄴ 은 거짓이다.","확인":null,"스킬":"D12"},{"제목":"ㄷ. $x=-1$ 의 좌·우극한의 합","힌트":"$x\\to-1+$ 에서 곡선이 시작하는 높이와 $x\\to-1-$ 에서 곡선이 향하는 높이는?","식":["$\\lim_{x\\to-1+}f(x)=0,\\ \\lim_{x\\to-1-}f(x)=1$","$0+1=1$"],"설명":"$x=-1$ 의 오른쪽 곡선은 닫힌 점 $(-1,0)$ 에서 내려가고, 왼쪽 곡선은 열린 점 $(-1,1)$ 로 오른다. 좌·우를 바꿔 읽지 않는다. ㄷ 은 참이다.","확인":null,"스킬":"D12","고비":true},{"제목":"ㄹ. $x=-2$ 의 극한","힌트":"$x=-2$ 의 꼭짓점에서 좌·우극한은?","식":["$\\lim_{x\\to-2-}f(x)=0,\\ \\lim_{x\\to-2+}f(x)=0$","$\\lim_{x\\to-2}f(x)=0$"],"설명":"좌극한과 우극한이 같으므로 극한이 존재한다. ㄹ 은 거짓이고, 옳은 것은 ㄱ, ㄷ 이다.","확인":"0","스킬":"D12"}]},"ns-74fc25c4aa81":{"길":"(나)로 $f$ 의 꼴을 정하고 (가)로 $(x+2)^2$ 을 인수로 묶어 $f$ 를 완성한 뒤 $k$ 를 구한다","단계":[{"제목":"(나)로 $f(x)$ 의 꼴 정하기","힌트":"분모가 이차이고 극한이 $1$ 이면 분자 $f(x)-x^3$ 의 차수와 최고차항 계수는?","식":["$f(x)-x^3$ 은 이차식이고 최고차항 계수는 $2$","$f(x)=x^3+2x^2+ax+b$"],"설명":"분자의 차수가 분모와 같고 계수의 비가 $1$ 이므로 분자의 최고차항 계수는 분모와 같다.","확인":null,"스킬":"A11"},{"제목":"(가)로 인수 찾기","힌트":"분모 $(x+2)^2$ 이 $0$ 으로 가는데 극한이 존재하려면 $f$ 는 무엇을 인수로 가져야 하는가?","식":["$f(x)=(x+2)^2(x-c)$"],"설명":"$f(-2)=0$ 이어야 하므로 $f(x)=(x+2)h(x)$ 이고, 다시 $\\dfrac{h(x)}{x+2}$ 가 수렴해야 하므로 $h(-2)=0$ 이다. 따라서 $(x+2)^2$ 이 인수이고, 삼차식에서 남은 인수는 일차식이다.","확인":null,"스킬":"D11","고비":true},{"제목":"$c$ 의 값","힌트":"전개한 $x^2$ 의 계수를 (나)의 $2$ 와 비교하면?","식":["$(x^2+4x+4)(x-c)=x^3+(4-c)x^2+\\cdots$","$4-c=2$ 에서 $c=2$"],"설명":"$f(x)=x^3+2x^2+ax+b$ 와 같아야 하므로 $x^2$ 의 계수를 비교한다. $f(x)=(x+2)^2(x-2)$ 이다.","확인":"2","스킬":"A3"},{"제목":"$k$ 의 값","힌트":"$(x+2)^2$ 을 약분하고 $x\\to-2$ 를 넣으면?","식":["$\\displaystyle k=\\lim_{x\\to-2}\\frac{(x+2)^2(x-2)}{(x+2)^2}=\\lim_{x\\to-2}(x-2)=-4$"],"설명":"$x\\to-2$ 이지만 $x\\ne-2$ 이므로 약분한다.","확인":"-4","스킬":"D11"}]},"ns-7ba5de949b9c":{"길":"$\\frac1g\\to0$ 을 곱해 $\\frac fg$ 의 극한을 구한 뒤 구하는 식의 분모·분자를 $g$ 로 나눈다","단계":[{"제목":"$\\dfrac fg$ 와 합의 관계","힌트":"$3f+4g$ 를 $g$ 로 나누면 어떤 꼴이 되고 그 극한은?","식":["$\\dfrac{3f(x)+4g(x)}{g(x)}=\\dfrac{3f(x)}{g(x)}+4$","$\\dfrac{1}{g(x)}\\to0$ 이므로 $\\displaystyle\\lim_{x\\to2}\\frac{3f(x)+4g(x)}{g(x)}=0\\times5=0$"],"설명":"$g\\to-\\infty$ 이므로 $x$ 가 $2$ 에 가까우면 $g(x)\\ne0$ 이어서 나눌 수 있다. 극한이 $5$ 인 식에 $0$ 으로 가는 식을 곱한 극한은 $0$ 이다.","확인":null,"스킬":"A1"},{"제목":"$\\dfrac fg$ 의 극한","힌트":"$3\\cdot\\dfrac fg+4\\to0$ 에서 $\\dfrac fg$ 의 극한은?","식":["$3\\displaystyle\\lim_{x\\to2}\\frac{f(x)}{g(x)}+4=0$","$\\displaystyle\\lim_{x\\to2}\\frac{f(x)}{g(x)}=-\\frac43$"],"설명":"$\\dfrac fg$ 가 극한을 가지므로 합의 극한을 각각의 극한으로 쪼갤 수 있다.","확인":"-4/3","스킬":"A1","고비":true},{"제목":"분모·분자를 $g$ 로 나누기","힌트":"구하는 식의 분모·분자를 $g(x)$ 로 나누면?","식":["$\\dfrac{f+2g}{2f+g}=\\dfrac{\\frac fg+2}{2\\cdot\\frac fg+1}$"],"설명":"$g(x)\\ne0$ 이므로 나눌 수 있고 식이 $\\dfrac fg$ 만으로 나타난다.","확인":null,"스킬":"A1"},{"제목":"극한값","힌트":"$\\dfrac fg\\to-\\dfrac43$ 을 넣으면?","식":["$\\dfrac{-\\frac43+2}{2\\cdot\\left(-\\frac43\\right)+1}=\\dfrac{\\frac23}{-\\frac53}=-\\dfrac25$"],"설명":"분자와 분모를 각각 계산한 뒤 나눈다.","확인":"-2/5","스킬":"A1"}]},"ns-7bac9f23920f":{"길":"보기마다 유한한 값으로 수렴하는지 가려 발산하는 것과 구별한다","단계":[{"제목":"ㄱ, ㄷ, ㅂ: 발산","힌트":"좌·우극한이 다르거나 $\\pm\\infty$ 로 가는 보기는 어느 것인가?","식":["ㄱ. $\\lim_{x\\to0+}\\frac2x=\\infty,\\ \\lim_{x\\to0-}\\frac2x=-\\infty$ 로 극한 없음","ㄷ. $-\\dfrac{1}{(x-2)^2}\\to-\\infty$, ㅂ. $\\dfrac{2x^2}{x+1}\\to\\infty$"],"설명":"$\\pm\\infty$ 로 가는 것은 극한값이 존재하는 것이 아니다. ㄱ, ㄷ, ㅂ 은 제외한다.","확인":null,"스킬":"C3"},{"제목":"ㄴ: 상수로 수렴","힌트":"$x\\to-\\infty$ 에서 $\\dfrac1x$ 는 어느 값에 가까워지는가?","식":["$\\displaystyle\\lim_{x\\to-\\infty}\\left(\\frac1x+3\\right)=0+3=3$"],"설명":"분모가 절댓값이 커지므로 $\\dfrac1x\\to0$ 이다. 유한한 값 $3$ 으로 수렴하므로 ㄴ 은 존재한다.","확인":"3","스킬":"C3","고비":true},{"제목":"ㄹ, ㅁ: $0$ 으로 수렴","힌트":"ㄹ 의 분모와 ㅁ 의 분모·분자의 차수를 비교하면?","식":["ㄹ. $\\displaystyle\\lim_{x\\to\\infty}\\frac{1}{|x-2|}=0$","ㅁ. $\\displaystyle\\lim_{x\\to\\infty}\\frac{2x}{x^2-2x+3}=\\lim_{x\\to\\infty}\\frac{\\frac2x}{1-\\frac2x+\\frac3{x^2}}=0$"],"설명":"ㄹ 은 분모가 무한히 커지고, ㅁ 은 분모의 차수가 분자보다 커서 $0$ 으로 간다. 존재하는 것은 ㄴ, ㄹ, ㅁ 이다.","확인":"0","스킬":"C3"}]},"ns-802d25bbf01f":{"길":"선지마다 극한이 수렴하는지 $\\pm\\infty$ 로 가는지, 부호까지 따져 틀린 것을 찾는다","단계":[{"제목":"①~④ 확인","힌트":"①~④ 에서 극한을 결정하는 항과 그 부호는?","식":["① $-2x+1\\to-\\infty$ ② $x^2-3x+2\\to\\infty$","③ $\\dfrac1{x+5}\\to0$ ④ $3+\\dfrac1{x^2}\\to3$"],"설명":"①은 최고차항 $-2x$ 의 부호를 따르고, ②는 $x^2$ 이 $x\\to-\\infty$ 에서도 양수이다. ③④ 는 분모가 커져 $0$ 으로 가는 항이다. ①~④ 는 옳다.","확인":null,"스킬":"C3"},{"제목":"⑤ 의 극한","힌트":"$x\\to0$ 일 때 $\\dfrac1{x^2}$ 은 양수인가 음수인가?","식":["$\\dfrac1{x^2}>0$ 이고 $x\\to0$ 이면 $\\dfrac1{x^2}\\to\\infty$","$\\displaystyle\\lim_{x\\to0}\\left(3-\\frac1{x^2}\\right)=-\\infty$"],"설명":"$\\dfrac1{x^2}$ 은 좌·우 어느 쪽에서도 $+\\infty$ 로 가므로 $3$ 에서 빼면 $-\\infty$ 이다. ⑤ 는 $\\infty$ 라고 했으므로 옳지 않다.","확인":null,"스킬":"C3","고비":true}]},"ns-812e90968106":{"길":"선지마다 극한값을 직접 대입하거나 발산 여부를 확인해 바른 것을 고른다","단계":[{"제목":"①②③ 대입","힌트":"$x$ 에 극한이 향하는 값을 넣으면 각 식의 값은?","식":["① $2\\cdot1-1=1$ ② $0^2-1=-1$","③ $\\sqrt{3\\cdot(-1)+7}=\\sqrt4=2$"],"설명":"연속인 함수이므로 $x$ 값을 그대로 넣는다. ①②③ 의 값은 선지에 적힌 $0$, $1$, $10$ 과 모두 다르므로 바르지 않다.","확인":"2","스킬":"C3","고비":true},{"제목":"④⑤ 확인","힌트":"④⑤ 는 값을 넣거나 발산 여부를 따지면 어떻게 되는가?","식":["④ $\\displaystyle\\lim_{x\\to1}\\frac1x=1$","⑤ $\\dfrac1{x^2}\\to\\infty$ 이므로 $\\dfrac1{x^2}+2\\to\\infty$"],"설명":"④ 는 $x=1$ 을 넣은 값 $1$ 과 같아 바르다. ⑤ 는 $2$ 가 아니라 발산하므로 바르지 않다.","확인":null,"스킬":"C3"}]},"ns-81e803aabffb":{"길":"$a$ 의 부호를 정하고 유리화해 분자의 $x^2$ 계수가 $0$ 이 되는 $a$ 를 구한 뒤 $b$ 를 계산한다","단계":[{"제목":"$a$ 의 부호 판단","힌트":"$a\\ge0$ 이면 $\\sqrt{x^2-3x}+ax$ 는 $x\\to\\infty$ 에서 어떻게 되는가?","식":["$a\\ge0$ 이면 두 항이 모두 $\\infty$ 로 가므로 극한은 $\\infty$","따라서 $a<0$"],"설명":"극한이 유한한 값 $b$ 이므로 $a\\ge0$ 은 쓸 수 없다. $a<0$ 일 때만 두 항이 서로 상쇄될 수 있다.","확인":null,"스킬":"D11"},{"제목":"분자의 유리화","힌트":"$\\sqrt{x^2-3x}-ax$ 를 분자와 분모에 곱하면?","식":["$\\dfrac{(x^2-3x)-a^2x^2}{\\sqrt{x^2-3x}-ax}=\\dfrac{(1-a^2)x^2-3x}{\\sqrt{x^2-3x}-ax}$"],"설명":"$(\\sqrt{x^2-3x}+ax)(\\sqrt{x^2-3x}-ax)=(x^2-3x)-a^2x^2$ 이다.","확인":null,"스킬":"D11","고비":true},{"제목":"$a$ 의 값","힌트":"분모는 $x$ 에 대한 일차, 분자는 이차이면 극한이 수렴하려면?","식":["분모 $\\sqrt{x^2-3x}-ax$ 는 일차 크기이므로 분자의 $x^2$ 계수 $1-a^2=0$","$a<0$ 이므로 $a=-1$"],"설명":"$1-a^2\\ne0$ 이면 분자가 분모보다 빨리 커져 발산한다. $a=1$ 은 $a<0$ 에 맞지 않아 버린다.","확인":"-1","스킬":"D11"},{"제목":"$b$ 의 값","힌트":"$a=-1$ 일 때 분모·분자를 $x$ 로 나누고 $x\\to\\infty$ 로 보내면?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{-3x}{\\sqrt{x^2-3x}+x}=\\lim_{x\\to\\infty}\\frac{-3}{\\sqrt{1-\\frac3x}+1}=-\\frac32$"],"설명":"$a=-1$ 이면 분모는 $\\sqrt{x^2-3x}-ax=\\sqrt{x^2-3x}+x$ 이다. $\\sqrt{1-\\frac3x}\\to1$ 이다.","확인":"-3/2","스킬":"D11"},{"제목":"$a+b$ 의 값","힌트":"구한 $a$, $b$ 를 더하면?","식":["$a+b=-1-\\dfrac32=-\\dfrac52$"],"설명":"앞에서 구한 두 값을 더한다.","확인":"-5/2","스킬":"D11"}]},"ns-8574cfd9233f":{"길":"$\\mathrm{Q}$ 의 좌표를 구해 $\\overline{\\mathrm{PQ}}^2$ 과 $\\overline{\\mathrm{AP}}^2$ 을 $t$ 로 나타낸 뒤 비의 극한을 구한다","단계":[{"제목":"점 $\\mathrm{Q}$ 의 좌표","힌트":"$y=x+1$ 에 수직이고 $\\mathrm{P}$ 를 지나는 직선이 $y$축과 만나는 점은?","식":["$y=-(x-t)+t+1=-x+2t+1$","$\\mathrm{Q}(0,\\ 2t+1)$"],"설명":"$y=x+1$ 의 기울기가 $1$ 이므로 수직인 직선의 기울기는 $-1$ 이다. $x=0$ 을 넣어 $y$절편을 구한다.","확인":null,"스킬":"S4","고비":true},{"제목":"$\\overline{\\mathrm{PQ}}^2$ 과 $\\overline{\\mathrm{AP}}^2$","힌트":"두 점 사이의 좌표 차를 각각 제곱해 더하면?","식":["$\\overline{\\mathrm{PQ}}^2=t^2+\\{(t+1)-(2t+1)\\}^2=2t^2$","$\\overline{\\mathrm{AP}}^2=(t+1)^2+(t+1)^2=2(t+1)^2$"],"설명":"$\\mathrm{P}(t,t+1)$, $\\mathrm{Q}(0,2t+1)$, $\\mathrm{A}(-1,0)$ 의 좌표 차를 쓴다.","확인":null,"스킬":"S4"},{"제목":"비의 극한","힌트":"$\\dfrac{2t^2}{2(t+1)^2}$ 의 $t\\to\\infty$ 극한은?","식":["$\\displaystyle\\lim_{t\\to\\infty}\\frac{2t^2}{2(t+1)^2}=\\lim_{t\\to\\infty}\\frac{1}{\\left(1+\\frac1t\\right)^2}=1$"],"설명":"분모·분자를 $t^2$ 으로 나누면 $\\dfrac1t\\to0$ 만 남는다.","확인":"1","스킬":"A11"}]},"ns-926a56c612a3":{"길":"보기마다 반례를 찾고 ㄷ 은 곱의 극한 성질로 참임을 확인한다","단계":[{"제목":"ㄱ. 극한과 함숫값","힌트":"$x=0$ 에서만 값이 다른 함수를 만들면?","식":["$f(x)=1\\ (x\\ne0),\\ f(0)=-1$","$\\lim_{x\\to0}f(x)=1$ 이지만 $f(0)=-1$"],"설명":"극한은 $x=0$ 에서의 값이 아니라 주변의 값으로 정해진다. 반례가 있으므로 ㄱ 은 항상 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄴ. 곱의 극한이 있어도 한쪽은 없는 경우","힌트":"$g(x)=x-1$ 과 곱하면 상수가 되는 $f(x)$ 는?","식":["$g(x)=x-1,\\ f(x)=\\dfrac1{x-1}\\ (x\\ne1)$ 이고 $f(1)$ 은 임의의 값","$\\displaystyle\\lim_{x\\to1}f(x)g(x)=1$"],"설명":"$\\displaystyle\\lim_{x\\to1}g(x)=0$ 이고 $f(x)g(x)=1$ 로 극한이 존재하지만 $\\dfrac1{x-1}$ 은 $x\\to1$ 에서 발산한다. ㄴ 은 항상 옳지 않다.","확인":"1","스킬":"C3","고비":true},{"제목":"ㄷ. 곱으로 쓰기","힌트":"$g(x)$ 를 $f(x)$ 와 $\\dfrac{g(x)}{f(x)}$ 의 곱으로 쓰면?","식":["$g(x)=f(x)\\cdot\\dfrac{g(x)}{f(x)}$","$\\displaystyle\\lim_{x\\to a}g(x)=\\lim_{x\\to a}f(x)\\times\\lim_{x\\to a}\\frac{g(x)}{f(x)}$"],"설명":"두 극한이 각각 존재하면 곱의 극한은 극한의 곱이므로 $\\displaystyle\\lim_{x\\to a}g(x)$ 가 존재한다. ㄷ 은 항상 옳다.","확인":null,"스킬":"C3"},{"제목":"ㄹ. 합성함수의 좌극한","힌트":"$f$ 는 $x=1$ 에서 부호가 갈리고 $g(x)=x$ 일 때 $x\\to1-$ 에서 $f(g(x))$ 는?","식":["$f(x)=1\\ (x\\ge1),\\ -1\\ (x<1)$, $g(x)=x$","$\\displaystyle\\lim_{x\\to1-}f(g(x))=\\lim_{x\\to1-}f(x)=-1,\\ \\lim_{x\\to1+}f(g(x))=1$"],"설명":"$\\displaystyle\\lim_{x\\to1}g(x)=1$ 로 존재하지만 합성함수의 좌·우극한이 달라 극한이 없다. ㄹ 은 항상 옳지 않으므로 항상 옳은 것은 ㄷ 뿐이다.","확인":"-1","스킬":"C3"}]},"ns-9cb77d5ba9d5":{"길":"$f(-x)$ 는 $-x$ 의 방향으로 바꿔 읽고, $f(f(x))$ 는 안쪽 $f(x)$ 의 방향부터 정한다","단계":[{"제목":"첫째 극한: $f(-x)$","힌트":"$x\\to1-$ 일 때 $-x$ 는 $-1$ 의 어느 쪽에서 다가가는가?","식":["$x<1$ 이면 $-x>-1$ 이므로 $-x\\to-1+$","$\\displaystyle\\lim_{x\\to1-}f(-x)=\\lim_{u\\to-1+}f(u)=0$"],"설명":"$x=-1$ 의 오른쪽 곡선은 닫힌 점 $(-1,0)$ 에서 시작한다. 왼쪽 열린 점의 높이 $1$ 은 좌극한이어서 쓰지 않는다.","확인":"0","스킬":"T6"},{"제목":"안쪽 $f(x)$ 의 방향","힌트":"$x\\to0-$ 일 때 $f(x)$ 는 $2$ 의 어느 쪽에서 다가가는가?","식":["$-1<x<0$ 에서 $f(x)$ 는 $0$ 에서 $2$ 로 증가하며 $f(x)<2$","$x\\to0-$ 이면 $f(x)\\to2-$"],"설명":"닫힌 점 $(0,2)$ 는 $x=0$ 일 때의 값이므로 $x\\to0-$ 인 동안 $f(x)$ 는 $2$ 에 도달하지 않는다.","확인":null,"스킬":"T6","고비":true},{"제목":"둘째 극한과 합","힌트":"$y\\to2-$ 일 때 $f(y)$ 의 극한은? 그 값과 첫째 극한을 더하면?","식":["$\\displaystyle\\lim_{x\\to0-}f(f(x))=\\lim_{y\\to2-}f(y)=0$","$0+0=0$"],"설명":"$x=2$ 근처에서 오른쪽 위로 향하는 직선이 $(2,0)$ 을 지난다. 이 직선은 $x=2$ 에서 끊기지 않으므로 극한은 $0$ 이다.","확인":"0","스킬":"T6"}]},"ns-a612c7d303f0":{"길":"극한값이 $0$ 이 되는 조건으로 $f$ 의 인수를 정하고 $n=4,\\ 5$ 의 값으로 $g$ 의 계수를 구한다","단계":[{"제목":"$x=2$ 의 공통인수","힌트":"$g(2)=0$ 이고 $\\displaystyle\\lim_{x\\to2}\\frac{f(x)}{g(x)}$ 가 존재하면 $f(2)$ 는?","식":["분모 $g(x)\\to0$ 이므로 분자 $f(2)=0$","$f(x)=(x-2)(x+a)(x+b),\\ g(x)=(x-2)(x+c)(x+d)$"],"설명":"분모가 $0$ 으로 가는데 극한이 존재하므로 분자도 $0$ 이어야 한다. 두 함수 모두 $x-2$ 를 인수로 가진다.","확인":null,"스킬":"D11"},{"제목":"$n=2$ 의 조건으로 $f$ 의 꼴","힌트":"약분한 식의 극한이 $0$ 이 되려면 분자 $(x+a)(x+b)$ 는?","식":["$\\displaystyle\\lim_{x\\to2}\\frac{(x+a)(x+b)}{(x+c)(x+d)}=0$ 이므로 분자가 $x=2$ 에서 $0$","$a=-2$ 로 두면 $f(x)=(x-2)^2(x+b)$"],"설명":"분모가 $0$ 이 아닌데 극한이 $0$ 이므로 분자의 한 인수가 $x-2$ 이다. $a$, $b$ 는 바꿔 불러도 같으므로 $a=-2$ 로 둔다.","확인":null,"스킬":"A3"},{"제목":"$n=3$ 의 조건으로 $b$ 구하기","힌트":"$x\\to3$ 에서 극한이 $0$ 이려면 분자에 있어야 하는 인수는?","식":["$\\displaystyle\\lim_{x\\to3}\\frac{f(x)}{g(x)}=0$ 이므로 $f(3)=0$","$(x-2)^2$ 은 $x=3$ 에서 $0$ 이 아니므로 $b=-3$"],"설명":"$g$ 가 $x-3$ 을 인수로 가지면 약분되어 극한이 $0$ 이 아니므로 $g(3)\\ne0$ 이다. 따라서 $f(x)=(x-2)^2(x-3)$ 이다.","확인":"-3","스킬":"A3","고비":true},{"제목":"$n=4,\\ 5$ 로 식 세우기","힌트":"$f$ 와 $g$ 의 $x-2$ 를 약분한 식에 $x\\to4$, $x\\to5$ 를 넣으면?","식":["$\\dfrac{f(x)}{g(x)}=\\dfrac{(x-2)(x-3)}{(x+c)(x+d)}$","$n=4$: $\\dfrac{2}{(4+c)(4+d)}=2$ 에서 $(4+c)(4+d)=1$","$n=5$: $\\dfrac{6}{(5+c)(5+d)}=6$ 에서 $(5+c)(5+d)=1$"],"설명":"$n=4$ 일 때 $(n-2)(n-3)=2$, $n=5$ 일 때 $6$ 이다.","확인":null,"스킬":"A3"},{"제목":"$c+d$ 와 $cd$ 의 값","힌트":"두 식을 전개해 $cd+k(c+d)$ 꼴로 정리하고 빼면?","식":["$cd+4(c+d)=-15,\\ cd+5(c+d)=-24$","$c+d=-9,\\ cd=21$"],"설명":"두 식을 빼면 $c+d$ 가 먼저 나온다. 이를 넣어 $cd$ 를 구한다.","확인":"-9","스킬":"A3"},{"제목":"$g(1)$ 의 값","힌트":"$g(x)=(x-2)\\{x^2+(c+d)x+cd\\}$ 에 $x=1$ 을 넣으면?","식":["$g(x)=(x-2)(x^2-9x+21)$","$g(1)=-1\\times(1-9+21)=-13$"],"설명":"$x^2-9x+21$ 에 $x=1$ 을 넣으면 $13$ 이다.","확인":"-13","스킬":"A3"}]},"ns-a7c40464c883":{"길":"$f$ 의 꼴을 두고 $f(2)=0$, $f\\,'(2)=-10$ 으로 계수를 구한 뒤 $x f(\\frac1x)$ 를 $f\\,'(0)$ 으로 읽는다","단계":[{"제목":"$f(x)$ 의 꼴","힌트":"분모가 $x^2$ 이고 극한이 $-13$ 이면 분자 $f(x)-2x^3$ 은?","식":["$f(x)-2x^3$ 은 이차식이고 $x^2$ 의 계수는 $-13$","$f(x)=2x^3-13x^2+ax+b$"],"설명":"분자의 차수가 분모와 같고 최고차항 계수의 비가 $-13$ 이므로 분자의 $x^2$ 계수가 $-13$ 이다.","확인":null,"스킬":"A11"},{"제목":"$f(2)$ 와 $f\\,'(2)$ 의 조건","힌트":"$x\\to2$ 에서 분모가 $0$ 으로 가는데 극한이 $-10$ 이면 $f(2)$ 는?","식":["분모 $x-2\\to0$ 이므로 $f(2)=0$","$\\displaystyle\\lim_{x\\to2}\\frac{f(x)-f(2)}{x-2}=f\\,'(2)=-10$"],"설명":"분모가 $0$ 으로 가면 분자도 $0$ 이어야 하므로 $f(2)=0$ 이다. 그러면 주어진 극한은 미분계수의 정의 꼴이다.","확인":null,"스킬":"D11","고비":true},{"제목":"$a$ 와 $b$ 의 값","힌트":"$f\\,'(x)=6x^2-26x+a$ 와 $f(2)=0$ 으로 두 식을 세워 풀면?","식":["$f\\,'(2)=24-52+a=-10$ 에서 $a=18$","$f(2)=16-52+2a+b=0$ 에서 $b=0$"],"설명":"$f(x)=2x^3-13x^2+ax+b$ 를 미분하면 $f\\,'(x)=6x^2-26x+a$ 이다.","확인":"0","스킬":"A3"},{"제목":"$xf\\!\\left(\\frac1x\\right)$ 의 극한","힌트":"$\\dfrac1x=h$ 로 놓고 $xf\\!\\left(\\frac1x\\right)$ 를 $h$ 의 식으로 쓰면?","식":["$h=\\dfrac1x\\to0+$ 이므로 $xf\\!\\left(\\dfrac1x\\right)=\\dfrac{f(h)}{h}=\\dfrac{f(h)-f(0)}{h-0}$","$\\displaystyle\\lim_{h\\to0+}\\frac{f(h)-f(0)}{h-0}=f\\,'(0)=a=18$"],"설명":"$f(0)=b=0$ 이므로 $f(h)=f(h)-f(0)$ 이다. 미분계수의 정의에서 $f\\,'(0)=a$ 이다.","확인":"18","스킬":"D3"}]},"ns-ab3caee081dc":{"길":"$x\\to2+$ 와 $x\\to2-$ 에서 $[x^2]$, $[x]$ 의 값을 따로 넣어 두 식을 세우고 연립한다","단계":[{"제목":"우극한의 식","힌트":"$x$ 가 $2$ 보다 조금 클 때 $[x^2]$ 와 $[x]$ 는 각각 얼마인가?","식":["$x\\to2+$: $x^2$ 은 $4$ 보다 조금 크므로 $[x^2]=4$, $[x]=2$","$4a+2b=3$"],"설명":"$2<x<\\sqrt5$ 이면 $4<x^2<5$ 이다. 극한이 $3$ 이므로 우극한도 $3$ 이다.","확인":null,"스킬":"N7"},{"제목":"좌극한의 식","힌트":"$x$ 가 $2$ 보다 조금 작을 때 $[x^2]$ 와 $[x]$ 는 각각 얼마인가?","식":["$x\\to2-$: $x^2$ 은 $4$ 보다 조금 작으므로 $[x^2]=3$, $[x]=1$","$3a+b=3$"],"설명":"$x$ 가 $2$ 보다 작으면 $x^2<4$ 이므로 $[x^2]$ 은 $4$ 가 아니라 $3$ 이다. 좌극한도 $3$ 이어야 한다.","확인":null,"스킬":"N7","고비":true},{"제목":"$a$, $b$ 의 값","힌트":"두 식 $4a+2b=3$, $3a+b=3$ 을 연립하면?","식":["$b=3-3a$ 를 $4a+2b=3$ 에 넣으면 $-2a+6=3$","$a=\\dfrac32,\\ b=-\\dfrac32$"],"설명":"둘째 식에서 $b$ 를 $a$ 로 나타내 첫째 식에 대입한다.","확인":"3/2","스킬":"A10"},{"제목":"$a+b$ 의 값","힌트":"구한 $a$, $b$ 를 더하면?","식":["$a+b=\\dfrac32-\\dfrac32=0$"],"설명":"두 값의 부호가 반대이다.","확인":"0","스킬":"A10"}]},"ns-ac6d1bdcb32d":{"길":"$a$ 는 $x>1$ 에서 절댓값을 풀어, $b$ 는 약분해 구한 뒤 근호의 차를 유리화해 $x\\to\\infty$ 로 보낸다","단계":[{"제목":"$a$ 의 값","힌트":"$x\\to1+$ 에서 $4x-4$ 의 부호는? 그러면 $|4x-4|$ 는?","식":["$x>1$ 이면 $|4x-4|=4(x-1)$","$\\displaystyle a=\\lim_{x\\to1+}\\frac{4(x-1)}{x-1}=4$"],"설명":"$x\\to1+$ 이므로 $4x-4>0$ 이다. 절댓값 안이 양수이면 그대로 나온다.","확인":"4","스킬":"C2"},{"제목":"$b$ 의 값","힌트":"분자를 인수분해해 분모와 공통인수를 지우면?","식":["$\\dfrac{x^2+2x}{-x-2}=\\dfrac{x(x+2)}{-(x+2)}=-x$","$\\displaystyle b=\\lim_{x\\to-2}(-x)=2$"],"설명":"$x\\to-2$ 이지만 $x\\ne-2$ 이므로 $x+2$ 로 약분한다.","확인":"2","스킬":"D11"},{"제목":"근호의 차의 극한","힌트":"$a=4$, $b=2$ 를 넣고 근호의 차를 분수로 바꾸려면 무엇을 곱하는가?","식":["$\\sqrt{x^2-4x}-\\sqrt{x^2-2x}=\\dfrac{-2x}{\\sqrt{x^2-4x}+\\sqrt{x^2-2x}}$","$\\displaystyle\\lim_{x\\to\\infty}\\frac{-2}{\\sqrt{1-\\frac4x}+\\sqrt{1-\\frac2x}}=\\frac{-2}{2}=-1$"],"설명":"분자와 분모에 두 제곱근의 합을 곱한다. $x>0$ 이므로 분모·분자를 $x$ 로 나눌 수 있다.","확인":"-1","스킬":"A11","고비":true}]},"ns-b2ad4d789f06":{"길":"분모가 $0$ 으로 가므로 분자도 $0$ 이라는 조건으로 $b$ 를 줄이고 인수분해로 $a$ 를 구한다","단계":[{"제목":"분자가 $0$ 이 되는 조건","힌트":"$x\\to1$ 에서 분모가 $0$ 으로 가는데 극한이 존재하면 분자는?","식":["$1-a-b=0$","$b=1-a$"],"설명":"분모가 $0$ 으로 가는데 극한이 수렴하려면 분자도 $0$ 으로 가야 한다. $x=1$ 을 분자에 넣는다.","확인":null,"스킬":"D11"},{"제목":"인수분해로 $a$ 구하기","힌트":"$b=1-a$ 를 넣은 분자를 $x-1$ 로 묶어 약분하면?","식":["$x^3-ax^2+a-1=(x-1)\\{x^2+(1-a)x+(1-a)\\}$","$\\displaystyle\\lim_{x\\to1}\\frac{x^2+(1-a)x+(1-a)}{x+1}=\\frac{3-2a}{2}=-\\frac52$ 에서 $a=4$"],"설명":"분모 $x^2-1=(x-1)(x+1)$ 이므로 $x-1$ 이 약분된다. $x=1$ 을 넣으면 분자는 $1+2(1-a)=3-2a$ 이다.","확인":"4","스킬":"D11","고비":true},{"제목":"$b$ 와 $a^2+b^2$","힌트":"$b=1-a$ 로 $b$ 를 구해 제곱의 합을 계산하면?","식":["$b=1-4=-3$","$a^2+b^2=16+9=25$"],"설명":"$b$ 가 음수여도 제곱하면 양수이다.","확인":"25","스킬":"D11"}]},"ns-be5a12272acb":{"길":"$t=\\frac1x$ 로 바꿔 $(t+1)f(t)$ 의 꼴을 정하고, 인수정리와 $f(0)=3$ 으로 계수를 구한 뒤 $k$ 를 계산한다","단계":[{"제목":"$t=\\frac1x$ 로 치환","힌트":"$x=\\dfrac1t$ 를 넣고 분모·분자에 $t^3$ 을 곱하면?","식":["$x\\to0+$ 이면 $t\\to\\infty$","$\\displaystyle\\lim_{t\\to\\infty}\\frac{\\left(\\frac1{t^3}+\\frac1{t^2}\\right)f(t)-1}{2\\left(\\frac1{t^2}-\\frac1t\\right)}=\\lim_{t\\to\\infty}\\frac{(1+t)f(t)-t^3}{2t(1-t)}=-4$"],"설명":"분자는 $(1+t)f(t)-t^3$, 분모는 $2t-2t^2=2t(1-t)$ 가 된다.","확인":null,"스킬":"A1"},{"제목":"$(t+1)f(t)$ 의 꼴","힌트":"극한이 $-4$ 이려면 분자 $(t+1)f(t)-t^3$ 의 $t^2$ 계수는?","식":["분모의 최고차항은 $-2t^2$","분자 $(t+1)f(t)-t^3$ 은 이차식이고 $t^2$ 의 계수는 $(-4)\\times(-2)=8$","$(t+1)f(t)=t^3+8t^2+at+b$"],"설명":"분모가 이차이고 극한이 유한하므로 분자도 이차이다. 계수의 비가 $-4$ 이므로 분자의 $t^2$ 계수는 $8$ 이다.","확인":"8","스킬":"A11","고비":true},{"제목":"$f(t)$ 의 꼴","힌트":"좌변이 $t+1$ 을 인수로 가지므로 $t=-1$ 을 넣으면?","식":["$0=-1+8-a+b$ 에서 $b=a-7$","$t^3+8t^2+at+a-7=(t+1)(t^2+7t+a-7)$","$f(t)=t^2+7t+a-7$"],"설명":"$f$ 가 다항함수이므로 $(t+1)f(t)$ 는 $t+1$ 로 나누어떨어진다. 조립제법으로 몫을 구한다.","확인":null,"스킬":"A4"},{"제목":"$a$ 의 값","힌트":"$x\\to0$ 에서 분모가 $0$ 으로 가는데 $\\dfrac{f(x)-3}{x}$ 의 극한이 존재하면 $f(0)$ 은?","식":["분모 $x\\to0$ 이므로 $f(0)-3=0$, $f(0)=3$","$f(0)=a-7=3$ 에서 $a=10$"],"설명":"분모가 $0$ 으로 가는데 극한이 존재하므로 분자도 $0$ 이어야 한다.","확인":"10","스킬":"D11"},{"제목":"$k$ 의 값","힌트":"$f(x)=x^2+7x+3$ 을 넣어 약분하면?","식":["$\\displaystyle k=\\lim_{x\\to0}\\frac{x^2+7x}{x}=\\lim_{x\\to0}(x+7)=7$"],"설명":"$x\\to0$ 이지만 $x\\ne0$ 이므로 $x$ 로 약분한다.","확인":"7","스킬":"D3"}]},"ns-c21d421e0c63":{"길":"$\\frac{f+2g}{f}$ 의 극한으로 $\\frac gf$ 를 구한 뒤 구하는 식의 분모·분자를 $f$ 로 나눈다","단계":[{"제목":"$\\dfrac{f+2g}{f}$ 의 극한","힌트":"분자는 $1$ 로 수렴하고 분모는 $\\infty$ 로 가면 분수의 극한은?","식":["$\\displaystyle\\lim_{x\\to\\infty}\\frac{f(x)+2g(x)}{f(x)}=0$"],"설명":"유한한 값을 한없이 커지는 값으로 나누면 $0$ 으로 간다.","확인":"0","스킬":"A1"},{"제목":"$\\dfrac{2g}{f}$ 의 극한","힌트":"$\\dfrac{f+2g}{f}$ 를 $1+\\dfrac{2g}{f}$ 로 쓰면?","식":["$1+\\dfrac{2g(x)}{f(x)}\\to0$","$\\displaystyle\\lim_{x\\to\\infty}\\frac{2g(x)}{f(x)}=-1,\\ \\lim_{x\\to\\infty}\\frac{g(x)}{f(x)}=-\\frac12$"],"설명":"$f\\to\\infty$ 이므로 $x$ 가 크면 $f(x)\\ne0$ 이어서 $f$ 로 나눌 수 있다. $\\dfrac{2g}{f}$ 의 극한이 존재하므로 각각 쪼개 쓴다.","확인":"-1","스킬":"A1","고비":true},{"제목":"분모·분자를 $f$ 로 나누기","힌트":"구하는 식의 분모·분자를 $f(x)$ 로 나누고 $\\dfrac gf\\to-\\dfrac12$ 를 넣으면?","식":["$\\dfrac{f+4g}{f-2g}=\\dfrac{1+4\\cdot\\frac gf}{1-2\\cdot\\frac gf}$","$\\displaystyle\\lim_{x\\to\\infty}=\\frac{1+4\\cdot\\left(-\\frac12\\right)}{1-2\\cdot\\left(-\\frac12\\right)}=\\frac{-1}{2}=-\\frac12$"],"설명":"분자는 $1-2=-1$, 분모는 $1+1=2$ 이다.","확인":"-1/2","스킬":"A1"}]},"ns-c3d559d35711":{"길":"$a<4$, $a=4$, $a>4$ 로 나눠 절댓값의 부호를 정하고 극한이 존재하며 $b$ 가 자연수인 경우만 남긴다","단계":[{"제목":"$a<4$ 인 경우","힌트":"$x\\to4$ 일 때 $|x-a|$ 안의 부호는?","식":["$x>a$ 이므로 $|x-a|=x-a$, $|a-4|=4-a$","$\\displaystyle\\lim_{x\\to4}\\frac{(x-a)-(4-a)}{(x-4)(x+4)}=\\lim_{x\\to4}\\frac1{x+4}=\\frac18=\\frac b{16}$ 에서 $b=2$"],"설명":"$a<4$ 이면 $x$ 가 $4$ 에 가까울 때 $x>a$ 이다. $a$ 는 자연수이므로 $a=1,\\ 2,\\ 3$ 이고 $a+b$ 는 최대 $a=3$ 일 때 $5$ 이다.","확인":"2","스킬":"C2","고비":true},{"제목":"$a=4$ 인 경우","힌트":"분자가 $|x-4|$ 일 때 좌극한과 우극한은 같은가?","식":["$\\displaystyle\\lim_{x\\to4+}\\frac{|x-4|}{(x+4)(x-4)}=\\frac18$","$\\displaystyle\\lim_{x\\to4-}\\frac{|x-4|}{(x+4)(x-4)}=-\\frac18$"],"설명":"좌극한과 우극한이 다르므로 극한이 존재하지 않는다. 이 경우는 조건에 맞지 않아 버린다.","확인":null,"스킬":"C2"},{"제목":"$a>4$ 인 경우","힌트":"$x<a$ 일 때 절댓값을 풀어 분자를 쓰면?","식":["$|x-a|=a-x$, $|a-4|=a-4$ 이므로 분자는 $(a-x)-(a-4)=-(x-4)$","$\\displaystyle\\lim_{x\\to4}\\frac{-(x-4)}{(x-4)(x+4)}=-\\frac18=\\frac b{16}$ 에서 $b=-2$"],"설명":"$b$ 는 자연수여야 하는데 $-2$ 는 자연수가 아니므로 이 경우도 버린다.","확인":"-2","스킬":"C2"},{"제목":"$a+b$ 의 최댓값","힌트":"조건에 맞는 경우에서 $a+b$ 가 가장 큰 때는?","식":["가능한 경우는 $a<4$, $b=2$ 뿐","$a=3$ 일 때 $a+b=5$"],"설명":"$a=1,\\ 2,\\ 3$ 중 가장 큰 $a=3$ 을 택한다.","확인":"5","스킬":"C2"}]},"ns-c46d8ba74565":{"길":"$g(x)=x^3f(\\frac1x)$ 로 보아 $g$ 의 근이 $f$ 의 근의 역수임을 쓰고, 극한이 존재할 조건으로 $\\alpha$ 를 정한다","단계":[{"제목":"$g$ 의 근과 $f$ 의 근의 관계","힌트":"$x^3f\\!\\left(\\dfrac1x\\right)$ 을 전개하면 $g(x)$ 와 어떻게 비교되는가?","식":["$x^3f\\!\\left(\\dfrac1x\\right)=1+ax+bx^2+cx^3=g(x)$","$f(r)=0$ 이면 $g\\!\\left(\\dfrac1r\\right)=0$ 이므로 $g$ 의 근은 $2,\\ \\dfrac13,\\ \\dfrac1\\alpha$"],"설명":"$f$ 의 근 $\\dfrac12,\\ 3,\\ \\alpha$ 의 역수가 $g$ 의 근이다. $r\\ne0$ 이므로 $\\dfrac1r$ 이 정의된다.","확인":null,"스킬":"A3"},{"제목":"$\\alpha$ 의 값","힌트":"$t\\ne2$ 에서 극한이 존재하려면 $g$ 의 근 $\\dfrac13$ 은 $f$ 에 대해 어떤 조건을 만족해야 하는가?","식":["$g$ 의 근 $\\dfrac13$ 은 $f$ 의 근이어야 약분되므로 $\\alpha=\\dfrac13$","이때 $\\dfrac1\\alpha=3$ 도 $f$ 의 근"],"설명":"$\\dfrac13$ 은 $\\dfrac12,\\ 3$ 이 아니므로 $\\alpha=\\dfrac13$ 이다. $\\alpha=\\dfrac12$ 이면 $\\dfrac1\\alpha=2$ 가 되지만 $\\dfrac13$ 이 약분되지 않아 극한이 없는 점이 생기므로 버린다.","확인":"1/3","스킬":"C8","고비":true},{"제목":"$c$ 의 값과 $g(x)$","힌트":"$f(x)=\\left(x-\\dfrac12\\right)(x-3)(x-\\alpha)$ 의 상수항으로 $c$ 를 구하면?","식":["$c=-\\dfrac12\\cdot3\\cdot\\alpha=-\\dfrac12$","$g(x)=-\\dfrac12(x-2)\\left(x-\\dfrac13\\right)(x-3)$"],"설명":"$f$ 의 상수항이 $c$ 이고 $g$ 의 최고차항 계수도 $c$ 이다. $g$ 의 근은 $2,\\ \\dfrac13,\\ 3$ 이다.","확인":"-1/2","스킬":"A3"},{"제목":"$\\displaystyle\\lim_{x\\to\\alpha}\\frac{f(x)}{g(x)}$ 의 값","힌트":"$f$, $g$ 의 공통인수를 약분하고 $x=\\dfrac13$ 을 넣으면?","식":["$\\dfrac{f(x)}{g(x)}=\\dfrac{\\left(x-\\frac12\\right)(x-3)\\left(x-\\frac13\\right)}{-\\frac12(x-2)\\left(x-\\frac13\\right)(x-3)}=\\dfrac{x-\\frac12}{-\\frac12(x-2)}$","$\\displaystyle\\lim_{x\\to\\frac13}=\\frac{-\\frac16}{-\\frac12\\cdot\\left(-\\frac53\\right)}=-\\frac15$"],"설명":"$x\\to\\dfrac13$ 이지만 $x\\ne\\dfrac13$ 이므로 $x-\\dfrac13$ 과 $x-3$ 을 약분한다.","확인":"-1/5","스킬":"D11"}]},"ns-c71c99643ee4":{"길":"$x\\to2+$ 와 $x\\to2-$ 에서 절댓값을 따로 풀어 $a$, $b$ 를 구한 뒤 $2a+b$ 를 계산한다","단계":[{"제목":"$a$ 의 값","힌트":"$x\\to2+$ 일 때 $|2-x|$ 는 어떤 식으로 쓰이는가?","식":["$x>2$ 이면 $|2-x|=x-2$","$\\displaystyle a=\\lim_{x\\to2+}\\frac{(x-2)(x+1)}{x-2}=3$"],"설명":"분자는 $x^2-x-2=(x-2)(x+1)$ 로 인수분해된다. $x\\ne2$ 이므로 $x-2$ 로 약분한다.","확인":"3","스킬":"C2"},{"제목":"$b$ 의 값","힌트":"$x\\to2-$ 일 때 $|2-x|$ 는 어떤 식으로 쓰이는가?","식":["$x<2$ 이면 $|2-x|=2-x=-(x-2)$","$\\displaystyle b=\\lim_{x\\to2-}\\frac{(x-2)(x+1)}{-(x-2)}=-3$"],"설명":"$x<2$ 이면 $2-x>0$ 이어서 절댓값이 $2-x$ 이다. 부호가 바뀌어 우극한과 반대 부호가 나온다.","확인":"-3","스킬":"C2","고비":true},{"제목":"$2a+b$ 의 값","힌트":"$a$, $b$ 를 넣어 계산하면?","식":["$2a+b=2\\cdot3+(-3)=3$"],"설명":"좌극한과 우극한이 달라도 $a$, $b$ 는 각각 정의된 상수이다.","확인":"3","스킬":"C2"}]},"ns-c88a337176af":{"길":"보기마다 극한의 사칙 성질로 증명하거나 반례를 만들어 옳은 것의 개수를 센다","단계":[{"제목":"ㄱ. 차의 극한","힌트":"$g(x)$ 를 $f(x)+g(x)$ 와 $f(x)$ 로 나타내면?","식":["$g(x)=\\{f(x)+g(x)\\}-f(x)$","$\\displaystyle\\lim_{x\\to\\infty}g(x)=\\beta-\\alpha$"],"설명":"두 극한이 각각 존재하면 차의 극한은 극한의 차이다. ㄱ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"ㄴ. 곱의 극한이 있어도 없는 경우","힌트":"$f(x)=0$ 과 곱해도 극한이 정해지는 $g(x)$ 는?","식":["$f(x)=0,\\ g(x)=(-1)^{[x]}$","$\\displaystyle\\lim_{x\\to\\infty}f(x)=0,\\ \\lim_{x\\to\\infty}f(x)g(x)=0$ 이지만 $g$ 는 $1$, $-1$ 을 오가 극한이 없음"],"설명":"$f=0$ 이면 곱이 항상 $0$ 이어서 $g$ 의 모양과 무관하다. 반례가 있으므로 ㄴ 은 옳지 않다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄷ. 부등호가 극한에서 유지되는가","힌트":"$f(x)<g(x)$ 인데 두 극한이 같아지는 예는?","식":["$f(x)=-\\dfrac1{x^2+1},\\ g(x)=\\dfrac1{x^2+1}$","$f(x)<g(x)$ 이지만 $\\displaystyle\\lim_{x\\to\\infty}f(x)=\\lim_{x\\to\\infty}g(x)=0$"],"설명":"극한을 취하면 $<$ 가 $\\le$ 로 약해진다. 반례가 있으므로 ㄷ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄹ. $\\dfrac{x}{f(x)}\\to0$ 의 해석과 개수","힌트":"$f(x)=1$ 이면 $\\dfrac{x}{f(x)}$ 와 $f$ 의 극한은?","식":["$f(x)=1$: $\\displaystyle\\lim_{x\\to0}\\frac{x}{f(x)}=0$ 이지만 $\\lim_{x\\to0}f(x)=1\\ne0$","옳은 것은 ㄱ 하나이므로 개수는 $1$"],"설명":"분자가 $0$ 으로 가는 것만으로 분수가 $0$ 이 될 수 있어 $f$ 가 $0$ 일 필요가 없다. ㄹ 은 옳지 않다.","확인":"1","스킬":"C3"}]},"ns-cce838e8998d":{"길":"$x=-t$ 로 치환해 $t\\to\\infty$ 로 바꾼 뒤 근호의 차를 유리화해 $a$ 를 구한다","단계":[{"제목":"치환으로 $t\\to\\infty$ 만들기","힌트":"$x=-t$ 로 놓으면 $x\\to-\\infty$ 는 어떤 극한이 되고 식은 어떻게 쓰이는가?","식":["$x\\to-\\infty$ 이면 $t\\to\\infty$","$\\sqrt{x^2+ax}-\\sqrt{x^2+3x}=\\sqrt{t^2-at}-\\sqrt{t^2-3t}$"],"설명":"$x<0$ 이면 분모·분자를 $x$ 로 나눌 때 부호가 바뀌기 쉽다. $t>0$ 으로 바꾸면 $\\sqrt{t^2}=t$ 로 정리된다.","확인":null,"스킬":"A1"},{"제목":"근호의 차를 분수로","힌트":"분자와 분모에 두 제곱근의 합을 곱하면?","식":["$\\sqrt{t^2-at}-\\sqrt{t^2-3t}=\\dfrac{(t^2-at)-(t^2-3t)}{\\sqrt{t^2-at}+\\sqrt{t^2-3t}}=\\dfrac{(3-a)t}{\\sqrt{t^2-at}+\\sqrt{t^2-3t}}$"],"설명":"$(A-B)(A+B)=A^2-B^2$ 이다. $t^2$ 이 지워져 $t$ 의 일차식만 남는다.","확인":null,"스킬":"A1","고비":true},{"제목":"극한과 $a$ 의 값","힌트":"분모·분자를 $t$ 로 나누고 $t\\to\\infty$ 로 보낸 값을 $5$ 와 같게 놓으면?","식":["$\\displaystyle\\lim_{t\\to\\infty}\\frac{3-a}{\\sqrt{1-\\frac at}+\\sqrt{1-\\frac3t}}=\\frac{3-a}{2}=5$","$a=-7$"],"설명":"$\\dfrac at$, $\\dfrac3t$ 는 $0$ 으로 가므로 두 제곱근은 각각 $1$ 로 가까워진다.","확인":"-7","스킬":"A1"}]},"ns-dd87ed0f49ce":{"길":"$x\\to a\\pm$ 에서 $[x]$ 의 값을 정해 $(-1)^{[x]}$ 의 부호를 계산하고 보기마다 비교한다","단계":[{"제목":"ㄱ, ㄴ: $x\\to-1+$, $x\\to1+$","힌트":"$x$ 가 $-1$ 과 $1$ 의 오른쪽에 있을 때 $[x]$ 는 각각 얼마인가?","식":["ㄱ. $[x]=-1$ 이므로 $\\dfrac{(-1)^{-1}}{-1}=\\dfrac{-1}{-1}=1$, 옳음","ㄴ. $[x]=1$ 이므로 $\\dfrac{(-1)^{1}}{1}=-1\\ne1$, 옳지 않음"],"설명":"$a$ 의 오른쪽에서는 $[x]=a$ 이다. ㄴ 의 실제 값은 $1$ 이 아니라 $-1$ 이다.","확인":"-1","스킬":"N7"},{"제목":"ㄷ, ㄹ: $x\\to3-$, $x\\to2+$","힌트":"$x$ 가 $3$ 의 왼쪽, $2$ 의 오른쪽에 있을 때 $[x]$ 는 각각 얼마인가?","식":["ㄷ. $[x]=2$ 이므로 $\\displaystyle\\lim_{x\\to3-}f(x)=\\frac{(-1)^2}{3}=\\frac13$, 옳음","ㄹ. $[x]=2$ 이므로 $\\displaystyle\\lim_{x\\to2+}f(x)=\\frac{(-1)^2}{2}=\\frac12$, 옳음"],"설명":"$a$ 의 왼쪽에서는 $[x]=a-1$ 이므로 $x\\to3-$ 에서 $[x]=2$ 이다. 옳은 것은 ㄱ, ㄷ, ㄹ 이다.","확인":null,"스킬":"N7","고비":true}]},"ns-e7884bb10c07":{"길":"$n=2,\\ 3$ 의 극한이 $0$ 임을 써서 $f$ 를 정하고, $n=1,\\ 4$ 의 값으로 $g$ 의 이차인수를 구한다","단계":[{"제목":"$x=2$ 에서의 인수","힌트":"$g(2)=0$ 인데 $\\displaystyle\\lim_{x\\to2}\\frac{f(x)}{g(x)}=0$ 이면 $f$ 는 $x-2$ 를 몇 번 인수로 가져야 하는가?","식":["$g(x)=(x-2)h(x)$ 라 하면 $\\dfrac{f(x)}{g(x)}\\to0$ 이므로 $f(x)=(x-2)^2(\\cdots)$"],"설명":"분모에 $x-2$ 가 한 번 있으므로 분자는 두 번 이상 가져야 극한이 $0$ 이 된다. $g$ 가 $(x-2)^2$ 을 가지면 $f=(x-2)^3$ 이 되어 $n=3$ 에서 극한이 $0$ 일 수 없으므로 버린다.","확인":null,"스킬":"D11"},{"제목":"$x=3$ 에서의 인수와 $f$ 의 꼴","힌트":"$\\displaystyle\\lim_{x\\to3}\\frac{f(x)}{g(x)}=0$ 이면 $f$ 의 나머지 인수는?","식":["$f(3)=0$ 이어야 하므로 $f(x)=(x-2)^2(x-3)$"],"설명":"$g(3)=0$ 이면 $f$ 가 $x-3$ 을 두 번 가져야 하는데 $f$ 에 남은 인수는 일차뿐이어서 불가능하다. 따라서 $g(3)\\ne0$ 이고 $f(3)=0$ 이다.","확인":null,"스킬":"D11","고비":true},{"제목":"$n=1,\\ 4$ 의 조건","힌트":"$g(x)=(x-2)h(x)$ 로 놓고 $\\dfrac{f(x)}{g(x)}$ 를 약분한 뒤 $x\\to1$, $x\\to4$ 를 넣으면?","식":["$\\dfrac{f(x)}{g(x)}=\\dfrac{(x-2)(x-3)}{h(x)}$","$n=1$: $\\dfrac{2}{h(1)}=2$ 에서 $h(1)=1$","$n=4$: $\\dfrac{2}{h(4)}=2$ 에서 $h(4)=1$"],"설명":"$n=1$, $4$ 일 때 $(n-2)(n-3)=2$ 이다. $h(1)=0$ 이면 분자가 $2$ 이므로 발산하여 조건에 맞지 않는다.","확인":"1","스킬":"A3"},{"제목":"$h(x)$ 의 식과 $h(5)$","힌트":"이차식 $h(x)-1$ 의 두 근이 $1$, $4$ 이면 $h(x)$ 는?","식":["$h(x)=(x-1)(x-4)+1=x^2-5x+5$","$h(5)=25-25+5=5$"],"설명":"$h$ 는 최고차항 계수가 $1$ 인 이차식이므로 $h(x)-1=(x-1)(x-4)$ 이다.","확인":"5","스킬":"A3"},{"제목":"$g(5)$ 의 값","힌트":"$g(x)=(x-2)h(x)$ 에 $x=5$ 를 넣으면?","식":["$g(5)=(5-2)\\times h(5)=3\\times5=15$"],"설명":"앞에서 구한 $h(5)=5$ 를 곱한다.","확인":"15","스킬":"A3"}]},"ns-006fd09ba710":{"길":"선지마다 경계에서 극한과 함숫값을 비교해 연속이 아닌 함수를 찾는다","단계":[{"제목":"기본 함수의 연속","힌트":"①, ②, ⑤ 는 모든 실수에서 연속인가?","식":["① 다항함수는 모든 실수에서 연속","② $x^2-2x+3=(x-1)^2+2>0$ 이라 분모가 $0$ 이 되지 않아 연속","⑤ 연속함수 $x^2-2x-2$ 의 절댓값이므로 연속"],"설명":"연속함수의 합·곱·몫(분모 $\\ne0$)과 절댓값은 연속이다.","확인":null,"스킬":"D12"},{"제목":"③ 의 경계 $x=-1$","힌트":"③ 에서 $x\\to-1-$, $x\\to-1+$ 일 때의 극한과 $f(-1)$ 은?","식":["$\\lim_{x\\to-1-}(x+2)=1$, $\\lim_{x\\to-1+}x^2=1$","$f(-1)=(-1)^2=1$"],"설명":"좌극한, 우극한, 함숫값이 모두 같으므로 $x=-1$ 에서 연속이다.","확인":"1","스킬":"D12"},{"제목":"④ 의 경계 $x=-1$","힌트":"④ 에서 $x\\to-1$ 일 때의 극한을 $f(-1)$ 과 비교하면?","식":["$\\lim_{x\\to-1}\\frac{x^2+3x+2}{x+1}=\\lim_{x\\to-1}\\frac{(x+1)(x+2)}{x+1}=\\lim_{x\\to-1}(x+2)=1$","$f(-1)=3$ 이므로 극한값 $\\ne$ 함숫값"],"설명":"극한값이 존재해도 함숫값과 다르면 불연속이다. 따라서 연속이 아닌 함수는 ④ 이다.","확인":null,"스킬":"D12","고비":true}]},"ns-05f51ab24162":{"길":"분모가 모든 실수에서 $0$ 이 되지 않도록 완전제곱 꼴로 바꿔 $a$ 의 범위를 구한다","단계":[{"제목":"연속이 되는 조건","힌트":"$\\frac{f(x)}{g(x)}$ 가 모든 실수에서 연속이려면 $g(x)$ 에 어떤 조건이 필요한가?","식":["모든 실수 $x$ 에서 $g(x)\\ne0$"],"설명":"$f$, $g$ 는 다항함수라 연속이므로 분모가 $0$ 이 되는 $x$ 가 없어야 한다.","확인":null,"스킬":"C1"},{"제목":"분모의 완전제곱 꼴","힌트":"$g(x)=x^2+4x+a$ 를 $(x+2)^2$ 이 보이게 고치면?","식":["$g(x)=x^2+4x+4+a-4$","$=(x+2)^2+a-4$"],"설명":"$x^2+4x$ 에 $4$ 를 더해 $(x+2)^2=x^2+4x+4$ 를 만든다.","확인":null,"스킬":"A6"},{"제목":"$a$ 의 범위","힌트":"$(x+2)^2\\ge0$ 일 때 $g(x)$ 가 모든 실수에서 $0$ 이 아니려면 $a-4$ 의 부호는?","식":["$g(x)$ 의 최솟값은 $x=-2$ 일 때 $a-4$","$a-4>0$ 이므로 $a>4$"],"설명":"$a-4=0$ 이면 $g(-2)=0$ 이고, $a-4<0$ 이면 $g(x)=0$ 인 실근이 생겨 연속이 아니다.","확인":null,"스킬":"C1","고비":true},{"제목":"정수 $a$ 의 최솟값","힌트":"$a>4$ 를 만족하는 정수 $a$ 중 가장 작은 값은?","식":["$a>4$ 인 정수 중 최소는 $5$"],"설명":"$a=4$ 는 범위에 들지 않는다.","확인":"5","스킬":"C1"}]},"ns-08143eae7661":{"길":"보기마다 좌·우극한과 함숫값을 그래프에서 읽고 합성은 안쪽 함수의 극한 방향을 먼저 정한다","단계":[{"제목":"ㄱ. $x=1$ 에서의 곱","힌트":"$x=1$ 에서 $f(x)g(x)$ 의 좌극한, 우극한, 함숫값을 구하면?","식":["$\\lim_{x\\to1+}f(x)g(x)=1\\times0=0$, $\\lim_{x\\to1-}f(x)g(x)=0\\times1=0$","$f(1)g(1)=0\\times0=0$"],"설명":"그래프에서 $f(1+)=1$, $f(1-)=0$, $f(1)=0$ 이고 $g(1+)=0$, $g(1-)=1$, $g(1)=0$ 이다. 세 값이 같으므로 연속이다.","확인":"0","스킬":"D12"},{"제목":"ㄴ. 합성함수의 우극한","힌트":"$x\\to0+$ 일 때 $f(x)$ 는 어느 쪽에서 어떤 값에 가까워지는가?","식":["$x\\to0+$ 일 때 $f(x)\\to1-$","$\\lim_{x\\to0+}g(f(x))=\\lim_{t\\to1-}g(t)=1$"],"설명":"$0<x\\le1$ 에서 $f(x)=1-x$ 이므로 $t=f(x)$ 는 $1$ 보다 작은 쪽에서 $1$ 에 가까워진다. 그래프에서 $0\\le t<1$ 일 때 $g(t)=1$ 이다.","확인":null,"스킬":"T6"},{"제목":"ㄷ. $x=0$ 에서의 $f(f(x))$","힌트":"$x\\to0+$, $x\\to0-$ 일 때 $f(f(x))$ 의 극한과 $f(f(0))$ 은?","식":["$\\lim_{x\\to0+}f(f(x))=\\lim_{t\\to1-}f(t)=0$","$\\lim_{x\\to0-}f(f(x))=\\lim_{t\\to0-}f(t)=0$, $f(f(0))=f(0)=0$"],"설명":"$x\\to0+$ 이면 $f(x)\\to1-$ 이고, $x\\to0-$ 이면 $f(x)=x\\to0-$ 이다. 세 값이 모두 $0$ 이므로 연속이다.","확인":"0","스킬":"T6","고비":true},{"제목":"보기의 판정","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 어느 것인가?","식":["ㄱ, ㄴ, ㄷ 모두 옳다"],"설명":"정답은 ⑤ 이다.","확인":null,"스킬":"D12"}]},"ns-084ce0a45196":{"길":"분수함수를 $2+\\frac{k}{x-1}$ 꼴로 고쳐 감소함을 읽고 끝값으로 최댓값을 구한다","단계":[{"제목":"분수함수의 변형","힌트":"$\\frac{2x+1}{x-1}$ 을 $2+\\frac{k}{x-1}$ 꼴로 나타내면 $k$ 는?","식":["$\\frac{2x+1}{x-1}=\\frac{2(x-1)+3}{x-1}=2+\\frac3{x-1}$"],"설명":"분자를 $2(x-1)+3$ 으로 쪼갠다. 구간 $[2,\\,4]$ 에서 $x-1>0$ 이므로 $f$ 는 감소한다.","확인":"3","스킬":"T4","고비":true},{"제목":"최댓값","힌트":"감소하는 함수의 최댓값은 구간의 어느 끝점에서 생기고 그 값은?","식":["최댓값은 $x=2$ 에서 $f(2)=\\frac51=5$"],"설명":"$f(4)=\\frac93=3$ 이므로 $f(2)$ 가 더 크다.","확인":"5","스킬":"T4"}]},"ns-0b2063edc034":{"길":"$x=0$ 에서 $f$, $g$ 의 좌·우극한과 함숫값을 그래프에서 읽어 보기마다 연속을 따진다","단계":[{"제목":"그래프에서 읽는 극한","힌트":"$x=0$ 에서 $f$ 의 좌극한·우극한·함숫값과 $g$ 의 좌극한·우극한은?","식":["$\\lim_{x\\to0-}f(x)=-1$, $\\lim_{x\\to0+}f(x)=1$, $f(0)=0$","$\\lim_{x\\to0-}g(x)=-\\infty$, $\\lim_{x\\to0+}g(x)=\\infty$, $g(0)=1$"],"설명":"$f$ 는 $x=0$ 에서 불연속이고 $g$ 는 $x=0$ 이 점근선이라 발산한다.","확인":null,"스킬":"D12"},{"제목":"ㄱ, ㄴ 의 발산","힌트":"$x\\to0$ 일 때 $f(x)g(x)$ 와 $f(g(x))$ 는 극한값을 가지는가?","식":["ㄱ. $x\\to0+$ 이면 $1\\times\\infty$, $x\\to0-$ 이면 $(-1)\\times(-\\infty)$ 이므로 모두 $\\infty$ 로 발산","ㄴ. $x\\to0-$ 이면 $g(x)\\to-\\infty$ 라 $f(g(x))\\to-\\infty$, $x\\to0+$ 이면 $f(g(x))\\to\\infty$"],"설명":"극한값이 존재하지 않으므로 ㄱ, ㄴ 은 $x=0$ 에서 불연속이다.","확인":null,"스킬":"T6","고비":true},{"제목":"ㄷ. $f(x-1)$","힌트":"$x\\to0$ 일 때 $f(x-1)$ 은 $f$ 의 어느 점의 값에 가까워지는가?","식":["$x\\to0$ 이면 $x-1\\to-1$","$\\lim_{x\\to0}f(x-1)=f(-1)=-2$, $f(0-1)=-2$"],"설명":"$f$ 는 $x=-1$ 근처에서 연속이므로 극한값과 함숫값이 같다.","확인":"-2","스킬":"D12"},{"제목":"ㄹ. $\\frac{f(x)}{g(x)}$","힌트":"$x\\to0$ 일 때 $\\frac{f(x)}{g(x)}$ 의 극한은?","식":["분자는 $\\pm1$ 에 가까워지고 $|g(x)|$ 는 한없이 커지므로 $\\lim_{x\\to0}\\frac{f(x)}{g(x)}=0$","$\\frac{f(0)}{g(0)}=\\frac01=0$"],"설명":"극한값과 함숫값이 모두 $0$ 이므로 연속이다.","확인":"0","스킬":"D12"},{"제목":"보기의 판정","힌트":"$x=0$ 에서 연속인 것은 ㄱ~ㄹ 중 어느 것인가?","식":["연속인 것은 ㄷ, ㄹ"],"설명":"정답은 ③ 이다.","확인":null,"스킬":"D12"}]},"ns-1211799cd241":{"길":"$x=2$ 에서 연속이려면 분자가 $0$ 이어야 함을 써서 $a$ 를 구하고 $f(2)$ 를 극한으로 구한다","단계":[{"제목":"$a$ 의 값","힌트":"분모가 $0$ 에 가까워지는데 극한값이 존재하려면 $a$ 는 어떤 값이어야 하는가?","식":["$x\\ne2$ 에서 $f(x)=\\frac{x^2+a(x-1)}{x-2}$","$\\lim_{x\\to2}\\left\\{x^2+a(x-1)\\right\\}=4+a=0$ 에서 $a=-4$"],"설명":"$f$ 가 $x=2$ 에서 연속이므로 $\\lim_{x\\to2}f(x)$ 가 존재한다. (분모)$\\to0$ 이므로 (분자)$\\to0$ 이어야 한다.","확인":"-4","스킬":"D11","고비":true},{"제목":"$f(2)$ 의 값","힌트":"$a=-4$ 일 때 $x\\ne2$ 에서 $f(x)$ 를 약분하면 $f(2)$ 는?","식":["$f(x)=\\frac{x^2-4x+4}{x-2}=\\frac{(x-2)^2}{x-2}=x-2$ ($x\\ne2$)","$f(2)=\\lim_{x\\to2}(x-2)=0$"],"설명":"연속이므로 $f(2)$ 는 $x\\to2$ 일 때의 극한값과 같다.","확인":"0","스킬":"D11"}]},"ns-12e48ff2df46":{"길":"보기마다 $x=0$, $x=3$ 에서 좌·우극한과 함숫값을 그래프에서 읽어 비교한다","단계":[{"제목":"ㄱ. $x=0$ 에서의 합","힌트":"$x\\to0-$ 일 때 $f(x)+g(x)$ 의 극한은?","식":["$\\lim_{x\\to0-}\\{f(x)+g(x)\\}=0+3=3$","$\\lim_{x\\to0+}\\{f(x)+g(x)\\}=3+3=6$"],"설명":"좌극한과 우극한이 다르므로 $x=0$ 에서 극한값이 없고 불연속이다.","확인":"3","스킬":"D12"},{"제목":"ㄴ. $x=3$ 에서의 곱","힌트":"$x=3$ 에서 $f(x)g(x)$ 의 극한과 함숫값 $f(3)g(3)$ 은?","식":["$\\lim_{x\\to3-}f(x)g(x)=3\\times0=0$, $\\lim_{x\\to3+}f(x)g(x)=5\\times0=0$","$f(3)g(3)=5\\times3=15$"],"설명":"극한값 $0$ 과 함숫값 $15$ 가 다르므로 불연속이다.","확인":"15","스킬":"D12"},{"제목":"ㄷ. $x=3$ 에서의 합성함수","힌트":"$x\\to3-$, $x\\to3+$ 일 때 $f(x)$ 의 값을 따라 $g(f(x))$ 의 극한은?","식":["$x\\to3-$ 이면 $f(x)=3$ 이므로 $g(f(x))=g(3)=3$","$x\\to3+$ 이면 $f(x)=5$ 이므로 $g(f(x))=g(5)=3$, $g(f(3))=g(5)=3$"],"설명":"$f(x)$ 가 $x=3$ 의 양쪽에서 상수 $3$, $5$ 이므로 바깥함수 $g$ 의 값 $g(3)$, $g(5)$ 만 읽으면 된다. 세 값이 같아 연속이다.","확인":"3","스킬":"T6","고비":true},{"제목":"보기의 판정","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 어느 것인가?","식":["ㄱ, ㄴ, ㄷ 모두 옳다"],"설명":"정답은 ⑤ 이다.","확인":null,"스킬":"D12"}]},"ns-15a2fced918d":{"길":"연속이므로 $f(1)$ 을 $x\\to1$ 의 극한으로 쓰고 분자를 유리화해 구한다","단계":[{"제목":"$f(1)$ 을 극한으로","힌트":"$f$ 가 $x=1$ 에서 연속이면 $f(1)$ 은 어떤 극한과 같은가?","식":["$x\\ne1$ 에서 $f(x)=\\frac{\\sqrt{x+3}-2}{x-1}$","$f(1)=\\lim_{x\\to1}f(x)=\\lim_{x\\to1}\\frac{\\sqrt{x+3}-2}{x-1}$"],"설명":"$x=1$ 에서 분모가 $0$ 이라 $f(1)$ 은 바로 대입할 수 없고, 연속이므로 극한값과 같다고 둔다.","확인":null,"스킬":"D11"},{"제목":"분자의 유리화","힌트":"분자의 $\\sqrt{x+3}-2$ 를 유리화해 약분하면 어떤 식이 되는가?","식":["$\\frac{\\left(\\sqrt{x+3}-2\\right)\\left(\\sqrt{x+3}+2\\right)}{(x-1)\\left(\\sqrt{x+3}+2\\right)}=\\frac{x-1}{(x-1)\\left(\\sqrt{x+3}+2\\right)}$","$=\\frac1{\\sqrt{x+3}+2}$ ($x\\ne1$)"],"설명":"$(x+3)-4=x-1$ 이라 분모의 $x-1$ 과 약분된다.","확인":null,"스킬":"D11","고비":true},{"제목":"극한값","힌트":"$x\\to1$ 일 때 $\\frac1{\\sqrt{x+3}+2}$ 의 값은?","식":["$\\lim_{x\\to1}\\frac1{\\sqrt{x+3}+2}=\\frac1{2+2}=\\frac14$"],"설명":"$f(1)$ 은 이 극한값과 같다.","확인":"1/4","스킬":"D11"}]},"ns-19dddfc661f7":{"길":"$x=1$ 에서 $\\frac gf$ 와 $g(f(x))$ 는 좌·우극한과 함숫값을 비교하고 곱이 불연속이면 미분 불가임을 쓴다","단계":[{"제목":"ㄱ. $x=1$ 에서의 몫","힌트":"$x=1$ 에서 $\\frac{g(x)}{f(x)}$ 의 좌극한, 우극한, 함숫값을 구하면?","식":["$\\lim_{x\\to1+}\\frac{g(x)}{f(x)}=\\frac{-1}{-1}=1$, $\\lim_{x\\to1-}\\frac{g(x)}{f(x)}=\\frac11=1$","$\\frac{g(1)}{f(1)}=\\frac{-1}{-1}=1$"],"설명":"그래프에서 $f(1+)=-1$, $f(1-)=1$, $f(1)=-1$ 이고 $g(1+)=-1$, $g(1-)=1$, $g(1)=-1$ 이다. 세 값이 같으므로 연속이다.","확인":"1","스킬":"D12"},{"제목":"ㄴ. $x=1$ 에서의 $g(f(x))$","힌트":"$x\\to1+$, $x\\to1-$ 일 때 $f(x)$ 의 값을 따라 $g(f(x))$ 의 극한은?","식":["$x\\to1+$ 이면 $f(x)=-1$ 이므로 $g(f(x))=g(-1)=1$","$x\\to1-$ 이면 $f(x)\\to1-$ 이므로 $g(f(x))\\to\\lim_{t\\to1-}g(t)=1$","$g(f(1))=g(-1)=1$"],"설명":"$x\\ge1$ 에서 $f(x)=-1$ 이고 $-1<x<1$ 에서 $f(x)=x$ 이다. 그래프에서 $g(-1)=1$ 이고 $-1\\le t<1$ 일 때 $g(t)=1$ 이다. 세 값이 같아 연속이다.","확인":null,"스킬":"T6","고비":true},{"제목":"ㄷ. $x=-1$ 에서의 미분가능성","힌트":"$x=-1$ 에서 $f(x)g(x)$ 의 좌극한과 우극한은?","식":["$\\lim_{x\\to-1-}f(x)g(x)=1\\times0=0$, $\\lim_{x\\to-1+}f(x)g(x)=(-1)\\times1=-1$","$f(-1)g(-1)=1\\times1=1$"],"설명":"좌극한과 우극한이 달라 불연속이다. 미분가능하면 연속이므로 불연속인 점에서는 미분가능하지 않다.","확인":"0","스킬":"D12"},{"제목":"보기의 판정","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 어느 것인가?","식":["ㄱ, ㄴ 은 옳고 ㄷ 은 옳지 않다"],"설명":"정답은 ③ 이다.","확인":null,"스킬":"D12"}]},"ns-1aec6fc3b4d7":{"길":"$g(x)=f(x)-x$ 로 놓고 사잇값 정리로 $g(-1)g(2)<0$ 인 정수 $k$ 를 센다","단계":[{"제목":"$g(x)=f(x)-x$ 의 양 끝값","힌트":"$g(x)=f(x)-x$ 로 놓을 때 $g(-1)$ 과 $g(2)$ 를 $k$ 로 나타내면?","식":["$g(-1)=f(-1)+1=(k-3)+1=k-2$","$g(2)=f(2)-2=(k+4)-2=k+2$"],"설명":"$f(x)=x$ 의 실근은 $g(x)=0$ 의 실근이다. $g$ 는 연속함수이다.","확인":null,"스킬":"C8"},{"제목":"근이 구간 안에 있을 조건","힌트":"근이 중근이 아닌 하나뿐일 때 그 근이 $(-1,\\,2)$ 안에 있으려면 $g(-1)$, $g(2)$ 의 부호는?","식":["$g(-1)g(2)<0$","$(k-2)(k+2)<0$ 에서 $-2<k<2$"],"설명":"근이 중근이 아니면 그 근의 앞뒤에서 부호가 바뀐다. 근이 $(-1,\\,2)$ 안에 있으면 두 끝값의 부호가 다르고, 반대로 부호가 다르면 사잇값 정리로 안에 근이 있다.","확인":null,"스킬":"C8","고비":true},{"제목":"정수 $k$ 의 개수","힌트":"$-2<k<2$ 를 만족하는 정수 $k$ 는 모두 몇 개인가?","식":["$k=-1,\\ 0,\\ 1$ 이므로 $3$ 개"],"설명":"$k=\\pm2$ 는 부등식의 경계라 제외된다.","확인":"3","스킬":"C8"}]},"ns-20446912ce3f":{"길":"$f$ 가 $x=2$ 에서 불연속이므로 곱이 연속이려면 $g(2)=0$ 이어야 함을 좌·우극한으로 확인한다","단계":[{"제목":"조건이 필요한 점","힌트":"$f(x)g(x)$ 가 실수 전체에서 연속이려면 어느 점에서 조건이 필요한가?","식":["$f$ 는 $x=2$ 에서 불연속 ($\\lim_{x\\to2-}f(x)=0$, $f(2)=3$)","$g$ 는 다항함수라 연속"],"설명":"$x\\ne2$ 에서는 $f$, $g$ 가 모두 연속이라 곱도 연속이다. 따라서 $x=2$ 에서만 따지면 된다.","확인":null,"스킬":"D12"},{"제목":"$x=2$ 에서의 극한과 함숫값","힌트":"$x\\to2-$, $x\\to2+$ 일 때 $f(x)g(x)$ 의 극한을 $a$ 로 나타내면?","식":["$\\lim_{x\\to2-}(-x+2)(x^2-a)=0$","$\\lim_{x\\to2+}(2x-1)(x^2-a)=3(4-a)=f(2)g(2)$"],"설명":"$x\\ge2$ 이면 $f(x)=2x-1$ 이므로 우극한이 함숫값과 같다. 좌극한은 $(-x+2)\\to0$ 이라 $0$ 이다.","확인":null,"스킬":"D12","고비":true},{"제목":"$a$ 의 값","힌트":"좌극한 $0$ 과 우극한이 같아지려면 $a$ 는?","식":["$3(4-a)=0$ 에서 $a=4$"],"설명":"좌극한, 우극한, 함숫값이 모두 같아야 연속이다.","확인":"4","스킬":"D12"}]},"ns-221a19452cd8":{"길":"중심 거리와 반지름의 합·차로 접하는 조건을 세워 $r$ 구간별 $f(r)$ 를 구하고 보기를 판정한다","단계":[{"제목":"중심의 위치","힌트":"$x$ 축에 접하고 반지름이 $r$ 인 원의 중심은 어디에 있는가?","식":["중심은 $(t,\\ r)$ 또는 $(t,\\ -r)$","$(t,\\ -r)$ 이면 중심 거리 $\\sqrt{t^2+(3+r)^2}>r+1$ 이라 원 $C$ 와 만나지 않는다"],"설명":"원 $C$ 는 $x$ 축 위쪽에 있다. 한 점에서 만나려면 중심 거리가 $r+1$ (외접) 또는 $|r-1|$ (내접) 이어야 한다.","확인":null,"스킬":"S13"},{"제목":"외접하는 경우","힌트":"중심이 $(t,\\ r)$ 인 원이 $C$ 와 외접하면 $t^2$ 은 $r$ 로?","식":["$t^2+(3-r)^2=(r+1)^2$","$t^2=(r+1)^2-(r-3)^2=8(r-1)$"],"설명":"$0<r<1$ 이면 $t$ 가 없고, $r=1$ 이면 $t=0$ 인 원 $1$ 개, $r>1$ 이면 $t=\\pm\\sqrt{8(r-1)}$ 인 원 $2$ 개이다.","확인":null,"스킬":"S13"},{"제목":"내접하는 경우","힌트":"같은 중심의 원이 $C$ 와 내접하면 $t^2$ 은 $r$ 로?","식":["$t^2+(3-r)^2=(r-1)^2$","$t^2=(r-1)^2-(r-3)^2=4(r-2)$"],"설명":"$0<r<2$ 이면 $t$ 가 없고, $r=2$ 이면 $1$ 개, $r>2$ 이면 $2$ 개이다.","확인":null,"스킬":"S13"},{"제목":"$f(r)$ 의 값","힌트":"$r=2$ 에서 외접과 내접의 개수를 더하면 $f(2)$ 는?","식":["$f(r)=0\\ (0<r<1)$, $f(1)=1$, $f(r)=2\\ (1<r<2)$","$f(2)=2+1=3$, $f(r)=2+2=4\\ (r>2)$"],"설명":"$r=2$ 에서는 외접하는 원 $2$ 개와 내접하는 원 $1$ 개가 모두 있다.","확인":"3","스킬":"C2","고비":true},{"제목":"보기의 판정","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 어느 것인가?","식":["ㄱ. $f(1)=1$ 참","ㄴ. $\\lim_{r\\to2-}f(r)=2\\ne f(2)=3$ 이므로 거짓","ㄷ. $(1,\\,3)$ 에서 불연속인 점은 $r=2$ 하나뿐이라 참"],"설명":"$r=1$ 은 열린구간 $(1,\\,3)$ 에 들지 않는다. 정답은 ③ 이다.","확인":null,"스킬":"D12"}]},"ns-2cea2f4a0891":{"길":"$x=2$ 의 연속으로 $b$, $f(0)=f(5)$ 로 $a$ 를 구하고 주기 $5$ 로 $f(38)=f(3)$ 을 쓴다","단계":[{"제목":"$b$ 의 값","힌트":"$x=2$ 에서 연속이려면 $\\lim_{x\\to2+}f(x)$ 가 $f(2)$ 와 같다. $b$ 는?","식":["$f(2)=2+2=4$","$\\lim_{x\\to2+}\\left\\{a(x-2)^2+b\\right\\}=b$ 이므로 $b=4$"],"설명":"$x=2$ 는 $0\\le x\\le2$ 쪽 식에 속하므로 $f(2)=4$ 이다.","확인":"4","스킬":"D12"},{"제목":"$a$ 의 값","힌트":"$f(x)=f(x+5)$ 에 $x=0$ 을 넣으면 $a$ 는?","식":["$f(0)=f(5)$","$2=a\\cdot3^2+4$ 에서 $a=-\\frac29$"],"설명":"$f(0)=0+2=2$ 이고 $f(5)=a(5-2)^2+b=9a+4$ 이다.","확인":"-2/9","스킬":"T2","고비":true},{"제목":"주기로 줄이기","힌트":"주기가 $5$ 일 때 $f(38)$ 은 $0\\le x\\le5$ 의 어느 점의 함숫값과 같은가?","식":["$38=5\\times7+3$ 이므로 $f(38)=f(3)$"],"설명":"$f(x)=f(x+5)$ 를 되풀이하면 $f(x)=f(x+5k)$ 이다.","확인":"3","스킬":"T2"},{"제목":"$f(3)$ 의 값","힌트":"$f(3)$ 은 $a(x-2)^2+b$ 에 $x=3$ 을 넣으면?","식":["$f(3)=a+b=-\\frac29+4=\\frac{34}9$"],"설명":"$2<3\\le5$ 이므로 아래쪽 식을 쓴다.","확인":"34/9","스킬":"D12"}]},"ns-38d7080793f3":{"길":"연속이므로 $f(2)$ 를 $x\\to2$ 의 극한으로 쓰고 분자를 유리화해 구한다","단계":[{"제목":"$f(2)$ 를 극한으로","힌트":"$f$ 가 $x=2$ 에서 연속이면 $f(2)$ 는 어떤 극한과 같은가?","식":["$x\\ne2$ 에서 $f(x)=\\frac{\\sqrt{x-1}-1}{x-2}$","$f(2)=\\lim_{x\\to2}\\frac{\\sqrt{x-1}-1}{x-2}$"],"설명":"$x=2$ 에서 분모가 $0$ 이라 바로 대입할 수 없고, 연속이므로 극한값과 같다고 둔다.","확인":null,"스킬":"D11"},{"제목":"분자의 유리화","힌트":"분자의 $\\sqrt{x-1}-1$ 을 유리화해 약분하면 어떤 식이 되는가?","식":["$\\frac{\\left(\\sqrt{x-1}-1\\right)\\left(\\sqrt{x-1}+1\\right)}{(x-2)\\left(\\sqrt{x-1}+1\\right)}=\\frac{x-2}{(x-2)\\left(\\sqrt{x-1}+1\\right)}$","$=\\frac1{\\sqrt{x-1}+1}$ ($x\\ne2$)"],"설명":"$(x-1)-1=x-2$ 라 분모의 $x-2$ 와 약분된다.","확인":null,"스킬":"D11","고비":true},{"제목":"극한값","힌트":"$x\\to2$ 일 때 $\\frac1{\\sqrt{x-1}+1}$ 의 값은?","식":["$\\lim_{x\\to2}\\frac1{\\sqrt{x-1}+1}=\\frac1{1+1}=\\frac12$"],"설명":"$f(2)$ 는 이 극한값과 같다.","확인":"1/2","스킬":"D11"}]},"ns-3c29b12bbc18":{"길":"$x=1$ 에서 $f$, $g$ 의 좌·우극한과 함숫값을 읽어 보기마다 극한과 함숫값을 비교한다","단계":[{"제목":"그래프에서 읽는 값","힌트":"$x=1$ 에서 $f$, $g$ 의 좌극한·우극한·함숫값은?","식":["$\\lim_{x\\to1-}f(x)=-2$, $\\lim_{x\\to1+}f(x)=-2$, $f(1)=2$","$\\lim_{x\\to1-}g(x)=-1$, $\\lim_{x\\to1+}g(x)=1$, $g(1)=-1$"],"설명":"$f$ 는 극한이 $-2$ 이고 함숫값이 $2$ 인 불연속이다. $g$ 는 좌극한과 우극한이 달라 불연속이다.","확인":null,"스킬":"D12"},{"제목":"ㄱ. $h(x)=f(x)-2|g(x)|$","힌트":"$x\\to1$ 일 때 $h(x)$ 의 극한은?","식":["$\\lim_{x\\to1+}h(x)=-2-2|1|=-4$, $\\lim_{x\\to1-}h(x)=-2-2|-1|=-4$","$h(1)=2-2|-1|=0$"],"설명":"극한값 $-4$ 와 함숫값 $0$ 이 다르므로 불연속이다.","확인":"-4","스킬":"D12"},{"제목":"ㄴ. $k(x)=f(x)\\times|g(x)|$","힌트":"$x\\to1$ 일 때 $k(x)$ 의 극한은?","식":["$\\lim_{x\\to1+}k(x)=(-2)\\times|1|=-2$, $\\lim_{x\\to1-}k(x)=(-2)\\times|-1|=-2$","$k(1)=2\\times|-1|=2$"],"설명":"$|g(x)|$ 는 $x=1$ 의 양쪽에서 극한이 $1$ 로 같지만 $f$ 의 극한 $-2$ 가 $f(1)=2$ 와 달라 불연속이다.","확인":"-2","스킬":"D12"},{"제목":"ㄷ. $t(x)=\\frac{(x-1)g(x)}{f(x)}$","힌트":"$x\\to1$ 일 때 $t(x)$ 의 극한은?","식":["$\\lim_{x\\to1+}t(x)=\\frac{0\\times1}{-2}=0$, $\\lim_{x\\to1-}t(x)=\\frac{0\\times(-1)}{-2}=0$","$t(1)=\\frac{0\\times g(1)}{f(1)}=0$"],"설명":"$(x-1)$ 이 $0$ 에 가까워져 분자가 $0$ 이 되고 분모의 극한 $-2$ 는 $0$ 이 아니다. 세 값이 모두 $0$ 이라 연속이다.","확인":"0","스킬":"D12","고비":true},{"제목":"보기의 판정","힌트":"$x=1$ 에서 연속인 것은 ㄱ~ㄷ 중 어느 것인가?","식":["연속인 것은 ㄷ"],"설명":"ㄱ, ㄴ 은 불연속이므로 정답은 ② 이다.","확인":null,"스킬":"D12"}]},"ns-3e008d8df99c":{"길":"$x=-1$ 과 $x=1$ 을 각각 대입해 $a$, $b$ 를 구하고 $f(x)$ 를 간단히 해 $f(-1)$ 을 극한으로 구한다","단계":[{"제목":"$a$, $b$ 사이의 첫째 식","힌트":"$(x+1)f(x)=ax^2-bx$ 에 $x=-1$ 을 넣으면 $a$, $b$ 사이에 어떤 식이 생기는가?","식":["$0\\times f(-1)=a+b$","$a+b=0$"],"설명":"좌변의 $(x+1)$ 이 $0$ 이 되고 $f(-1)$ 은 연속이라 유한한 값이므로 좌변은 $0$ 이다.","확인":null,"스킬":"D11"},{"제목":"$a$, $b$ 사이의 둘째 식","힌트":"$x=1$ 을 넣고 $f(1)=3$ 을 쓰면 $a-b$ 는?","식":["$2f(1)=a-b$","$a-b=2\\times3=6$"],"설명":"$x=1$ 이면 $(x+1)=2$ 이고 $ax^2-bx=a-b$ 이다.","확인":"6","스킬":"A3"},{"제목":"$a$, $b$ 의 값","힌트":"$a+b=0$, $a-b=6$ 을 연립하면 $a$, $b$ 는?","식":["$a=3,\\ b=-3$"],"설명":"두 식을 더하면 $2a=6$ 이다.","확인":null,"스킬":"A3"},{"제목":"$f(-1)$ 의 값","힌트":"$x\\ne-1$ 에서 $f(x)$ 를 약분하면 $f(-1)$ 은?","식":["$f(x)=\\frac{3x^2+3x}{x+1}=\\frac{3x(x+1)}{x+1}=3x$ ($x\\ne-1$)","$f(-1)=\\lim_{x\\to-1}3x=-3$"],"설명":"$f$ 가 $x=-1$ 에서 연속이므로 $f(-1)$ 은 극한값과 같다.","확인":"-3","스킬":"D11","고비":true}]},"ns-3f112d45eb18":{"길":"$x^2+2x-4$ 가 $(0,\\,2)$ 에서 증가하며 정수값을 지나는 점마다 가우스 기호가 불연속임을 센다","단계":[{"제목":"$x^2+2x-4$ 의 값의 범위","힌트":"$0<x<2$ 에서 $g(x)=x^2+2x-4$ 가 취하는 값의 범위는?","식":["$g(x)=(x+1)^2-5$ 이므로 $x>-1$ 에서 증가","$g(0)=-4$, $g(2)=4$ 이므로 $-4<g(x)<4$"],"설명":"축이 $x=-1$ 이라 $0<x<2$ 에서 증가하므로 값의 범위는 양 끝값 사이이다.","확인":null,"스킬":"N7"},{"제목":"불연속이 되는 조건","힌트":"$\\left[g(x)\\right]$ 는 $g(x)$ 가 어떤 값을 지날 때 불연속이 되는가?","식":["$g(x)$ 가 정수 $n$ 이 되는 $x$ 에서 불연속","$-4<n<4$ 인 정수 $n$ 은 $-3,\\ -2,\\ \\cdots,\\ 3$"],"설명":"$g$ 가 증가하며 정수 $n$ 을 지나는 순간 $\\left[g(x)\\right]$ 의 값이 $n-1$ 에서 $n$ 으로 뛴다. 증가하므로 각 $n$ 에 해당하는 $x$ 는 구간에 하나씩이다.","확인":null,"스킬":"N7","고비":true},{"제목":"불연속인 $x$ 의 개수","힌트":"$n=-3$ 부터 $3$ 까지 정수는 모두 몇 개인가?","식":["$n=-3,\\ -2,\\ -1,\\ 0,\\ 1,\\ 2,\\ 3$ 이므로 $7$ 개"],"설명":"$n$ 마다 불연속인 $x$ 가 하나씩이므로 $x$ 도 $7$ 개이다.","확인":"7","스킬":"N7"}]},"ns-4059f2bd270b":{"길":"$f(x)=\\frac5{x-4}+1$ 이 구간에서 감소함을 읽고 양 끝값으로 최대·최소를 구해 곱한다","단계":[{"제목":"구간에서의 증감","힌트":"$y=\\frac5x$ 를 평행이동한 $f(x)$ 는 구간 $[-6,\\,3]$ 에서 증가하는가 감소하는가?","식":["$f(x)$ 는 $y=\\frac5x$ 를 $x$ 축 방향으로 $4$, $y$ 축 방향으로 $1$ 만큼 평행이동한 것","점근선 $x=4$ 의 왼쪽인 구간 $[-6,\\,3]$ 에서 감소"],"설명":"$x<4$ 에서 $x$ 가 커질수록 $\\frac5{x-4}$ 는 작아진다.","확인":null,"스킬":"T4","고비":true},{"제목":"최솟값","힌트":"감소하는 함수의 최솟값은 구간의 어느 끝점에서 생기고 그 값은?","식":["최솟값은 $f(3)=\\frac5{3-4}+1=-4$","최댓값은 $f(-6)=\\frac5{-10}+1=\\frac12$"],"설명":"감소하므로 왼쪽 끝 $x=-6$ 에서 최대, 오른쪽 끝 $x=3$ 에서 최소이다.","확인":"-4","스킬":"T4"},{"제목":"최댓값과 최솟값의 곱","힌트":"최댓값 $\\frac12$ 과 최솟값 $-4$ 의 곱은?","식":["$\\frac12\\times(-4)=-2$"],"설명":"곱의 부호는 음수이다.","확인":"-2","스킬":"T4"}]},"ns-42089465934b":{"길":"분모가 모든 실수에서 $0$ 이 아니도록 판별식 $D<0$ 으로 $a$ 의 범위를 구한다","단계":[{"제목":"분모의 조건","힌트":"$h(x)$ 가 모든 실수에서 연속이려면 분모 $g(x)$ 는 어떤 조건을 만족해야 하는가?","식":["모든 실수 $x$ 에서 $g(x)\\ne0$","방정식 $x^2-2ax+3a=0$ 이 실근을 갖지 않는다"],"설명":"$f$, $g$ 는 다항함수라 연속이므로 분모가 $0$ 이 되는 점만 없으면 된다.","확인":null,"스킬":"C1"},{"제목":"판별식","힌트":"$x^2-2ax+3a=0$ 이 실근을 갖지 않을 조건을 판별식 $D$ 로 쓰면?","식":["$\\frac D4=(-a)^2-3a=a^2-3a<0$"],"설명":"이차방정식이 실근을 갖지 않으려면 $D<0$ 이다.","확인":null,"스킬":"G2","고비":true},{"제목":"$a$ 의 범위","힌트":"$a^2-3a<0$ 을 풀면?","식":["$a(a-3)<0$ 에서 $0<a<3$"],"설명":"아래로 볼록한 이차식이 음수인 구간은 두 근 사이이다.","확인":null,"스킬":"G2"}]},"ns-4d198d078ad9":{"길":"꼭짓점이 구간 안에 있음을 확인하고 꼭짓점과 양 끝점의 함숫값을 비교한다","단계":[{"제목":"꼭짓점의 위치","힌트":"$x^2-4x+3$ 을 완전제곱 꼴로 고치면 꼭짓점의 $x$ 좌표는?","식":["$y=(x-2)^2-1$"],"설명":"꼭짓점 $(2,\\,-1)$ 의 $x$ 좌표가 구간 $[-1,\\,3]$ 안에 있다.","확인":"2","스킬":"G7","고비":true},{"제목":"최댓값 $M$","힌트":"꼭짓점과 양 끝점 $x=-1$, $x=3$ 의 함숫값 중 가장 큰 값 $M$ 은?","식":["$f(-1)=1+4+3=8$, $f(2)=-1$, $f(3)=9-12+3=0$","$M=8$"],"설명":"아래로 볼록하므로 최솟값은 꼭짓점에서, 최댓값은 꼭짓점에서 먼 끝점에서 생긴다.","확인":"8","스킬":"G7"},{"제목":"$M+m$ 의 값","힌트":"$M=8$ 일 때 최솟값 $m$ 을 더한 $M+m$ 은?","식":["$m=-1$ 이므로 $M+m=8+(-1)=7$"],"설명":"최솟값은 꼭짓점의 $y$ 좌표 $-1$ 이다.","확인":"7","스킬":"G7"}]},"ns-55b30977c820":{"길":"$x=1$ 에서 연속이려면 분자가 $0$ 이 되어야 함을 써서 $a$, $b$ 를 구한다","단계":[{"제목":"$a$ 의 값","힌트":"$x\\to1$ 일 때 분모가 $0$ 에 가까운데 극한값이 존재하려면 $a$ 는?","식":["$\\lim_{x\\to1}\\frac{x^2+3x+a}{x-1}=b$ 이므로 분자 $\\to0$","$1+3+a=0$ 에서 $a=-4$"],"설명":"연속이므로 $\\lim_{x\\to1}f(x)=f(1)=b$ 이다.","확인":"-4","스킬":"D11","고비":true},{"제목":"$b$ 의 값","힌트":"$a=-4$ 일 때 $\\lim_{x\\to1}\\frac{x^2+3x-4}{x-1}$ 은?","식":["$b=\\lim_{x\\to1}\\frac{(x-1)(x+4)}{x-1}=\\lim_{x\\to1}(x+4)=5$"],"설명":"분자가 $(x-1)(x+4)$ 로 인수분해되어 약분된다.","확인":"5","스킬":"D11"},{"제목":"$a+b$ 의 값","힌트":"$a=-4$, $b=5$ 일 때 $a+b$ 는?","식":["$a+b=-4+5=1$"],"설명":"두 값을 더한다.","확인":"1","스킬":"D11"}]},"ns-6aeb4a8a5ff0":{"길":"연속함수의 연산 성질로 ①~④ 를 걸러내고 근호 안의 부호가 문제되는 ⑤ 를 찾는다","단계":[{"제목":"연속함수의 연산","힌트":"$x=a$ 에서 연속인 함수의 거듭제곱·역수·합·차는 $x=a$ 에서 연속인가?","식":["① $\\{f(x)\\}^2=f(x)\\times f(x)$ 는 연속","② $f(a)\\ne0$ 이므로 $\\frac1{f(x)}$ 는 연속","③ $g(x)-2f(x)$, ④ $x^2+f(x)$ 는 연속함수의 차·합이라 연속"],"설명":"연속함수의 합·차·곱·몫(분모 $\\ne0$)은 연속이다.","확인":null,"스킬":"C3"},{"제목":"근호 안의 부호","힌트":"$f(a)g(a)<0$ 이면 $\\sqrt{f(x)g(x)}$ 는 $x=a$ 에서 어떻게 되는가?","식":["$f(a)g(a)<0$ 이면 $x=a$ 근처에서 $f(x)g(x)<0$ 이라 $\\sqrt{f(x)g(x)}$ 가 정의되지 않는다","예: $f(x)=1$, $g(x)=-1$"],"설명":"함수값이 정의되지 않으면 연속이 아니다. 따라서 반드시 연속이라 할 수 없는 것은 ⑤ 이다.","확인":null,"스킬":"C3","고비":true}]},"ns-6fe9ab0bf1c2":{"길":"선지마다 $x=2$ 에서 극한과 함숫값을 비교해 불연속인 하나를 찾는다","단계":[{"제목":"①, ②, ③ 의 연속","힌트":"①, ②, ③ 은 $x=2$ 에서 극한값과 함숫값이 같은가?","식":["① $\\lim_{x\\to2}\\frac1{x+2}=\\frac14=f(2)$","② $\\lim_{x\\to2}(x^2-3x)=-2=f(2)$","③ $\\lim_{x\\to2}\\sqrt{x-1}=1=f(2)$"],"설명":"$x=2$ 에서 정의된 유리함수·다항함수·무리함수는 그 점에서 연속이다.","확인":null,"스킬":"D12"},{"제목":"④ 의 좌극한과 우극한","힌트":"④ 에서 $x\\to2-$ 일 때 $\\frac{x-2}{|x-2|}$ 의 극한은?","식":["$\\lim_{x\\to2-}\\frac{x-2}{-(x-2)}=-1$","$\\lim_{x\\to2+}\\frac{x-2}{x-2}=1$, $f(2)=1$"],"설명":"좌극한 $-1$ 과 우극한 $1$ 이 달라 $x=2$ 에서 극한값이 없으므로 불연속이다.","확인":"-1","스킬":"D12","고비":true},{"제목":"⑤ 의 연속","힌트":"⑤ 에서 분자를 유리화해 $x\\to2$ 의 극한을 구하면?","식":["$\\lim_{x\\to2}\\frac{\\sqrt{x-1}-\\sqrt{3-x}}{x-2}=\\lim_{x\\to2}\\frac{(x-1)-(3-x)}{(x-2)\\left(\\sqrt{x-1}+\\sqrt{3-x}\\right)}=\\lim_{x\\to2}\\frac2{\\sqrt{x-1}+\\sqrt{3-x}}=1=f(2)$"],"설명":"극한값과 함숫값이 같아 연속이다. 따라서 $x=2$ 에서 불연속인 함수는 ④ 이다.","확인":null,"스킬":"D11"}]},"ns-723145325931":{"길":"근호 안이 $0$ 이상인 범위를 구하고 끝점에서의 연속을 한쪽 극한으로 따진다","단계":[{"제목":"정의역","힌트":"$\\sqrt{2-x}$ 가 정의되려면 $2-x$ 는 어떤 범위여야 하는가?","식":["$2-x\\ge0$ 에서 $x\\le2$"],"설명":"근호 안은 $0$ 이상이어야 한다.","확인":null,"스킬":"T3"},{"제목":"끝점 $x=2$ 에서의 극한","힌트":"정의역의 끝점 $x=2$ 에서는 $x\\to2-$ 일 때 $\\sqrt{2-x}$ 의 극한은?","식":["$\\lim_{x\\to2-}\\sqrt{2-x}=0=f(2)$"],"설명":"$x>2$ 에서는 정의되지 않으므로 $x=2$ 에서는 좌극한으로 연속을 확인한다.","확인":"0","스킬":"T3","고비":true},{"제목":"연속인 구간","힌트":"$x<2$ 에서 연속이고 $x=2$ 에서도 연속이면 연속인 구간은?","식":["연속인 구간은 $(-\\infty,\\,2]$"],"설명":"$x<2$ 에서 $\\sqrt{2-x}$ 는 연속함수이고 끝점 $x=2$ 에서도 연속이다.","확인":null,"스킬":"T3"}]},"ns-74ad8368550c":{"길":"보기마다 연속의 성질과 반례를 따져 참인 것을 고른다","단계":[{"제목":"ㄱ. 제곱의 연속","힌트":"$f$ 가 $x=a$ 에서 연속이면 $\\{f(x)\\}^2$ 은 $x=a$ 에서 연속인가?","식":["$\\{f(x)\\}^2=f(x)\\times f(x)$ 이고 $\\lim_{x\\to a}\\{f(x)\\}^2=\\{f(a)\\}^2$"],"설명":"연속함수의 곱은 연속이다. 따라서 ㄱ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"ㄴ. 절댓값의 반례","힌트":"$|f(x)|$ 는 연속인데 $f(x)$ 는 불연속인 예가 있는가?","식":["$f(x)=\\begin{cases}1&(x<0)\\\\-1&(x\\ge0)\\end{cases}$","$f$ 는 $x=0$ 에서 불연속이지만 $|f(x)|=1$ 은 연속"],"설명":"반례가 있으므로 ㄴ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄷ. 몫의 반례","힌트":"$f$, $g$ 가 모두 불연속인데 $\\frac{f(x)}{g(x)}$ 가 연속인 예가 있는가?","식":["$f(x)=g(x)$ 가 $x=a$ 에서 불연속이고 $g(x)\\ne0$ 이면 $\\frac{f(x)}{g(x)}=1$ 은 연속"],"설명":"반례가 있으므로 ㄷ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄹ. 대우로 판정","힌트":"ㄹ 의 대우는 무엇이며 참인가?","식":["대우: $g$ 가 $x=a$ 에서 연속이면 $f(x)g(x)$ 도 $x=a$ 에서 연속이다 ($f$ 는 연속)","연속함수의 곱은 연속이므로 대우가 참이고 ㄹ 도 참"],"설명":"명제와 그 대우는 참·거짓이 같다. 따라서 옳은 것은 ㄱ, ㄹ 이다.","확인":null,"스킬":"C3","고비":true}]},"ns-7606167e30bb":{"길":"$g(x)=f(x)-(3x+1)$ 의 부호 변화를 사잇값 정리로 읽고 삼차방정식의 실근 수로 나머지 구간을 배제한다","단계":[{"제목":"$g$ 의 네 함숫값","힌트":"$g(x)=f(x)-(3x+1)$ 로 놓고 $g(-1)$, $g(0)$, $g(2)$, $g(3)$ 의 부호를 구하면?","식":["$g(-1)=4-(-2)=6>0$, $g(0)=0-1=-1<0$","$g(2)=-4-7=-11<0$, $g(3)=12-10=2>0$"],"설명":"교점의 $x$ 좌표는 $g(x)=0$ 의 실근이다. 주어진 네 점의 $y$ 좌표를 그대로 쓴다.","확인":null,"스킬":"C8"},{"제목":"부호가 바뀌는 두 구간","힌트":"$g$ 는 연속이므로 부호가 바뀌는 인접한 두 점 사이에는 무엇이 있는가?","식":["$g(-1)g(0)<0$ 이므로 $(-1,\\,0)$ 에 근","$g(2)g(3)<0$ 이므로 $(2,\\,3)$ 에 근"],"설명":"사잇값 정리에 의해 부호가 바뀌는 구간 안에 $g(x)=0$ 의 근이 있다.","확인":null,"스킬":"C8"},{"제목":"$x\\to-\\infty$ 에서의 부호","힌트":"최고차항의 계수가 양수인 삼차함수 $g$ 는 $x\\to-\\infty$ 일 때 어떻게 되는가?","식":["$\\lim_{x\\to-\\infty}g(x)=-\\infty$ 이므로 어떤 $m<-1$ 에서 $g(m)<0$","$g(m)<0<g(-1)$ 이므로 $(-\\infty,\\,-1)$ 에 근"],"설명":"$g$ 도 삼차식이고 최고차항의 계수가 $f$ 와 같은 양수이다.","확인":null,"스킬":"C8","고비":true},{"제목":"나머지 구간의 배제","힌트":"삼차방정식의 실근은 최대 몇 개이고 이미 몇 개를 찾았는가?","식":["삼차방정식 $g(x)=0$ 의 실근은 최대 $3$ 개","세 구간에서 하나씩 찾았으므로 $(0,\\,2)$, $(3,\\,\\infty)$ 에는 근이 없다","교점이 존재하는 구간은 ㄱ, ㄴ, ㄹ"],"설명":"정답은 ③ 이다.","확인":null,"스킬":"C8"}]},"ns-76c1c2b8c10c":{"길":"$f(a)$, $f(b)$, $f(c)$ 의 부호를 구해 사잇값 정리로 두 근의 위치를 정한다","단계":[{"제목":"세 점에서의 부호","힌트":"$f(x)=(x-a)(x-b)+(x-b)(x-c)+(x-c)(x-a)$ 로 놓을 때 $f(a)$, $f(b)$, $f(c)$ 의 부호는?","식":["$f(a)=(a-b)(a-c)>0$","$f(b)=(b-c)(b-a)<0$, $f(c)=(c-a)(c-b)>0$"],"설명":"$a<b<c$ 이므로 $(a-b)$, $(a-c)$ 는 둘 다 음수라 곱이 양수이고, $(b-c)<0$, $(b-a)>0$ 이라 곱이 음수이며, $(c-a)$, $(c-b)$ 는 둘 다 양수라 곱이 양수이다.","확인":null,"스킬":"C8","고비":true},{"제목":"사잇값 정리","힌트":"$f(a)f(b)<0$, $f(b)f(c)<0$ 이면 $f(x)=0$ 은 어느 구간에 근을 가지는가?","식":["$f(a)f(b)<0$ 이므로 $(a,\\,b)$ 에 근","$f(b)f(c)<0$ 이므로 $(b,\\,c)$ 에 근"],"설명":"$f$ 는 이차함수라 연속이다.","확인":null,"스킬":"C8"},{"제목":"두 근의 위치","힌트":"이차방정식의 근이 두 개뿐일 때 $\\alpha$, $\\beta$ 는 각각 어느 구간에 있는가?","식":["두 구간에 근이 하나씩 있고 이차방정식의 근은 $2$ 개이므로","$a<\\alpha<b<\\beta<c$"],"설명":"$\\alpha<\\beta$ 이므로 작은 근이 $(a,\\,b)$ 에, 큰 근이 $(b,\\,c)$ 에 있다. 정답은 ① 이다.","확인":null,"스킬":"C8"}]},"ns-7bd9aaf3f751":{"길":"인접한 두 점의 함숫값 곱이 음수인 구간마다 사잇값 정리로 근을 하나씩 센다","단계":[{"제목":"인접한 함숫값의 곱","힌트":"인접한 두 점의 함숫값의 곱 $f(-2)f(-1)$, $f(-1)f(0)$, $f(0)f(1)$, $f(1)f(2)$ 의 부호는?","식":["$f(-2)f(-1)=1\\times(-1)=-1<0$, $f(-1)f(0)=(-1)\\times(-2)=2>0$","$f(0)f(1)=(-2)\\times2=-4<0$, $f(1)f(2)=2\\times(-3)=-6<0$"],"설명":"곱이 음수이면 두 함숫값의 부호가 다르다.","확인":null,"스킬":"C8","고비":true},{"제목":"근의 개수","힌트":"곱이 음수인 구간은 모두 몇 개인가?","식":["$(-2,\\,-1)$, $(0,\\,1)$, $(1,\\,2)$ 에서 각각 근이 하나 이상","따라서 적어도 $3$ 개"],"설명":"세 구간은 서로 겹치지 않으므로 근도 서로 다르다. 사잇값 정리를 쓴다.","확인":"3","스킬":"C8"}]},"ns-818a7c373362":{"길":"$g(x)=f(x)-2x$ 의 값의 부호가 바뀌는 구간마다 사잇값 정리로 근을 하나씩 센다","단계":[{"제목":"방정식의 변형","힌트":"$g(x)=f(x)-2x$ 로 놓으면 $f(x)=2x$ 는 $g(x)$ 에 대한 어떤 방정식과 같은가?","식":["$f(x)=2x$ 는 $g(x)=0$ 과 같은 방정식","$g(x)=f(x)-2x$ 는 연속"],"설명":"연속함수 $f$ 와 일차함수 $2x$ 의 차이므로 $g$ 도 연속이다.","확인":null,"스킬":"C8"},{"제목":"$g$ 의 함숫값","힌트":"$g(-2)$ 부터 $g(2)$ 까지의 값은?","식":["$g(-2)=-3+4=1$, $g(-1)=-4+2=-2$, $g(0)=3$","$g(1)=4-2=2$, $g(2)=3-4=-1$"],"설명":"$g(x)=f(x)-2x$ 에 $x$ 를 하나씩 넣는다.","확인":null,"스킬":"C8"},{"제목":"부호가 바뀌는 구간의 수","힌트":"$g$ 의 값의 부호가 바뀌는 인접 구간은 모두 몇 개인가?","식":["$g$ 의 부호는 $+,\\ -,\\ +,\\ +,\\ -$ 이므로 $(-2,\\,-1)$, $(-1,\\,0)$, $(1,\\,2)$ 에서 부호가 바뀐다","따라서 적어도 $3$ 개"],"설명":"세 구간 각각에 사잇값 정리로 근이 하나 이상 있다.","확인":"3","스킬":"C8","고비":true}]},"ns-87e9627eec1c":{"길":"양의 쪽 두 구간, $f(0)=0$, 대칭인 음의 쪽 두 구간의 근을 더한다","단계":[{"제목":"양의 쪽 근","힌트":"$f(1)f(2)<0$, $f(3)f(4)<0$ 이면 양수인 근은 모두 몇 개 이상 있는가?","식":["$f(1)f(2)<0$ 이므로 $(1,\\,2)$ 에 근","$f(3)f(4)<0$ 이므로 $(3,\\,4)$ 에 근"],"설명":"$f$ 가 연속이라 사잇값 정리를 쓴다. 두 구간은 겹치지 않는다.","확인":"2","스킬":"C8"},{"제목":"$x=0$ 에서의 값","힌트":"$f(-x)=-f(x)$ 에 $x=0$ 을 넣으면 $f(0)$ 은?","식":["$f(0)=-f(0)$ 에서 $f(0)=0$"],"설명":"$x=0$ 은 열린구간 $(-4,\\,4)$ 안에 있으므로 근이 하나 더 있다.","확인":"0","스킬":"T2"},{"제목":"음의 쪽 근","힌트":"$f(-x)=-f(x)$ 를 이용해 $f(-1)f(-2)$ 의 부호를 구하면?","식":["$f(-1)f(-2)=\\{-f(1)\\}\\{-f(2)\\}=f(1)f(2)<0$","$f(-3)f(-4)=f(3)f(4)<0$"],"설명":"그러므로 $(-2,\\,-1)$, $(-4,\\,-3)$ 에도 근이 하나씩 있다.","확인":null,"스킬":"T2","고비":true},{"제목":"근의 개수의 합","힌트":"양의 쪽, $x=0$, 음의 쪽의 근을 모두 더하면?","식":["$2+1+2=5$"],"설명":"다섯 근은 서로 다른 구간 또는 점에 있으므로 적어도 $5$ 개이다.","확인":"5","스킬":"C8"}]},"ns-8bf08e00de05":{"길":"$x=3$ 에서 연속이려면 분자도 $x-3$ 으로 약분되어야 함을 써서 $a$, $b$ 를 구한다","단계":[{"제목":"$a$ 의 값","힌트":"$x\\to3$ 일 때 분모가 $0$ 에 가까운데 극한값이 존재하려면 $a$ 는?","식":["$\\lim_{x\\to3}\\frac{x^2-5x+a}{x-3}=b$ 이므로 분자 $\\to0$","$9-15+a=0$ 에서 $a=6$"],"설명":"연속이므로 $\\lim_{x\\to3}f(x)=f(3)=b$ 이다.","확인":"6","스킬":"D11","고비":true},{"제목":"$b$ 의 값","힌트":"$a=6$ 일 때 $\\lim_{x\\to3}\\frac{x^2-5x+6}{x-3}$ 은?","식":["$b=\\lim_{x\\to3}\\frac{(x-3)(x-2)}{x-3}=\\lim_{x\\to3}(x-2)=1$"],"설명":"분자가 $(x-3)(x-2)$ 로 인수분해되어 약분된다.","확인":"1","스킬":"D11"},{"제목":"$a+b$ 의 값","힌트":"$a=6$, $b=1$ 일 때 $a+b$ 는?","식":["$a+b=6+1=7$"],"설명":"두 값을 더한다.","확인":"7","스킬":"D11"}]},"ns-8d6dfbda7322":{"길":"정수 $n$ 에서 좌극한과 우극한이 같다는 식을 세워 모든 정수 $n$ 에서 성립하도록 계수를 비교한다","단계":[{"제목":"정수 $n$ 에서의 좌·우극한","힌트":"정수 $n$ 에서 $x\\to n+$, $x\\to n-$ 일 때 $[x]$ 는 각각 얼마인가?","식":["$x\\to n+$ 이면 $[x]=n$ 이라 $\\lim f(x)=n^2-(an+b)n=f(n)$","$x\\to n-$ 이면 $[x]=n-1$ 이라 $\\lim f(x)=(n-1)^2-(an+b)(n-1)$"],"설명":"$ax+b$ 는 연속이라 $x\\to n$ 일 때 $an+b$ 에 가까워진다.","확인":null,"스킬":"N7"},{"제목":"연속 조건의 식","힌트":"좌극한과 우극한이 같다는 식을 정리하면 $n$ 에 대한 어떤 식이 되는가?","식":["$n^2-(an+b)n=(n-1)^2-(an+b)(n-1)$","$n^2-(n-1)^2=(an+b)\\{n-(n-1)\\}$ 에서 $2n-1=an+b$","$(a-2)n+(b+1)=0$"],"설명":"$n^2-(n-1)^2=2n-1$ 이다.","확인":null,"스킬":"D12","고비":true},{"제목":"계수 비교","힌트":"모든 정수 $n$ 에서 $(a-2)n+(b+1)=0$ 이 성립하려면 $a$, $b$ 는?","식":["$a-2=0$, $b+1=0$ 이므로 $a=2,\\ b=-1$"],"설명":"서로 다른 두 정수 $n$ 에서 성립하면 일차식이 항등적으로 $0$ 이어야 한다.","확인":null,"스킬":"A3"},{"제목":"$a+b$ 의 값","힌트":"$a=2$, $b=-1$ 일 때 $a+b$ 는?","식":["$a+b=2+(-1)=1$"],"설명":"두 값을 더한다.","확인":"1","스킬":"A3"}]},"ns-91b1bdeebbf8":{"길":"$g$ 가 $x=1$ 에서 발산하므로 $f(1)=0$ 이어야 하고 좌·우극한을 맞춰 $(x-1)^2$ 을 인수로 얻는다","단계":[{"제목":"$f(1)$ 의 값","힌트":"$x\\to1$ 에서 $g(x)$ 가 발산할 때 $f(x)g(x)$ 가 연속이려면 $f(1)$ 은?","식":["$\\lim_{x\\to1+}\\frac{x}{x-1}=\\infty$, $\\lim_{x\\to1-}\\frac1{1-x}=\\infty$ 로 $g$ 는 $x=1$ 에서 발산","$f(1)=0$ 이어야 하므로 $f(x)=(x-1)h(x)$"],"설명":"$f(1)\\ne0$ 이면 $f(x)g(x)$ 도 $x=1$ 근처에서 발산해 연속일 수 없다. $g$ 는 $x=1$ 이외의 점에서 연속이다 ($x=-1$ 에서도 좌·우극한과 함숫값이 모두 $\\frac12$).","확인":"0","스킬":"D11"},{"제목":"$x=1$ 에서의 좌·우극한","힌트":"$f(x)=(x-1)h(x)$ 일 때 $x\\to1+$, $x\\to1-$ 에서 $f(x)g(x)$ 의 극한을 $h(1)$ 로 나타내면?","식":["$\\lim_{x\\to1+}(x-1)h(x)\\times\\frac x{x-1}=\\lim_{x\\to1+}xh(x)=h(1)$","$\\lim_{x\\to1-}(x-1)h(x)\\times\\frac1{1-x}=\\lim_{x\\to1-}\\{-h(x)\\}=-h(1)$"],"설명":"$x>1$ 이면 $g(x)=\\frac{x}{x-1}$, $x<1$ 이면 $g(x)=\\frac1{1-x}$ 이다. $h$ 는 다항함수라 연속이다.","확인":null,"스킬":"D12"},{"제목":"$h(1)$ 의 값과 인수","힌트":"우극한 $h(1)$ 과 좌극한 $-h(1)$ 이 같아야 할 때 $h(x)$ 는 어떤 인수를 가지는가?","식":["$h(1)=-h(1)$ 에서 $h(1)=0$","$h(x)=(x-1)k(x)$ 이므로 $f(x)=(x-1)^2k(x)$"],"설명":"$h(1)=0$ 이면 $f(1)g(1)=0$ 이고 좌·우극한도 $0$ 이라 $x=1$ 에서 연속이다.","확인":null,"스킬":"A4","고비":true},{"제목":"$f_n(3)$ 의 값","힌트":"차수가 가장 낮고 최고차항의 계수가 $1$ 인 $f$ 를 구해 $x=3$ 을 넣으면?","식":["$f_n(x)=(x-1)^2$","$f_n(3)=(3-1)^2=4$"],"설명":"$f$ 가 $(x-1)^2$ 을 인수로 가지고 최고차항의 계수가 $1$ 인 가장 낮은 차수는 $k(x)=1$ 일 때이다.","확인":"4","스킬":"A11"}]},"ns-953480ebcbaa":{"길":"$\\lim\\{f(x)-x\\}=3$ 에서 $a$, $x=2$ 에서 분자의 근으로 $b$, 연속으로 $c$ 를 정한다","단계":[{"제목":"$a$ 의 값","힌트":"$f(x)-x$ 를 통분해 $x\\to\\infty$ 의 극한이 $3$ 이 되게 하면 $a$ 는?","식":["$f(x)-x=\\frac{x^2+ax-b}{x-2}-x=\\frac{(a+2)x-b}{x-2}$","$\\lim_{x\\to\\infty}\\frac{(a+2)x-b}{x-2}=a+2=3$ 에서 $a=1$"],"설명":"분자와 분모가 모두 일차식이므로 극한은 $x$ 의 계수의 비이다.","확인":"1","스킬":"A3"},{"제목":"$b$ 의 값","힌트":"$x\\to2$ 에서 극한값이 존재하려면 분자 $x^2+x-b$ 는 $x=2$ 에서 어떤 값이어야 하는가?","식":["$a=1$ 이므로 $f(x)=\\frac{x^2+x-b}{x-2}$ ($x\\ne2$)","$4+2-b=0$ 에서 $b=6$"],"설명":"연속이므로 $\\lim_{x\\to2}f(x)=f(2)$ 가 존재해야 하고, (분모)$\\to0$ 이면 (분자)$\\to0$ 이다.","확인":"6","스킬":"D11"},{"제목":"$c$ 의 값","힌트":"$x\\to2$ 의 극한을 구해 $f(2)=-2+c$ 와 같게 하면 $c$ 는?","식":["$\\lim_{x\\to2}\\frac{x^2+x-6}{x-2}=\\lim_{x\\to2}\\frac{(x-2)(x+3)}{x-2}=5$","$f(2)=-2+c=5$ 에서 $c=7$"],"설명":"$x=2$ 에서 연속이므로 극한값과 함숫값이 같다.","확인":"7","스킬":"D12","고비":true},{"제목":"$a+b+c$ 의 값","힌트":"$a=1$, $b=6$, $c=7$ 일 때 $a+b+c$ 는?","식":["$a+b+c=1+6+7=14$"],"설명":"세 값을 더한다.","확인":"14","스킬":"D11"}]},"ns-9931bae6f87b":{"길":"$h=f-g$ 의 부호가 바뀌는 인접한 구간마다 사잇값 정리로 근을 하나씩 센다","단계":[{"제목":"$h=f-g$ 의 부호","힌트":"$h(x)=f(x)-g(x)$ 로 놓을 때 $h(0)$ 부터 $h(4)$ 까지의 부호는?","식":["$h(0)<0$, $h(1)>0$, $h(2)<0$, $h(3)<0$, $h(4)>0$"],"설명":"$f(0)<g(0)$ 이면 $h(0)<0$ 이다. $h$ 는 연속함수의 차라 연속이다.","확인":null,"스킬":"C8","고비":true},{"제목":"근의 개수","힌트":"부호가 바뀌는 인접한 구간은 모두 몇 개인가?","식":["부호가 바뀌는 구간은 $(0,\\,1)$, $(1,\\,2)$, $(3,\\,4)$","각 구간에 사잇값 정리로 근이 하나 이상 있으므로 적어도 $3$ 개"],"설명":"$h(2)$ 와 $h(3)$ 은 같은 부호라 $(2,\\,3)$ 에서는 근이 있다고 할 수 없다.","확인":"3","스킬":"C8"}]},"ns-9d9194f9d156":{"길":"$\\frac{x+4}{x-1}=1+\\frac5{x-1}$ 로 고쳐 감소함을 알고 양 끝값으로 $a$, $b$ 를 구한다","단계":[{"제목":"분수함수의 변형","힌트":"$\\frac{x+4}{x-1}$ 를 $1+\\frac{k}{x-1}$ 꼴로 나타내면 $k$ 는?","식":["$\\frac{x+4}{x-1}=\\frac{(x-1)+5}{x-1}=1+\\frac5{x-1}$"],"설명":"$[2,\\,4]$ 에서 $x-1>0$ 이고 $x$ 가 커질수록 $\\frac5{x-1}$ 은 작아지므로 $f$ 는 감소한다.","확인":"5","스킬":"T4","고비":true},{"제목":"최댓값 $a$ 와 최솟값 $b$","힌트":"감소하는 함수의 최솟값 $b$ 는 어느 끝점의 함숫값인가?","식":["$a=f(2)=\\frac61=6$","$b=f(4)=\\frac83$"],"설명":"감소하므로 $x=2$ 에서 최대, $x=4$ 에서 최소이다.","확인":"8/3","스킬":"T4"},{"제목":"$a+3b$ 의 값","힌트":"$a=6$, $b=\\frac83$ 일 때 $a+3b$ 는?","식":["$a+3b=6+3\\times\\frac83=6+8=14$"],"설명":"$3\\times\\frac83=8$ 이다.","확인":"14","스킬":"T4"}]},"ns-9de667a4b7be":{"길":"$f$ 는 $x=1$ 에서만 불연속이라 $a=0$ 과 $a\\ne0$ 으로 나누어 불연속점에서 다른 인수가 $0$ 이 되게 한다","단계":[{"제목":"$f$ 의 불연속점","힌트":"$x\\to1-$ 일 때 $f(x)$ 의 극한과 $f(1)$ 은?","식":["$\\lim_{x\\to1-}f(x)=\\frac12\\times2\\times4=4$","$f(1)=-2\\times(-1)\\times(-2)=-4$"],"설명":"좌극한 $4$ 와 함숫값 $-4$ 가 달라 $x=1$ 에서만 불연속이다. 두 식은 각각 다항식이라 다른 점에서는 연속이다.","확인":"4","스킬":"D12"},{"제목":"$a=0$ 인 경우","힌트":"$a=0$ 이면 $f(x)f(x+a)$ 는 어떤 함수인가?","식":["$a=0$ 이면 $f(x)f(x+a)=\\{f(x)\\}^2$","$\\lim_{x\\to1-}\\{f(x)\\}^2=16=\\{f(1)\\}^2=\\lim_{x\\to1+}\\{f(x)\\}^2$"],"설명":"$4^2=(-4)^2$ 이라 제곱하면 끊김이 없어져 연속이다. $a=0$ 은 조건을 만족한다.","확인":null,"스킬":"C2"},{"제목":"$a\\ne0$ 일 때의 조건","힌트":"$a\\ne0$ 일 때 $f(x)f(x+a)$ 가 $x=1$ 과 $x=1-a$ 에서 연속이려면 어떤 값이 $0$ 이어야 하는가?","식":["$f(x)$ 는 $x=1$ 에서, $f(x+a)$ 는 $x=1-a$ 에서 불연속","$x=1$ 에서 연속이려면 $f(1+a)=0$","$x=1-a$ 에서 연속이려면 $f(1-a)=0$"],"설명":"한쪽 인수가 불연속인 점에서는 다른 쪽 인수의 값이 $0$ 이어야 곱이 끊기지 않는다. $a\\ne0$ 이라 두 점은 서로 다르다.","확인":null,"스킬":"C2","고비":true},{"제목":"$a$ 의 후보","힌트":"$f(x)=0$ 의 해를 구해 두 조건을 모두 만족하는 $a$ 는?","식":["$f(x)=0$ 의 해는 $x=-3,\\ -1,\\ 2,\\ 3$","$f(1+a)=0$ 에서 $a=-4,\\ -2,\\ 1,\\ 2$ 이고 $f(1-a)=0$ 에서 $a=4,\\ 2,\\ -1,\\ -2$","공통인 $a$ 는 $-2$, $2$"],"설명":"$x<1$ 에서 $\\frac12(x+1)(x+3)=0$ 의 해 $-3$, $-1$ 은 모두 $1$ 보다 작고, $x\\ge1$ 에서 $-2(x-2)(x-3)=0$ 의 해 $2$, $3$ 은 $1$ 이상이다.","확인":null,"스킬":"D12"},{"제목":"상수 $a$ 의 개수","힌트":"$a=0$ 인 경우와 $a\\ne0$ 인 경우를 합하면 조건을 만족하는 $a$ 는 모두 몇 개인가?","식":["$a=0,\\ -2,\\ 2$ 이므로 $3$ 개"],"설명":"$a=0$ 하나와 $a=-2$, $a=2$ 두 개를 합한다.","확인":"3","스킬":"C2"}]},"ns-a22bce9ccb6e":{"길":"$f(x)=x^3+3x-10$ 의 함숫값 부호가 바뀌는 구간에 사잇값 정리를 쓴다","단계":[{"제목":"구간 끝의 함숫값","힌트":"$f(x)=x^3+3x-10$ 에 $x=-2$ 부터 $3$ 까지 넣으면 부호는?","식":["$f(-2)=-24$, $f(-1)=-14$, $f(0)=-10$","$f(1)=1+3-10=-6$, $f(2)=8+6-10=4$, $f(3)=27+9-10=26$"],"설명":"$f$ 는 다항함수라 연속이다. 선지 구간마다 양 끝값의 부호를 본다.","확인":null,"스킬":"C8","고비":true},{"제목":"근이 있는 구간","힌트":"함숫값의 부호가 바뀌는 구간은?","식":["$f(1)f(2)=(-6)\\times4<0$ 이므로 $(1,\\,2)$ 에 근"],"설명":"다른 선지의 구간은 양 끝값의 부호가 같고 실근은 하나뿐이다. 따라서 근은 $(1,\\,2)$ 에 있고 정답은 ④ 이다.","확인":null,"스킬":"C8"}]},"ns-a387d63c8b21":{"길":"보기마다 $x=0$, $x=1$ 에서 값의 부호가 다른지 보고 사잇값 정리를 쓴다","단계":[{"제목":"ㄱ. 양 끝값의 부호","힌트":"$g(x)=f(x)+2x$ 의 $g(0)$, $g(1)$ 은?","식":["$g(0)=f(0)+0=2$","$g(1)=f(1)+2=2$"],"설명":"두 값이 모두 양수라 부호가 같다. 사잇값 정리를 쓸 수 없으므로 $(0,\\,1)$ 에 근이 반드시 있다고 할 수 없다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄴ. 양 끝값의 부호","힌트":"$g(x)=f(x)-x^2$ 의 $g(0)$, $g(1)$ 은?","식":["$g(0)=2-0=2$","$g(1)=0-1=-1$"],"설명":"부호가 달라 $g(0)g(1)<0$ 이므로 사잇값 정리로 $(0,\\,1)$ 에 근이 반드시 있다.","확인":"-1","스킬":"C8"},{"제목":"ㄷ. 양 끝값의 부호","힌트":"$g(x)=f(x)-\\frac1{x+1}$ 의 $g(0)$, $g(1)$ 은?","식":["$g(0)=2-1=1$","$g(1)=0-\\frac12=-\\frac12$"],"설명":"부호가 달라 $(0,\\,1)$ 에 근이 반드시 있다. 따라서 반드시 존재하는 것은 ㄴ, ㄷ 이고 정답은 ⑤ 이다.","확인":null,"스킬":"C8"}]},"ns-af43c40f5cc1":{"길":"$g(x)$ 를 구간별로 정리한 뒤 경계점에서 좌·우극한과 함숫값을 비교한다","단계":[{"제목":"$f(-x)$ 의 구간별 식","힌트":"$f(-x)$ 에서 $x=2$ 일 때와 $x=-2$ 일 때 각각 $f$ 의 어느 점의 값을 읽는가?","식":["$|x|>2$ 이면 $f(-x)=0$, $|x|<2$ 이면 $f(-x)=|2x|-2$","$x=2$ 이면 $f(-x)=f(-2)=-1$, $x=-2$ 이면 $f(-x)=f(2)=1$"],"설명":"$f(-x)$ 는 $f$ 의 $x$ 자리에 $-x$ 를 넣은 것이므로 $x=\\pm2$ 에서는 $f(2)$ 와 $f(-2)$ 의 값이 서로 바뀐다. $|x|<2$ 에서는 $|2(-x)|=|2x|$ 라 식이 그대로이다.","확인":null,"스킬":"D12"},{"제목":"$|f(x)|$ 의 구간별 식","힌트":"$x=0$ 에서 $|f(0)|$ 의 값은?","식":["$|x|=2$ 이면 $|f(x)|=1$, $|x|>2$ 이면 $|f(x)|=0$","$1\\le|x|<2$ 이면 $|f(x)|=|2x|-2$","$|x|<1$ 이면 $|f(x)|=-(|2x|-2)=2-2|x|$, 예를 들어 $|f(0)|=2$"],"설명":"$|2x|-2\\ge0$ 이려면 $|x|\\ge1$ 이다. $|x|<1$ 에서는 $f(x)$ 가 음수이므로 절댓값을 벗길 때 부호를 바꾼다.","확인":"2","스킬":"G5","고비":true},{"제목":"$g(x)$ 의 구간별 식","힌트":"$x=2$ 에서 $g(2)=f(-2)-|f(2)|$ 의 값은?","식":["$|x|>2$ 이면 $g(x)=0$, $1\\le|x|<2$ 이면 $g(x)=(|2x|-2)-(|2x|-2)=0$","$g(2)=-1-1=-2$, $g(-2)=1-1=0$","$|x|<1$ 이면 $g(x)=(|2x|-2)-(2-2|x|)=4|x|-4$"],"설명":"$x=\\pm2$ 는 위의 두 식이 아니라 $f(-x)$ 와 $|f(x)|$ 의 값을 따로 읽어 뺀다. $x=2$ 와 $x=-2$ 의 값이 서로 다르다.","확인":"-2","스킬":"D12"},{"제목":"경계점의 좌·우극한 비교","힌트":"경계점 $x=\\pm2$, $x=\\pm1$ 중 불연속인 $x$ 의 개수는?","식":["$x=2$: 좌극한 $0$, 우극한 $0$, 그러나 $g(2)=-2$ 이므로 불연속","$x=-2$: 좌극한 $0$, 우극한 $0$, $g(-2)=0$ 이므로 연속","$x=\\pm1$: $4|x|-4\\to0=g(\\pm1)$ 이므로 연속, $x=0$ 은 $4|x|-4$ 가 이어진다"],"설명":"$x=-2$ 는 경계이지만 함숫값 $0$ 이 극한과 같아 후보에서 버린다. $x=\\pm1$ 도 $|x|<1$ 의 식이 $0$ 으로 이어져 버린다. 불연속인 $x$ 의 값은 $2$ 하나이다.","확인":"1","스킬":"D12"}]},"ns-b0463cf6dccb":{"길":"두 함수의 증가·감소를 보고 끝점의 함숫값에서 최댓값 $a$, 최솟값 $b$ 를 구한다","단계":[{"제목":"$f$ 의 최댓값 $a$","힌트":"구간 $[-1,\\,3]$ 에서 $f$ 가 가장 큰 곳의 $x$ 와 그 값은?","식":["$x+3>0$ 이고 $x$ 가 커지면 분모가 커지므로 $f$ 는 감소","$a=f(-1)=\\dfrac{8}{-1+3}=4$"],"설명":"감소함수는 왼쪽 끝 $x=-1$ 에서 최대이다. 오른쪽 끝의 $f(3)=\\dfrac43$ 은 최솟값이다.","확인":"4","스킬":"T3","고비":true},{"제목":"$g$ 의 최솟값 $b$","힌트":"구간 $[-1,\\,3]$ 에서 $g$ 가 가장 작은 곳의 함숫값은?","식":["$\\sqrt{x+1}$ 은 $x$ 가 커질 때 커지므로 $g$ 는 증가","$b=g(-1)=\\sqrt{0}-4=-4$"],"설명":"증가함수는 왼쪽 끝 $x=-1$ 에서 최소이다. $g(3)=\\sqrt4-4=-2$ 는 최댓값이다.","확인":"-4","스킬":"T3"},{"제목":"$ab$ 의 값","힌트":"$a$ 와 $b$ 의 곱은?","식":["$ab=4\\times(-4)=-16$"],"설명":"$a$ 는 $f$ 의 최댓값, $b$ 는 $g$ 의 최솟값이다.","확인":"-16","스킬":"T3"}]},"ns-b6cd1c4ecf8e":{"길":"$x=0$ 의 연속으로 $b$ 를 구하고 주기 $2$ 로 $x=1$ 의 연속에서 $a$ 와 $f(3)$ 을 잇는다","단계":[{"제목":"$x=0$ 에서의 연속","힌트":"$x=0$ 에서 좌극한과 $f(0)$ 이 같으려면 $b$ 는?","식":["$\\displaystyle\\lim_{x\\to0-}f(x)=\\lim_{x\\to0-}(ax+2)=2$","$f(0)=0^2+b=b$ 이므로 $b=2$"],"설명":"$x=0$ 에서 연속이려면 좌극한과 함숫값이 같아야 한다. 우극한 $\\displaystyle\\lim_{x\\to0+}(x^2+b)=b$ 도 같은 값이다.","확인":"2","스킬":"D12"},{"제목":"주기로 옮긴 $x=1$ 의 연속","힌트":"$f(1)$ 은 주기 조건으로 $f$ 의 어느 점의 값과 같고, 그때 $a$ 는?","식":["$f(1)=f(-1)=-a+2$","$\\displaystyle\\lim_{x\\to1-}f(x)=\\lim_{x\\to1-}(x^2+2)=3$","연속이므로 $-a+2=3$, $a=-1$"],"설명":"식이 주어진 구간은 $[-1,\\,1)$ 뿐이므로 $x=1$ 의 함숫값은 $f(x+2)=f(x)$ 에서 $f(1)=f(-1)$ 로 옮겨 읽는다. $x=1$ 에서 연속이려면 이 값이 좌극한과 같아야 한다.","확인":"-1","스킬":"T2","고비":true},{"제목":"$f(3)$ 의 값","힌트":"$f(3)$ 을 $f(-1)$ 로 옮겨 구하면?","식":["$f(3)=f(1)=f(-1)=-a+2=1+2=3$"],"설명":"주기가 $2$ 이므로 $f(3)=f(1)$ 이고 다시 $f(1)=f(-1)$ 이다.","확인":"3","스킬":"T2"}]},"ns-bb2f92476b07":{"길":"$x=1$ 에서 $f$ 의 불연속을 $g(1)=0$ 으로 메우도록 $a$ 를 정한다","단계":[{"제목":"$x=1$ 에서 $f$ 의 극한과 함숫값","힌트":"$x\\ne1$ 에서 약분하면 $x\\to1$ 일 때 $f(x)$ 는 어떤 값에 가까워지는가?","식":["$x\\ne1$ 이면 $\\dfrac{x^2-1}{x-1}=x+1$","$\\displaystyle\\lim_{x\\to1}f(x)=2$, $f(1)=3$"],"설명":"극한값 $2$ 와 함숫값 $3$ 이 달라 $f$ 는 $x=1$ 에서 불연속이다. $x\\ne1$ 에서는 $x+1$ 이므로 연속이다.","확인":"2","스킬":"D12"},{"제목":"$fg$ 가 연속일 조건","힌트":"$x=1$ 에서 $\\displaystyle\\lim_{x\\to1}f(x)g(x)$ 와 $f(1)g(1)$ 이 같으려면 $g(1)$ 은?","식":["$g$ 는 연속이므로 $\\displaystyle\\lim_{x\\to1}f(x)g(x)=2\\,g(1)$","$f(1)g(1)=3\\,g(1)$","$2\\,g(1)=3\\,g(1)$ 에서 $g(1)=0$"],"설명":"$g$ 는 다항함수라 극한이 $g(1)$ 로 표현된다. 두 값이 같으려면 $g(1)=0$ 이어야 한다.","확인":"0","스킬":"D12","고비":true},{"제목":"$a$ 의 값","힌트":"$g(1)=0$ 이 되도록 $a$ 를 정하면?","식":["$g(1)=a-3=0$","$a=3$"],"설명":"$x\\ne1$ 에서는 $f$ 와 $g$ 가 모두 연속이므로 $x=1$ 의 조건만 만족하면 된다.","확인":"3","스킬":"D12"}]},"ns-bcc8f7f0956a":{"길":"$a=1$ 을 따로 보고 판별식 부호로 근의 개수를 나눈 뒤 $f(a)$ 가 끊기는 $a$ 를 찾는다","단계":[{"제목":"$a=1$ 인 경우","힌트":"$a=1$ 을 대입하면 방정식은 어떻게 되고 원소는 몇 개인가?","식":["$a=1$ 이면 $0\\cdot x^2+0\\cdot x-1=0$, 즉 $-1=0$","해가 없으므로 $f(1)=0$"],"설명":"$a-1=0$ 이면 이차항뿐 아니라 일차항도 사라져 상수 $-1$ 만 남는다. 거짓인 등식이므로 원소가 없다.","확인":"0","스킬":"C2"},{"제목":"$a\\ne1$ 일 때의 판별식","힌트":"이차방정식 $(a-1)x^2+2(a-1)x-a=0$ 의 $\\dfrac D4$ 를 $a$ 의 식으로 쓰면?","식":["$\\dfrac D4=(a-1)^2-(a-1)(-a)=(a-1)^2+a(a-1)$","$\\dfrac D4=(a-1)(2a-1)$"],"설명":"$x$ 의 계수가 $2(a-1)$ 로 짝수이므로 $\\dfrac D4=(\\text{계수의 절반})^2-(\\text{이차항 계수})\\times(\\text{상수항})$ 을 쓴다.","확인":null,"스킬":"G2"},{"제목":"$f(a)$ 의 구간별 값","힌트":"$a=\\dfrac12$ 일 때 방정식의 서로 다른 실근은 몇 개인가?","식":["$a<\\dfrac12$ 또는 $a>1$: $D>0$ 이므로 $f(a)=2$","$a=\\dfrac12$: $D=0$ 이므로 $f(a)=1$","$\\dfrac12<a<1$: $D<0$ 이므로 $f(a)=0$"],"설명":"$D$ 의 부호는 $(a-1)(2a-1)$ 의 부호와 같다. $a=1$ 은 이차방정식이 아니므로 이 경우에서 버리고 앞 단계의 $f(1)=0$ 을 쓴다.","확인":"1","스킬":"C2","고비":true},{"제목":"불연속인 $a$ 의 값의 합","힌트":"$f$ 가 불연속이 되는 $a$ 의 값을 모두 더하면?","식":["$a=\\dfrac12$: 좌극한 $2$, 우극한 $0$, $f\\!\\left(\\dfrac12\\right)=1$ 이므로 불연속","$a=1$: 좌극한 $0$, 우극한 $2$ 로 달라 극한이 없으므로 불연속","$\\dfrac12+1=\\dfrac32$"],"설명":"$a=1$ 은 좌극한이 $f(1)=0$ 과 같아도 우극한이 달라 불연속이다. 그 밖의 $a$ 에서는 $f(a)$ 가 상수인 구간 안이라 연속이다.","확인":"3/2","스킬":"D12"}]},"ns-bebb8f67e646":{"길":"정수에서만 좌·우극한이 달라질 수 있으므로 정수마다 극한을 구해 비교한다","단계":[{"제목":"불연속 후보인 정수","힌트":"열린구간 $(1,\\,7)$ 안에서 $[x]$ 의 값이 바뀌는 $x$ 는 몇 개인가?","식":["정수가 아닌 $x$ 에서는 $[x]$ 가 상수이고 $[x]\\ge1$ 이므로 $f$ 는 연속","따질 후보는 $x=2,\\,3,\\,4,\\,5,\\,6$"],"설명":"$x=1$ 과 $x=7$ 은 구간에 포함되지 않으므로 후보에서 뺀다.","확인":"5","스킬":"N7"},{"제목":"정수 $n$ 의 좌·우극한","힌트":"$n=3$ 일 때 $x\\to3-$ 의 극한은?","식":["$x\\to n+$ 이면 $[x]=n$ 이므로 $\\dfrac{n^2+n}{n}=n+1=f(n)$","$x\\to n-$ 이면 $[x]=n-1$ 이므로 $\\dfrac{(n-1)^2+n}{n-1}=n+\\dfrac1{n-1}$"],"설명":"우극한은 모든 $n$ 에서 $f(n)$ 과 같다. 그러므로 좌극한이 $n+1$ 과 같은지만 보면 된다. $n=3$ 이면 좌극한은 $3+\\dfrac12$ 이다.","확인":"7/2","스킬":"N7","고비":true},{"제목":"$n=2$ 와 나머지 정수의 판정","힌트":"$n=2$ 일 때 $x\\to2-$ 의 극한은?","식":["$n+\\dfrac1{n-1}=n+1$ 이려면 $n=2$, 좌극한 $3=f(2)$ 이므로 연속","$n=3,\\,4,\\,5,\\,6$ 의 좌극한은 $\\dfrac72,\\,\\dfrac{13}3,\\,\\dfrac{21}4,\\,\\dfrac{31}5$","$f(n)=4,\\,5,\\,6,\\,7$ 과 모두 달라 불연속"],"설명":"$n=2$ 는 좌극한과 우극한이 모두 $3$ 으로 같아 후보에서 버린다. 나머지는 좌극한이 분수이고 $f(n)$ 은 정수라 같을 수 없다.","확인":"3","스킬":"D12"},{"제목":"불연속인 $x$ 의 합","힌트":"불연속인 $x$ 의 값 $3,\\,4,\\,5,\\,6$ 을 모두 더하면?","식":["$3+4+5+6=18$"],"설명":"불연속점은 정수 $3$ 부터 $6$ 까지 네 개이다.","확인":"18","스킬":"N7"}]},"ns-c4b74ade0738":{"길":"보기마다 좌·우극한을 따져 연속과 극한의 존재를 판정한다","단계":[{"제목":"그래프에서 읽는 $x=0$, $x=1$","힌트":"그래프에서 $f(0)$ 과 $f(1)$ 은 각각 얼마인가?","식":["$f(0)=1$, $\\displaystyle\\lim_{x\\to0-}f(x)=0$, $\\displaystyle\\lim_{x\\to0+}f(x)=1$","$f(1)=1$, $\\displaystyle\\lim_{x\\to1-}f(x)=0$, $\\displaystyle\\lim_{x\\to1+}f(x)=1$"],"설명":"$x=0$ 은 왼쪽 직선이 열린 점 $(0,0)$ 으로 향하고 함숫값은 닫힌 점 $(0,1)$ 의 높이이다. $x=1$ 은 곡선이 열린 점 $(1,0)$ 으로 향하고 함숫값은 닫힌 점 $(1,1)$ 의 높이이다. 두 점에서 좌극한이 $f$ 의 값과 달라 불연속이다.","확인":"1","스킬":"D12"},{"제목":"ㄱ. $|f(x)|$ 의 $x=2$","힌트":"$x=2$ 근처에서 $f(x)$ 의 식을 쓰고 $|f(2)|$ 의 값은?","식":["$x$ 가 $2$ 근처이면 $f(x)=-x+2$ 이므로 $|f(x)|=|x-2|$","$\\displaystyle\\lim_{x\\to2}|f(x)|=0=|f(2)|$"],"설명":"$f$ 는 $x=2$ 에서 연속이고 절댓값 함수도 연속이므로 $|f(x)|$ 도 연속이다. ㄱ 은 옳다.","확인":"0","스킬":"D12"},{"제목":"ㄴ. $f(f(x))$ 의 불연속 후보","힌트":"$f(x)=1$ 을 만족시키는 $x$ 는 모두 몇 개인가?","식":["바깥 $f$ 가 불연속인 곳은 $0$, $1$ 이므로 $f(x)=0$ 또는 $f(x)=1$ 인 $x$ 가 후보","$f(x)=0$ 이면 $x=2$ ($x<0$ 에서는 $-x\\ne0$, $0\\le x<1$ 에서는 $-x^2+1\\ne0$ 이라 해가 없다)","$f(x)=1$ 이면 $x=-1,\\ 0,\\ 1$"],"설명":"안쪽 $f$ 가 불연속인 $x=0$, $x=1$ 은 $f(x)=1$ 의 해에 이미 들어 있다. 후보는 $x=-1,\\ 0,\\ 1,\\ 2$ 이다.","확인":"3","스킬":"T6","고비":true},{"제목":"후보점에서의 좌·우극한","힌트":"$x\\to2-$ 일 때 $f(f(x))$ 의 극한은?","식":["$x\\to2-$: $f(x)\\to0+$ 이므로 $f(f(x))\\to1$","$x\\to2+$: $f(x)\\to0-$ 이므로 $f(f(x))\\to0$","$x=-1,\\ 0,\\ 1$ 에서도 좌극한 $1$, 우극한 $0$"],"설명":"$f(x)\\to0+$ 이면 바깥 $f$ 는 $x=0$ 의 오른쪽 값 $1$ 로, $0-$ 이면 왼쪽 값 $0$ 으로 간다. 네 후보 모두 좌·우극한이 달라 불연속점은 $4$ 개이므로 ㄴ 은 옳다.","확인":"1","스킬":"T6"},{"제목":"ㄷ. $[f(x)]$ 의 $x=0$ 과 결론","힌트":"$x\\to0$ 일 때 $f(x)$ 가 $0$ 과 $1$ 사이의 값이면 $[f(x)]$ 는 얼마인가?","식":["$x\\to0-$: $f(x)=-x$ 는 $0$ 에 가까운 양수이므로 $[f(x)]=0$","$x\\to0+$: $f(x)=-x^2+1$ 은 $0$ 보다 크고 $1$ 보다 작으므로 $[f(x)]=0$","$\\displaystyle\\lim_{x\\to0}[f(x)]=0$"],"설명":"$[f(0)]=[1]=1$ 이라 함숫값은 극한과 다르지만 극한값 자체는 존재한다. ㄷ 은 옳다. ㄱ, ㄴ, ㄷ 이 모두 옳으므로 정답은 ⑤ 이다.","확인":null,"스킬":"N7"}]},"ns-c631842e6238":{"길":"$x=1,\\,2,\\,3$ 에서 좌극한·우극한·함숫값을 읽어 극한이 없는 곳과 불연속인 곳을 센다","단계":[{"제목":"극한이 없는 $x$ 의 개수 $m$","힌트":"그래프에서 좌극한과 우극한이 서로 다른 $x$ 는 몇 개인가?","식":["$x=1$: 좌극한 $3$, 우극한 $3$ 이므로 극한 존재","$x=2$: 좌극한 $2$, 우극한 $1$ 로 달라 극한이 없다","$x=3$: 좌극한 $0$, 우극한 $0$ 이므로 극한 존재, 따라서 $m=1$"],"설명":"$x=3$ 은 속이 빈 점이어도 양쪽에서 모이는 높이가 $0$ 으로 같으므로 극한은 존재한다. 극한이 없는 곳은 $x=2$ 하나뿐이다.","확인":"1","스킬":"D12"},{"제목":"불연속인 $x$ 의 개수 $n$","힌트":"극한은 있어도 함숫값이 없거나 극한과 다른 $x$ 까지 모두 세면 몇 개인가?","식":["$x=1$: $f(1)=3=\\displaystyle\\lim_{x\\to1}f(x)$ 이므로 연속","$x=2$: 극한이 없으므로 불연속","$x=3$: 극한 $0$ 이 있으나 $f(3)$ 의 값이 없어 불연속, 따라서 $n=2$"],"설명":"연속이려면 극한이 존재하고 그 값이 함숫값과 같아야 한다. $x=1$ 은 이 조건을 만족하므로 센 것에서 버린다. $x=3$ 은 함숫값이 정의되지 않아 조건을 만족하지 못한다.","확인":"2","스킬":"D12","고비":true},{"제목":"$m-n$ 의 값","힌트":"$m$ 과 $n$ 의 차는?","식":["$m-n=1-2=-1$"],"설명":"$m$ 은 극한이 없는 $x$ 의 개수, $n$ 은 불연속인 $x$ 의 개수이다.","확인":"-1","스킬":"D12"}]},"ns-c7bcd8fd3461":{"길":"사잇값 정리는 양 끝값의 부호가 다를 때만 근을 보장함을 보기마다 확인한다","단계":[{"제목":"ㄱ. 구간 $[-2,\\,0]$","힌트":"$f(-2)f(0)$ 의 값은?","식":["$f(-2)=5$, $f(0)=-3$ 이므로 $f(-2)f(0)=-15<0$","연속이고 양 끝값의 부호가 다르므로 사잇값 정리로 $[-2,\\,0]$ 에 실근이 있다"],"설명":"$f$ 가 연속이므로 $y$ 좌표가 양수에서 음수로 바뀌는 동안 $0$ 을 지난다. ㄱ 은 항상 옳다.","확인":"-15","스킬":"C8"},{"제목":"ㄴ. 구간 $(0,\\,1)$","힌트":"$f(0)f(1)$ 의 값은?","식":["$f(0)=-3$, $f(1)=-1$ 이므로 $f(0)f(1)=3>0$","양 끝값의 부호가 같아 근이 있다고 보장할 수 없다"],"설명":"두 끝값이 모두 음수이면 그래프가 $0$ 을 지나지 않고 이어질 수 있다. 근이 있는 경우도 가능하지만 항상 그렇다고는 할 수 없으므로 ㄴ 은 옳지 않다.","확인":"3","스킬":"C8"},{"제목":"ㄷ. 구간 $(-2,\\,2)$","힌트":"서로 겹치지 않는 두 구간에서 부호가 바뀌는 곳을 찾으면 어디인가?","식":["$f(-2)f(0)<0$ 이므로 $(-2,\\,0)$ 에 근","$f(1)=-1$, $f(2)=3$ 이므로 $f(1)f(2)<0$ 이고 $(1,\\,2)$ 에 근","두 구간이 겹치지 않으므로 서로 다른 근이 적어도 $2$ 개"],"설명":"$(-2,\\,0)$ 과 $(1,\\,2)$ 는 모두 $(-2,\\,2)$ 안에 있고 공통부분이 없다. 따라서 ㄷ 은 항상 옳다. 정답은 ⑤ 이다.","확인":null,"스킬":"C8","고비":true}]},"ns-c805c4b164e8":{"길":"요금을 올림 함수로 쓰고 요금이 뛰는 시간의 개수를 세어 $a$, $b$ 를 구한다","단계":[{"제목":"$7000$원으로 고정되는 시간","힌트":"요금이 $7000$원으로 고정되기 시작하는 시간은 몇 분을 넘을 때인가?","식":["$x>30$ 이면 $f(x)=2000+500\\times\\left\\langle\\dfrac{x-30}{10}\\right\\rangle$ ($\\langle t\\rangle$ 는 $t$ 보다 작지 않은 최소의 정수)","$2000+500k=7000$ 에서 $k=10$, 즉 $\\left\\langle\\dfrac{x-30}{10}\\right\\rangle\\ge10$ 이면 $x>120$"],"설명":"$10$분을 넘길 때마다 $500$원이 더해지므로 올림을 쓴다. $120<x\\le130$ 에서 올림값이 $10$ 이 되어 $7000$원이 되고, 하루 최대 요금 때문에 그 뒤로도 $7000$원이다.","확인":"120","스킬":"C7"},{"제목":"소형차의 요금 $a$","힌트":"오전 $10$시부터 $11$시 $11$분까지는 몇 분이고 요금은?","식":["$x=71$ 이므로 $\\dfrac{71-30}{10}=4.1$","$\\langle4.1\\rangle=5$ 이므로 $a=2000+500\\times5=4500$"],"설명":"$71$ 분은 $30$ 분을 넘고 $120$ 분 이하이므로 둘째 식을 쓴다. $4.1$ 은 정수가 아니므로 올림하여 $5$ 이다.","확인":"4500","스킬":"N7"},{"제목":"불연속점의 개수 $b$","힌트":"요금이 뛰는 $x$ 는 $30$ 에서 시작해 몇 개인가?","식":["$0<x\\le30$ 에서 $2000$, 바로 뒤에서 $2500$ 이므로 $x=30$ 에서 불연속","올림값이 바뀌는 $x=30,\\,40,\\,50,\\,\\cdots,\\,120$ 에서 불연속","$30$ 부터 $120$ 까지 $10$ 씩 커지므로 $b=10$"],"설명":"$x=120$ 에서는 $6500$ 에서 $7000$ 으로 뛰므로 포함한다. $x=130$ 이후는 이미 $7000$ 으로 일정한 구간 안이라 버린다.","확인":"10","스킬":"N7","고비":true},{"제목":"$a+b$ 의 값","힌트":"$a$ 와 $b$ 의 합은?","식":["$a+b=4500+10=4510$"],"설명":"$a$ 는 요금, $b$ 는 불연속점의 개수이다.","확인":"4510","스킬":"C7"}]},"ns-cb11bfc4856a":{"길":"$g(x)=xf(x)$ 로 놓고 세 구간 끝값의 곱의 부호를 $f$ 의 부호 조건으로 옮긴다","단계":[{"제목":"$g$ 의 끝값 곱의 부호","힌트":"삼차식 $g(x)=xf(x)$ 의 세 실근이 세 구간에 하나씩이면 구간 끝값의 곱의 부호는?","식":["$g(x)=xf(x)$ 는 삼차식이므로 서로 다른 세 실근이 세 구간에 하나씩이면 모두 단근이다","$g(-2)g(1)<0,\\ g(1)g(2)<0,\\ g(2)g(4)<0$"],"설명":"단근에서는 부호가 바뀌므로 구간의 양 끝값의 곱이 음수이다. 삼차방정식의 실근은 많아야 $3$ 개이므로 세 구간에 하나씩 있으면 다른 근은 없다.","확인":null,"스킬":"C8"},{"제목":"$f$ 의 부호 조건으로 바꾸기","힌트":"$g(2)g(4)$ 를 $f(2)f(4)$ 로 쓰면 앞에 붙는 수는?","식":["$g(-2)g(1)=-2f(-2)f(1)<0$ 이므로 $f(-2)f(1)>0$","$g(1)g(2)=2f(1)f(2)<0$ 이므로 $f(1)f(2)<0$","$g(2)g(4)=8f(2)f(4)<0$ 이므로 $f(2)f(4)<0$"],"설명":"$g(a)=af(a)$ 이므로 곱의 앞에 붙는 수는 두 점의 $x$ 값의 곱이다. 이 수가 음수이면 부등호의 방향이 바뀐다.","확인":"8","스킬":"C8"},{"제목":"ㄱ, ㄴ 의 판정","힌트":"$f(1)f(2)$ 와 $f(2)f(4)$ 를 곱하면 $f(1)f(4)$ 와 어떤 관계인가?","식":["ㄱ: $f(-2)f(1)>0$ 이므로 $f(-2)f(1)<0$ 은 거짓","ㄴ: $f(1)f(2)\\times f(2)f(4)=f(1)f(4)\\{f(2)\\}^2>0$","$\\{f(2)\\}^2>0$ 이므로 $f(1)f(4)>0$, ㄴ 은 참"],"설명":"음수 둘의 곱은 양수이다. $f(2)=0$ 이면 $f(1)f(2)=0$ 이라 조건에 어긋나므로 $\\{f(2)\\}^2>0$ 이다.","확인":null,"스킬":"C8","고비":true},{"제목":"ㄷ 의 판정","힌트":"$f(-2)>0$ 인 경우와 $f(-2)<0$ 인 경우 $f(-2)f(2)f(4)$ 의 부호는 각각?","식":["$f(-2)>0$ 이면 $f(1)>0$, $f(2)<0$, $f(4)>0$ 이므로 $f(-2)f(2)f(4)<0$","$f(-2)<0$ 이면 $f(1)<0$, $f(2)>0$, $f(4)<0$ 이므로 $f(-2)f(2)f(4)>0$"],"설명":"두 경우가 모두 가능하므로 $f(-2)f(2)f(4)<0$ 이 항상 성립하지는 않는다. ㄷ 은 거짓이다. 옳은 것은 ㄴ 뿐이므로 정답은 ② 이다.","확인":null,"스킬":"C8"}]},"ns-dfa0be142475":{"길":"$x=1,\\,2$ 에서 좌극한·우극한·함숫값을 읽어 극한이 없는 곳과 불연속인 곳을 센다","단계":[{"제목":"극한이 없는 $x$ 의 개수 $a$","힌트":"그래프에서 좌극한과 우극한이 서로 다른 $x$ 는 몇 개인가?","식":["$x=1$: 좌극한 $1$, 우극한 $2$ 로 달라 극한이 없다","$x=2$: 좌극한 $2$, 우극한 $2$ 이므로 극한 존재, 따라서 $a=1$"],"설명":"$x=2$ 는 닫힌 점의 높이가 $3$ 으로 다르지만, 극한은 가까이 가는 높이이므로 양쪽에서 모이는 $2$ 로 정해진다. 극한이 없는 곳은 $x=1$ 하나뿐이다.","확인":"1","스킬":"D12"},{"제목":"불연속인 $x$ 의 개수 $b$","힌트":"극한이 있어도 함숫값과 다른 $x$ 까지 모두 세면 몇 개인가?","식":["$x=1$: 극한이 없으므로 불연속","$x=2$: $\\displaystyle\\lim_{x\\to2}f(x)=2$, $f(2)=3$ 으로 달라 불연속","$x=3$: $f(3)=3=\\displaystyle\\lim_{x\\to3}f(x)$ 이므로 연속, 따라서 $b=2$"],"설명":"연속이려면 극한이 존재하고 그 값이 함숫값과 같아야 한다. $x=3$ 은 이 조건을 만족하므로 센 것에서 버린다.","확인":"2","스킬":"D12","고비":true},{"제목":"$a-b$ 의 값","힌트":"$a$ 와 $b$ 의 차는?","식":["$a-b=1-2=-1$"],"설명":"$a$ 는 극한이 없는 $x$ 의 개수, $b$ 는 불연속인 $x$ 의 개수이다.","확인":"-1","스킬":"D12"}]},"ns-f65fdc854e23":{"길":"연속의 성질을 보기마다 증명하거나 반례를 찾아 판정한다","단계":[{"제목":"ㄱ. 불연속끼리의 곱","힌트":"$x<0$ 에서 $-1$, $x\\ge0$ 에서 $1$ 인 $f$ 와 그 부호를 뒤집은 $g$ 의 곱 $f(x)g(x)$ 의 값은?","식":["$f(x)=\\begin{cases}-1&(x<0)\\\\1&(x\\ge0)\\end{cases}$, $g(x)=\\begin{cases}1&(x<0)\\\\-1&(x\\ge0)\\end{cases}$","두 함수 모두 $x=0$ 에서 불연속이지만 $f(x)g(x)=-1$ 이므로 $x=0$ 에서 연속"],"설명":"반례가 하나라도 있으면 거짓이다. ㄱ 은 옳지 않다.","확인":"-1","스킬":"C3"},{"제목":"ㄴ. 역수의 연속","힌트":"$f(x)=x$ 이면 $\\dfrac{1}{|f(0)|}$ 은 정의되는가?","식":["$f(x)=x$ 는 $x=0$ 에서 연속","$\\dfrac1{|f(0)|}=\\dfrac10$ 이므로 $x=0$ 에서 정의되지 않아 불연속"],"설명":"$f(0)=0$ 이면 분모가 $0$ 이 된다. 반례가 있으므로 ㄴ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄷ. $x\\to0\\pm$ 의 극한 옮기기","힌트":"$x\\to0-$ 일 때 $t=-x$ 는 어느 쪽에서 $0$ 에 가까워지는가?","식":["$\\displaystyle\\lim_{x\\to0-}f(-x)g(-x)=\\lim_{t\\to0+}f(t)g(t)=f(0)g(0)$","$\\displaystyle\\lim_{x\\to0+}f(-x)g(-x)=\\lim_{t\\to0-}f(t)g(t)=f(0)g(0)$","좌극한 $=$ 우극한 $=f(0)g(0)=$ 함숫값 이므로 연속"],"설명":"$t=-x$ 로 바꾸면 좌·우가 서로 바뀐다. 주어진 조건은 $t\\to0$ 의 양쪽에서 $f(t)\\to f(0)$, $g(t)\\to g(0)$ 이므로 ㄷ 은 참이다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄹ. 몫이 연속일 때","힌트":"ㄱ 의 $f$, $g$ 를 그대로 쓰면 $\\dfrac{f(x)}{g(x)}$ 는 어떻게 되는가?","식":["$\\dfrac{f(x)}{g(x)}=-1$ 이므로 $x=0$ 에서 연속","그러나 $g$ 는 $x=0$ 에서 불연속"],"설명":"몫이 연속이어도 분모의 함수가 연속이라고는 할 수 없다. ㄹ 은 거짓이다. 옳은 것은 ㄷ 뿐이므로 정답은 ① 이다.","확인":null,"스킬":"C3"}]},"ns-ff466091f104":{"길":"$f$ 의 좌·우극한이 서로 다른 점에서 곱이 이어지려면 $g$ 의 값이 어때야 하는지 따진다","단계":[{"제목":"$f$ 의 불연속인 점","힌트":"닫힌구간 $[-1,\\,2]$ 에서 그래프가 끊어지는 $x$ 는?","식":["$x=0$: 왼쪽 직선이 $(0,1)$ 에 닿아 수평선과 이어지므로 연속","$x=1$: 좌극한 $1$, 우극한 $-1$, $f(1)=0$ 이므로 불연속"],"설명":"그림에서 $x=1$ 의 왼쪽은 높이 $1$ 인 열린 점, 오른쪽은 높이 $-1$ 인 열린 점이고 함숫값은 닫힌 점의 높이 $0$ 이다. 나머지는 이어진 직선이다.","확인":"1","스킬":"D12"},{"제목":"$fg$ 가 $x=1$ 에서 연속일 조건","힌트":"$g$ 가 연속일 때 $\\displaystyle\\lim_{x\\to1\\pm}f(x)g(x)$ 와 $f(1)g(1)$ 이 같아지려면 $g(1)$ 은?","식":["$\\displaystyle\\lim_{x\\to1-}f(x)g(x)=1\\times g(1)$, $\\displaystyle\\lim_{x\\to1+}f(x)g(x)=-1\\times g(1)$","$f(1)g(1)=0\\times g(1)=0$","세 값이 모두 같으려면 $g(1)=0$"],"설명":"좌극한 $g(1)$ 과 우극한 $-g(1)$ 이 같아야 하므로 $g(1)=0$ 이다. 이때 함숫값 $0$ 과도 같다.","확인":"0","스킬":"D12","고비":true},{"제목":"보기의 $g(1)$ 계산","힌트":"ㄱ, ㄴ, ㄷ 중 $g(1)=0$ 인 것은 어느 것인가?","식":["ㄱ: $g(1)=1+1=2\\ne0$ 이므로 불연속","ㄴ: $g(1)=-|1|+1=0$ 이므로 연속","ㄷ: $g(1)=1+1-2=0$ 이므로 연속"],"설명":"세 함수는 모두 모든 실수에서 연속이므로 $x=1$ 의 조건만 확인하면 된다. ㄱ 은 $g(1)\\ne0$ 이라 버린다. 알맞은 것은 ㄴ, ㄷ 이므로 정답은 ⑤ 이다.","확인":null,"스킬":"D12"}]},"ns-039b08328694":{"길":"도함수 $f'(x)=2ax+b$ 로 $b$, $a$ 를 먼저 정하고 $f(1)$ 의 값으로 $c$ 를 구한 뒤 $f(2)$ 를 계산한다","단계":[{"제목":"도함수로 구하는 $b$, $a$","힌트":"$f'(0)$ 과 $f'(1)$ 을 $a$, $b$ 로 나타내면?","식":["$f'(x)=2ax+b$","$f'(0)=b=-3$, $f'(1)=2a+b=1$ 이므로 $2a-3=1$, $a=2$"],"설명":"이차함수 $ax^2+bx+c$ 를 미분하면 $2ax+b$ 이다. $x=0$ 을 넣으면 $b$ 만 남는다.","확인":"2","스킬":"A3","고비":true},{"제목":"$c$ 의 값","힌트":"$f(1)=a+b+c=3$ 에 $a$, $b$ 를 넣으면 $c$ 는?","식":["$a+b+c=2-3+c=3$","$c=4$"],"설명":"$f(1)$ 의 값은 $x=1$ 을 대입한 $a+b+c$ 이다.","확인":"4","스킬":"A3"},{"제목":"$f(2)$ 의 값","힌트":"$f(x)=2x^2-3x+4$ 에 $x=2$ 를 넣으면?","식":["$f(2)=4a+2b+c=8-6+4=6$"],"설명":"$a=2$, $b=-3$, $c=4$ 를 대입한다.","확인":"6","스킬":"A3"}]},"ns-05db51b2bd61":{"길":"분자를 $f(x)-f(2)$ 와 $x^2-4$ 를 쓴 꼴로 쪼개 미분계수 꼴을 만든다","단계":[{"제목":"분자를 쪼개기","힌트":"$4f(x)-x^2f(2)$ 에서 $4f(2)$ 를 더하고 빼 $f(x)-f(2)$ 가 보이게 묶으면?","식":["$4f(x)-x^2f(2)=4\\{f(x)-f(2)\\}-f(2)(x^2-4)$"],"설명":"$4f(x)-4f(2)$ 를 만들면 남는 부분은 $4f(2)-x^2f(2)=-f(2)(x^2-4)$ 이다. $x^2-4$ 에는 $x-2$ 가 인수로 들어 있다.","확인":null,"스킬":"D3","고비":true},{"제목":"두 극한의 값","힌트":"$\\displaystyle\\lim_{x\\to2}\\frac{f(x)-f(2)}{x-2}$ 를 이용하면 앞의 극한은 얼마인가?","식":["$\\displaystyle\\lim_{x\\to2}\\frac{4\\{f(x)-f(2)\\}}{x-2}=4f'(2)=12$","$\\displaystyle\\lim_{x\\to2}\\frac{f(2)(x^2-4)}{x-2}=\\lim_{x\\to2}f(2)(x+2)=4f(2)$"],"설명":"앞의 극한은 미분계수의 정의 그대로이다. 뒤의 극한은 $x^2-4=(x+2)(x-2)$ 로 약분한다.","확인":"12","스킬":"D3"},{"제목":"$f(2)$ 의 값","힌트":"$12-4f(2)=-4$ 를 풀면?","식":["$12-4f(2)=-4$","$f(2)=4$"],"설명":"주어진 극한값이 $-4$ 이므로 두 극한의 차를 $-4$ 로 놓는다.","확인":"4","스킬":"D3"}]},"ns-0798d51ac850":{"길":"$f(0)=0$ 과 미분계수의 정의로 $f'(x)$ 가 상수임을 보이고 $f(x)$ 를 구한다","단계":[{"제목":"$f(0)$ 의 값","힌트":"$f(x+y)=f(x)+f(y)$ 에 $x=y=0$ 을 넣으면 $f(0)$ 은?","식":["$f(0)=f(0)+f(0)$","$f(0)=0$"],"설명":"양변에서 $f(0)$ 을 빼면 $f(0)=0$ 이다.","확인":"0","스킬":"A3"},{"제목":"$f'(x)$ 구하기","힌트":"$f(x+h)-f(x)$ 에 주어진 조건을 쓰면 무엇과 같아지는가?","식":["$f(x+h)-f(x)=f(h)$","$\\displaystyle f'(x)=\\lim_{h\\to0}\\frac{f(x+h)-f(x)}{h}=\\lim_{h\\to0}\\frac{f(h)}{h}$","$f'(0)=\\displaystyle\\lim_{h\\to0}\\frac{f(h)-f(0)}{h}=\\lim_{h\\to0}\\frac{f(h)}{h}$ 이므로 모든 $x$ 에서 $f'(x)=f'(0)$"],"설명":"$x$ 가 어떤 값이어도 $\\dfrac{f(h)}{h}$ 의 극한이 같으므로 $f'(x)$ 는 $x$ 에 따라 변하지 않는다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f(2)$ 의 값","힌트":"$f'(x)$ 가 상수일 때 $f(x)$ 는 어떤 꼴이고 $f(0)=0$ 이면 $f(2)$ 는?","식":["$f'(x)=5$ 이므로 $f(x)=5x+C$","$f(0)=0$ 이므로 $C=0$, $f(x)=5x$","$f(2)=10$"],"설명":"도함수가 상수이면 함수는 일차식이다. 상수항은 $f(0)=0$ 으로 정해진다.","확인":"10","스킬":"A3"}]},"ns-0a80620e58fe":{"길":"나머지를 $ax^2+bx+c$ 로 놓고 $x=\\pm1$ 대입과 $x=1$ 에서의 미분으로 세 식을 얻는다","단계":[{"제목":"나눗셈 식 세우기","힌트":"삼차식으로 나눈 나머지는 몇 차 이하이고 나눗셈 식은 어떻게 쓰는가?","식":["$P(x)=x^{100}-2x^{49}+2$ 라 하고 $R(x)=ax^2+bx+c$ 로 놓는다","$P(x)=(x+1)(x-1)^2Q(x)+ax^2+bx+c$"],"설명":"나누는 식이 삼차이므로 나머지는 이차 이하이다. 이 식은 $x$ 에 대한 항등식이다.","확인":null,"스킬":"A4"},{"제목":"$x=1$, $x=-1$ 대입","힌트":"$P(1)$ 과 $P(-1)$ 에서 $a+b+c$ 와 $a-b+c$ 를 얻으면 $b$ 는?","식":["$P(1)=1-2+2=1$ 이므로 $a+b+c=1$","$P(-1)=1+2+2=5$ 이므로 $a-b+c=5$","두 식을 빼면 $2b=-4$, $b=-2$ 이고 $a+c=3$"],"설명":"$x=1$ 과 $x=-1$ 에서는 나누는 식이 $0$ 이 되어 $Q(x)$ 를 몰라도 $R$ 의 값을 알 수 있다. $x^{49}$ 는 $x=-1$ 에서 $-1$ 이다.","확인":"-2","스킬":"A4"},{"제목":"양변을 미분해 $x=1$ 대입","힌트":"$P'(1)=R'(1)=2a+b$ 에서 $a$ 는?","식":["$P'(x)=100x^{99}-98x^{48}$ 이므로 $P'(1)=2$","$(x+1)(x-1)^2Q(x)$ 를 미분하면 모든 항에 $(x-1)$ 이 남아 $x=1$ 에서 $0$","$2a+b=2$ 에 $b=-2$ 를 넣으면 $a=2$, $c=1$"],"설명":"$x=1$ 이 중근이라 한 번 미분해도 $x=1$ 에서 $0$ 이 된다. 이것이 세 번째 식이다.","확인":"2","스킬":"A3","고비":true},{"제목":"$R(2)$ 의 값","힌트":"$R(x)=2x^2-2x+1$ 에 $x=2$ 를 넣으면?","식":["$R(2)=8-4+1=5$"],"설명":"$a=2$, $b=-2$, $c=1$ 이다.","확인":"5","스킬":"A4"}]},"ns-0b88611e34ef":{"길":"분자가 $x=1$ 에서 $0$ 임을 확인해 주어진 극한을 $f'(1)$ 로 읽고 $n$ 을 구한다","단계":[{"제목":"극한을 미분계수로 읽기","힌트":"$f(x)=x^{2n}+3x^n-4$ 로 놓을 때 $f(1)$ 은?","식":["$f(1)=1+3-4=0$","$\\displaystyle\\lim_{x\\to1}\\frac{x^{2n}+3x^n-4}{x-1}=\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}=f'(1)$"],"설명":"$f(1)=0$ 이므로 분자 $f(x)$ 는 $f(x)-f(1)$ 과 같다. 극한이 $f'(1)$ 의 정의 그대로이다.","확인":"0","스킬":"D3","고비":true},{"제목":"$f'(1)$ 을 $n$ 으로 나타내기","힌트":"$x^n$ 의 도함수는 무엇이고 $f'(1)$ 은 $n$ 의 식으로 어떻게 되는가?","식":["$f'(x)=2nx^{2n-1}+3nx^{n-1}$","$f'(1)=2n+3n=5n$"],"설명":"$x=1$ 에서는 $1$ 의 거듭제곱이 모두 $1$ 이라 지수에 상관없이 계수만 남는다.","확인":null,"스킬":"D3"},{"제목":"$n$ 의 값","힌트":"$f'(1)=15$ 에서 $n$ 은?","식":["$5n=15$","$n=3$"],"설명":"주어진 극한값이 $15$ 이므로 $f'(1)=15$ 이다.","확인":"3","스킬":"D3"}]},"ns-0cce32b2eddb":{"길":"$f(x+h)-f(x-2h)$ 를 $f(x)$ 를 사이에 두고 쪼개 미분계수 꼴을 두 번 만든다","단계":[{"제목":"분자를 두 차이로 쪼개기","힌트":"$f(x+h)-f(x-2h)$ 를 $f(x)$ 를 사이에 두고 두 개의 차로 쓰면?","식":["$f(x+h)-f(x-2h)=\\{f(x+h)-f(x)\\}+\\{f(x)-f(x-2h)\\}$","$g(x)=\\displaystyle\\lim_{h\\to0}\\frac{f(x+h)-f(x)}{h}+\\lim_{h\\to0}\\frac{f(x)-f(x-2h)}{h}$"],"설명":"$f(x)$ 를 더하고 빼도 값은 변하지 않는다. 첫째 극한은 그대로 $f'(x)$ 이다.","확인":null,"스킬":"D3"},{"제목":"둘째 극한과 $g(x)$","힌트":"$\\dfrac{f(x)-f(x-2h)}{h}$ 의 극한은 $f'(x)$ 의 몇 배인가?","식":["$\\displaystyle\\lim_{h\\to0}\\frac{f(x)-f(x-2h)}{h}=2\\lim_{h\\to0}\\frac{f(x)-f(x-2h)}{2h}=2f'(x)$","$g(x)=f'(x)+2f'(x)=3f'(x)$"],"설명":"분모를 $2h$ 로 맞추려면 $2$ 를 곱하고 나누어야 한다. $2h\\to0$ 이므로 $\\dfrac{f(x)-f(x-2h)}{2h}$ 는 $f'(x)$ 로 간다.","확인":"2","스킬":"D3","고비":true},{"제목":"$g(1)$ 의 값","힌트":"$f'(x)=2x-1$ 을 이용해 $g(1)$ 은?","식":["$f'(1)=2-1=1$","$g(1)=3f'(1)=3$"],"설명":"$g(x)=3f'(x)=6x-3$ 에 $x=1$ 을 넣어도 같은 값이다.","확인":"3","스킬":"D3"}]},"ns-0f30069f4297":{"길":"분모가 $0$ 으로 가므로 분자도 $0$ 이 되게 하고 $x-3$ 을 새 변수로 보아 $f'(1)$ 꼴을 만든다","단계":[{"제목":"분자의 극한으로 $f(1)$ 구하기","힌트":"$x\\to4$ 일 때 분모가 $0$ 으로 가고 극한이 존재하면 분자는 어떻게 되어야 하는가?","식":["$x^2-16\\to0$ 이고 극한이 존재하므로 $\\displaystyle\\lim_{x\\to4}\\{f(x-3)-5\\}=0$","$f(1)-5=0$ 이므로 $f(1)=5$"],"설명":"분모가 $0$ 으로 가는데 분자가 $0$ 이 아닌 값으로 가면 극한이 존재하지 않는다. 다항함수는 연속이므로 $\\displaystyle\\lim_{x\\to4}f(x-3)=f(1)$ 이다.","확인":null,"스킬":"D11"},{"제목":"미분계수 꼴 만들기","힌트":"$x^2-16=(x-4)(x+4)$ 로 나누면 $\\dfrac1{x+4}$ 의 극한은?","식":["$\\dfrac{f(x-3)-5}{x^2-16}=\\dfrac{f(x-3)-f(1)}{x-4}\\times\\dfrac{1}{x+4}$","$x-3=t$ 로 놓으면 $x\\to4$ 일 때 $t\\to1$ 이므로 앞의 극한은 $f'(1)$","$\\displaystyle\\lim_{x\\to4}\\frac1{x+4}=\\frac18$"],"설명":"$\\dfrac{f(x-3)-f(1)}{x-4}=\\dfrac{f(t)-f(1)}{t-1}$ 이므로 미분계수의 정의 꼴이다.","확인":"1/8","스킬":"D3","고비":true},{"제목":"$f'(1)$ 의 값","힌트":"$\\dfrac18f'(1)=2$ 에서 $f'(1)$ 은?","식":["$\\dfrac18f'(1)=2$","$f'(1)=16$"],"설명":"주어진 극한값이 $2$ 이다.","확인":"16","스킬":"D3"},{"제목":"$f(1)+f'(1)$ 의 값","힌트":"$f(1)$ 과 $f'(1)$ 의 합은?","식":["$f(1)+f'(1)=5+16=21$"],"설명":"첫 단계에서 $f(1)=5$ 를 얻었다.","확인":"21","스킬":"D3"}]},"ns-14d333f06c0d":{"길":"$f(0)$ 을 구한 뒤 $f'(0)$ 과 $f'(x)$ 를 정의대로 써서 같은 극한이 나오게 한다","단계":[{"제목":"$f(0)$ 의 값","힌트":"$x=y=0$ 을 넣으면 $f(0)$ 은?","식":["$f(0)=2\\{f(0)\\}^2$","$f(0)\\{2f(0)-1\\}=0$ 이고 $f(0)>0$ 이므로 $f(0)=\\dfrac12$"],"설명":"$f(0)=0$ 은 함숫값이 항상 양수라는 조건에 어긋나므로 버린다.","확인":"1/2","스킬":"A3"},{"제목":"$f'(0)$ 에서 얻는 극한","힌트":"$f(h)-f(0)$ 에 주어진 식을 써서 $f'(0)=2$ 를 $\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}$ 로 나타내면?","식":["$f(0+h)=2f(0)f(h)$ 이므로 $f(0+h)-f(0)=2f(0)f(h)-f(0)=f(0)\\{2f(h)-1\\}$","$f'(0)=\\displaystyle\\lim_{h\\to0}\\frac{f(0)\\{2f(h)-1\\}}{h}=\\frac12\\lim_{h\\to0}\\frac{2f(h)-1}{h}$","$\\dfrac12\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}=2$ 이므로 $\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}=4$"],"설명":"$f(0+h)$ 에 관계식을 쓸 때 $x=0$, $y=h$ 로 본다. 극한 앞에 $f(0)=\\dfrac12$ 이 붙는다.","확인":null,"스킬":"D3","고비":true},{"제목":"$\\dfrac{f'(x)}{f(x)}$ 의 값","힌트":"$f(x+h)-f(x)$ 에 관계식을 쓰면 $f'(x)$ 는 $f(x)$ 의 몇 배인가?","식":["$f(x+h)-f(x)=2f(x)f(h)-f(x)=f(x)\\{2f(h)-1\\}$","$f'(x)=f(x)\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}=4f(x)$","$\\dfrac{f'(x)}{f(x)}=4$"],"설명":"$x$ 를 고정하면 $f(x)$ 는 $h$ 와 무관한 상수이므로 극한 밖으로 나온다. 극한값은 앞 단계에서 구한 값이다.","확인":"4","스킬":"D3"}]},"ns-1b14558d9973":{"길":"$f(x)-x$ 를 세 근의 곱으로 쓰고 미분해 $\\beta-\\alpha$ 와 $\\gamma-\\beta$ 의 비로 $f'(\\beta)$ 를 구한다","단계":[{"제목":"$f(x)-x$ 를 인수로 쓰기","힌트":"$y=f(x)$ 와 $y=x$ 가 $x=\\alpha,\\,\\beta,\\,\\gamma$ 에서 만나면 $f(x)-x$ 는 어떻게 쓰이는가?","식":["$f(x)-x=0$ 의 세 근이 $\\alpha$, $\\beta$, $\\gamma$ 이고 최고차항의 계수가 $k>0$ 이므로","$f(x)-x=k(x-\\alpha)(x-\\beta)(x-\\gamma)$"],"설명":"$f$ 는 삼차식이므로 $f(x)-x$ 도 삼차식이고 최고차항의 계수 $k$ 는 $f$ 의 것과 같다.","확인":null,"스킬":"A3"},{"제목":"세 점에서의 $f'(x)-1$","힌트":"$g(x)=f(x)-x$ 라 할 때 $g'(\\gamma)=f'(\\gamma)-1$ 의 값은?","식":["$p=\\beta-\\alpha$, $q=\\gamma-\\beta$ 라 하면 $g'(\\alpha)=kp(p+q)=f'(\\alpha)-1=6$","$g'(\\gamma)=k(p+q)q=f'(\\gamma)-1=10$","$g'(\\beta)=-kpq=f'(\\beta)-1$"],"설명":"곱의 미분에서 $x=\\alpha$ 를 넣으면 $(x-\\alpha)$ 가 든 항이 사라지고 $k(\\alpha-\\beta)(\\alpha-\\gamma)=kp(p+q)$ 만 남는다. $\\gamma$, $\\beta$ 에서도 같은 방식이다.","확인":"10","스킬":"D5"},{"제목":"$p:q$ 의 비","힌트":"$g'(\\alpha)$ 와 $g'(\\gamma)$ 를 나누면 $\\dfrac pq$ 는?","식":["$\\dfrac{kp(p+q)}{k(p+q)q}=\\dfrac pq=\\dfrac{6}{10}=\\dfrac35$","$p=3s$, $q=5s$ ($s>0$) 로 둔다"],"설명":"$k(p+q)$ 가 약분되어 $k$ 를 몰라도 비를 알 수 있다.","확인":"3/5","스킬":"D5","고비":true},{"제목":"$ks^2$ 의 값","힌트":"$kp(p+q)=6$ 에 $p=3s$, $q=5s$ 를 넣으면 $ks^2$ 은?","식":["$k\\cdot3s\\cdot8s=24ks^2=6$","$ks^2=\\dfrac14$"],"설명":"$p+q=8s$ 이다.","확인":"1/4","스킬":"A3"},{"제목":"$f'(\\beta)$ 의 값","힌트":"$f'(\\beta)-1=-kpq$ 에 $ks^2$ 을 넣으면 $f'(\\beta)$ 는?","식":["$-kpq=-k\\cdot3s\\cdot5s=-15ks^2=-\\dfrac{15}{4}$","$f'(\\beta)=1-\\dfrac{15}{4}=-\\dfrac{11}{4}$"],"설명":"그림에서 $\\beta$ 는 $f$ 가 직선을 위에서 아래로 가로지르는 곳이라 $f'(\\beta)<1$ 이고, 구한 값과 맞다.","확인":"-11/4","스킬":"D5"}]},"ns-1d8d040f2d3c":{"길":"평균변화율을 두 점을 잇는 직선의 기울기로 읽어 $\\dfrac{f(2)-f(0)}{2-0}$ 를 계산한다","단계":[{"제목":"두 끝의 함숫값","힌트":"$f(0)$ 과 $f(2)$ 는 각각 얼마인가?","식":["$f(0)=-0^2+1=1$","$f(2)=-2^2+1=-3$"],"설명":"$f(2)$ 에서는 $-x^2$ 의 부호에 주의한다. $-(2^2)=-4$ 이다.","확인":"-3","스킬":"G9","고비":true},{"제목":"평균변화율","힌트":"$\\dfrac{f(2)-f(0)}{2-0}$ 의 값은?","식":["$\\dfrac{f(2)-f(0)}{2-0}=\\dfrac{-3-1}{2}=-2$"],"설명":"평균변화율은 $x$ 의 증가량에 대한 $y$ 의 증가량의 비이다.","확인":"-2","스킬":"G9"}]},"ns-297fbd58222e":{"길":"나눗셈 식에 $x=-1$ 을 대입하고 양변을 미분해 $x=-1$ 을 대입해 $a$, $b$ 를 구한다","단계":[{"제목":"$x=-1$ 대입","힌트":"나눗셈 식에 $x=-1$ 을 넣으면 $a+b$ 는?","식":["$x^{10}+ax^2+b=(x+1)^2Q(x)+8x-7$","$x=-1$ 이면 $1+a+b=-8-7=-15$ 이므로 $a+b=-16$"],"설명":"$x=-1$ 을 넣으면 $(x+1)^2Q(x)$ 가 $0$ 이 되어 $Q(x)$ 를 몰라도 된다.","확인":"-16","스킬":"A4"},{"제목":"양변을 미분해 $x=-1$ 대입","힌트":"양변을 미분해 $x=-1$ 을 넣으면 $a$ 는?","식":["$10x^9+2ax=2(x+1)Q(x)+(x+1)^2Q'(x)+8$","$x=-1$ 이면 $-10-2a=8$ 이므로 $a=-9$"],"설명":"$(x+1)^2Q(x)$ 를 미분하면 모든 항에 $(x+1)$ 이 남으므로 $x=-1$ 에서 $0$ 이 된다. $x=-1$ 이 중근이라 한 번 더 쓸 수 있는 식이다.","확인":"-9","스킬":"A3","고비":true},{"제목":"$a-2b$ 의 값","힌트":"$a+b=-16$ 에서 $b$ 와 $a-2b$ 는?","식":["$b=-16-(-9)=-7$","$a-2b=-9+14=5$"],"설명":"앞 단계에서 $a=-9$ 를 얻었다.","확인":"5","스킬":"A3"}]},"ns-2b552e8e9b08":{"길":"주어진 극한을 미분계수 두 개로 쪼개 $f'(1)$ 을 구하고 $x^3$ 꼴 극한에 옮긴다","단계":[{"제목":"$f'(1)$ 의 값","힌트":"$f(1+3h)-f(1-2h)$ 를 $f(1)$ 을 사이에 두고 쪼개 미분계수로 나타내면 $f'(1)$ 은?","식":["$f(1+3h)-f(1-2h)=\\{f(1+3h)-f(1)\\}-\\{f(1-2h)-f(1)\\}$","$\\displaystyle\\lim_{h\\to0}\\frac{f(1+3h)-f(1)}{3h}\\times3=3f'(1)$, $\\displaystyle\\lim_{h\\to0}\\frac{f(1-2h)-f(1)}{-2h}\\times(-2)=-2f'(1)$","$3f'(1)-(-2f'(1))=5f'(1)=10$ 이므로 $f'(1)=2$"],"설명":"분모를 $3h$, $-2h$ 로 각각 맞추려고 $3$ 과 $-2$ 를 곱한다. 둘째 항은 앞에 빼기가 붙어 있어 $+2f'(1)$ 이 된다.","확인":"2","스킬":"D3"},{"제목":"$x^3$ 꼴로 맞추기","힌트":"$\\dfrac{f(x^3)-f(1)}{x-1}$ 를 $\\dfrac{f(x^3)-f(1)}{x^3-1}$ 와 $x^2+x+1$ 의 곱으로 쓰면 $x^2+x+1$ 의 극한은?","식":["$x^3-1=(x-1)(x^2+x+1)$ 이므로 $\\dfrac{f(x^3)-f(1)}{x-1}=\\dfrac{f(x^3)-f(1)}{x^3-1}\\times(x^2+x+1)$","$x\\to1$ 이면 $x^3\\to1$ 이므로 앞의 극한은 $f'(1)$","$\\displaystyle\\lim_{x\\to1}(x^2+x+1)=3$"],"설명":"$t=x^3$ 으로 보면 $\\dfrac{f(t)-f(1)}{t-1}$ 이 되어 미분계수의 정의 꼴이다.","확인":"3","스킬":"D3","고비":true},{"제목":"극한값","힌트":"$f'(1)\\times3$ 은?","식":["$\\displaystyle\\lim_{x\\to1}\\frac{f(x^3)-f(1)}{x-1}=f'(1)\\times3=2\\times3=6$"],"설명":"두 극한이 각각 존재하므로 곱의 극한은 극한의 곱이다.","확인":"6","스킬":"D3"}]},"ns-324398d51fa2":{"길":"$x=1$ 에서 연속인 식과 좌·우 미분계수가 같은 식을 연립해 $a$, $b$ 를 정한다","단계":[{"제목":"연속 조건","힌트":"$x=1$ 에서 좌극한과 $f(1)$ 이 같으려면 $a+b$ 는?","식":["$\\displaystyle\\lim_{x\\to1-}f(x)=1+a+b$, $f(1)=-1+2=1$","$1+a+b=1$ 이므로 $a+b=0$"],"설명":"미분가능하면 연속이어야 하므로 먼저 연속 조건을 쓴다.","확인":"0","스킬":"D12"},{"제목":"좌·우 미분계수 조건","힌트":"$x=1$ 의 좌미분계수와 우미분계수가 같으려면 $a$ 는?","식":["우미분계수: $\\displaystyle\\lim_{x\\to1+}\\frac{-x+2-1}{x-1}=-1$","좌미분계수: $b=-a$ 를 쓰면 $\\displaystyle\\lim_{x\\to1-}\\frac{x^2+ax-a-1}{x-1}=\\lim_{x\\to1-}(x+a+1)=2+a$","$2+a=-1$ 이므로 $a=-3$, $b=3$"],"설명":"$x^2+ax-a-1=(x-1)(x+a+1)$ 로 인수분해된다. 좌미분계수는 $x<1$ 의 식을 미분한 $2x+a$ 에 $x=1$ 을 넣은 값과도 같다.","확인":"-3","스킬":"D12","고비":true},{"제목":"$f(-1)$ 의 값","힌트":"$a=-3$, $b=3$ 일 때 $f(-1)$ 은?","식":["$-1<1$ 이므로 $f(-1)=(-1)^2+a(-1)+b=1-a+b=1+3+3=7$"],"설명":"$x<1$ 인 곳의 식을 쓴다.","확인":"7","스킬":"D12"}]},"ns-391979503e8f":{"길":"$x=1$ 에서 연속인 식과 좌·우 미분계수가 같은 식으로 $a$, $b$ 를 구한다","단계":[{"제목":"연속 조건","힌트":"$x=1$ 에서 두 식의 값이 같으려면 $a+b$ 는?","식":["$f(1)=a+4$, $\\displaystyle\\lim_{x\\to1-}f(x)=1-b+3=4-b$","$a+4=4-b$ 이므로 $a+b=0$"],"설명":"미분가능하면 연속이어야 하므로 먼저 연속 조건을 쓴다.","확인":"0","스킬":"D12"},{"제목":"미분계수 조건","힌트":"$x=1$ 에서 두 식의 도함수 값이 같으려면 $a$ 는?","식":["$x>1$ 의 도함수 $2ax+4$ 의 $x=1$ 값은 $2a+4$, $x<1$ 의 도함수 $3x^2-b$ 의 $x=1$ 값은 $3-b$","$2a+4=3-b$ 이므로 $2a+b=-1$","$a+b=0$ 과 연립하면 $a=-1$, $b=1$"],"설명":"연속 조건에서 얻은 $b=-a$ 를 넣으면 $2a-a=-1$ 이다.","확인":"-1","스킬":"D12","고비":true},{"제목":"$a^2+b^2$ 의 값","힌트":"$a=-1$, $b=1$ 일 때 $a^2+b^2$ 은?","식":["$a^2+b^2=1+1=2$"],"설명":"$a$, $b$ 의 부호가 달라도 제곱의 합은 같다.","확인":"2","스킬":"D12"}]},"ns-3ea35412c321":{"길":"각 함수의 $x=0$ 에서 좌·우 미분계수를 구해 같은 것을 찾는다","단계":[{"제목":"$x=0$ 에서의 연속","힌트":"다섯 함수 모두 $f(0)$ 의 값은?","식":["다섯 함수 모두 $f(0)=0$ 이고 $|x|$ 와 다항식의 합·곱이므로 $x=0$ 에서 연속"],"설명":"연속은 모두 만족하므로 미분가능성만 가려내면 된다.","확인":"0","스킬":"D12"},{"제목":"좌·우 미분계수 비교","힌트":"$f(x)=x+|x|$ 의 $x=0$ 에서 우미분계수 $\\displaystyle\\lim_{x\\to0+}\\frac{f(x)-f(0)}{x}$ 는?","식":["$|x|$: 좌 $-1$, 우 $1$ 이므로 불가능","$x+|x|$: 좌 $0$, 우 $2$ 이므로 불가능","$2x^2+|x|$: 좌 $-1$, 우 $1$ 이므로 불가능","$-|x|$: 좌 $1$, 우 $-1$ 이므로 불가능"],"설명":"$x>0$ 에서 $\\dfrac{x+x}{x}=2$ 이고 $x<0$ 에서 $\\dfrac{x-x}{x}=0$ 이다. 네 함수 모두 좌·우 미분계수가 달라 $x=0$ 에서 미분가능하지 않으므로 버린다.","확인":"2","스킬":"D12","고비":true},{"제목":"$f(x)=x|x|$ 의 판정","힌트":"$\\dfrac{x|x|-0}{x-0}$ 를 정리하면?","식":["$\\displaystyle\\lim_{x\\to0}\\frac{x|x|-0}{x-0}=\\lim_{x\\to0}|x|=0$","좌미분계수와 우미분계수가 모두 $0$ 이므로 미분가능"],"설명":"$x\\ne0$ 에서 $x$ 로 약분하면 $|x|$ 만 남는다. 정답은 ② 이다.","확인":null,"스킬":"D12"}]},"ns-4e5beb70b030":{"길":"보기마다 $x=-1$ 에서 연속인지와 좌·우 미분계수가 같은지를 차례로 따진다","단계":[{"제목":"ㄱ. $|x^2+x|$ 의 $x=-1$","힌트":"$x=-1$ 의 왼쪽에서 $f(x)$ 의 식을 미분한 값, 즉 좌미분계수는?","식":["$x<-1$ 이면 $f(x)=x^2+x$, $-1\\le x\\le0$ 이면 $f(x)=-(x^2+x)$","$f(-1)=0$ 이고 좌극한·우극한도 $0$ 이므로 연속","좌미분계수 $2(-1)+1=-1$, 우미분계수 $-2(-1)-1=1$ 로 달라 미분계수가 없다"],"설명":"$x^2+x=x(x+1)$ 은 $x<-1$ 에서 양수이고 $-1<x<0$ 에서 음수라서 절댓값을 벗기는 식이 $x=-1$ 에서 바뀐다. 그래프가 $x=-1$ 에서 꺾인다. ㄱ 은 조건에 맞다.","확인":"-1","스킬":"D12","고비":true},{"제목":"ㄴ. $(x+1)^2$ 의 $x=-1$","힌트":"$g'(-1)$ 의 값은?","식":["$g'(x)=2(x+1)$ 이므로 $g'(-1)=0$","다항함수이므로 $x=-1$ 에서 연속이고 미분계수도 존재"],"설명":"미분계수가 존재하므로 ㄴ 은 조건에 맞지 않아 버린다.","확인":"0","스킬":"D12"},{"제목":"ㄷ. $\\dfrac1{x+1}$ 의 $x=-1$ 과 결론","힌트":"$x=-1$ 에서 $h(x)$ 의 값이 정의되는가?","식":["$x=-1$ 이면 분모가 $0$ 이므로 $h(-1)$ 이 정의되지 않아 불연속"],"설명":"연속이 아니므로 ㄷ 도 조건에 맞지 않는다. 연속이면서 미분계수가 없는 것은 ㄱ 뿐이므로 정답은 ① 이다.","확인":null,"스킬":"D12"}]},"ns-5a1c60dd9856":{"길":"곱의 미분법으로 $f'(x)$ 를 구한 뒤 $x=1$ 을 넣는다","단계":[{"제목":"곱의 미분법","힌트":"$(x^2+2)$ 와 $(2x-1)$ 를 각각 미분해 곱의 미분법을 쓰면 $f'(x)$ 는?","식":["$f'(x)=(x^2+2)'(2x-1)+(x^2+2)(2x-1)'$","$f'(x)=2x(2x-1)+2(x^2+2)=6x^2-2x+4$"],"설명":"$\\{g(x)h(x)\\}'=g'(x)h(x)+g(x)h'(x)$ 이다.","확인":null,"스킬":"D1","고비":true},{"제목":"$f'(1)$ 의 값","힌트":"$x=1$ 을 넣으면?","식":["$f'(1)=6-2+4=8$"],"설명":"$f'(x)=6x^2-2x+4$ 에 $x=1$ 을 대입한다.","확인":"8","스킬":"D1"}]},"ns-5d025e3955cb":{"길":"$x=0$ 을 넣어 $f(0)$ 을 구하고 $f'$ 의 연속성으로 $f'(0)$ 을 극한식에 옮긴다","단계":[{"제목":"$f(0)$ 의 값","힌트":"조건 (나) 에 $x=0$ 을 넣으면 $f(0)$ 은?","식":["$0\\cdot f'(0)=2f(0)+0+0$","$f(0)=0$"],"설명":"좌변은 $0$ 이고 우변은 $2f(0)$ 만 남는다.","확인":"0","스킬":"D3"},{"제목":"연속성으로 $f'(0)$ 을 극한으로 쓰기","힌트":"$f'$ 가 연속이면 $f'(0)$ 은 $\\displaystyle\\lim_{x\\to0}f'(x)$ 와 같은가?","식":["$x\\ne0$ 이면 $f'(x)=\\dfrac{2f(x)+x^2+3x}{x}$","(가) 에 의해 $f'(0)=\\displaystyle\\lim_{x\\to0}f'(x)=\\lim_{x\\to0}\\frac{2f(x)+x^2+3x}{x}$"],"설명":"도함수가 연속이라는 것은 $x=0$ 에서도 $\\displaystyle\\lim_{x\\to0}f'(x)=f'(0)$ 이라는 뜻이다. $x=0$ 에서는 (나) 를 $x$ 로 나눌 수 없어 이 조건이 필요하다.","확인":null,"스킬":"D3","고비":true},{"제목":"극한을 둘로 쪼개기","힌트":"$\\displaystyle\\lim_{x\\to0}\\frac{x^2+3x}{x}$ 의 값은?","식":["$\\displaystyle\\lim_{x\\to0}\\frac{2f(x)}{x}+\\lim_{x\\to0}\\frac{x^2+3x}{x}$","$f(0)=0$ 이므로 $\\displaystyle\\lim_{x\\to0}\\frac{f(x)-f(0)}{x-0}=f'(0)$ 이고 $\\displaystyle\\lim_{x\\to0}(x+3)=3$","$f'(0)=2f'(0)+3$"],"설명":"$f(0)=0$ 이어서 $\\dfrac{f(x)}{x}$ 가 미분계수의 정의 꼴이 된다.","확인":"3","스킬":"D3"},{"제목":"$f'(0)$ 의 값","힌트":"$f'(0)=2f'(0)+3$ 을 풀면?","식":["$-f'(0)=3$","$f'(0)=-3$"],"설명":"$f'(0)$ 은 양변에 있는 같은 수이므로 이항해 푼다.","확인":"-3","스킬":"D3"}]},"ns-613e22c59672":{"길":"(가) 로 $f'(0)$ 을, (나) 에 $x=y=0$ 을 넣어 $f(0)$ 을 구한 뒤 $f(2+h)$ 로 $f'(2)$ 를 쓴다","단계":[{"제목":"(가) 에서 $f'(0)$","힌트":"(가) 의 극한을 $f'(0)$ 에 대한 식으로 쓰면 $f'(0)$ 은?","식":["$\\displaystyle\\lim_{h\\to0}\\frac{f(3h)-f(0)}{2h}=\\frac32\\lim_{h\\to0}\\frac{f(3h)-f(0)}{3h}=\\frac32f'(0)$","$\\dfrac32f'(0)=3$ 이므로 $f'(0)=2$"],"설명":"분모를 $3h$ 로 만들려고 $\\dfrac32$ 를 곱하고 나눈다. $3h\\to0$ 이므로 미분계수의 정의 꼴이다.","확인":"2","스킬":"D3"},{"제목":"(나) 에서 $f(0)$","힌트":"(나) 에 $x=y=0$ 을 넣으면 $f(0)$ 은?","식":["$f(0)=f(0)+f(0)+0-1$","$f(0)=1$"],"설명":"$2xy$ 는 $0$ 이 되어 $f(0)=2f(0)-1$ 만 남는다.","확인":"1","스킬":"D3"},{"제목":"$f'(2)$ 의 값","힌트":"(나) 에 $x=2$, $y=h$ 를 넣으면 $f(2+h)-f(2)$ 는?","식":["$f(2+h)=f(2)+f(h)+4h-1$ 이므로 $f(2+h)-f(2)=f(h)+4h-1$","$f'(2)=\\displaystyle\\lim_{h\\to0}\\frac{f(h)-1+4h}{h}=\\lim_{h\\to0}\\frac{f(h)-f(0)}{h}+4$","$f'(2)=f'(0)+4=6$"],"설명":"$f(0)=1$ 이므로 $f(h)-1=f(h)-f(0)$ 이고 극한은 $f'(0)$ 이다. $2xy$ 에서 $x=2$, $y=h$ 를 넣으면 $4h$ 이다.","확인":"6","스킬":"D3","고비":true}]},"ns-61c23ba206cc":{"길":"$x=2$ 에서 연속이고 좌·우 미분계수가 같다는 두 식을 연립한다","단계":[{"제목":"연속 조건","힌트":"$x=2$ 에서 좌극한과 $f(2)$ 가 같으려면 $2a+b$ 는?","식":["$\\displaystyle\\lim_{x\\to2-}f(x)=4+\\dfrac12\\times2=5$, $f(2)=2a+b$","$2a+b=5$"],"설명":"미분가능하면 연속이어야 하므로 먼저 연속 조건을 쓴다.","확인":"5","스킬":"D12"},{"제목":"미분계수 조건","힌트":"$x=2$ 에서 좌·우 미분계수가 같으려면 $a$ 는?","식":["$x<2$ 의 도함수 $2x+\\dfrac12$ 의 $x=2$ 값은 $\\dfrac92$","$x>2$ 의 도함수는 $a$","$a=\\dfrac92$"],"설명":"$x\\ge2$ 의 식 $ax+b$ 는 일차식이라 어디서나 기울기가 $a$ 이다.","확인":"9/2","스킬":"D12","고비":true},{"제목":"$a+b$ 의 값","힌트":"$2a+b=5$ 에서 $b$ 와 $a+b$ 는?","식":["$b=5-2\\times\\dfrac92=-4$","$a+b=\\dfrac92-4=\\dfrac12$"],"설명":"$a=\\dfrac92$ 를 연속 조건에 넣는다.","확인":"1/2","스킬":"D12"}]},"ns-694a15dc720c":{"길":"곱의 미분법과 합성함수의 미분으로 $f'(x)$ 를 구해 $x=0$ 을 넣는다","단계":[{"제목":"곱의 미분법","힌트":"$(2x+1)^2$ 의 도함수 $8x+4$ 를 이용해 곱의 미분법을 쓰면 $f'(x)$ 는?","식":["$f'(x)=(x+1)'(2x+1)^2+(x+1)\\{(2x+1)^2\\}'$","$f'(x)=(2x+1)^2+(x+1)(8x+4)$"],"설명":"$(2x+1)^2$ 을 전개한 뒤 미분해도 같은 결과이다.","확인":null,"스킬":"D1","고비":true},{"제목":"$f'(0)$ 의 값","힌트":"$x=0$ 을 넣으면?","식":["$f'(0)=1^2+1\\times4=5$"],"설명":"$x=0$ 이면 $2x+1=1$, $x+1=1$, $8x+4=4$ 이다.","확인":"5","스킬":"D1"}]},"ns-703e165febee":{"길":"나눗셈 식에 $x=2$ 를 넣고 양변을 미분해 $x=2$ 를 넣어 나머지의 계수를 구한다","단계":[{"제목":"$x=2$ 대입","힌트":"$P(x)=x^4-3x^3+8x$ 라 할 때 $P(2)$ 는?","식":["$P(x)=(x-2)^2Q(x)+ax+b$","$x=2$ 이면 $P(2)=16-24+16=8=2a+b$"],"설명":"나누는 식이 이차이므로 나머지는 일차 이하이다. $x=2$ 를 넣으면 $(x-2)^2Q(x)$ 가 $0$ 이 된다.","확인":"8","스킬":"A4"},{"제목":"양변을 미분해 $x=2$ 대입","힌트":"양변을 미분해 $x=2$ 를 넣으면 $a$ 는?","식":["$4x^3-9x^2+8=2(x-2)Q(x)+(x-2)^2Q'(x)+a$","$x=2$ 이면 $32-36+8=a$ 이므로 $a=4$"],"설명":"$(x-2)^2Q(x)$ 를 미분하면 모든 항에 $(x-2)$ 가 남아 $x=2$ 에서 $0$ 이다. $x=2$ 가 중근이라 쓸 수 있는 식이다.","확인":"4","스킬":"D1","고비":true},{"제목":"나머지의 식","힌트":"$2a+b=8$ 에 $a=4$ 를 넣어 나머지 $ax+b$ 를 구하면?","식":["$b=8-2\\times4=0$","나머지는 $ax+b=4x$"],"설명":"선지 ④ 의 $4x$ 가 나머지이므로 정답은 ④ 이다.","확인":null,"스킬":"A4"}]},"ns-72c013d20746":{"길":"나눗셈 식에 $x=-1$ 을 넣고 양변을 미분해 $x=-1$ 을 넣어 $a$, $b$ 를 구한다","단계":[{"제목":"$x=-1$ 대입","힌트":"나머지 $4x-3$ 에 $x=-1$ 을 넣은 값은?","식":["$x^3+ax+b=Q(x)(x+1)^2+4x-3$","$x=-1$ 이면 $-1-a+b=4(-1)-3=-7$ 이므로 $-a+b=-6$"],"설명":"$x=-1$ 을 넣으면 $Q(x)(x+1)^2$ 이 $0$ 이 되어 $Q(x)$ 를 몰라도 된다.","확인":"-7","스킬":"A4"},{"제목":"양변을 미분해 $x=-1$ 대입","힌트":"양변을 미분해 $x=-1$ 을 넣으면 $a$ 는?","식":["$3x^2+a=Q'(x)(x+1)^2+2Q(x)(x+1)+4$","$x=-1$ 이면 $3+a=4$ 이므로 $a=1$"],"설명":"$(x+1)^2Q(x)$ 를 미분하면 모든 항에 $(x+1)$ 이 남아 $x=-1$ 에서 $0$ 이다. $x=-1$ 이 중근이라 쓸 수 있는 식이다.","확인":"1","스킬":"D1","고비":true},{"제목":"$a+b$ 의 값","힌트":"$-a+b=-6$ 에서 $b$ 와 $a+b$ 는?","식":["$b=-6+a=-5$","$a+b=1-5=-4$"],"설명":"$a=1$ 을 첫 단계의 식에 넣는다.","확인":"-4","스킬":"A4"}]},"ns-734f2b9af36b":{"길":"양변의 최고차항 차수를 비교해 $f$ 의 차수를 정하고 (나) 로 식을 세워 계수를 비교한다","단계":[{"제목":"$f$ 의 차수","힌트":"$f$ 가 $n$ 차식이면 $\\{f'(x)\\}^2$ 과 $4f(x)+1$ 의 차수는 각각?","식":["$f$ 가 $n$ 차식이면 $\\{f'(x)\\}^2$ 은 $2(n-1)$ 차, $4f(x)+1$ 은 $n$ 차","$2(n-1)=n$ 이므로 $n=2$"],"설명":"$n=1$ 이면 좌변은 상수이고 우변은 일차식이라 맞지 않는다. $n=0$ 이면 $f'=0$ 에서 $f=-\\dfrac14$ 이 되어 $f(-1)=2$ 와 어긋난다. 그러므로 이차함수이다.","확인":"2","스킬":"A11"},{"제목":"(나) 로 $f$ 의 꼴 세우기","힌트":"$f(-1)=f(2)=2$ 이면 $f(x)-2$ 는 어떤 인수를 갖는가?","식":["$f(x)-2=a(x+1)(x-2)$ ($a\\ne0$)","$f(x)=ax^2-ax-2a+2$, $f'(x)=a(2x-1)$"],"설명":"$f(x)-2$ 가 $x=-1$ 과 $x=2$ 에서 $0$ 이므로 $(x+1)(x-2)$ 를 인수로 가지고 이차식이므로 나머지 인수는 상수 $a$ 이다.","확인":null,"스킬":"A3"},{"제목":"(가) 에 넣어 계수 비교","힌트":"$x^2$ 의 계수를 비교하면 $a$ 는?","식":["$\\{f'(x)\\}^2=4a^2x^2-4a^2x+a^2$","$4f(x)+1=4ax^2-4ax-8a+9$","$x^2$ 의 계수에서 $4a^2=4a$, $a\\ne0$ 이므로 $a=1$"],"설명":"상수항도 $a^2=-8a+9$ 에 $a=1$ 을 넣으면 $1=1$ 로 성립한다. $a=0$ 은 이차함수 조건에 어긋나 버린다.","확인":"1","스킬":"A3","고비":true},{"제목":"$f'(3)$ 의 값","힌트":"$f'(x)=a(2x-1)$ 에 $a=1$, $x=3$ 을 넣으면?","식":["$f'(x)=2x-1$","$f'(3)=5$"],"설명":"$a=1$ 이므로 $f(x)=x^2-x$ 이다.","확인":"5","스킬":"A3"}]},"ns-736bfb933312":{"길":"세 인수의 곱의 미분법으로 $f'(x)$ 를 쓰고 $x=2$ 에서 사라지는 항을 뺀다","단계":[{"제목":"세 인수의 곱의 미분법","힌트":"$f(x)=u\\,v\\,w$ 의 도함수에서 각 항은 어떤 꼴인가?","식":["$u=x$, $v=x-2$, $w=3x^2+x$ 이므로 $f'=u'vw+uv'w+uvw'$","$f'(x)=(x-2)(3x^2+x)+x(3x^2+x)+x(x-2)(6x+1)$"],"설명":"한 인수만 미분하고 나머지는 그대로 곱한 항 세 개를 더한다.","확인":null,"스킬":"D1","고비":true},{"제목":"$f'(2)$ 의 값","힌트":"$x=2$ 를 넣고 $(x-2)$ 가 곱해지지 않은 항만 계산하면?","식":["$x=2$ 이면 첫째 항과 셋째 항은 $(x-2)=0$ 이 곱해져 $0$","$f'(2)=2(12+2)=28$"],"설명":"둘째 항만 남는다. $3\\cdot2^2+2=14$ 이다.","확인":"28","스킬":"D1"}]},"ns-783ae6290393":{"길":"$f(0)$ 을 구한 뒤 $f'(0)$ 과 $f'(x)$ 를 정의대로 써서 같은 극한이 나오게 한다","단계":[{"제목":"$f(0)$ 의 값","힌트":"$x=y=0$ 을 넣으면 $f(0)$ 은?","식":["$f(0)=2\\{f(0)\\}^2$","$f(0)\\{2f(0)-1\\}=0$ 이고 $f(0)>0$ 이므로 $f(0)=\\dfrac12$"],"설명":"$f(0)=0$ 은 항상 양의 값을 갖는다는 조건에 어긋나므로 버린다.","확인":"1/2","스킬":"A3"},{"제목":"$f'(0)$ 에서 얻는 극한","힌트":"$f'(0)=1$ 을 $\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}$ 로 나타내면 이 극한은?","식":["$f(0+h)=2f(0)f(h)$ 이므로 $f(0+h)-f(0)=f(0)\\{2f(h)-1\\}$","$f'(0)=\\displaystyle\\lim_{h\\to0}\\frac{f(0)\\{2f(h)-1\\}}{h}=\\frac12\\lim_{h\\to0}\\frac{2f(h)-1}{h}$","$\\dfrac12\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}=1$ 이므로 $\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}=2$"],"설명":"$f(0+h)$ 에 관계식을 쓸 때 $x=0$, $y=h$ 로 본다. 극한 앞에 $f(0)=\\dfrac12$ 이 붙는다.","확인":null,"스킬":"D3","고비":true},{"제목":"$\\dfrac{f'(x)}{f(x)}$ 의 값","힌트":"$f(x+h)-f(x)$ 에 관계식을 쓰면 $f'(x)$ 는 $f(x)$ 의 몇 배인가?","식":["$f(x+h)-f(x)=2f(x)f(h)-f(x)=f(x)\\{2f(h)-1\\}$","$f'(x)=f(x)\\displaystyle\\lim_{h\\to0}\\frac{2f(h)-1}{h}=2f(x)$","$\\dfrac{f'(x)}{f(x)}=2$"],"설명":"$x$ 를 고정하면 $f(x)$ 는 $h$ 와 무관한 상수이므로 극한 밖으로 나온다. 극한값은 앞 단계에서 구한 값이다.","확인":"2","스킬":"D3"}]},"ns-81ad4690de9f":{"길":"그래프에서 불연속인 점과 연속이지만 꺾인 점을 가려 미분 불가능한 점을 센다","단계":[{"제목":"불연속인 $x$ 의 개수 $m$","힌트":"구간 $(-1,\\,5)$ 에서 그래프가 끊어지는 $x$ 는 몇 개인가?","식":["$x=0$: 극한은 있으나 닫힌 점의 높이 $f(0)$ 이 극한과 다르다","$x=1$, $x=3$: 좌극한과 우극한이 서로 달라 극한이 없다","$x=2$: 곡선과 수평 선분이 이어지므로 연속, 따라서 $m=3$"],"설명":"연속이려면 극한이 존재하고 함숫값과 같아야 한다. $x=2$ 는 그래프가 끊기지 않으므로 센 것에서 버린다.","확인":"3","스킬":"D12"},{"제목":"미분 불가능한 $x$ 의 개수 $n$","힌트":"연속인 점 중에서 좌·우 미분계수가 다른 $x$ 는 어디인가?","식":["불연속인 $x=0,\\,1,\\,3$ 은 미분가능하지 않다","$x=2$: 연속이지만 왼쪽 곡선의 기울기와 오른쪽 수평 선분의 기울기 $0$ 이 달라 꺾인 점이므로 미분 불가능","$x=4$ 등 매끄러운 점은 미분가능, 따라서 $n=4$"],"설명":"미분가능하면 연속이므로 불연속인 점은 모두 미분 불가능이다. 여기에 연속이지만 꺾인 점을 더한다.","확인":"4","스킬":"D12","고비":true},{"제목":"$n-m$ 의 값","힌트":"$n$ 과 $m$ 의 차는?","식":["$n-m=4-3=1$"],"설명":"$m$ 은 불연속인 $x$ 의 개수, $n$ 은 미분 불가능한 $x$ 의 개수이다.","확인":"1","스킬":"D12"}]},"ns-842a95249ecb":{"길":"짝함수에서 $f'(-2)$ 를 구하고 분자·분모를 미분계수 꼴 두 개와 $x-2$ 의 곱으로 나눈다","단계":[{"제목":"짝함수의 도함수","힌트":"$f(-x)=f(x)$ 의 양변을 미분해 $f'(-2)$ 를 구하면?","식":["양변을 미분하면 $-f'(-x)=f'(x)$, 즉 $f'(-x)=-f'(x)$","$f'(-2)=-f'(2)=2$"],"설명":"$f(-x)$ 를 미분하면 안쪽 함수 $-x$ 의 도함수 $-1$ 이 곱해져 $-f'(-x)$ 이다.","확인":"2","스킬":"D3"},{"제목":"세 인수의 곱으로 나누어 쓰기","힌트":"분자를 $x^2-4$ 로, 분모를 $x+2$ 로 나누려면 곱해야 하는 식은?","식":["$\\dfrac{f(x^2)-f(4)}{f(x)-f(-2)}=\\dfrac{\\dfrac{f(x^2)-f(4)}{x^2-4}}{\\dfrac{f(x)-f(-2)}{x+2}}\\times\\dfrac{x^2-4}{x+2}$","$\\dfrac{x^2-4}{x+2}=x-2$"],"설명":"분자·분모를 각각 미분계수의 정의 꼴로 만들면 남는 인수가 $\\dfrac{x^2-4}{x+2}$ 이다. $x\\ne-2$ 이므로 약분된다.","확인":null,"스킬":"D3","고비":true},{"제목":"세 극한의 값","힌트":"$x\\to-2$ 일 때 $x-2$ 의 극한은?","식":["$x\\to-2$ 이면 $x^2\\to4$ 이므로 $\\displaystyle\\lim\\frac{f(x^2)-f(4)}{x^2-4}=f'(4)=5$","$\\displaystyle\\lim_{x\\to-2}\\frac{f(x)-f(-2)}{x+2}=f'(-2)=2$","$\\displaystyle\\lim_{x\\to-2}(x-2)=-4$"],"설명":"$x^2$ 을 한 덩어리로 보면 $x^2\\to4$ 일 때 미분계수의 정의 꼴이다.","확인":"-4","스킬":"D3"},{"제목":"극한값","힌트":"$\\dfrac{f'(4)}{f'(-2)}\\times(-4)$ 의 값은?","식":["$\\dfrac{5}{2}\\times(-4)=-10$"],"설명":"분모의 극한 $f'(-2)=2$ 가 $0$ 이 아니므로 몫의 극한은 극한의 몫이다.","확인":"-10","스킬":"D3"}]},"ns-85db9ec2cb32":{"길":"양변의 최고차항을 비교해 차수를 정하고 이차인 경우의 모순과 일차인 경우의 해를 가려낸다","단계":[{"제목":"$n\\ge2$ 일 때의 차수","힌트":"$f$ 가 $n$ 차식이면 $f'(x^2)$ 와 $2f(x)$ 의 차수는 각각?","식":["$f'(x)$ 는 $n-1$ 차이므로 $f'(x^2)$ 은 $2(n-1)$ 차, $2f(x)-6x+5$ 는 $n$ 차","$2(n-1)=n$ 이므로 $n=2$"],"설명":"$n\\ge2$ 이면 $-6x+5$ 는 차수가 낮아 최고차항에 영향이 없다. 최고차항의 계수는 좌변 $3n\\,x^{2n-2}$, 우변 $6x^n$ 으로도 맞는다.","확인":"2","스킬":"A11"},{"제목":"$n=2$ 가 안 되는 이유","힌트":"$f(x)=3x^2+ax+b$ 로 놓을 때 $f'(1)=3$ 에서 $a$ 는?","식":["$f'(x)=6x+a$ 이고 $f'(1)=6+a=3$ 이므로 $a=-3$","(가) 의 좌변 $f'(x^2)=6x^2-3$, 우변 $2f(x)-6x+5=6x^2-12x+2b+5$","$x$ 의 계수가 좌변 $0$, 우변 $-12$ 로 달라 등식이 성립하지 않는다"],"설명":"이차식이면 모순이 생기므로 버린다. 남는 경우는 일차식과 상수이다. 상수함수 $f=3$ 은 좌변이 $0$ 이고 우변이 $11-6x$ 라 맞지 않는다.","확인":"-3","스킬":"A3","고비":true},{"제목":"$n=1$ 일 때","힌트":"$f(x)=3x+c$ 라 할 때 (가) 에서 $c$ 는?","식":["$f'(x)=3$ 이므로 (나) 를 만족하고 $f'(x^2)=3$","(가) 에서 $3=2(3x+c)-6x+5=2c+5$","$c=-1$"],"설명":"$x$ 항이 $6x-6x=0$ 으로 사라져 상수 $c$ 에 대한 식만 남는다.","확인":"-1","스킬":"A3"},{"제목":"$f(-1)$ 의 값","힌트":"$f(x)=3x-1$ 에 $x=-1$ 을 넣으면?","식":["$f(-1)=-3-1=-4$"],"설명":"일차식 $f(x)=3x-1$ 이 두 조건을 모두 만족한다.","확인":"-4","스킬":"A3"}]},"ns-865017848540":{"길":"보기마다 반례를 찾거나 정의에 따라 증명해 참과 거짓을 가른다","단계":[{"제목":"ㄱ. 좌·우극한이 각각 존재","힌트":"$f(x)=|x|$ 의 $x=0$ 에서 좌미분계수는?","식":["$\\displaystyle\\lim_{x\\to0-}\\frac{|x|-0}{x}=-1$, $\\displaystyle\\lim_{x\\to0+}\\frac{|x|-0}{x}=1$","두 극한이 각각 존재해도 서로 달라 $x=0$ 에서 미분 불가능"],"설명":"미분가능하려면 두 극한이 존재하는 데서 그치지 않고 값이 같아야 한다. 반례가 있으므로 ㄱ 은 거짓이다.","확인":"-1","스킬":"C3"},{"제목":"ㄴ. 미분 불가인 $f$ 에 $g$ 를 더해 미분가능","힌트":"$f+g$ 와 $g$ 가 모두 $x=a$ 에서 미분가능하면 $f=(f+g)-g$ 는 어떻게 되는가?","식":["$f(x)=\\{f(x)+g(x)\\}-g(x)$","$f+g$ 와 $g$ 가 $x=a$ 에서 미분가능하면 그 차인 $f$ 도 미분가능하여 가정에 어긋난다"],"설명":"미분가능한 두 함수의 차는 미분가능하다. 그러므로 그런 $g$ 는 존재하지 않고 ㄴ 은 거짓이다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄷ. $f(|x|)$ 의 $x=0$","힌트":"$x\\ge0$ 과 $x<0$ 에서 $f(|x|)$ 의 식은 각각?","식":["$f(|x|)=ax^2+bx+c\\ (x\\ge0)$, $ax^2-bx+c\\ (x<0)$","$x=0$ 의 우미분계수는 $b$, 좌미분계수는 $-b$","$b\\ne-b$ 이므로 $b\\ne0$ 이면 미분 불가능"],"설명":"$x<0$ 에서는 $|x|=-x$ 이므로 $f(|x|)=a(-x)^2+b(-x)+c$ 이다. ㄷ 은 참이다.","확인":null,"스킬":"D12"},{"제목":"ㄹ. 두 접선의 교점","힌트":"$(a,\\,a^2)$ 과 $(b,\\,b^2)$ 에서의 접선의 식은?","식":["접선 $y=2ax-a^2$, $y=2bx-b^2$","$2ax-a^2=2bx-b^2$ 에서 $r=\\dfrac{a+b}{2}$","$a<0<b$, $|a|<|b|$ 이면 $b>-a$ 이므로 $a+b>0$, $r>0$"],"설명":"ㄹ 은 참이다. 옳은 것은 ㄷ, ㄹ 이므로 정답은 ⑤ 이다.","확인":null,"스킬":"C3"}]},"ns-8a7e4a7dda83":{"길":"그래프에서 불연속인 점과 연속이지만 꺾인 점을 가려 미분 불가능한 점을 센다","단계":[{"제목":"불연속인 $x$ 의 개수","힌트":"열린구간 $(0,\\,5)$ 에서 그래프가 끊어지는 $x$ 는 몇 개인가?","식":["$x=1$: 극한은 있으나 닫힌 점의 높이 $f(1)$ 이 극한과 다르다","$x=3$: 좌극한과 우극한이 서로 달라 극한이 없다"],"설명":"$x=2$ 와 $x=4$ 는 그래프가 끊기지 않으므로 센 것에서 버린다. $x=0$ 과 $x=5$ 는 구간에 포함되지 않는다.","확인":"2","스킬":"D12"},{"제목":"연속이지만 꺾인 $x$ 의 개수","힌트":"끊어지지 않았지만 좌·우 기울기가 다른 $x$ 는 몇 개인가?","식":["$x=2$: 왼쪽은 올라가고 오른쪽은 내려가는 꺾인 점이므로 미분 불가능","$x=4$: 한 직선 위의 점이라 좌·우 기울기가 같아 미분가능"],"설명":"미분가능하면 연속이지만 연속이라고 미분가능한 것은 아니다. 꺾인 점은 연속이어도 미분계수가 없다.","확인":"1","스킬":"D12","고비":true},{"제목":"미분 불가능한 $x$ 의 개수","힌트":"불연속인 $x$ 와 꺾인 $x$ 를 합하면?","식":["$1,\\ 3$ 과 $2$ 를 합쳐 $2+1=3$"],"설명":"불연속인 점은 모두 미분 불가능이다.","확인":"3","스킬":"D12"}]},"ns-8ad02a27b9fb":{"길":"접선의 기울기는 접점에서의 미분계수이므로 도함수에 접점의 $x$ 좌표를 넣는다","단계":[{"제목":"곡선의 도함수","힌트":"$y=-2x^{2}-3x$ 를 $x$ 에 대하여 미분하면?","식":["$y'=-4x-3$"],"설명":"곡선 위의 점에서의 접선의 기울기는 그 점에서의 미분계수와 같다.","확인":null,"스킬":"D1","고비":true},{"제목":"접점에서의 미분계수","힌트":"점 $(-1,\\,1)$ 의 $x$ 좌표 $-1$ 을 $y'$ 에 넣으면?","식":["$y'(-1)=-4\\times(-1)-3=1$"],"설명":"접선의 기울기는 $x=-1$ 에서의 미분계수이다.","확인":"1","스킬":"D1"}]},"ns-8c9be1175b94":{"길":"주어진 극한이 $f'(2)$ 임을 알아보고 도함수에 $x=2$ 를 넣어 $a$ 를 구한다","단계":[{"제목":"극한의 뜻","힌트":"$\\lim_{h\\to0}\\frac{f(2+h)-f(2)}{h}$ 는 무엇을 뜻하는가?","식":["$\\lim_{h\\to0}\\frac{f(2+h)-f(2)}{h}=f'(2)=16$"],"설명":"미분계수의 정의 그대로이다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f'(2)$ 를 $a$ 로 나타내기","힌트":"$f(x)=x^{3}-2x^{2}+ax+5$ 의 도함수에 $x=2$ 를 넣으면?","식":["$f'(x)=3x^{2}-4x+a$","$f'(2)=12-8+a=4+a$"],"설명":"$a$ 는 상수이므로 $ax$ 의 미분은 $a$ 이다.","확인":null,"스킬":"D3"},{"제목":"$a$ 의 값","힌트":"$4+a=16$ 에서 $a$ 는?","식":["$4+a=16$ 에서 $a=12$"],"설명":"$f'(2)=16$ 이라는 조건에 대입한다.","확인":"12","스킬":"D3"}]},"ns-930979dbc4aa":{"길":"나머지를 $ax+b$ 로 놓고 $x=1$ 대입과 양변의 미분으로 $a$, $b$ 를 구한다","단계":[{"제목":"나머지의 꼴","힌트":"$(x-1)^{2}$ 으로 나눈 나머지는 최대 몇 차식인가?","식":["$x^{10}+3x^{2}+2=(x-1)^{2}Q(x)+ax+b$"],"설명":"나누는 식이 이차식이므로 나머지는 일차 이하이다.","확인":"1","스킬":"A4"},{"제목":"$x=1$ 대입","힌트":"양변에 $x=1$ 을 넣으면 $a$, $b$ 사이에 어떤 식이 생기는가?","식":["$1+3+2=6=a+b$","$b=6-a$"],"설명":"$(x-1)^{2}Q(x)$ 는 $x=1$ 에서 $0$ 이다. 이 식의 좌변 $a+b$ 가 $R(1)$ 이다.","확인":null,"스킬":"A4"},{"제목":"양변의 미분과 $a$","힌트":"양변을 $x$ 로 미분해 $x=1$ 을 넣으면 $a$ 는?","식":["$10x^{9}+6x=2(x-1)Q(x)+(x-1)^{2}Q'(x)+a$","$x=1$ 을 넣으면 $16=a$"],"설명":"$(x-1)$ 이 곱해진 두 항은 $x=1$ 에서 모두 $0$ 이 된다.","확인":"16","스킬":"A4","고비":true},{"제목":"$R(1)$ 의 값","힌트":"$b$ 를 구해 $R(x)=ax+b$ 에 $x=1$ 을 넣으면?","식":["$b=6-16=-10$","$R(x)=16x-10$ 이므로 $R(1)=6$"],"설명":"$R(1)=a+b$ 이므로 $x=1$ 대입에서 얻은 값과 같다.","확인":"6","스킬":"A4"}]},"ns-9325ca2595b1":{"길":"분모를 $2h$ 로 맞춰 $f'(1)$ 의 정의 꼴을 만든다","단계":[{"제목":"분모를 $2h$ 로 맞추기","힌트":"분모 $h$ 를 $2h$ 로 바꾸려면 식 전체에 어떤 수를 곱하는가?","식":["$\\frac{f(1+2h)-f(1)}{h}=\\frac{f(1+2h)-f(1)}{2h}\\times2$"],"설명":"분모의 $h$ 를 $2h$ 로 맞추면 분자의 증분 $2h$ 와 같아져 정의 꼴이 된다.","확인":null,"스킬":"D3","고비":true},{"제목":"극한값","힌트":"$\\lim_{h\\to0}\\frac{f(1+2h)-f(1)}{2h}$ 를 $f'(1)$ 로 읽으면 전체 극한값은?","식":["$\\lim_{h\\to0}\\frac{f(1+2h)-f(1)}{2h}\\times2=2f'(1)=2\\times5=10$"],"설명":"$h\\to0$ 이면 $2h\\to0$ 이므로 앞 극한은 $f'(1)$ 이다.","확인":"10","스킬":"D3"}]},"ns-9dc448b87d16":{"길":"$f'(1)$ 은 상수이므로 양변을 미분한 뒤 $x=1$ 을 넣어 $f'(1)$ 을 구한다","단계":[{"제목":"양변의 미분","힌트":"$f'(1)$ 이 상수임을 이용해 양변을 $x$ 로 미분하면?","식":["$f'(x)=4x-f'(1)$"],"설명":"$f'(1)$ 은 수이므로 $-xf'(1)$ 의 미분은 $-f'(1)$ 이다.","확인":null,"스킬":"D13"},{"제목":"$f'(1)$ 의 값","힌트":"$f'(x)=4x-f'(1)$ 에 $x=1$ 을 넣으면 $f'(1)$ 은?","식":["$f'(1)=4-f'(1)$","$2f'(1)=4$ 에서 $f'(1)=2$"],"설명":"$f'(1)$ 이 양변에 모두 있으므로 한쪽으로 모아 푼다.","확인":"2","스킬":"A3","고비":true},{"제목":"$f'(-1)$ 의 값","힌트":"$f'(x)=4x-2$ 에 $x=-1$ 을 넣으면?","식":["$f'(-1)=4\\times(-1)-2=-6$"],"설명":"미분한 식에 $f'(1)=2$ 를 넣어 $f'(x)$ 를 완성한 뒤 대입한다.","확인":"-6","스킬":"D13"}]},"ns-a40712d61143":{"길":"평균변화율 $\\frac{f(3)-f(-1)}{3-(-1)}$ 에 두 함숫값을 넣는다","단계":[{"제목":"양 끝의 함숫값","힌트":"$f(x)=2x^{2}-x$ 에 $x=-1$ 과 $x=3$ 을 넣으면?","식":["$f(-1)=2+1=3$","$f(3)=18-3=15$"],"설명":"$x$ 의 값이 $-1$ 에서 $3$ 까지 변하므로 두 끝점의 함숫값이 필요하다.","확인":null,"스킬":"D2","고비":true},{"제목":"평균변화율","힌트":"$\\frac{f(3)-f(-1)}{3-(-1)}$ 의 값은?","식":["$\\frac{15-3}{4}=3$"],"설명":"평균변화율은 $x$ 의 증가량에 대한 $y$ 의 증가량의 비이다.","확인":"3","스킬":"D2"}]},"ns-a652aa0a958f":{"길":"대칭축이 $x=1$ 이므로 $f(x)=p(x-1)^{2}+q$ 로 놓고 보기를 하나씩 식으로 판정한다","단계":[{"제목":"이차함수의 꼴과 도함수","힌트":"축이 $x=1$ 인 이차함수의 식과 그 도함수는?","식":["$f(x)=p(x-1)^{2}+q$ ($p\\ne0$)","$f'(x)=2p(x-1)$"],"설명":"대칭축이 $x=1$ 이면 꼭짓점의 $x$ 좌표가 $1$ 이다.","확인":null,"스킬":"D2"},{"제목":"ㄱ. $f'(-1)$ 과 $f'(3)$","힌트":"$f'(-1)$ 과 $f'(3)$ 을 $p$ 로 나타내면?","식":["$f'(-1)=-4p$, $f'(3)=4p$","$f'(-1)=-f'(3)$ 이므로 ㄱ 은 참"],"설명":"대칭축 $x=1$ 에서 같은 거리에 있는 두 점의 접선의 기울기는 부호만 다르다.","확인":null,"스킬":"C3"},{"제목":"ㄴ. 평균변화율의 부호","힌트":"$m=\\frac{f(b)-f(a)}{b-a}$ 를 $p$, $a$, $b$ 로 나타내면?","식":["$m=\\frac{p(b-1)^{2}-p(a-1)^{2}}{b-a}=p(a+b-2)$"],"설명":"$a+b>2$ 라도 $p<0$ 이면 $m<0$ 이므로 ㄴ 은 거짓이다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄷ. $f'(c)$ 와 $m$","힌트":"$c=\\frac{a+b}{2}$ 일 때 $f'(c)$ 를 $p$, $a$, $b$ 로 나타내면?","식":["$f'(c)=2p\\left(\\frac{a+b}{2}-1\\right)=p(a+b-2)=m$","ㄷ 은 참이므로 옳은 것은 ㄱ, ㄷ"],"설명":"$a+b=2c$ 이면 $c=\\frac{a+b}{2}$ 이다. 따라서 정답은 ④ 이다.","확인":null,"스킬":"D2"}]},"ns-a94a6f4bc59f":{"길":"치환한 변수가 양쪽에서 $0$ 으로 가는지 보고 반례 $|x-a|$ 로 필요충분조건을 가린다","단계":[{"제목":"ㄱ. $h^{2}$ 치환의 방향","힌트":"$h\\to0$ 일 때 $s=h^{2}$ 은 어느 쪽에서 $0$ 에 가까워지는가?","식":["$s=h^{2}>0$ 이므로 $s\\to0+$","ㄱ 의 극한은 $\\lim_{s\\to0+}\\frac{f(a+s)-f(a)}{s}$ 와 같다"],"설명":"우미분계수만 나타나고 좌미분계수는 포함되지 않는다.","확인":null,"스킬":"D3"},{"제목":"ㄱ. 반례 $|x-a|$","힌트":"$f(x)=|x-a|$ 이면 ㄱ 의 극한과 $x=a$ 에서의 미분가능성은?","식":["$\\lim_{h\\to0}\\frac{|h^{2}|}{h^{2}}=1$ 로 극한은 존재","$|x-a|$ 는 $x=a$ 에서 미분가능하지 않다"],"설명":"ㄱ 이 성립해도 미분가능하지 않을 수 있으므로 ㄱ 은 필요조건일 뿐이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ. $h^{3}$ 치환의 방향","힌트":"$h\\to0$ 일 때 $s=h^{3}$ 은 어느 범위의 값으로 $0$ 에 가까워지는가?","식":["$s=h^{3}$ 은 양수와 음수 모두 가능하므로 $s\\to0$","$\\lim_{h\\to0}\\frac{f(a+h^{3})-f(a)}{h^{3}}=\\lim_{s\\to0}\\frac{f(a+s)-f(a)}{s}$"],"설명":"양쪽에서 $0$ 으로 가므로 ㄴ 의 극한이 존재하는 것과 $f'(a)$ 가 존재하는 것은 서로 같다.","확인":null,"스킬":"D3","고비":true},{"제목":"ㄷ. 대칭 차분의 반례","힌트":"$f(x)=|x-a|$ 이면 ㄷ 의 극한값은?","식":["$\\lim_{h\\to0}\\frac{|2h|-|-2h|}{4h}=0$ 으로 극한은 존재","그러나 $|x-a|$ 는 $x=a$ 에서 미분가능하지 않다"],"설명":"ㄷ 도 필요조건일 뿐 충분조건이 아니다.","확인":"0","스킬":"C3"},{"제목":"필요충분조건 판정","힌트":"보기 ㄱ, ㄴ, ㄷ 중 필요충분조건인 것은?","식":["ㄱ, ㄷ 은 필요조건이지만 충분조건이 아니다","ㄴ 은 $f'(a)$ 의 존재와 서로 같으므로 필요충분조건"],"설명":"따라서 정답은 ② 이다.","확인":null,"스킬":"C4"}]},"ns-a958606c27cf":{"길":"$f+xf'$ 의 최고차항으로 차수와 계수를 정하고 나머지 계수는 비교로 구한다","단계":[{"제목":"$f$ 의 차수","힌트":"$f(x)=ax^{n}+\\cdots$ 일 때 $f(x)+xf'(x)$ 의 최고차항을 우변과 비교하면 $n$ 은?","식":["$f'(x)=nax^{n-1}+\\cdots$ 이므로 $f(x)+xf'(x)$ 의 최고차항은 $(n+1)ax^{n}$","우변 $-4x^{3}+3x^{2}-4x-1$ 이 삼차이므로 $n=3$"],"설명":"$f$ 에서 $ax^{n}$, $xf'$ 에서 $nax^{n}$ 이 나와 합이 $(n+1)ax^{n}$ 이다.","확인":"3","스킬":"A11"},{"제목":"최고차항의 계수","힌트":"$n=3$ 일 때 $(n+1)a=-4$ 에서 $a$ 는?","식":["$4a=-4$ 에서 $a=-1$"],"설명":"좌변의 $x^{3}$ 의 계수와 우변의 $-4$ 를 같게 놓는다.","확인":"-1","스킬":"A3"},{"제목":"나머지 계수의 비교","힌트":"$f(x)=-x^{3}+bx^{2}+cx+d$ 를 넣어 $x^{2}$, $x$, 상수항을 비교하면 $b$, $c$, $d$ 는?","식":["$f'(x)=-3x^{2}+2bx+c$ 이므로 $f(x)+xf'(x)=-4x^{3}+3bx^{2}+2cx+d$","$3b=3$, $2c=-4$, $d=-1$ 에서 $b=1$, $c=-2$, $d=-1$"],"설명":"우변 $-4x^{3}+3x^{2}-4x-1$ 과 각 항의 계수를 비교한다.","확인":null,"스킬":"A3","고비":true},{"제목":"$f(-2)$ 의 값","힌트":"$f(x)=-x^{3}+x^{2}-2x-1$ 에 $x=-2$ 를 넣으면?","식":["$f(-2)=8+4+4-1=15$"],"설명":"$-(-2)^{3}=8$, $(-2)^{2}=4$, $-2\\times(-2)=4$ 이다.","확인":"15","스킬":"A3"}]},"ns-ad38705a45c1":{"길":"$f(0)=0$ 을 구하고 $f(x+y)-f(x)$ 를 $y$ 로 나눠 $y\\to0$ 으로 보내 $f'(x)$ 를 구한다","단계":[{"제목":"$f(0)$ 의 값","힌트":"$x=y=0$ 을 대입하면 $f(0)$ 은?","식":["$f(0)=2f(0)$","$f(0)=0$"],"설명":"$6x^{2}y+6xy^{2}$ 은 $x=y=0$ 에서 $0$ 이다.","확인":"0","스킬":"A3"},{"제목":"$f'(x)$ 의 식","힌트":"$f(x+y)-f(x)=f(y)+6x^{2}y+6xy^{2}$ 의 양변을 $y$ 로 나눠 $y\\to0$ 으로 보내면 $f'(x)$ 는?","식":["$\\frac{f(x+y)-f(x)}{y}=\\frac{f(y)-f(0)}{y}+6x^{2}+6xy$","$f'(x)=f'(0)+6x^{2}=6x^{2}+1$"],"설명":"$f(0)=0$ 이므로 $\\frac{f(y)}{y}=\\frac{f(y)-f(0)}{y-0}$ 이고 $y\\to0$ 이면 $f'(0)=1$ 이 된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f(x)$ 의 식","힌트":"$f'(x)=6x^{2}+1$ 을 적분하고 $f(0)=0$ 을 쓰면 $f(x)$ 는?","식":["$f(x)=2x^{3}+x+C$","$f(0)=0$ 에서 $C=0$"],"설명":"적분상수 $C$ 는 $f(0)=0$ 으로 정한다.","확인":null,"스킬":"D3"},{"제목":"$f(1)$ 의 값","힌트":"$f(x)=2x^{3}+x$ 에 $x=1$ 을 넣으면?","식":["$f(1)=2+1=3$"],"설명":"$f(x)=2x^{3}+x$ 이다.","확인":"3","스킬":"D3"}]},"ns-ae8f87e525f1":{"길":"분모를 $3h$ 로 맞춰 $f'(1)$ 의 정의 꼴로 고친다","단계":[{"제목":"분모를 $3h$ 로 맞추기","힌트":"분모 $2h$ 를 $3h$ 로 만들려면 어떤 수를 곱하고 나누는가?","식":["$\\frac{f(1+3h)-f(1)}{2h}=\\frac{f(1+3h)-f(1)}{3h}\\times\\frac32$"],"설명":"분자의 증분이 $3h$ 이므로 분모도 $3h$ 로 맞춘다.","확인":null,"스킬":"D3","고비":true},{"제목":"극한값","힌트":"$\\lim_{h\\to0}\\frac{f(1+3h)-f(1)}{3h}=f'(1)$ 을 쓰면 전체 극한값은?","식":["$\\frac32f'(1)=\\frac32\\times10=15$"],"설명":"$h\\to0$ 이면 $3h\\to0$ 이므로 정의 꼴의 극한은 $f'(1)$ 이다.","확인":"15","스킬":"D3"}]},"ns-afdf3b056c4b":{"길":"도함수의 정의 분모와 인수분해로 (가), (나), (다) 를 차례로 채운다","단계":[{"제목":"(가) 정의의 분모","힌트":"$t\\to x$ 일 때 $f(t)-f(x)$ 를 나누는 식은?","식":["$f'(x)=\\lim_{t\\to x}\\frac{f(t)-f(x)}{t-x}$"],"설명":"변화한 값 $t-x$ 가 분모이다.","확인":null,"스킬":"D3"},{"제목":"(나) 인수분해","힌트":"$t^{5}-x^{5}$ 에서 $t^{4}+t^{3}x+t^{2}x^{2}+tx^{3}+x^{4}$ 와 곱해지는 인수는?","식":["$t^{5}-x^{5}=(t-x)(t^{4}+t^{3}x+t^{2}x^{2}+tx^{3}+x^{4})$"],"설명":"$t=x$ 를 넣으면 $0$ 이므로 $t-x$ 가 인수이다. 곱해 전개하면 가운데 항이 모두 지워진다.","확인":null,"스킬":"A4","고비":true},{"제목":"(다) 극한값","힌트":"약분한 뒤 $t\\to x$ 로 보내면 다섯 항의 합은?","식":["$\\lim_{t\\to x}(t^{4}+t^{3}x+t^{2}x^{2}+tx^{3}+x^{4})=5x^{4}$"],"설명":"각 항이 $x^{4}$ 이 되고 다섯 개이다. 따라서 (가) $t-x$, (나) $t-x$, (다) $5x^{4}$ 이다.","확인":null,"스킬":"D3"}]},"ns-b095ac82efb1":{"길":"분자에 $9f(3)$ 을 더하고 빼서 $f'(3)$ 의 정의 꼴이 나오도록 둘로 나눈다","단계":[{"제목":"분자 나누기","힌트":"분자 $x^{2}f(3)-9f(x)$ 에 $9f(3)$ 을 더하고 빼면 어떤 두 묶음이 되는가?","식":["$x^{2}f(3)-9f(x)=(x^{2}-9)f(3)-9\\{f(x)-f(3)\\}$","$\\frac{x^{2}f(3)-9f(x)}{x-3}=(x+3)f(3)-9\\times\\frac{f(x)-f(3)}{x-3}$"],"설명":"$x^{2}-9=(x-3)(x+3)$ 이므로 첫 묶음은 약분된다.","확인":null,"스킬":"D3","고비":true},{"제목":"첫째 항의 극한","힌트":"$x\\to3$ 일 때 $(x+3)f(3)$ 의 극한값은?","식":["$\\lim_{x\\to3}(x+3)f(3)=6\\times2=12$"],"설명":"$f(3)=2$ 이다.","확인":"12","스킬":"D3"},{"제목":"둘째 항의 극한","힌트":"$x\\to3$ 일 때 $9\\times\\frac{f(x)-f(3)}{x-3}$ 의 극한값은?","식":["$9f'(3)=9\\times1=9$"],"설명":"$\\frac{f(x)-f(3)}{x-3}$ 의 극한은 $f'(3)$ 이다.","확인":"9","스킬":"D3"},{"제목":"극한값","힌트":"두 극한값의 차는?","식":["$12-9=3$"],"설명":"둘째 항 앞의 부호가 $-$ 이므로 첫째 항의 극한에서 뺀다.","확인":"3","스킬":"D3"}]},"ns-b408f240789c":{"길":"주어진 극한이 $f'(1)$ 임을 알아보고 도함수에 $x=1$ 을 넣는다","단계":[{"제목":"극한의 뜻","힌트":"$\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}$ 은 무엇을 뜻하는가?","식":["$\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}=f'(1)$"],"설명":"미분계수의 정의 그대로이다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f'(1)$ 의 값","힌트":"$f(x)=x^{4}-3x^{3}+2x^{2}-x+1$ 의 도함수에 $x=1$ 을 넣으면?","식":["$f'(x)=4x^{3}-9x^{2}+4x-1$","$f'(1)=4-9+4-1=-2$"],"설명":"항마다 $x^{n}$ 의 미분은 $nx^{n-1}$ 이다.","확인":"-2","스킬":"D3"}]},"ns-b53a0f00dd2b":{"길":"평균변화율을 $a$ 로 나타내고 $f'(3)$ 과 같다고 놓는다","단계":[{"제목":"평균변화율","힌트":"$x$ 가 $1$ 에서 $a$ 까지 변할 때의 평균변화율을 $a$ 로 나타내면?","식":["$\\frac{f(a)-f(1)}{a-1}=\\frac{a^{2}+2a-3}{a-1}=\\frac{(a-1)(a+3)}{a-1}=a+3$"],"설명":"$f(1)=7$ 이고 $a\\ne1$ 이므로 약분된다.","확인":null,"스킬":"D2","고비":true},{"제목":"$a$ 의 값","힌트":"평균변화율 $a+3$ 이 $f'(3)$ 과 같다고 놓으면 $a$ 는?","식":["$f'(x)=2x+2$ 이므로 $f'(3)=8$","$a+3=8$ 에서 $a=5$"],"설명":"두 값이 같다는 조건으로 $a$ 에 관한 일차방정식을 세운다.","확인":"5","스킬":"D2"}]},"ns-b5a67b6ac21e":{"길":"$f(0)=0$ 을 구하고 $f(x+y)-f(x)$ 를 $y$ 로 나눠 $f'(x)$ 를 구한 뒤 적분한다","단계":[{"제목":"$f(0)$ 의 값","힌트":"$x=y=0$ 을 대입하면 $f(0)$ 은?","식":["$f(0)=2f(0)$","$f(0)=0$"],"설명":"$2xy$ 는 $x=y=0$ 에서 $0$ 이다.","확인":"0","스킬":"A3"},{"제목":"$f'(x)$ 의 식","힌트":"$\\frac{f(x+y)-f(x)}{y}$ 에서 $y\\to0$ 으로 보내면 $f'(x)$ 는 $f'(0)$ 과 $x$ 로 어떻게 나타나는가?","식":["$f(x+y)-f(x)=f(y)-f(0)+2xy$","$\\frac{f(x+y)-f(x)}{y}=\\frac{f(y)-f(0)}{y}+2x$","$f'(x)=f'(0)+2x=2x+2$"],"설명":"$f(0)=0$ 이므로 $f(y)=f(y)-f(0)$ 이고 $y\\to0$ 이면 $f'(0)$ 이 된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f(x)$ 의 식","힌트":"$f'(x)=2x+2$ 를 적분하고 $f(0)=0$ 을 쓰면 $f(x)$ 는?","식":["$f(x)=x^{2}+2x+C$","$f(0)=0$ 에서 $C=0$"],"설명":"적분상수 $C$ 는 $f(0)=0$ 으로 정한다.","확인":null,"스킬":"D3"},{"제목":"$f(-3)$ 의 값","힌트":"$f(x)=x^{2}+2x$ 에 $x=-3$ 을 넣으면?","식":["$f(-3)=9-6=3$"],"설명":"$(-3)^{2}=9$, $2\\times(-3)=-6$ 이다.","확인":"3","스킬":"D3"}]},"ns-b862e6c63aa3":{"길":"접선의 기울기는 접점에서의 미분계수이므로 도함수에 접점의 $x$ 좌표를 넣는다","단계":[{"제목":"곡선의 도함수","힌트":"$y=-x^{3}+3x^{2}-2x-1$ 을 $x$ 에 대하여 미분하면?","식":["$y'=-3x^{2}+6x-2$"],"설명":"곡선 위의 점에서의 접선의 기울기는 그 점에서의 미분계수와 같다.","확인":null,"스킬":"D1","고비":true},{"제목":"접점에서의 미분계수","힌트":"점 $(1,\\,-1)$ 의 $x$ 좌표 $1$ 을 $y'$ 에 넣으면?","식":["$y'(1)=-3+6-2=1$"],"설명":"접선의 기울기는 $x=1$ 에서의 미분계수이다.","확인":"1","스킬":"D1"}]},"ns-c219fc8a64dd":{"길":"$f(0)=0$ 을 구하고 $f(x+h)-f(x)$ 를 $h$ 로 나눠 $f'(x)=f'(0)+x$ 를 얻는다","단계":[{"제목":"$f(0)$ 의 값","힌트":"$x=y=0$ 을 대입하면 $f(0)$ 은?","식":["$f(0)=2f(0)+0$","$f(0)=0$"],"설명":"$xy$ 는 $x=y=0$ 에서 $0$ 이다.","확인":"0","스킬":"A3"},{"제목":"$f'(x)$ 와 $f'(0)$ 의 관계","힌트":"$\\frac{f(x+h)-f(x)}{h}$ 에서 $h\\to0$ 으로 보내면 $f'(x)$ 는 $f'(0)$ 과 $x$ 로 어떻게 나타나는가?","식":["$f(x+h)-f(x)=f(h)+xh=f(h)-f(0)+xh$","$\\frac{f(x+h)-f(x)}{h}=\\frac{f(h)-f(0)}{h-0}+x$","$f'(x)=f'(0)+x$"],"설명":"$f(0)=0$ 이므로 $f(h)=f(h)-f(0)$ 이고 $h\\to0$ 이면 $f'(0)$ 이 된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f'(0)$ 의 값","힌트":"$f'(1)=3$ 을 $f'(x)=f'(0)+x$ 에 넣으면 $f'(0)$ 은?","식":["$f'(1)=f'(0)+1=3$","$f'(0)=2$"],"설명":"$x=1$ 을 넣어 $f'(0)$ 에 관한 식을 만든다.","확인":"2","스킬":"D3"}]},"ns-c71463e1c30f":{"길":"주어진 극한이 $f'(2)$ 이고 $f'(x)$ 는 피적분함수이므로 $x=2$ 를 넣는다","단계":[{"제목":"극한의 뜻과 도함수","힌트":"$f(x)=\\int(5x^{2}-3x-1)\\,dx$ 일 때 $f'(x)$ 는?","식":["$\\lim_{x\\to2}\\frac{f(x)-f(2)}{x-2}=f'(2)$","$f'(x)=5x^{2}-3x-1$"],"설명":"부정적분을 미분하면 피적분함수가 된다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f'(2)$ 의 값","힌트":"$f'(x)=5x^{2}-3x-1$ 에 $x=2$ 를 넣으면?","식":["$f'(2)=20-6-1=13$"],"설명":"$5\\times2^{2}=20$ 이다.","확인":"13","스킬":"D3"}]},"ns-c71dbc57346d":{"길":"(가)에서 $f(2)=g(2)$ 와 $f'(2)-g'(2)=-4$, (나)와 그 미분으로 $f(2)$, $g(2)$, $f'(2)$, $g'(2)$ 를 구한다","단계":[{"제목":"(가)에서 얻는 두 식","힌트":"$x\\to2$ 에서 분모가 $0$ 으로 가면 분자 $f(x)-g(x)$ 는 어떻게 되는가?","식":["$f(2)-g(2)=0$ 에서 $f(2)=g(2)$ ㉠","$\\lim_{x\\to2}\\left\\{\\frac{f(x)-f(2)}{x-2}-\\frac{g(x)-g(2)}{x-2}\\right\\}=f'(2)-g'(2)=-4$ ㉡"],"설명":"분모가 $0$ 으로 가는데 극한값이 있으려면 분자도 $0$ 으로 가야 한다. ㉠을 쓰면 극한이 두 미분계수의 차가 된다.","확인":null,"스킬":"D11","고비":true},{"제목":"$f(2)$, $g(2)$ 의 값","힌트":"(나)에 $x=2$ 를 넣고 ㉠과 연립하면 $f(2)$ 는?","식":["$g(2)-10f(2)+9=0$","㉠에서 $-9f(2)+9=0$ 이므로 $f(2)=g(2)=1$"],"설명":"$x^{3}+x$ 에 $x=2$ 를 넣으면 $10$ 이다.","확인":"1","스킬":"A3"},{"제목":"(나)의 양변의 미분","힌트":"(나)를 $x$ 로 미분해 $x=2$ 를 넣으면 $g'(2)$ 는 $f'(2)$ 로 어떻게 나타나는가?","식":["$g'(x)-(3x^{2}+1)f(x)-(x^{3}+x)f'(x)=0$","$g'(2)-13f(2)-10f'(2)=0$ 에서 $g'(2)=13+10f'(2)$"],"설명":"곱의 미분법을 쓰고 $f(2)=1$ 을 넣는다.","확인":null,"스킬":"D3"},{"제목":"$f'(2)$, $g'(2)$ 의 값","힌트":"㉡ $f'(2)-g'(2)=-4$ 와 연립하면 $f'(2)$ 는?","식":["$f'(2)-\\{13+10f'(2)\\}=-4$ 에서 $-9f'(2)=9$, $f'(2)=-1$","$g'(2)=13+10\\times(-1)=3$"],"설명":"$g'(2)$ 를 $f'(2)$ 로 나타낸 식을 ㉡에 넣는다.","확인":"-1","스킬":"D3"},{"제목":"접선의 기울기","힌트":"곱의 미분법으로 $\\{f(x)g(x)\\}'$ 에 $x=2$ 를 넣으면?","식":["$\\{f(x)g(x)\\}'=f'(x)g(x)+f(x)g'(x)$","$x=2$ 에서 $(-1)\\times1+1\\times3=2$"],"설명":"접선의 기울기는 $y=f(x)g(x)$ 의 $x=2$ 에서의 미분계수이다.","확인":"2","스킬":"D3"}]},"ns-ccbde5132804":{"길":"분자가 $0$ 이 되는 조건으로 $f(1)$ 을, 인수분해로 $f'(1)$ 을 구한 뒤 곱의 미분법을 쓴다","단계":[{"제목":"$f(1)$ 의 값","힌트":"$x\\to1$ 에서 분모가 $0$ 으로 가면 분자 $f(x)-2$ 는 $x=1$ 에서 어떤 값인가?","식":["$f(1)-2=0$ 에서 $f(1)=2$"],"설명":"분모가 $0$ 으로 가는데 극한값 $3$ 이 있으려면 분자도 $0$ 으로 가야 한다.","확인":null,"스킬":"D11"},{"제목":"$f'(1)$ 의 값","힌트":"$x^{2}-1=(x-1)(x+1)$ 로 인수분해해 극한을 $f'(1)$ 로 나타내면 $f'(1)$ 은?","식":["$\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}\\times\\frac1{x+1}=\\frac{f'(1)}{2}=3$","$f'(1)=6$"],"설명":"$f(1)=2$ 이므로 분자는 $f(x)-f(1)$ 이다. $\\frac1{x+1}$ 은 $x\\to1$ 에서 $\\frac12$ 이다.","확인":"6","스킬":"D3","고비":true},{"제목":"$g'(1)$ 의 값","힌트":"곱의 미분법으로 $g'(x)$ 를 구해 $x=1$ 을 넣으면?","식":["$g'(x)=2xf(x)+x^{2}f'(x)$","$g'(1)=2f(1)+f'(1)=4+6=10$"],"설명":"$g(x)=x^{2}f(x)$ 는 두 함수의 곱이다.","확인":"10","스킬":"D3"}]},"ns-cd8c28ba6f1a":{"길":"$f(0)$ 을 구해 $f(x+y)-f(x)$ 를 $f(y)-f(0)$ 꼴로 바꾸고 $y\\to0$ 으로 보내 $f'(x)$ 를 얻는다","단계":[{"제목":"$f(0)$ 의 값","힌트":"(가)에 $x=y=0$ 을 넣으면 $f(0)$ 은?","식":["$f(0)=2f(0)+0+1$","$f(0)=-1$"],"설명":"$xy$ 는 $x=y=0$ 에서 $0$ 이다.","확인":"-1","스킬":"A3"},{"제목":"$f'(x)$ 와 $f'(0)$ 의 관계","힌트":"$\\frac{f(x+y)-f(x)}{y}$ 에서 $y\\to0$ 으로 보내면 $f'(x)$ 는 $f'(0)$ 과 $x$ 로 어떻게 나타나는가?","식":["$f(x+y)-f(x)=f(y)+xy+1=f(y)-f(0)+xy$","$\\frac{f(x+y)-f(x)}{y}=\\frac{f(y)-f(0)}{y}+x$","$f'(x)=f'(0)+x$"],"설명":"$f(0)=-1$ 이므로 $f(y)+1=f(y)-f(0)$ 이다.","확인":null,"스킬":"D3","고비":true},{"제목":"$f'(x)$ 의 식","힌트":"(나) $f'(0)=3$ 을 넣으면 $f'(x)$ 는?","식":["$f'(x)=3+x=x+3$"],"설명":"$f'(x)=f'(0)+x$ 에 $f'(0)=3$ 을 대입한다. 따라서 정답은 ⑤ 이다.","확인":null,"스킬":"D3"}]},"ns-0de94a05f88a":{"길":"롤의 정리의 조건 $f(-k)=f(k)$ 로 $k$ 를, $f'(c)=0$ 으로 $c$ 를 구한다","단계":[{"제목":"$k$ 의 값","힌트":"$f(-k)=f(k)$ 를 풀어 자연수 $k$ 를 구하면?","식":["$\\frac13k^{3}+k^{2}-3k+2=-\\frac13k^{3}+k^{2}+3k+2$","$k^{3}-9k=0$, $k(k+3)(k-3)=0$ 에서 $k=3$"],"설명":"롤의 정리를 쓰려면 양 끝의 함숫값이 같아야 한다. $k$ 는 자연수이다.","확인":"3","스킬":"D2"},{"제목":"$c$ 의 값","힌트":"$f'(c)=0$ 의 해 중 구간 $(-3,\\,3)$ 안에 있는 것은?","식":["$f'(x)=x^{2}+2x-3=(x+3)(x-1)$","$f'(c)=0$ 에서 $c=-3$ 또는 $c=1$ 이고 $-3<c<3$ 이므로 $c=1$"],"설명":"롤의 정리의 $c$ 는 열린구간 $(-k,\\,k)$ 안에 있다.","확인":"1","스킬":"D2","고비":true},{"제목":"$kc$ 의 값","힌트":"$k=3$, $c=1$ 일 때 $kc$ 는?","식":["$kc=3\\times1=3$"],"설명":"두 값을 곱한다.","확인":"3","스킬":"D2"}]},"ns-13a0480297a3":{"길":"접선의 기울기에 수직인 직선의 기울기로 직선의 식을 세우고 $x=10$ 을 넣는다","단계":[{"제목":"점 $(2,\\,1)$ 에서의 접선의 기울기","힌트":"$y=(x^{2}-5)^{2}$ 의 $x=2$ 에서의 접선의 기울기는?","식":["$y'=2(x^{2}-5)\\times2x=4x(x^{2}-5)$","$y'(2)=8\\times(-1)=-8$"],"설명":"합성함수의 미분법을 쓴다.","확인":"-8","스킬":"D1","고비":true},{"제목":"수직인 직선의 기울기","힌트":"기울기가 $-8$ 인 접선에 수직인 직선의 기울기는?","식":["$-8\\times m=-1$ 에서 $m=\\frac18$"],"설명":"서로 수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":"1/8","스킬":"G9"},{"제목":"$a$ 의 값","힌트":"점 $(2,\\,1)$ 을 지나고 기울기가 $\\frac18$ 인 직선이 점 $(10,\\,a)$ 를 지날 때 $a$ 는?","식":["$y=\\frac18(x-2)+1$","$a=\\frac18\\times8+1=2$"],"설명":"$x=10$ 을 직선의 식에 넣는다.","확인":"2","스킬":"D1"}]},"ns-196c435d3996":{"길":"그래프에서 접선의 기울기와 두 점을 잇는 직선의 기울기를 부호와 크기로 비교한다","단계":[{"제목":"극값에서의 접선의 기울기","힌트":"그래프가 극대, 극소인 $x=a$, $x=b$ 에서 $f'$ 의 값은?","식":["$f'(a)=0$, $f'(b)=0$","$x=c$ 에서는 그래프가 오르므로 $f'(c)>0$"],"설명":"극값을 갖는 점에서 접선은 $x$ 축과 평행하다.","확인":"0","스킬":"D1"},{"제목":"평균변화율의 부호","힌트":"구간 $[a,\\,b]$ 와 $[b,\\,c]$ 의 평균변화율은 각각 어떤 부호인가?","식":["$[a,\\,b]$ 에서 $f(b)<f(a)$ 이므로 평균변화율 $<0$","$[b,\\,c]$ 에서 $f(c)>f(b)$ 이므로 평균변화율 $>0$"],"설명":"평균변화율은 두 점을 잇는 직선의 기울기이다.","확인":null,"스킬":"D2","고비":true},{"제목":"선지 판정","힌트":"①~⑤ 중 위에서 구한 부호와 크기에 맞는 것은?","식":["②: $f'(a)=0$ 은 $[b,\\,c]$ 의 평균변화율($>0$)보다 작으므로 거짓","③: $f'(b)=0<f'(c)$, ④: $[a,\\,b]$ 의 평균변화율$<0=f'(b)$, ⑤: $[b,\\,c]$ 의 평균변화율$>0>[a,\\,b]$ 의 평균변화율이므로 모두 거짓","①: $x=c$ 에서의 접선이 점 $(a,\\,f(a))$, $(c,\\,f(c))$ 를 잇는 직선보다 가파르므로 참"],"설명":"따라서 옳은 것은 ① 이다.","확인":null,"스킬":"D1"}]},"ns-1daa10234d99":{"길":"접점을 $(t,\\,f(t))$ 로 두고 접선이 $(-2,\\,7)$ 을 지난다는 식으로 $t$ 를 구한 뒤 $a<0$ 인 접선을 고른다","단계":[{"제목":"접선의 방정식","힌트":"접점의 $x$ 좌표를 $t$ 라 할 때 접선의 방정식은?","식":["$y'=-2x-4$","$y=(-2t-4)(x-t)-t^{2}-4t-1$"],"설명":"접점이 $(t,\\,-t^{2}-4t-1)$ 이고 기울기가 $y'(t)=-2t-4$ 이다.","확인":null,"스킬":"D7"},{"제목":"$t$ 의 값","힌트":"접선이 점 $(-2,\\,7)$ 을 지난다는 식에서 $t$ 는?","식":["$7=(-2t-4)(-2-t)-t^{2}-4t-1$","$t^{2}+4t=0$ 에서 $t=-4$ 또는 $t=0$"],"설명":"$x=-2$, $y=7$ 을 접선의 식에 넣는다. 접선이 두 개 나온다.","확인":null,"스킬":"D7","고비":true},{"제목":"$a<0$ 인 접선의 기울기","힌트":"$a<0$ 인 접선의 기울기 $a$ 는?","식":["$t=-4$ 이면 기울기 $4$, $y=4x+15$","$t=0$ 이면 기울기 $-4$, $y=-4x-1$"],"설명":"$a<0$ 이므로 $t=0$ 의 접선이다.","확인":"-4","스킬":"D1"},{"제목":"$a+b$ 의 값","힌트":"접선 $y=-4x-1$ 에서 $b$ 를 구하면 $a+b$ 는?","식":["$b=-1$","$a+b=-4+(-1)=-5$"],"설명":"$y=ax+b$ 와 $y=-4x-1$ 을 비교한다.","확인":"-5","스킬":"D1"}]},"ns-3a238b86f2cf":{"길":"평균값 정리 $\\frac{f(2)-f(a)}{2-a}=f'\\left(\\frac12\\right)$ 로 $a$ 에 관한 이차방정식을 세운다","단계":[{"제목":"$f'\\left(\\frac12\\right)$ 의 값","힌트":"$f'(x)=2x-3$ 에 $x=\\frac12$ 을 넣으면?","식":["$f'(x)=2x-3$","$f'\\left(\\frac12\\right)=1-3=-2$"],"설명":"평균값 정리의 $c$ 가 $\\frac12$ 이므로 $f'(c)=f'\\left(\\frac12\\right)$ 이다.","확인":"-2","스킬":"D2"},{"제목":"평균변화율의 식","힌트":"$f(2)=2$, $f(a)=a^{2}-3a+4$ 일 때 평균변화율이 $-2$ 라 놓으면 $a$ 의 방정식은?","식":["$\\frac{2-(a^{2}-3a+4)}{2-a}=-2$","$-a^{2}+3a-2=-2(2-a)$ 에서 $a^{2}-a-2=0$"],"설명":"양변에 $2-a$ 를 곱해 분모를 없앤다.","확인":null,"스킬":"D2","고비":true},{"제목":"$a$ 의 값","힌트":"$a^{2}-a-2=0$ 의 근 중 $a<\\frac12$ 인 것은?","식":["$(a+1)(a-2)=0$","$a<\\frac12$ 이므로 $a=-1$"],"설명":"$a=2$ 는 조건 $a<\\frac12$ 을 만족하지 못한다.","확인":"-1","스킬":"D2"}]},"ns-416c5c63288d":{"길":"평균변화율을 구해 $f'(c)$ 와 같게 놓고 $c$ 가 구간 안에 있는 근을 고른다","단계":[{"제목":"평균변화율","힌트":"$\\frac{f(1)-f(-1)}{1-(-1)}$ 의 값은?","식":["$f(1)=-2$, $f(-1)=-4$","$\\frac{-2-(-4)}{2}=1$"],"설명":"평균값 정리의 $f'(c)$ 는 이 평균변화율과 같다.","확인":"1","스킬":"D2"},{"제목":"$c$ 에 관한 방정식","힌트":"$f'(c)=1$ 을 $c$ 의 이차방정식으로 쓰면?","식":["$f'(x)=3x^{2}-6x$","$3c^{2}-6c=1$ 에서 $3c^{2}-6c-1=0$"],"설명":"우변의 평균변화율 $1$ 을 좌변으로 옮긴다.","확인":null,"스킬":"D2"},{"제목":"$c$ 의 값","힌트":"근의 공식으로 구한 두 근 중 $-1<c<1$ 인 것은?","식":["$c=\\frac{6\\pm\\sqrt{48}}{6}=\\frac{3\\pm2\\sqrt3}{3}$","$-1<c<1$ 이므로 $c=\\frac{3-2\\sqrt3}{3}$"],"설명":"$\\frac{3+2\\sqrt3}{3}$ 은 $1$ 보다 크므로 구간 밖이다.","확인":null,"스킬":"D2","고비":true}]},"ns-4621dc0aa5ab":{"길":"접점을 $t$ 로 두고 $(0,\\,k)$ 를 지나는 조건에서 두 접점을 잡아 기울기의 곱을 $-1$ 로 놓는다","단계":[{"제목":"접선의 방정식","힌트":"접점의 $x$ 좌표를 $t$ 라 할 때 접선의 방정식은?","식":["$y'=-2x+4$","$y=(-2t+4)(x-t)-t^{2}+4t$"],"설명":"접점이 $(t,\\,-t^{2}+4t)$ 이고 기울기가 $y'(t)=-2t+4$ 이다.","확인":null,"스킬":"D7"},{"제목":"$k$ 와 $t$ 의 관계","힌트":"접선이 점 $(0,\\,k)$ 를 지난다는 식에서 $k$ 를 $t$ 로 나타내면?","식":["$k=(-2t+4)(0-t)-t^{2}+4t$","$k=t^{2}$ 이므로 $t=\\pm\\sqrt{k}$"],"설명":"$k>0$ 이므로 접점이 두 개이고 접선도 두 개이다.","확인":null,"스킬":"D7","고비":true},{"제목":"수직 조건","힌트":"두 접점 $t=\\pm\\sqrt{k}$ 에서 접선의 기울기의 곱을 $-1$ 로 놓으면 $k$ 의 식은?","식":["두 기울기는 $-2\\sqrt{k}+4$ 와 $2\\sqrt{k}+4$","$(-2\\sqrt{k}+4)(2\\sqrt{k}+4)=16-4k=-1$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":null,"스킬":"D1"},{"제목":"$k$ 의 값","힌트":"$16-4k=-1$ 에서 $k$ 는?","식":["$4k=17$ 에서 $k=\\frac{17}{4}$"],"설명":"$k>0$ 조건을 만족한다.","확인":"17/4","스킬":"D1"}]},"ns-56a59ed2943b":{"길":"할선과 평행한 접선의 접점을 그림에서 세고, 롤의 정리는 $f'=0$ 인 점을 센다","단계":[{"제목":"평균값 정리의 조건","힌트":"$[a,\\,c]$ 에서 평균값 정리를 만족하는 $x$ 는 $f'(x)$ 가 무엇과 같은 점인가?","식":["$f'(x)=\\frac{f(c)-f(a)}{c-a}$ ($a<x<c$)","우변은 두 점 $(a,\\,f(a))$, $(c,\\,f(c))$ 를 잇는 직선 $l$ 의 기울기"],"설명":"접선의 기울기가 직선 $l$ 의 기울기와 같은 점을 찾는다.","확인":null,"스킬":"D2"},{"제목":"접점의 개수 $m$","힌트":"직선 $l$ 과 평행하게 곡선에 접하는 직선을 그리면 접점은 몇 개인가?","식":["직선 $l$ 을 평행이동하며 곡선에 접하는 직선은 $3$ 개","접점이 $3$ 개이므로 $m=3$"],"설명":"접점은 모두 $a<x<c$ 안에 있다.","확인":"3","스킬":"D2","고비":true},{"제목":"롤의 정리와 $n$","힌트":"$f(b)=f(c)$ 일 때 $(b,\\,c)$ 에서 $f'(x)=0$ 인 점은 그래프에서 몇 개인가?","식":["그림에서 $f(b)=f(c)$ 이므로 $(b,\\,c)$ 에 접선이 수평인 점이 있다","$(b,\\,c)$ 에서 극값을 갖는 점은 한 개이므로 $n=1$"],"설명":"롤의 정리를 만족하는 $x$ 는 $f'(x)=0$ 인 점이다.","확인":"1","스킬":"D2"},{"제목":"$m+n$ 의 값","힌트":"$m=3$, $n=1$ 일 때 $m+n$ 은?","식":["$m+n=3+1=4$"],"설명":"두 개수를 더한다.","확인":"4","스킬":"D2"}]},"ns-6b609504e6f6":{"길":"$[-2,\\,0]$ 에서 평균값 정리를 쓰고 (나)의 $f'\\ge5$ 로 $f(-2)$ 의 범위를 구한다","단계":[{"제목":"평균값 정리의 식","힌트":"(가)로 $f(0)=3$ 일 때 $[-2,\\,0]$ 에서 평균값 정리를 쓰면 $f'(k)$ 는 $f(-2)$ 로 어떻게 나타나는가?","식":["$f(0)=3$","$f'(k)=\\frac{f(0)-f(-2)}{0-(-2)}=\\frac{3-f(-2)}{2}$ ($-2<k<0$)"],"설명":"다항함수는 닫힌구간에서 연속이고 열린구간에서 미분가능하므로 평균값 정리를 쓸 수 있다.","확인":null,"스킬":"D2","고비":true},{"제목":"(나)에서 얻는 부등식","힌트":"$f'(k)\\ge5$ 를 $f(-2)$ 의 부등식으로 고치면?","식":["$\\frac{3-f(-2)}{2}\\ge5$","$3-f(-2)\\ge10$ 에서 $f(-2)\\le-7$"],"설명":"$-2<k<0$ 이므로 (나)에 의해 $f'(k)\\ge5$ 이다.","확인":null,"스킬":"D2"},{"제목":"$f(-2)$ 의 최댓값","힌트":"$f(-2)\\le-7$ 일 때 $f(-2)$ 의 최댓값은?","식":["$f(x)=5x+3$ 이면 (가), (나)를 만족하고 $f(-2)=-7$"],"설명":"위 부등식의 등호가 성립하는 함수가 있으므로 최댓값에 도달한다.","확인":"-7","스킬":"D2"}]},"ns-71c188f0121a":{"길":"평균변화율을 구해 $f'(c)$ 와 같게 놓고 $c$ 가 구간 안에 있는 값을 고른다","단계":[{"제목":"평균변화율","힌트":"$\\frac{f(3)-f(0)}{3-0}$ 의 값은?","식":["$f(3)=25$, $f(0)=-2$","$\\frac{25-(-2)}{3}=9$"],"설명":"평균값 정리의 $f'(c)$ 는 이 평균변화율과 같다.","확인":"9","스킬":"D2","고비":true},{"제목":"$c$ 의 값","힌트":"$f'(c)=9$ 를 풀어 구간 $(0,\\,3)$ 안의 $c$ 를 구하면?","식":["$f'(x)=3x^{2}$ 이므로 $3c^{2}=9$","$c^{2}=3$ 이고 $0<c<3$ 이므로 $c=\\sqrt3$"],"설명":"$c=-\\sqrt3$ 은 구간 밖이다.","확인":null,"스킬":"D2"}]},"ns-75f247c3d56c":{"길":"접점을 $(t,\\,f(t))$ 로 두고 접선이 $(1,\\,6)$ 을 지나는 조건에서 $t$ 를 구한 뒤 수직인 직선을 세운다","단계":[{"제목":"접선의 방정식","힌트":"접점의 $x$ 좌표를 $t$ 라 할 때 접선의 방정식을 $t$ 로 정리하면?","식":["$y'=3x^{2}-4x$","$y=(3t^{2}-4t)x-2t^{3}+2t^{2}-5$"],"설명":"접점이 $(t,\\,t^{3}-2t^{2}-5)$ 이고 기울기가 $y'(t)=3t^{2}-4t$ 이다.","확인":null,"스킬":"D7"},{"제목":"$t$ 의 값","힌트":"접선이 점 $(1,\\,6)$ 을 지난다는 식에서 실수 $t$ 는?","식":["$6=(3t^{2}-4t)-2t^{3}+2t^{2}-5$ 에서 $2t^{3}-5t^{2}+4t+11=0$","$(t+1)(2t^{2}-7t+11)=0$ 이고 $2t^{2}-7t+11$ 은 판별식이 음수이므로 $t=-1$"],"설명":"$x=1$, $y=6$ 을 접선의 식에 넣는다. 이차식은 실근이 없다.","확인":"-1","스킬":"D7","고비":true},{"제목":"수직인 직선의 기울기","힌트":"$t=-1$ 인 접선에 수직인 직선의 기울기는?","식":["접선의 기울기 $3t^{2}-4t=3+4=7$","$7m=-1$ 에서 $m=-\\frac17$"],"설명":"서로 수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":"-1/7","스킬":"D1"},{"제목":"$y$ 절편","힌트":"점 $(7,\\,1)$ 을 지나고 기울기가 $-\\frac17$ 인 직선의 $y$ 절편은?","식":["$y-1=-\\frac17(x-7)$","$y=-\\frac17x+2$ 이므로 $y$ 절편은 $2$"],"설명":"$x=0$ 을 넣어도 같은 값이 나온다.","확인":"2","스킬":"D1"}]},"ns-787163b84b96":{"길":"접선의 기울기를 $a$ 로 두고 접할 조건을 $a$ 의 이차방정식으로 만들어 판별식의 부호로 접선의 개수를 센다","단계":[{"제목":"곡선과 직선의 교점의 방정식","힌트":"점 $(-2,\\,k)$ 를 지나는 기울기 $a$ 인 직선과 곡선이 만나는 점의 $x$ 좌표가 만족하는 방정식은?","식":["$y=a(x+2)+k$","$a(x+2)+k=-x^{2}-2x$ 에서 $x^{2}+(a+2)x+2a+k=0$"],"설명":"곡선과 직선의 식을 연립한다.","확인":null,"스킬":"G2"},{"제목":"접할 조건","힌트":"접하려면 이 방정식의 판별식 $D$ 는 어떤 식이 되는가?","식":["$D=(a+2)^{2}-4(2a+k)=a^{2}-4a+4-4k=0$"],"설명":"접하면 중근을 가지므로 $D=0$ 이다.","확인":null,"스킬":"G2"},{"제목":"접선의 개수","힌트":"$a$ 에 관한 방정식 $a^{2}-4a+4-4k=0$ 의 판별식의 $\\frac14$ 은?","식":["$\\frac{D'}{4}=(-2)^{2}-(4-4k)=4k$"],"설명":"$a$ 의 값의 개수가 접선의 개수이다. $4k>0$ 이면 $2$ 개, $4k=0$ 이면 $1$ 개, $4k<0$ 이면 $0$ 개이다.","확인":null,"스킬":"G2","고비":true},{"제목":"선지 판정","힌트":"접선의 개수가 $k$ 의 부호에 따라 이렇게 정해질 때 옳은 선지는?","식":["$k>0$ 이면 $2$ 개, $k=0$ 이면 $1$ 개, $k<0$ 이면 $0$ 개","①, ②, ③, ⑤ 는 이와 달라 거짓이고 ④ 가 참"],"설명":"따라서 정답은 ④ 이다.","확인":null,"스킬":"G2"}]},"ns-865f37851b8e":{"길":"밑변 $\\mathrm{OA}$ 가 고정이므로 직선 $y=2x$ 와 기울기가 같은 접선의 접점에서 넓이가 최대이다","단계":[{"제목":"점 $\\mathrm{A}$ 의 좌표","힌트":"$f(x)=2x$ 의 원점이 아닌 실근은?","식":["$\\frac14x^{2}(x^{2}-6x+12)-2x=\\frac14x(x-2)^{3}=0$","원점이 아닌 근은 $x=2$ 이므로 $\\mathrm{A}(2,\\,4)$"],"설명":"$x^{3}-6x^{2}+12x-8=(x-2)^{3}$ 이다.","확인":"2","스킬":"G1"},{"제목":"넓이가 최대인 점 $\\mathrm{P}$","힌트":"$\\mathrm{P}$ 에서의 접선이 직선 $\\mathrm{OA}$ 와 평행할 때 $0<t<2$ 인 $t$ 는?","식":["$f'(x)=x^{3}-\\frac92x^{2}+6x$ 이므로 $f'(t)-2=\\frac12(t-2)^{2}(2t-1)=0$","$0<t<2$ 이므로 $t=\\frac12$"],"설명":"밑변 $\\mathrm{OA}$ 가 고정이면 높이가 최대일 때 넓이가 최대이다. 직선 $y=2x$ 에서 가장 먼 점은 접선의 기울기가 $2$ 인 점이다.","확인":"1/2","스킬":"D1","고비":true},{"제목":"$\\mathrm{P}$ 의 $y$ 좌표","힌트":"$f\\left(\\frac12\\right)$ 의 값은?","식":["$f\\left(\\frac12\\right)=\\frac14\\cdot\\frac14\\cdot\\frac{37}{4}=\\frac{37}{64}$"],"설명":"$f(x)=\\frac14x^{2}(x^{2}-6x+12)$ 에 $x=\\frac12$ 을 넣는다.","확인":"37/64","스킬":"D1"},{"제목":"삼각형의 넓이의 최댓값","힌트":"직선 $y=2x$ 위의 $x=\\frac12$ 인 점과 $\\mathrm{P}$ 사이의 세로 길이로 넓이를 구하면?","식":["$x=\\frac12$ 에서 직선의 $y$ 좌표는 $1$ 이므로 세로 길이는 $1-\\frac{37}{64}=\\frac{27}{64}$","넓이 $=\\frac12\\times\\frac{27}{64}\\times2=\\frac{27}{64}$"],"설명":"세로 선분을 밑변으로 보면 높이의 합은 $\\mathrm{O}$ 와 $\\mathrm{A}$ 의 $x$ 좌표의 차 $2$ 이다.","확인":"27/64","스킬":"G10"}]},"ns-90c032261818":{"길":"점 $(1,\\,3)$ 에서의 미분계수를 기울기로 하는 접선의 식을 세운다","단계":[{"제목":"접선의 기울기","힌트":"점 $(1,\\,3)$ 에서의 접선의 기울기 $a$ 는?","식":["$y'=4x+4$","$a=y'(1)=8$"],"설명":"접선의 기울기는 접점에서의 미분계수이다.","확인":"8","스킬":"D1","고비":true},{"제목":"접선의 방정식과 $a+b$","힌트":"기울기가 $8$ 이고 점 $(1,\\,3)$ 을 지나는 직선에서 $a+b$ 는?","식":["$y-3=8(x-1)$ 에서 $y=8x-5$","$a+b=8+(-5)=3$"],"설명":"$y=ax+b$ 와 비교해 $a=8$, $b=-5$ 이다.","확인":"3","스킬":"D1"}]},"ns-ac63dfb8707f":{"길":"롤의 정리의 조건을 확인하고 $f'(c)=0$ 을 푼다","단계":[{"제목":"롤의 정리의 조건","힌트":"$f(0)$ 과 $f(2)$ 를 비교하면?","식":["$f(0)=1$, $f(2)=4-4+1=1$","$f(0)=f(2)$ 이므로 $f'(c)=0$ 인 $c$ 가 $(0,\\,2)$ 에 있다"],"설명":"다항함수는 연속이고 미분가능하므로 양 끝의 함숫값만 같으면 된다.","확인":null,"스킬":"D2"},{"제목":"$c$ 의 값","힌트":"$f'(c)=0$ 을 풀면 $c$ 는?","식":["$f'(x)=2x-2$","$2c-2=0$ 에서 $c=1$"],"설명":"$c=1$ 은 구간 $(0,\\,2)$ 안에 있다.","확인":"1","스킬":"D2","고비":true}]},"ns-ac9a916b544d":{"길":"롤의 정리의 조건을 확인하고 $f'(c)=0$ 의 해 중 구간 안의 것을 고른다","단계":[{"제목":"롤의 정리의 조건","힌트":"$f(0)$ 과 $f(2)$ 를 비교하면?","식":["$f(0)=0$, $f(2)=8-16+8=0$","$f(0)=f(2)$ 이므로 $f'(c)=0$ 인 $c$ 가 $(0,\\,2)$ 에 있다"],"설명":"다항함수는 연속이고 미분가능하므로 양 끝의 함숫값만 같으면 된다.","확인":null,"스킬":"D2"},{"제목":"$c$ 의 값","힌트":"$f'(c)=0$ 의 해 중 구간 $(0,\\,2)$ 안에 있는 것은?","식":["$f'(x)=3x^{2}-8x+4=(3x-2)(x-2)$","$f'(c)=0$ 에서 $c=\\frac23$ 또는 $c=2$ 이고 $0<c<2$ 이므로 $c=\\frac23$"],"설명":"$c=2$ 는 열린구간의 끝점이라 제외된다.","확인":"2/3","스킬":"D2","고비":true}]},"ns-b2d9ef8e8794":{"길":"구간 $[1,\\,3]$ 의 평균변화율을 구해 $f'(c)$ 와 같게 놓는다","단계":[{"제목":"평균변화율","힌트":"$f(x)=-x^{2}+2x$ 의 $[1,\\,3]$ 에서의 평균변화율은?","식":["$f(1)=1$, $f(3)=-9+6=-3$","$\\frac{f(3)-f(1)}{3-1}=\\frac{-4}{2}=-2$"],"설명":"평균변화율은 $x$ 의 증가량에 대한 $y$ 의 증가량의 비이다.","확인":"-2","스킬":"D2","고비":true},{"제목":"$c$ 의 값","힌트":"$f'(c)$ 가 평균변화율과 같다고 놓으면 $c$ 는?","식":["$f'(x)=-2x+2$","$-2c+2=-2$ 에서 $c=2$"],"설명":"$c$ 는 구간 $(1,\\,3)$ 안에 있다.","확인":"2","스킬":"D2"}]},"ns-b8d99fef24d2":{"길":"접점에서 함숫값이 같고 미분계수가 같다는 두 조건으로 $a$, $b$, $c$ 를 정한다","단계":[{"제목":"$a$ 의 값","힌트":"$f(-2)=5$ 에서 $a$ 는?","식":["$f(-2)=-16+2a+3=5$","$2a=18$ 에서 $a=9$"],"설명":"점 $(-2,\\,5)$ 가 곡선 $y=f(x)$ 위에 있다.","확인":"9","스킬":"D1"},{"제목":"$b$ 의 값","힌트":"접점에서 미분계수가 같다는 조건 $f'(-2)=g'(-2)$ 에서 $b$ 는?","식":["$f'(x)=6x^{2}-9$ 에서 $f'(-2)=15$","$g'(x)=-2x+b$ 에서 $g'(-2)=4+b=15$, $b=11$"],"설명":"두 곡선이 접하면 접점에서 접선이 같으므로 기울기도 같다.","확인":"11","스킬":"D1","고비":true},{"제목":"$c$ 의 값","힌트":"$g(-2)=5$ 에서 $c$ 는?","식":["$g(-2)=-4-2b+c=-4-22+c=5$","$c=31$"],"설명":"$b=11$ 을 넣는다.","확인":"31","스킬":"D1"},{"제목":"$2a+b-c$ 의 값","힌트":"$a=9$, $b=11$, $c=31$ 일 때 $2a+b-c$ 는?","식":["$2a+b-c=18+11-31=-2$"],"설명":"세 값을 식에 넣는다.","확인":"-2","스킬":"D1"}]},"ns-c8a74d5b5a57":{"길":"접선의 기울기가 평행한 직선의 기울기와 같다는 조건으로 접점을 구한다","단계":[{"제목":"접점의 $x$ 좌표","힌트":"기울기가 직선 $3x+y-2=0$ 과 같은 접선의 접점의 $x$ 좌표는?","식":["$3x+y-2=0$ 의 기울기는 $-3$","$f'(x)=3x^{2}-3=-3$ 에서 $x=0$"],"설명":"평행한 두 직선의 기울기는 같다.","확인":"0","스킬":"D1","고비":true},{"제목":"$k$ 의 값","힌트":"접점 $(0,\\,f(0))$ 이 직선 $3x+y+k=0$ 위에 있다고 놓으면 $k$ 는?","식":["$f(0)=-4$ 이므로 접점은 $(0,\\,-4)$","$-4+k=0$ 에서 $k=4$"],"설명":"접선이 접점을 지나므로 접점의 좌표를 직선의 식에 넣는다.","확인":"4","스킬":"D1"}]},"ns-c98fb52d7351":{"길":"접점을 $(t,\\,f(t))$ 로 두고 접선이 $(0,\\,4)$ 를 지나는 조건에서 $t$ 를 구한 뒤 절편으로 넓이를 구한다","단계":[{"제목":"접선의 방정식","힌트":"접점의 $x$ 좌표를 $t$ 라 할 때 접선의 방정식은?","식":["$f'(x)=-3x^{2}$","$y=-3t^{2}(x-t)-t^{3}+2$"],"설명":"접점이 $(t,\\,-t^{3}+2)$ 이고 기울기가 $f'(t)=-3t^{2}$ 이다.","확인":null,"스킬":"D7"},{"제목":"$t$ 의 값","힌트":"접선이 점 $(0,\\,4)$ 를 지난다는 식에서 $t$ 는?","식":["$4=-3t^{2}(0-t)-t^{3}+2=2t^{3}+2$","$t^{3}=1$ 에서 $t=1$"],"설명":"$x=0$, $y=4$ 를 접선의 식에 넣는다.","확인":"1","스킬":"D7","고비":true},{"제목":"접선의 $x$ 절편","힌트":"$t=1$ 인 접선이 $x$ 축과 만나는 점의 $x$ 좌표는?","식":["$f(1)=1$ 이므로 $y=-3(x-1)+1=-3x+4$","$y=0$ 에서 $x=\\frac43$"],"설명":"접선의 $y$ 절편은 $4$ 이다.","확인":"4/3","스킬":"D1"},{"제목":"삼각형의 넓이","힌트":"$x$ 절편과 $y$ 절편으로 삼각형의 넓이를 구하면?","식":["$\\frac12\\times4\\times\\frac43=\\frac83$"],"설명":"좌표축과 접선으로 둘러싸인 삼각형은 두 절편이 직각을 낀 두 변이다.","확인":"8/3","스킬":"G10"}]},"ns-ceca667ac9b1":{"길":"$f'\\ge0$ 으로 증가함을 보이고 $f(a)>0$ 이라 가정해 평균값 정리로 모순을 만든다","단계":[{"제목":"$f$ 의 증가","힌트":"$f'(x)\\ge0$ 이면 $x_{1}<x_{2}$ 일 때 $f(x_{1})$ 과 $f(x_{2})$ 의 대소는?","식":["$\\frac{f(x_{2})-f(x_{1})}{x_{2}-x_{1}}=f'(c)\\ge0$ ($x_{1}<c<x_{2}$)","$f(x_{1})\\le f(x_{2})$"],"설명":"$f$ 는 미분가능하므로 연속이다. 평균값 정리를 쓰면 $f$ 는 감소하지 않고, $f(0)=0$ 이므로 $x\\ge0$ 에서 $f(x)\\ge0$ 이다.","확인":null,"스킬":"D2"},{"제목":"귀류법의 가정","힌트":"$0<a<1$ 인 $a$ 에서 $f(a)>0$ 이라 가정하고 $[0,\\,a]$ 에 평균값 정리를 쓰면?","식":["$\\frac{f(a)-f(0)}{a-0}=\\frac{f(a)}{a}=f'(c_{2})$ ($0<c_{2}<a$)"],"설명":"$f(0)=0$ 이므로 평균변화율이 $\\frac{f(a)}{a}$ 이다.","확인":null,"스킬":"D2"},{"제목":"부등식의 연쇄","힌트":"$f'(c_{2})\\le f(c_{2})$ 와 $f$ 가 증가함을 이어 $\\frac{f(a)}{a}$ 를 $f(a)$ 와 비교하면?","식":["$\\frac{f(a)}{a}=f'(c_{2})\\le f(c_{2})\\le f(a)$"],"설명":"(나)에서 $f'(c_{2})\\le f(c_{2})$ 이고 $c_{2}<a$ 이므로 증가함수에서 $f(c_{2})\\le f(a)$ 이다.","확인":null,"스킬":"C9","고비":true},{"제목":"모순과 결론","힌트":"$a<1$ 이고 $f(a)>0$ 이면 $\\frac{f(a)}{a}$ 와 $f(a)$ 의 대소는?","식":["$\\frac{f(a)}{a}>f(a)$ 이므로 위 부등식과 모순","따라서 $[0,\\,1)$ 에서 $f(x)=0$"],"설명":"$f(x)\\ge0$ 이므로 $f(a)>0$ 이 불가능하면 $f(a)=0$ 이다.","확인":null,"스킬":"C9"},{"제목":"$f(1)$ 의 값","힌트":"$f$ 가 $x=1$ 에서 연속일 때 $\\lim_{x\\to1-}f(x)$ 는?","식":["$f(1)=\\lim_{x\\to1-}f(x)=0$"],"설명":"$[0,\\,1)$ 에서 $f(x)=0$ 이므로 좌극한도 $0$ 이다.","확인":"0","스킬":"D12"}]},"ns-d2f6b67b9df6":{"길":"평균값 정리로 $f(t)\\le$ 와 $f(t)\\ge$ 를 모두 얻어 $f(t)$ 를 정하고 빈칸을 읽는다","단계":[{"제목":"(가) 평균값 정리의 분모","힌트":"닫힌구간 $[1,\\,t]$ 에서 평균값 정리의 분모는?","식":["$\\frac{f(t)-f(1)}{t-1}=f'(c_{1})$","$g(t)=t-1$"],"설명":"구간의 길이가 분모이다.","확인":null,"스킬":"D2"},{"제목":"(나) $f(t)$ 의 상한","힌트":"$f'(c_{1})\\le3$ 과 $f(1)=2$ 로 $f(t)$ 의 상한은?","식":["$f(t)-2\\le3(t-1)$ 에서 $f(t)\\le3t-1$","$h(t)=3t-1$"],"설명":"(ⅱ)에서도 같은 값이 $f(t)$ 의 하한이 되어 $f(t)=3t-1$ 이다.","확인":null,"스킬":"D2","고비":true},{"제목":"(다) $f(2)$ 의 값","힌트":"$f(t)=3t-1$ 에서 $f(2)$ 는?","식":["$f(2)=3\\times2-1=5$"],"설명":"$1<t<3$ 이므로 $t=2$ 를 넣을 수 있다. 따라서 $m=5$ 이다.","확인":"5","스킬":"D2"},{"제목":"$\\frac{g(0)+h(4)}{m}$ 의 값","힌트":"$g(t)=t-1$, $h(t)=3t-1$, $m=5$ 일 때 $\\frac{g(0)+h(4)}{m}$ 는?","식":["$g(0)=-1$, $h(4)=11$","$\\frac{-1+11}{5}=2$"],"설명":"$g$, $h$ 는 식이므로 구간 밖의 값도 대입할 수 있다.","확인":"2","스킬":"D2"}]}});
